INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_everyday_science', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Top Everyday Science', NULL, 2184, 1790968052413) ON CONFLICT(id) DO UPDATE SET total_mcqs = 2184;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eds_general', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'General Everyday Science', 'top_everyday_science', 1013, 1790968052457) ON CONFLICT(id) DO UPDATE SET total_mcqs = 1013;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a4fee25e7e2baf94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following best describes the residual volume of the lungs?', '{"A":"The volume of air that always remains in the lungs.","B":"The amount of air normally inhaled and exhaled with each breath.","C":"The maximum amount of air that can be forcibly inhaled and exhaled from the lungs.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Residual volume (RV) is the volume of air that remains in the lungs after maximum forced expiration.It cannot be voluntarily exhaled completely.It helps prevent the lungs from collapsing.It is different from normal tidal breathing.Last verified on 01-10-2026', 0, 0, 0, 1790968052502) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ee1e83de41ae5485', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Chromosomes are present in _____?', '{"A":"Nucleus","B":"Ribosomes","C":"Cytoplasm","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chromosomes are present in the nucleus of eukaryotic cells.They are thread-like structures made of DNA and proteins.They carry genetic information.They help ensure the accurate distribution of genetic material during cell division.Last verified on 01-10-2026', 0, 0, 0, 1790968052502) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce22536e75f0ac56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Two strands of DNA are ____?', '{"A":"Antiparallel to each other","B":"Parallel to each other","C":"Perpendicular to each other","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The two strands of DNA run in opposite directions (5'' to 3'' on one strand and 3'' to 5'' on the other).This orientation is known as antiparallel.It is crucial for proper DNA replication and function.Last verified on 01-10-2026', 0, 0, 0, 1790968052502) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45cd3070d743125d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following planets is known for its beautiful, prominent, and visible rings around it?', '{"A":"Jupiter","B":"Saturn","C":"Uranus","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Saturn is famous for its prominent and beautiful ring system.Its rings are made mainly of ice particles, dust, and rock fragments.Additional information:It is the second-largest planet in the Solar System.It is often called the “Ringed Planet.”Famous moon: TitanOrbital period: About 29.5 Earth yearsIt is the sixth planet from the Sun.Last verified on 27-09-2026', 0, 0, 0, 1790968052502) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cbed0e4111bb7294', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In physics, the smallest unit of matter is ____?', '{"A":"Atom","B":"Cell","C":"Tissue","D":"Organ"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The smallest unit of matter is an atom.Structure of an AtomNucleus: The central part made of heavy protons and neutrons.Electrons: Tiny, light particles that circle the nucleus.Protons: Particles with a positive charge.Neutrons: Particles with no electrical charge', 0, 0, 0, 1790968052502) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_65d91ec334aee83a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is used in fire ‘extinguishers’?', '{"A":"Carbon sulphite","B":"Carbon monoxide","C":"Carbon dioxide","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carbon dioxide (CO₂) is used in fire extinguishers.It extinguishes fire by displacing oxygen and cooling the burning material.CO₂ fire extinguishers are especially effective for electrical and flammable liquid fires.Carbon dioxide is a colorless and non-flammable gas.It leaves no residue after use.', 0, 0, 0, 1790968052502) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b42ba37e9a0a9bd2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which enzyme is responsible for breaking down starch into maltose in the human digestive system?', '{"A":"Lipase","B":"Pepsin","C":"Amylase","D":"Trypsin"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amylase breaks down starch.Starch → Maltose + smaller sugars.Found in saliva and pancreatic juice.Salivary amylase starts starch digestion in the mouth', 0, 0, 0, 1790968052502) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8eaaef73778a8037', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The most abundant gase in the earth''s atmosphere by volume is _____?', '{"A":"Nitrogen","B":"Oxygen","C":"Argon","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nitrogen (N₂) → 78%Additional information:Oxygen (O₂) → 21%Argon (Ar) → 0.93%Carbon dioxide (CO₂) → 0.04% (approximately)Other gases → Trace amountsLast verified on 28-06-2026', 0, 0, 0, 1790968052502) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c65434a172bf71e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Hailstorm occurs in summer season due to the formation of clouds called?', '{"A":"Cirrus","B":"Cumulus","C":"Cumulonimbus","D":"Curriculum"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cumulonimbus clouds are tall, dense clouds associated with thunderstorms.They can produce hail, heavy rain, lightning, and strong winds.Hail forms when strong updrafts inside these storm clouds carry water droplets upward, where they freeze.Last verified on 09-09-2026', 0, 0, 0, 1790968052539) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_63802b052081d42c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Deficiency of Iodine causes ____?', '{"A":"Imbalances in fluid volume in the vessels and tissues","B":"Goiter","C":"Tetnas","D":"Cancer"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iodine deficiency causes goiter, an enlargement of the thyroid gland.Iodine is essential for the production of thyroid hormones.Severe iodine deficiency during pregnancy or early childhood can impair brain development.Last verified on 07-09-2026', 0, 0, 0, 1790968052539) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_37a6d7f6316f62d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'For which purpose seismograph is used?', '{"A":"For predicting earthquake","B":"For recording earthquake","C":"For measuring intensity of earthquake","D":"For locating epicenter of earthquake"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A seismograph is an instrument used to detect and record earthquakes. It consists of a mass attached to a fixed baseDuring an earthquake, the base moves and the mass does not.Last verified on 07-09-2026', 0, 0, 0, 1790968052539) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a9c63b6b35881376', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the major function of the human lungs?', '{"A":"Pumping blood","B":"Digestion","C":"Exhaling CO₂ & inhaling O₂","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The lungs exchange gases — they absorb oxygen (O₂) and release carbon dioxide (CO₂).This process is essential for respiration and energy production in the body.Last verified on 05-09-2026', 0, 0, 0, 1790968052539) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_47341861978892ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Where is the pituitary gland located?', '{"A":"In the chest","B":"At the base of the brain","C":"In the abdomen","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The pituitary gland is located at the base of the brain.It is below the hypothalamus.It sits in a hollowed-out area of the sphenoid bone called the sella turcica.Last verified on 05-09-2026', 0, 0, 0, 1790968052539) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_37cf5d10f30e6d88', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who discovered the Law of Motion (Three Laws of Motion)?', '{"A":"Galileo Galilei","B":"Albert Einstein","C":"Isaac Newton","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Isaac Newton formulated the Three Laws of Motion.He presented them in 1687 in his famous work Principia Mathematica.Three Laws of Motion:First Law — Law of Inertia: An object remains at rest or in uniform motion unless acted upon by an external force.Second Law — Law of Acceleration: The net force on an object is related to its mass and acceleration.Third Law — Action and Reaction: For every action, there is an equal and opposite reaction.Last verified on 05-09-2026', 0, 0, 0, 1790968052539) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f79765575ac60c58', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which is the largest gland in the human body?', '{"A":"Thyroid","B":"Liver","C":"Pancreas","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The liver is the largest gland in the human body.It is situated in the right upper quadrant of the abdomen, beneath the diaphragm, and above the stomach.It is reddish-brown.It is weighs approximately 1.5 kg.Additional information:The pineal gland is the smallest gland.It about the size of a grain of rice.It weighs approximately 150 mg.It is part of the endocrine system.Last verified on 02-04-2026', 0, 0, 0, 1790968052539) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9506d9342ff2dcf0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Deforestation is primarily caused by?', '{"A":"Urbanization","B":"Acid Rain","C":"Earthquakes","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Urbanization leads to clearing of forests for housing, infrastructure, and industries.Other causes include agriculture, logging, and mining.Last verified on 05-09-2026', 0, 0, 0, 1790968052539) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bbf83a46d57c94f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Allergy is caused due to?', '{"A":"Introduction of external material into body","B":"Inflammation of upper respiratory tract","C":"Antigen-antibody reaction","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allergy is an abnormal immune response to harmless substances like dust or pollen.It occurs when the body reacts excessively to an allergen.This reaction involves the immune system producing antibodies.Thus, allergy is mainly due to an antigen–antibody reaction.Last verified on 23-04-2026', 0, 0, 0, 1790968052589) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4a269079d953debb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'GPS is an abbreviation of _____?', '{"A":"Google Positioning System","B":"Global Positioning System","C":"Global Positioning Station","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation GPS is an abbreviation of the Global Positioning System.It is a satellite-based radio navigation system.Owned by the United States government. First launch: February 22, 1978Last verified on 05-09-2026', 0, 0, 0, 1790968052589) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c952a94c39c7b376', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The number of ribs in a human body is?', '{"A":"23","B":"26","C":"24","D":"22"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The normal number of ribs in a human body is 24 (12 pairs).Additional information:Upper ribs: True ribs (1–7 pairs)Lower ribs: False ribs (8–12 pairs)Floating ribs: Last 2 pairs (11–12)Last verified on 24-06-2026', 0, 0, 0, 1790968052589) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_42dab9cc4ab56bea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'MRI is stands for _____?', '{"A":"Magnetic Resonance Imaging","B":"Magnetic Related  Imaging","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation MRI stands for Magnetic Resonance Imaging.It is a medical imaging technique.It uses strong magnetic fields and radio waves to create detailed images of organs and tissues.Last verified on 03-09-2026', 0, 0, 0, 1790968052589) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d7e524c7595c1cb8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is not a digestive gland?', '{"A":"Liver","B":"Adrenal gland","C":"Pancreas","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adrenal gland → Endocrine gland, not a digestive gland.Liver → Digestive gland; produces bile.Pancreas → Digestive gland; produces digestive enzymes.Last verified on 03-09-2026', 0, 0, 0, 1790968052589) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_53ed605741fd1705', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who invented Radio?', '{"A":"Graham Bell","B":"Thomas Edison","C":"Marconi","D":"Wright Brothers"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Marconi invented Radio.Radio was invented in 1895.Guglielmo Marconi was an Italian inventor.Last verified on 12-08-2026', 0, 0, 0, 1790968052589) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_98468dcab75163cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who invented Telephone?', '{"A":"Thomas Edison","B":"Nikola Tesla","C":"Alexander Graham Bell","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alexander Graham Bell is credited as the inventor of the telephone.He was awarded the first successful patent for it.The telephone was invented in 1876.Bell made the first-ever telephone call to his assistant Thomas Watson.Last verified on 31-03-2026', 0, 0, 0, 1790968052589) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e51b47717857282', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'DNA is the abbreviation of _______?', '{"A":"Decomposednucleic Acid","B":"Degeneratenucleic Acid","C":"Deoxyribonucleic Acid","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DNA stands for Deoxyribonucleic Acid.DNA is a biological molecule found in all living cells.It carries genetic information from parents to offspring.It controls growth, development, and body functions.DNA is present in the nucleus of cells (mainly in chromosomes).It is made of nucleotides arranged in a double helix structure.It was discovered by James Watson and Francis Crick (1953 structure model).Last verified on 01-06-2026', 0, 0, 0, 1790968052589) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17faa312cb9d2290', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The production of ammonia in industry can be increased by increasing ______?', '{"A":"Temperature","B":"Pressure","C":"Catalyst","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ammonia is produced by the Haber process.The reaction is: N₂ + 3H₂ ⇌ 2NH₃.There are 4 moles of gas on the left and 2 moles on the right.Increasing pressure shifts the equilibrium toward ammonia.Therefore, higher pressure increases ammonia production.', 0, 0, 0, 1790968052626) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_34c092baa5063b69', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Humidity in the air was measured by _____?', '{"A":"Barometer","B":"Hygrometer","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Humidity is the measure of the amount of moisture (water vapour) in the air.A hygrometer is used to measure relative humidity.A psychrometer is an example of a hygrometer.Relative humidity tells us the ratio of water vapour present in the air compared with the maximum amount the air can hold at a given temperature.Humidity is commonly expressed as a percentage (%).Last verified on 23-08-2026', 0, 0, 0, 1790968052626) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c83d465885517971', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who postulated the law of universal gravitation?', '{"A":"Newton","B":"Dalton","C":"Einstein","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The law of universal gravitation was proposed by Isaac Newton.He introduced it in 1687 in his famous book Principia.It explains that every object attracts every other object.The force depends on mass and distance.Last verified on 27-04-2026', 0, 0, 0, 1790968052626) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_71a3a79de38a5857', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Ozone is present in which layer of atmosphere?', '{"A":"Biosphere","B":"Thermosphere","C":"Troposphere","D":"Stratosphere"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ozone (O₃) is mainly found in the Stratosphere, called the ozone layer.It absorbs harmful ultraviolet (UV) radiation from the sun, protecting life on Earth.Located roughly 15–35 km above the Earth’s surface.Last verified on 17-01-2026', 0, 0, 0, 1790968052626) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_173a4fd2a195bb82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Radioactivity measured by which device?', '{"A":"Radioactivity meter","B":"Geiger counter","C":"Roll counter","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Antoine Henri Becquerel was an engineer, physicist, Nobel laureate, First person to discover evidence of radioactivity. He belonged to France.', 0, 0, 0, 1790968052626) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b3462def28ad4876', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Ginger is a _____?', '{"A":"Leaf","B":"Stem (Rhizome)","C":"Root","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ginger is an underground modified stem called a rhizome.It stores nutrients.It helps in vegetative propagation.Last verified on 27-07-2026', 0, 0, 0, 1790968052626) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66b5a2570ff642d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Viruses are ______?', '{"A":"Cellular","B":"Non-Cellular","C":"Parasites","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Viruses are non-cellular and obligate intracellular parasites.They cannot carry out life processes or reproduce without a living host cell.Viruses contain either DNA or RNA.They are considered to be at the boundary between living and non-living.The branch of science that studies viruses is called Virology.Last verified on 27-07-2026', 0, 0, 0, 1790968052626) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1473825a546ca0b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Geostationary satellites appear to be stationary when viewed from the Earth. Geostationary satellites are located directly above the ______?', '{"A":"Tropic of Cancer","B":"Prime Meridian","C":"Equator","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geostationary satellites are located directly above the equator. Altitude: About 35,786 kilometers (22,236 miles) above sea level.Speed and Direction: Moves from west to east, matching the Earth''s rotation speed.Time Period: Exactly 24 hours (one rotation day). Last updated 26-07-2026 by NA', 0, 0, 0, 1790968052626) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6f9fa1c76d023c8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Rainbow is produced due to _______ of lights.', '{"A":"Dispersion","B":"Diffraction","C":"Reflection","D":"Refraction"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A rainbow is produced due to the dispersion of sunlight by water droplets in the atmosphere.White sunlight splits into seven colours when it passes through raindrops.The formation of a rainbow involves refraction, dispersion, and internal reflection.Dispersion is the phenomenon responsible for separating white light into its constituent colours.Rainbows are usually seen opposite the Sun after rainfall.Last verified on 26-07-2026', 0, 0, 0, 1790968052662) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6d9fff23ceb38bf0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '27°C is equal to how many Kelvin (K)?', '{"A":"273 K","B":"290 K","C":"300 K","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kelvin = °C + 27327 + 273 = 300 K.Last verified on 06-07-2026', 0, 0, 0, 1790968052662) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af546a60b4f920f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'How many vertebrae / bones are present in the human vertebral column (spine)?', '{"A":"25","B":"33","C":"44","D":"39"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total Vertebrae: 33Cervical Vertebrae: 7Thoracic Vertebrae: 12Lumbar Vertebrae: 5Sacral Vertebrae: 5 (fused) and Coccygeal Vertebrae: 4 (fused)Additional information:Total bones in an adult: 206Bones in a newborn: About 300Longest bone: FemurShortest bone: StapesBones in the skull: 22Bones in one hand: 27Last verified on 21-07-2026', 0, 0, 0, 1790968052662) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_43140e3652216cd8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Lungs are located / situated in the which cavity?', '{"A":"Abdominal cavity","B":"Pericardial cavity","C":"Thoracic cavity","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The lungs are located in the thoracic cavity.The thoracic cavity is the chest cavity protected by the rib cage.It contains the lungs, heart, trachea, and major blood vessels.The lungs are enclosed by the pleural membranes.This cavity plays a vital role in breathing and respiration.Last verified on 18-07-2026', 0, 0, 0, 1790968052662) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_253b199a295f9604', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'White goods are?', '{"A":"Cosmetic Good","B":"Durable Consumption Goods","C":"Basic Raw Materials","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation White goods are durable consumer goods, mainly large household electrical appliances.The term originally referred to appliances that were usually finished in white enamel.These products are designed for long-term household use.Examples: Refrigerator, Washing Machine, Air Conditioner, Dishwasher, Deep FreezerAdditional information:Brown goods include entertainment electronics such as TVs, radios, and audio systems.Last verified on 18-07-2026', 0, 0, 0, 1790968052662) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b7ba9d2375f1fcab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Amino acids are building blocks of ______?', '{"A":"Nucleic acids","B":"Protein","C":"Vitamins","D":"Lipid"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amino acids are the building blocks of proteins.Proteins are formed when amino acids join together by peptide bonds.Proteins are essential for growth, repair, and body functions.There are 20 standard amino acids used to make proteins.Verified & Updated', 0, 0, 0, 1790968052662) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eab8b85d45756330', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The most abundant component in Earth''s atmosphere (Air) is?', '{"A":"Hydrogen","B":"Oxygen","C":"Nitrogen","D":"Carbon dioxide"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nitrogen (N₂): 78%Additional information:Oxygen (O₂): 21%Argon (Ar): 0.93%Carbon dioxide (CO₂): ~0.04%Other gases: ~0.03%Last verified on 16-05-2026', 0, 0, 0, 1790968052662) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e8f31e1a16bfda87', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What will happen if the ozone layer disappears?', '{"A":"UV Rays reach the earth","B":"UV Rays do not reach the earth","C":"X Rays breach the earth’s surface","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If the ozone layer disappears, harmful ultraviolet (UV) rays will reach the Earth''s surface in much larger amounts.The ozone layer protects life by absorbing most of the Sun''s harmful UV-B and UV-C radiation.Increased UV radiation can cause skin cancer, cataracts, and weakened immune systems.It can also damage crops, marine life, and ecosystems.The ozone layer is found mainly in the stratosphere.Verified & Updated', 0, 0, 0, 1790968052662) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d19b582030d5835c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A black hole has a very strong ______?', '{"A":"Electric field","B":"Magnetic field","C":"Gravitational field","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A black hole has an extremely strong gravitational field.Its gravity is so powerful that even light cannot escape from it.Black holes are formed when very massive stars collapse after exhausting their fuel.The boundary beyond which nothing can escape is called the event horizon.The idea of black holes comes from Einstein''s General Theory of Relativity (1915).Last verified on 08-07-2026', 0, 0, 0, 1790968052699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_15f1f760caebe1ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Sputnik-1 was the first manmade spacecraft, which was launched on October 4, 1957 by the ____?', '{"A":"USSR (Soviet Union)","B":"United States of America","C":"China","D":"Great Britain"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sputnik-1 was launched by the USSR (Soviet Union) on 4 October 1957.It was the world''s first artificial satellite, beginning of the Space Age.It started the Space Race between the Soviet Union and the United States.Launch Site: Baikonur Cosmodrome, KazakhstanWeight: 83.6 kgOrbital Period: About 96 minutesLast verified on 09-03-2026', 0, 0, 0, 1790968052699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f234caaf97fc5440', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Fathometer is used to measure ______?', '{"A":"Ocean Depth","B":"Earthquakes","C":"Rainfalls","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Fathometer is used to measure the depth of the ocean, sea, or any body of water.It determines the distance from the water surface to the seabed.The instrument works using sound waves (echo sounding).It measures the time taken for sound waves to travel to the seabed and return.Additional information:Galvanometer → Measures electric currentBarometer → Measures atmospheric pressureThermometer → Measures temperatureHygrometer → Measures humidityLast verified on 06-07-2026', 0, 0, 0, 1790968052699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_13619a8f73a186c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who explained the Photoelectric Effect?', '{"A":"Isaac Newton","B":"James Clerk Maxwell","C":"Albert Einstein","D":"Niels Bohr"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Albert Einstein explained the Photoelectric Effect in 1905 by proposing that light consists of tiny particles called photons.He showed that electrons are emitted from a metal surface when light of sufficient frequency falls on it.His explanation supported Quantum Theory.Einstein received the Nobel Prize in Physics in 1921 for this discovery.Last verified on 06-07-2026', 0, 0, 0, 1790968052699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a44de7c17dd5b4be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Freezing point of water is ______?', '{"A":"0°C","B":"32°F","C":"273K","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Freezing Point: 0°CFahrenheit: 32°FKelvin: 273.15 KAdditional information:Boiling Point: 100°C (212°F or 373.15 K)Standard Atmospheric Pressure: 1 atm (760 mmHg)Last verified on 06-07-2026', 0, 0, 0, 1790968052699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a2866bd7297aa583', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The boiling point of water on a centigrade scale is?', '{"A":"80°C","B":"90°C","C":"100°C","D":"10°C"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Boiling point of water: 100°CFreezing point of water: 0°CStandard atmospheric pressure: 1 atm (760 mmHg)0°C = 32°F100°C = 212°FLast verified on 06-07-2026', 0, 0, 0, 1790968052699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a30c6b5ff2393bc1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'One nanometer is equal to ______?', '{"A":"10⁻³ m","B":"10⁻⁶ m","C":"10⁻⁹ m","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 Nanometer (nm) = 10⁻⁹ mAdditional information:1 Kilometer (km) = 10³ m1 Meter (m) = 10⁰ m1 Millimeter (mm) = 10⁻³ m1 Micrometer (µm) = 10⁻⁶ mLast verified on 06-07-2026', 0, 0, 0, 1790968052699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dd42a615b7c4cac6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Laws of magnetic induction given by _____?', '{"A":"Tesla","B":"Faraday","C":"Newton","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The laws of magnetic induction were given by Michael Faraday.Faraday proposed these laws in 1831 after discovering electromagnetic induction.The laws explain that a changing magnetic field induces an electromotive force (EMF) in a conductor.These laws are the foundation of electric generators and transformers.Last verified on 06-07-2026', 0, 0, 0, 1790968052699) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0cb4f00150d99e3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Convex lenses are also known as ____?', '{"A":"Converging lenses","B":"Diverging lenses","C":"Deflecting lenses","D":"Reflecting lenses"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Convex lenses are known as Converging lenses.Because they bring parallel light rays to a single focal point.A convex lens is thicker at the center and thinner at the edges.It forms real and inverted images when the object is beyond the focal length.It can also produce a virtual, erect, and magnified image when the object is placed within the focal length.Additional information:Concave lens is also called a diverging lens.Last verified on 11-03-2026', 0, 0, 0, 1790968052740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f0a20eb5d5e3615c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The meat of calf is called _____?', '{"A":"Veal","B":"Venison","C":"Chevon","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Veal is the meat from young calves.It can come from calves of either sex and any breed.Last verified on 03-07-2026', 0, 0, 0, 1790968052740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_889ee49cbff796bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The SI unit of magnetic flux is?', '{"A":"Reluctance","B":"Resistance","C":"Permeance","D":"Weber"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Weber (Wb) is the SI unit of magnetic flux.One Weber is equal to one volt-second (V·s).A magnetic flux density of 1 Weber per square metre (1 Wb/m²) is equal to 1 Tesla (T).Magnetic flux measures the total magnetic field passing through a surface.Last verified on 03-07-2026', 0, 0, 0, 1790968052740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4209f78b98499492', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The intensity/magnitude of earthquake is measured by ____?', '{"A":"Beaufort scale","B":"Richter scale","C":"Mohs scale","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The magnitude of an earthquake is measured by the Richter scale.It measures the energy released by an earthquake.The Richter scale was developed in 1935 by Charles F. Richter.It is used in seismology (the study of earthquakes).Last verified on 30-06-2026', 0, 0, 0, 1790968052740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_982f333c3a509e01', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '1 BTU is equal to _____ Joules.', '{"A":"1200","B":"1055","C":"1000","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 🔹 1 BTU = 1055.06 Joules (approx.)🔹 1 BTU = 252 calories (approx.)🔹 1 Joule = 0.0009478 BTU🔹 1 kWh = 3412 BTU, linking electrical energy to heat energy.🔹 Commonly used in heating/cooling systems🔹 Named after the British engineers who developed early thermal measurementsLast verified on 30-06-2026', 0, 0, 0, 1790968052740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25edd24c5a5af9fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The SI Unit of Capacitance of capacitor is called?', '{"A":"Ampere","B":"Newton","C":"Farad","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790968052740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4e16db0b5c4dbbf2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following gases contributes to global warming?', '{"A":"CFC (Chlorofluorocarbon)","B":"Carbon dioxide","C":"Methane","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CFCs, carbon dioxide (CO₂), and methane (CH₄) are all greenhouse gases.Carbon dioxide traps heat in the atmosphere and increases temperature.Methane is a very strong greenhouse gas with high warming effect.CFCs also damage the ozone layer and act as greenhouse gases.Last verified on 16-06-2026', 0, 0, 0, 1790968052740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_95ce74ccc1b46eea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The ocean water is NOT drinkable due to the presence of large amount of salts, particularly?', '{"A":"Sodium chloride (Salts)","B":"Sulphuric acid","C":"Zinc bromide","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ocean water is not drinkable due to a high amount of sodium chloride (common salt).This salt makes water too salty for human consumption.Seawater also contains small amounts of other dissolved minerals.High salt concentration causes dehydration in the human body.Last verified on 25-06-2026', 0, 0, 0, 1790968052740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_281e36339d0c7ecb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The electrical device that converts AC to DC is called as?', '{"A":"Battery","B":"Rectifier","C":"Transistor","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A rectifier is an electrical device that converts Alternating Current (AC) into Direct Current (DC).It allows current to flow in only one direction.It is commonly used in power supplies and chargers.Rectifiers use components like diodes for conversion.Last verified on 25-06-2026', 0, 0, 0, 1790968052777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_93af776dc453de98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Electric fire alarm works on the principle of ______?', '{"A":"Contraction","B":"Expansion","C":"Conduction","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Electric fire alarms work on the principle of expansion of metals due to heat.A fire alarm uses a bimetallic strip that bends when heated because different metals expand at different rates.This bending completes an electric circuit and activates the alarm.It is an example of the thermal expansion principle.Last verified on 25-06-2026', 0, 0, 0, 1790968052777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_be8e2fa89ab3a08f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In our body, the percentage of water is?', '{"A":"30 percent","B":"90 percent","C":"60 percent","D":"50 percent"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On average, the human body contains about 60–70% water.Adult males: 60–65%Adult females: 50–60%Infants: ~75%Main functions: transport, digestion, temperature regulationLast verified on 23-06-2026', 0, 0, 0, 1790968052777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f2281a0d7664009', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The audible range of normal human ear is ____?', '{"A":"16 Hz to 20kHz","B":"10 Hz to 31kHz","C":"67 Hz to 45kHz","D":"20 Hz to 20kHz"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The audible range of a normal human ear is 20 Hz to 20,000 Hz (20 kHz).Sounds below this range are called infrasound,Sounds above it are called ultrasound. Lower limit: 20 Hz (deep rumbles)Upper limit: 20,000 Hz (high-pitched squeaks)Additional informationAdult change: The upper limit often drops to 15,000–17,000 Hz as people get older. Unit of frequency: Hertz (Hz)Last updated 27-07-2026 by NA', 0, 0, 0, 1790968052777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_492fdb2a624ef81c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Lead pencil is made up of?', '{"A":"Aluminum","B":"Silver","C":"Graphite","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lead pencil is made up of graphite.Graphite is a form (allotrope) of carbon.It is soft and leaves marks on paper easily.It is used in pencils because of its slippery layered structure.Despite the name “lead pencil,” it contains no real lead.Graphite was named by Abraham Gottlob Werner in 1789.Last verified on 21-06-2026', 0, 0, 0, 1790968052777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d8a9f50851b15fce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Diamond is allotropic form of?', '{"A":"Carbon","B":"Hydrogen","C":"Oxygen","D":"Aluminum"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Diamond is a naturally occurring allotropic form of carbon.Allotropy means a single element can exist in more than one form with different structures and properties.It is extremely hard.It has a high melting point.It is widely used in jewelry and cutting tools.Additional information:Graphite – soft, good conductorFullerenes (C60) – spherical moleculesCarbon nanotubes – tubular, high strengthAmorphous carbon – coal, sootLonsdaleite – hexagonal diamondLast verified on 17-01-2026', 0, 0, 0, 1790968052777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd9f464e8f552fbc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'How many time zones are there on/in earth/world?', '{"A":"24","B":"12","C":"10","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total standard zones: 24Earth rotation time: 24 hoursLongitude per zone: 15 degreesStarting point: Greenwich (0°)It is used worldwide for time coordination.Last verified on 14-06-2026', 0, 0, 0, 1790968052777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dee3f07e1e2d9f61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Solvent extraction is an equilibrium process and it is controlled by?', '{"A":"Dalton’s Law","B":"Raoult’s Law","C":"Nernst Distribution Law","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Solvent extraction is controlled by the Distribution Law (Nernst Distribution Law).It describes how a solute distributes between two immiscible liquids.At equilibrium, the concentration ratio remains constant.This law governs equilibrium in extraction processes.Last verified on 18-06-2026', 0, 0, 0, 1790968052777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b61f0ebb42fa2e0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The drying agent used in desiccator?', '{"A":"SrCl₂","B":"CaCl₂","C":"BeCl₂","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Calcium chloride (CaCl₂) is used as a drying agent in a desiccator.It absorbs moisture from the air.It keeps substances dry and free from water vapor.Desiccators are used in laboratories for drying chemicals.CaCl₂ is highly hygroscopic.Last verified 18-06-2026', 0, 0, 0, 1790968052815) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4ccdbb3c18f04019', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In SI unit of Time, Picosecond is equal to?', '{"A":"10⁻¹²","B":"10⁻⁶","C":"10⁻¹⁸","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Picosecond (ps) = 10⁻¹² secondsSI prefix “pico” means 10⁻¹².1 picosecond = one trillionth of a second.Additional information:Microsecond (μs) = 10⁻⁶ secondsNanosecond (ns) = 10⁻⁹ secondsMillisecond (ms) = 10⁻³ secondsFemtosecond (fs) = 10⁻¹⁵ secondsAttosecond (as) = 10⁻¹⁸ secondsZeptosecond (zs) = 10⁻²¹ secondsYoctosecond (ys) = 10⁻²⁴ secondsLast verified on 17-06-2026', 0, 0, 0, 1790968052815) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_87de73d90c9c1a27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In plants, the exchange of gases occurs through ______?', '{"A":"Chlorophyll","B":"Stomata","C":"Flowers","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plants need gas exchange for photosynthesis and respiration.Exchange of CO₂, O₂, and water vapor occurs through stomata on leaves.Stomata are tiny pores controlled by guard cells.Additional information:Helps maintain internal water balance and gas diffusion.Essential for growth, energy production, and transpiration.Last verified on 22-01-2026', 0, 0, 0, 1790968052815) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_58873ac552248710', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Moho discontinuity is found between?', '{"A":"Inner core and outer core","B":"Crust and Mantle","C":"Upper mantle and lower mantle","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Moho discontinuity is the boundary between the Earth’s crust and mantle.It was discovered by seismologist Andrija Mohorovičić in 1909.It is identified by a sudden change in seismic wave speed.The crust is solid outer layer, while the mantle lies beneath it.Depth varies from 5–70 km depending on land or ocean area.Last verified on 02-04-2026', 0, 0, 0, 1790968052815) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_67ddb78a6d196a6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The bodyguard of the Earth is ________ that save the Earth from many Comets and Asteroids.', '{"A":"Mars","B":"Uranus","C":"Jupitar","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The bodyguard of the Earth is Jupiter, which protects Earth from many comets and asteroids due to its strong gravity.Jupiter attracts or deflects space objects that might otherwise hit Earth.It is the largest planet in the solar system.Its strong gravitational field acts like a “shield” for inner planets.That is why it is often called Earth’s protector.Last verified on 14-06-2026', 0, 0, 0, 1790968052815) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_27aeab34efbbf678', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The biggest part of the earth by volume is the mantle. The thickness of the earth is about ______?', '{"A":"7000 km","B":"900 km","C":"2900 km","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The thickness of Earth is about 13,700 kilometers (8,500 miles). The mantle, which is the biggest part of Earth by volume.It is approximately 2,900 kilometers (1,800 miles) thick. Last verified on 09-06-2026', 0, 0, 0, 1790968052815) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4509d5fe5471bbae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The structural and functional unit of environment is?', '{"A":"Ecosystem","B":"Community","C":"Population","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ecosystem is the structural and functional unit of the environment.Ecosystem = Biotic + Abiotic componentsBiotic: plants, animals, microorganismsAbiotic: water, air, soil, sunlightLast verified on 08-06-2026', 0, 0, 0, 1790968052815) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8121140158d8b838', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The process of sublimation?', '{"A":"A solid turns directly into a liquid","B":"A liquid turns directly into a gas","C":"A gas turns directly into a liquid","D":"A solid turns directly into a gas"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sublimation is the direct transition of a solid into a gas without passing through the liquid phase.Additional information:Some common sublimating substances:Dry ice (CO₂) – solid → gasIodine crystals – solid → violet gasCamphor – solid → vaporNaphthalene (mothballs) – solid → gasAmmonium chloride – solid → gasLast verified on 13-03-2026', 0, 0, 0, 1790968052815) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b395903cab96bf73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which are the basic structural and functional units of the nervous system?', '{"A":"Axons","B":"Nephrons","C":"Neurons","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Neurons are the basic structural and functional units of the nervous system.They are specialized nerve cells.They transmit electrical and chemical signals.They control communication in the body.Brain, spinal cord, and nerves are made up of neurons.Last verified on 08-06-2026', 0, 0, 0, 1790968052850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_39406c2f86bd76f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The hardest natural substance in the world is known as?', '{"A":"Diamond","B":"Copper","C":"Iron","D":"Silver"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The hardest substance in the world is diamond.Its hardness is due to the strong covalent bonding between its carbon atoms.This making it the most resistant to scratching.Additional information:Category: Native mineralsCleavage: 111 (perfect in four directions)Crystal class: Hexoctahedral (m3m); H-M symbol: (4/m 3 2/m)Crystal habit: OctahedralCrystal system: CubicDana classification: 1.3.6.1Density: 3.5–3.53 g/cm3 3500–3530 kg/m3Last verified on 07-06-2026', 0, 0, 0, 1790968052850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da771641711248ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Apple is rich in _____?', '{"A":"Iron / Fiber","B":"Phosphorus","C":"Calcium","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Apple is rich in iron and dietary fiber.Iron helps in blood formation (RBC production).Fiber helps in digestion and stomach health.Apple also contains vitamins and antioxidants.It is a very healthy fruit for daily use.Last verified on 07-06-2026', 0, 0, 0, 1790968052850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_48c27a8677dee3b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The molecular mass of water is _____?', '{"A":"18 amu","B":"16 amu","C":"17 amu","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The chemical formula for water is H₂O.Atomic masses:Hydrogen (H) = 1 amu each → 2 × 1 = 2 amuOxygen (O) = 16 amuTotal molecular mass = 2 (from H) + 16 (from O) = 18 amu.Last verified on 07-06-2026', 0, 0, 0, 1790968052850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_14c9ccdc9acb17e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The primary component of glass is _____?', '{"A":"Carbon","B":"Limestone","C":"Silica","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Silica (SiO₂) is the main component of glass.It providing its transparency and hardness.It forms a network structure when melted, giving glass its solid yet brittle nature.Last verified on 07-06-2026', 0, 0, 0, 1790968052850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_81c79888b8696884', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which law states that mass can neither be created nor destroyed?', '{"A":"Law of Conservation of Mass","B":"Boyle’s Law","C":"Newton’s Law","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The law that states mass can neither be created nor destroyed is the Law of Conservation of Mass.This law states that mass remains constant in a chemical reaction.Matter cannot be created or destroyed, only transformed.Last verified on 02-04-2026', 0, 0, 0, 1790968052850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64944969e9f2105c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Short-sightedness defect can be corrected by wearing a _____?', '{"A":"Convex Lens","B":"Concave Lens","C":"Prism Lens","D":"Cylindrical Lens"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Short-sightedness is called Myopia.It is corrected by a concave lens.This lens is thin in the center and thick at edges.It helps light focus on the retina correctly.Without correction, distant objects look blurred.Additional information:Long-sightedness is called Hypermetropia.It is corrected by a convex lens.This lens is thick in the center and thin at edges.It helps light focus on the retina properly.Without correction, near objects look blurred.Last verified on 07-06-2026', 0, 0, 0, 1790968052850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10ab86856280638d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The volume of a sphere is?', '{"A":"4/3πr³","B":"2/3πr³","C":"πr³","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surface area = 4πr², Volume = 4/3πr³. Surface area is just derivative of volume w.r.t r.2πr is circumference of a circle, not volume at all.Last verified on 07-06-2026', 0, 0, 0, 1790968052850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1bb6b5985055eb88', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Smog is the cause of?', '{"A":"Acid rain","B":"Air pollution","C":"Ozone layer thinning","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Smog is a form of air pollution formed by smoke + fog.It mainly occurs in big cities due to vehicle and factory emissions.It reduces visibility and causes breathing problems.Smog is a serious environmental and health hazard.Last verified on 06-06-2026', 0, 0, 0, 1790968052884) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eff2a8e8fe330b3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which forests act as barriers against cyclones?', '{"A":"Alpine forests","B":"Mangrove forests","C":"Evergreen forests","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mangrove forests act as barriers against cyclones.Mangroves reduce erosion by trapping sediments, stabilizing the coastal zone and thus protecting the coast from storm surges and cyclones.Mangroves in Pakistan are found along the coastline of Sindh and Balochistan.Last verified on 06-06-2026', 0, 0, 0, 1790968052884) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd5067c204f95739', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Over-damping results in _____?', '{"A":"Slower return to equilibrium","B":"Faster return to equilibrium","C":"Equilibrium is never achieved","D":"Unrhythmic to equilibrium"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Over-damping occurs when damping force is very large.The system returns to equilibrium without oscillating.Because of strong resistance, motion becomes very slow.It takes more time compared to critical damping.Last verified on 05-06-2026', 0, 0, 0, 1790968052884) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4ebaf9d4648543f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The period of the Physical Pendulum is?', '{"A":"T = 2π√(I/Mgd)","B":"T = 2π√(1/x)","C":"√T = 4¹/MgR","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Physical pendulum depends on moment of inertia (I) and distance (d) from pivot to center of mass.Time period increases when mass is farther from pivot (larger d).Standard formula is T = 2π√(I/Mgd).Last verified on 05-06-2026', 0, 0, 0, 1790968052884) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa644890d5f45102', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the these is the best description of a zener diode?', '{"A":"It operates in reverse region","B":"It is a constant voltage device","C":"It is a constant current device","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zener diode is mainly used as a constant voltage regulator.It operates in the reverse breakdown region.In this region, voltage remains almost constant even if current changes.Last verified on 05-06-2026', 0, 0, 0, 1790968052884) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d4020345f3271ca5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following series of H-spectrum lies in ultraviolet region?', '{"A":"Lyman series","B":"Balmer series","C":"Paschen series","D":"Bracket series"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lyman series lies in the ultraviolet (UV) region of hydrogen spectrum.It is produced when an electron falls to the first energy level (n = 1).These transitions release high-energy photons.Additional information:Balmer series lies in the visible region.Paschen and Brackett are in infrared.Last verified on 05-06-2026', 0, 0, 0, 1790968052884) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17c813c221c81531', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In chromatographic analysis the principle used is?', '{"A":"Absorption","B":"Distribution","C":"Adsorption","D":"Evaporation"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chromatography mainly works on the principle of adsorption.Different substances are adsorbed to different extents on a stationary phase.This causes separation of components in a mixture.Last verified on 05-06-2026', 0, 0, 0, 1790968052884) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7cc5587b9ad9a4ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which endocrine glands become inactive during old age?', '{"A":"Pituitary","B":"Thymus","C":"Adrenal","D":"Pineal"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thymus gland becomes inactive during old age.It is active during childhood for immune system development.It helps in maturation of T-lymphocytes (T cells).After puberty, it gradually shrinks and loses function.Last verified on 04-06-2026', 0, 0, 0, 1790968052884) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b2642dab169a2f6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Enzymes required for transcription is?', '{"A":"RNAase","B":"Endonucleases","C":"RNA polymerase","D":"DNA polymerase"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RNA polymerase is the enzyme required for transcription.It helps in synthesizing RNA from a DNA template.Transcription is the first step of gene expression.It occurs in the nucleus of eukaryotic cells.RNA strand is formed complementary to DNA.Last verified on 04-06-2026', 0, 0, 0, 1790968052924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7fc0fdde5b864212', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Mulberry silkworm is ______?', '{"A":"Anthraea mylitta","B":"Bombyx mori","C":"Attacus atlas","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bombyx mori, which is the scientific name for the Mulberry silkworm. This species is widely cultivated for its silk production.It is often referred to as the "Domesticated silkworm" or simply "Silkworm".Last verified on 04-06-2026', 0, 0, 0, 1790968052924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac5b99f310b0fa1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the Circumference of Earth?', '{"A":"450,000 km","B":"50,075 km","C":"40,075 km","D":"30,000 km"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Earth’s circumference at the equator is about 40,075 km (24,901 miles).Measured through the poles, it is slightly smaller: 40,008 km (24,860 miles).The difference is due to the equatorial bulge caused by Earth''s rotation.Diameter: ~12,756 km (7,926 miles).Age of Earth: ~4.453 billion years.Last verified on 31-03-2026', 0, 0, 0, 1790968052924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b3e5f679d3179796', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Anemometer is the instrument used for measurement of ____?', '{"A":"Wind Speed / Electrically records with velocity","B":"Wind Direction","C":"Pressure","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Anemometer is a scientific instrument used to measure wind speed (velocity).It is mainly used in meteorology and weather forecasting.It helps in studying storms, cyclones, and air pressure changes.Common types include cup, vane, and hot-wire anemometers.Additional Information:A hygrometer is an instrument used to measure humidity.A salinometer is used to measure the salinityA bolometer is used to measure the power of incident electromagnetic radiationA barometer is used to measure air pressure in certain environment.Last verified on 30-05-2026', 0, 0, 0, 1790968052924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc9083f491d4cf1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Instrument used for measuring the thickness/purity of milk is called what?', '{"A":"Lucimeter","B":"Lactometer","C":"Barometer","D":"Hydrometer"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A lactometer is used to measure the purity and density (thickness) of milk.It checks if milk has been adulterated with water by measuring specific gravity.Works on the principle of buoyancy.Pure milk specific gravity: 1.028–1.032 at 15°CLast verified on 16-03-2026', 0, 0, 0, 1790968052924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b012af9007c50e3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Among the following, which group of food help our body grow and repair tissues and muscles?', '{"A":"Carbohydrates","B":"Vitamins","C":"Proteins","D":"Minerals"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Proteins are called body-building foods.They help in growth, repair of tissues, and muscle development.They are essential for maintaining and rebuilding body cells.They are made of amino acids, the building blocks of the body.Deficiency of protein can lead to weak muscles and poor growth.Last verified on 06-05-2026', 0, 0, 0, 1790968052924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_667c4a92db496e55', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Coulomb''s law states ______?', '{"A":"Force between two point charges is directly proportional to the sum of the charges and inversely proportional to the square of the distance between them","B":"Force between two point charges is directly proportional to the product of the charges and the square of the distance between them","C":"Force between two point charges is inversely proportional to the product of the charges and directly proportional to the square of the distance between them","D":"Force between two point charges is directly proportional to the product of the charges and inversely proportional to the square of the distance between them"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Coulomb''s Law states that the magnitude of the electrostatic force (F) between two point charges (q1 and q2) is directly proportional to the product of the charges and inversely proportional to the square of the distance (r) between them.Mathematically, this is expressed as: F ∝ (q1 × q2) / r². This law describes the relationship between electric charges and the force they exert on each other.Last verified on 22-05-2026', 0, 0, 0, 1790968052924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8dd864a60000e3af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Crossing over in meiosis takes place in ______?', '{"A":"Diakinesis","B":"Pachytene","C":"Zygotene","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Crossing over occurs in Pachytene stage of Prophase I.Homologous chromosomes are fully paired and exchange genetic material at this stage.This leads to new gene combinations.Last verified on 20-05-2026', 0, 0, 0, 1790968052924) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_38427e010947fcfc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Fertilization of the ovum by the sperm usually occurs in the _____?', '{"A":"Fallopian tubes","B":"Uterus","C":"Vagina","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fertilization typically occurs in the Fallopian tubes (oviducts).It is specifically in the ampulla region.The fertilized egg then moves to the uterus for implantation.Last verified on 20-05-2026', 0, 0, 0, 1790968052963) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0acb5bbb589bce99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is basic unit of classification?', '{"A":"Species","B":"Order","C":"Family","D":"Genus"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Species is the basic unit of classification.Species are a group of organisms that are morphologically similar and can interbreed.Classification system as proposed by Linnaeus.These groups or levels are:KingdomPhylumClassOrderFamilyGenus SpeciesSpecies is the smallest unit of classification.Last verified on 20-05-2026', 0, 0, 0, 1790968052963) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62d5594dafed6cc7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Crossing over of linked genes occurs during _____ of meiosis.', '{"A":"Prophase I","B":"Prophase II","C":"Metaphase I","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Crossing over occurs during Prophase I of meiosis.It occurs in specifically in the pachytene stage.This process allows genetic recombination, increasing genetic diversity.Last verified on 20-05-2026', 0, 0, 0, 1790968052963) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e027191e339fbfe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In the manufacturing of Nylon 6,6, which two chemicals are used?', '{"A":"Adipic acid and Hexamethylenediamine","B":"Terephthalic acid and Ethylene glycol","C":"Caprolactam and Water","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nylon 6,6 is a synthetic polyamide polymer.It is formed by condensation polymerization.Two monomers react to form long polymer chains.Nylon 6,6 is formed by condensation of adipic acid (diacid) and hexamethylenediamine (diamine).Each monomer contributes 6 carbon atoms (hence 6,6).Water is eliminated during the reaction.Last verified on 19-05-2026', 0, 0, 0, 1790968052963) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d77a79da7f377e40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following has the highest electrical conductivity?', '{"A":"Iron","B":"Steel","C":"Silver","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Electrical conductivity means how easily a material allows electric current to pass through it.Among common metals, silver has the highest electrical conductivity.Additional information:Silver: 100 (highest)Copper: 97 (very close second)Gold: 76Aluminum: 60Iron: ~17 (low compared to above metals)Last verified on 17-05-2026', 0, 0, 0, 1790968052963) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d8718bba74c07742', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Theory of relativity was given by ______?', '{"A":"Newton","B":"Chadwick","C":"Einstein","D":"Becquerel"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Theory of Relativity was proposed by Albert Einstein.It was introduced in the early 20th century.It includes Special Relativity (1905) and General Relativity (1915).The theory explains the relationship between space, time, and gravity.Last verified on 02-04-2026', 0, 0, 0, 1790968052963) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5f138b16804f04ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Isobars have the same ______?', '{"A":"Atomic number","B":"Mass number","C":"Neutrons","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Isobars are atoms of different elements.They have same mass number but different atomic number.They show different chemical properties but same nuclear mass.Example: Argon-40 and Calcium-40 both have mass number 40 but different atomic numbers.Last verified on 07-05-2026', 0, 0, 0, 1790968052963) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_50321a50ceeada91', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Whale has descended from ancestors that?', '{"A":"Lived on land","B":"Lived on the sea-bed","C":"Lived on trees","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Whales evolved from land-dwelling mammals.Their ancestors gradually adapted to aquatic life.Over millions of years, they moved from land to sea.They developed flippers instead of legs for swimming.This is an example of evolution and adaptation.Last verified on 26-04-2026', 0, 0, 0, 1790968052963) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c0b1eb930c5266a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Digestion begins in one of the following part of the body?', '{"A":"In the stomach","B":"In the mouth","C":"In the esophagus","D":"In the intestine"}', 'B', NULL, 0, 0, 0, 1790968052998) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3705164e3440e440', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who was considered as Father/Expert of Modern Optics?', '{"A":"Abū Mūsā Jābir ibn Ḥayyān","B":"Jafar Ibn Hayyan","C":"Ḥasan Ibn al-Haytham","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ibn al-Haytham is known as the Father of Modern Optics.He made groundbreaking discoveries about light and vision.His famous book is Kitab al-Manazir (Book of Optics).His research was done around 1011–1021 AD.Last verified on 27-04-2026', 0, 0, 0, 1790968052998) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2d336f7fd958fc58', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The highest density of sweat glands (eccrine) in the human body is found on the?', '{"A":"Cheeks","B":"Forehead","C":"Back","D":"Palms of the hands and soles of the feet"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Eccrine sweat glands help regulate body temperature.They are most densely found on palms and soles.These glands produce watery sweat for cooling.They are active throughout the body, especially in these areas.This helps maintain body temperature balance.Last verified on 26-04-2026', 0, 0, 0, 1790968052998) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c527aa3488bd6020', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Evaporation causes ______?', '{"A":"Cooling","B":"Vapor pressure","C":"High temperature","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Evaporation is the process of liquid changing into vapor.During this process, heat is absorbed from the surroundings.This causes a drop in temperature (cooling effect).That is why sweating cools the human body.Evaporation is a natural cooling phenomenon.Last verified on 26-04-2026', 0, 0, 0, 1790968052998) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_293c8270e8ab83f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which is known as Earth''s Twin?', '{"A":"Mercury","B":"Mars","C":"Venus","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Venus is the brightest planet.It has an atmosphere but no moons.It''s identical in size, chemistry and gravity.It has volcanoes, mountains and sand.It''s also called Sister Planet of the Earth.Last verified on 25-04-2026', 0, 0, 0, 1790968052998) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0d9cf122b1b5808f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is most soluble in water?', '{"A":"Sulphur","B":"Common Salt","C":"Camphor","D":"Sugar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sugar is the most soluble chemical in water.Sugar is made from sucrose.Sugar dissolves readily in water due to its polar nature.It forms hydrogen bonds with water molecules, increasing solubility.Used widely in food and beverages due to easy dissolution.Last verified on 23-04-2026', 0, 0, 0, 1790968052998) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b8e8999df3c1e8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following control the reflex action in the body?', '{"A":"Central nervous system","B":"Motor nerves","C":"Sensory nerves","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A reflex action is a quick, automatic response to a stimulus.It is mainly controlled by the spinal cord, which is part of the central nervous system.This allows fast response without involving the brain immediately.Thus, reflexes are coordinated by the central nervous system.Last verified on 23-04-2026', 0, 0, 0, 1790968052998) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_29a4f6c18d04803b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A Barometer is device used to measure ______?', '{"A":"Humidity","B":"Atmospheric Pressure","C":"Room Temperature","D":"Salt in sea water"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A barometer measures atmospheric (air) pressure.It helps in weather forecasting, detecting storms, and studying climate changes.Two common types of barometers: mercury barometer and aneroid barometer.Last verified on 13-03-2026', 0, 0, 0, 1790968052998) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dcf2aff3fd9355df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which is the only metal expands on Solidification?', '{"A":"Lithium","B":"Bismuth","C":"Dysprosium","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bismuth is the only pure metal that expands when it solidifies (freezes). Most substances contract on solidification, but bismuth behaves unusually—its solid form occupies a slightly larger volume than its liquid form.***', 0, 0, 0, 1790968053032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6cd089e1fde2ea92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In binary representation, what is the decimal equivalent of 1011?', '{"A":"11","B":"12","C":"13","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To find the decimal equivalent of the binary number 1011:(1 × 2³) + (0 × 2²) + (1 × 2¹) + (1 × 2⁰)= (1 × 8) + (0 × 4) + (1 × 2) + (1 × 1)= 8 + 0 + 2 + 1= 11Last verified on 12-04-2026', 0, 0, 0, 1790968053032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_def0a09a79dcb7e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A Covalent Bond is formed by?', '{"A":"Sharing of electron","B":"Gain of an electron","C":"Transfer of electron","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A covalent bond forms when atoms share electrons.It usually occurs between non-metals.Sharing helps atoms achieve stable electron configuration.No transfer of electrons occurs.Therefore, it is based on electron sharing.Last verified on 12-04-2026', 0, 0, 0, 1790968053032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7aed222643919dc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The refractive index of glass is ______?', '{"A":"1.5","B":"1.3","C":"1.42","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Refractive index shows how much light bends when entering a medium.Glass is a transparent solid with moderate optical density.Its refractive index is a standard value used in physics experiments.It is greater than water and less than diamond. So, the commonly accepted value for glass is around 1.5.Last verified on 12-04-2026', 0, 0, 0, 1790968053032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c28cd9a7fa6e991b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A chronometer meter measures _______?', '{"A":"Water waves","B":"Color contrast","C":"Time","D":"Sound waves"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chronometer is a highly precise time-measuring instrument.It is often used in navigation and scientific experiments.It is designed to measure time accurately, even under varying conditions.Chronometers played a key role in determining longitude at sea.Last verified on 03-04-2026', 0, 0, 0, 1790968053032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1f02ea527658caad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Echoes are produced due to _____?', '{"A":"Polarization of sound","B":"Diffraction of sound","C":"Refraction of sound","D":"Reflection of sound"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Echoes are produced when sound waves bounce back after hitting a surface, which is due to the reflection of sound.This reflected sound is heard as an echo.Last verified on 02-04-2026', 0, 0, 0, 1790968053032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7bd12486871ebe59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Plants at night exhale ______?', '{"A":"Oxygen (O2)","B":"Carbon dioxide (CO2)","C":"Hydrogen (H2)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During the day, plants perform photosynthesis, absorbing carbon dioxide and releasing oxygen.At night, in the absence of sunlight, they undergo respiration, where they take in oxygen and release carbon dioxide.Last verified on 02-04-2026', 0, 0, 0, 1790968053033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b878508c968b863c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In Fahrenheit scale the boiling point of water is ______?', '{"A":"208°F","B":"210°F","C":"212°F","D":"214°F"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the Fahrenheit scale:The freezing point of water is 32°FThe boiling point of water is 212°FLast verified on 02-04-2026', 0, 0, 0, 1790968053033) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b04cab1d2f402152', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The melting point of Ice on Fahrenheit Scale is taken as _____?', '{"A":"32°F","B":"0°F","C":"212°F","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The freezing (or melting) point of ice on the Fahrenheit scale is 32°F.This is the temperature at which ice turns from a solid to a liquid. The Fahrenheit scale also defines the boiling point of water as 212°F.A change of 1°F on the Fahrenheit scale is less than a 1°C change on the Celsius scale.Last verified on 02-04-2026', 0, 0, 0, 1790968053064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4185de1725c8233f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Lunar eclipse occurs when _____?', '{"A":"Moon is between the earth and the sun","B":"Earth is between the sun and the moon","C":"Sun is between the earth and the moon","D":"Earth is at right angles to the direction of the sun and the moon"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An eclipse occurs when one celestial body blocks another’s light.Lunar eclipse happens when Earth’s shadow falls on the Moon.Solar eclipse happens when the Moon blocks sunlight reaching Earth.These events occur due to alignment of Sun, Earth, and Moon.Last verified on 01-04-2026', 0, 0, 0, 1790968053064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_11e0fd428de16809', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The average heartbeat per minute in a normal man is _____?', '{"A":"70","B":"60","C":"50","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The normal resting heart rate of an adult human is about 70 beats per minute.It can vary depending on age, fitness, and health condition.Additional information:Normal adult: 60–100 beats/minAthletes: 40–60 beats/minChildren: 70–120 beats/minInfants: 100–160 beats/minLast verified on 31-03-2026', 0, 0, 0, 1790968053064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16249a68e77df004', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Jabir bin Hayyan was famous Muslim?', '{"A":"Physicist","B":"Chemist","C":"Discoverer","D":"Teacher"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jabir ibn Hayyan, known as the "father of chemistry."He was an Arab Chemist.Composition of Alchemy was written by Jabir Bin Hayyan.Notable ideas:Use of organic substances in chemistrySulfur-mercury theory of metals Science of the balance Science of artificial generationLast verified on 07-02-2026', 0, 0, 0, 1790968053064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62eba39e7de9af6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The main component of bones and teeth is _____?', '{"A":"Calcium Carbonate","B":"Calcium Phosphate","C":"Magnesium Sulfate","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Calcium phosphate, specifically hydroxyapatite, is the main component of bones and teeth.It is a calcium salt of phosphoric acid.It is the primary mineral constituent of bone tissue, making up about 70-80% of bone dry weight.Calcium phosphate gives bones and teeth their strength and rigidity.Last verified on 31-03-2026', 0, 0, 0, 1790968053064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5abc761620bf3406', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Hepatitis A is transmitted to different individuals by ______?', '{"A":"Hand shaking","B":"Water","C":"Air","D":"Blood transmission"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hepatitis A spreads mainly through contaminated water or food.Common in areas with poor sanitation.It is a fecal-oral transmission disease.Last verified on 31-03-2026', 0, 0, 0, 1790968053064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_931739e13d71e28f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Hepatitis which spreads through contaminated food and water is ______?', '{"A":"Hepatitis A","B":"Hepatitis B","C":"Hepatitis C","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hepatitis A is primarily spread through the fecal-oral route, often via consumption of contaminated food or water.It can be prevented by maintaining good hygiene, ensuring safe drinking water, and vaccination.Last verified on 31-03-2026', 0, 0, 0, 1790968053064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5ef29cfc11f0c16a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Rainfall is measured using a _____?', '{"A":"Salinometer","B":"Rainoscope","C":"Rain gauge","D":"Rainometer"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rainfall is measured using a Rain Gauge.It collects rainwater and measures it in millimeters (mm).Widely used in weather forecasting and meteorology.Helps in studying climate and agriculture patterns.Last verified on 31-03-2026', 0, 0, 0, 1790968053064) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c55b044dfa229744', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the freezing point of heavy water?', '{"A":"0°C","B":"3.82°C","C":"4.00°C","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The freezing point of heavy water is 3.82°C:Heavy water (D2O) Regular waterFreezing point 3.82°C 0°C |Boiling point 101.42°C 100°C | Heavy water is made up of two deuterium atoms and one oxygen atom.It contains more deuterium, a hydrogen isotope, than regular water, which contains hydrogen-1. Heavy water is used in reaction mechanisms.It is is prepared by electrolyzing water.Last verified on 30-03-2026', 0, 0, 0, 1790968053097) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d41fbc1cffe8edd0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who discovered homeopathy?', '{"A":"Samuel Hahnemann","B":"Hippocrates","C":"Paracelsus","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Samuel HahnemannBirth: 1755Death: 1843Country: GermanyPrinciple: “Similia similibus curentur” (like cures like)Famous work: Organon of MedicineLast verified on 30-03-2026', 0, 0, 0, 1790968053097) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_185aab20415361d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Cholera is caused by _____?', '{"A":"Bacteria","B":"Virus","C":"Fungi","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cholera is an infectious disease caused by the bacterium Vibrio cholerae.Symptoms include severe diarrhea, dehydration, and vomiting.Cholera can be prevented by clean drinking water and proper sanitation.It mainly spreads through contaminated water and food.It is most common in areas with poor hygiene and overcrowding.Last verified on 3-03-2026', 0, 0, 0, 1790968053097) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d614f735d2dbf0c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Noise pollution/intensity is measured in ______?', '{"A":"Decibels (dB)","B":"Hertz (Hz)","C":"Watts (W)","D":"Meters (m)"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Noise intensity is measured in decibels (dB).It indicates the loudness of sound.It helps assess noise pollution in cities, industries, and traffic areas.Noise pollution affects hearing, stress levels, and sleep.Reducing exposure above 85 dB is important for health protection.Last verified on 19-03-2026', 0, 0, 0, 1790968053097) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3401f50137e5ff7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following animal is secondary consumer? Dog, Cat, Cow, Both A and B', '{"A":"Dog","B":"Cat","C":"Cow","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cat and Dog is/are a secondary consumer.Because they eats primary consumers (herbivores).Like mice, birds, and rabbits.Last verified on 19-03-2026', 0, 0, 0, 1790968053097) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d73eb223e5632d8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The coloured part of the eye is called?', '{"A":"Pupil","B":"Iris","C":"Cornea","D":"Retina"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The iris is the colored part of the eye (blue, brown, green, etc.).It controls the size of the pupil, regulating how much light enters the eye.Additional information:Pupil – black opening for lightCornea – transparent front layerLens – focuses lightRetina – receives imageLast verified on 19-03-2026', 0, 0, 0, 1790968053097) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_44b99246c3a342ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Three essential elements needed for the healthy growth of plants are _____?', '{"A":"Carbon (C), Oxygen (O), and Hydrogen (H)","B":"Phosphorus (P), Potassium (K), and Nitrogen (N)","C":"Helium (He), Neon (Ne), and Argon (Ar)","D":"Calcium (Ca), Magnesium (Mg), and Sulfur (S)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Phosphorus (P), Potassium (K), and Nitrogen (N) are three essential macronutrients for plant growth.It is also referred to as "NPK".They play critical roles in various plant processes, including photosynthesis, root development, and cell growth.Last verified on 17-03-2026', 0, 0, 0, 1790968053097) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df1ab2ce83e00196', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '1 meter is equal to ______ feet.', '{"A":"3.2808 ft","B":"2.2808 ft","C":"4.2808 ft","D":"1.2808 ft"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 meter = 3.2808 feet exactly.Additional information:1 kilometer = 3280.8 feet1 centimeter = 0.032808 feet1 inch = 0.083333 feet1 mile = 5280 feet1 yard = 3 feetLast verified on 16-03-2026', 0, 0, 0, 1790968053097) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c52dcbc373c1751a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Days and nights are formed due to _____?', '{"A":"Earth’s revolution","B":"Earth’s rotation on its axis","C":"Earth’s rotation accompanied with its revolution","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Earth revolves around the Sun.It is rotates on its own axis.The Earth''s rotation causes day and night.One complete rotation takes 24 hours.Last verified on 16-03-2026', 0, 0, 0, 1790968053130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8bcda7f2a1a832c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Anion is a __________ charge?', '{"A":"Positive","B":"Neutral","C":"Negative","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An anion is a negative charge (or negatively charged ion).The ''n'' in anion stands for negativeFormed when non-metal gains electrons. They gain one or more than one electron.Formation: Gained electrons.Attracted to the anode (positively charged electrode).Generally larger than their parent atoms. ____Cations are ions that are positively chargedLast updated 15-03-2026', 0, 0, 0, 1790968053130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c468fad851fc697', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one the following gases is present in the atmosphere in the highest amount?', '{"A":"Oxygen","B":"Nitrogen","C":"Helium","D":"Carbon Dioxide"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nitrogen (N2) makes up about 78% of the Earth''s atmosphere.Making it the most abundant gas in the atmosphere.It is followed by oxygen (~21%), with other gases in much smaller amounts.Last verified on 15-03-2026', 0, 0, 0, 1790968053130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ecd8edda916f3b56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The filament of an electric bulb is made of _______?', '{"A":"Iron","B":"Tungsten","C":"Nichrome","D":"Graphite"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The filament of an electric bulb is made of Tungsten.Because it has a very high melting point (~3422°C).It can glow brightly without melting. Tungsten provides efficient and long-lasting light in incandescent bulbs.Last verified on 15-03-2026', 0, 0, 0, 1790968053130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cb98a2a35090877e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Earth rotates its axis from _____?', '{"A":"East to West","B":"West to East","C":"North to South","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All plants move Anticlockwise around Sun.All plants move anticlockwise around their axis.Earth rotates its axis from West to East.Last verified on 15-03-2026', 0, 0, 0, 1790968053130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5fe8d95e7132cd9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Mitochondria are commonly known as?', '{"A":"Kitchen of the cell","B":"Powerhouse of the cell","C":"Brain of the cell","D":"Skeleton of the cell"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mitochondria are cell organelles responsible for producing energy in the form of ATP (Adenosine Triphosphate) through cellular respiration. They are called the “Powerhouse of the cell” because they provide the energy required for all cellular activities.Mitochondria have their own DNA and ribosomes, allowing them to replicate independently.Last verified on 14-03-2026', 0, 0, 0, 1790968053130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da7b7936b17d7bf9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The law of inertia also called _____?', '{"A":"First Law of Motion","B":"Second Law of Motion","C":"Third Law of Motion","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Law of Inertia = Newton’s First Law of Motion.States: “An object at rest stays at rest, and an object in motion continues in the same direction and speed unless acted upon by an unbalanced force.”Explains why seat belts are important in cars.Applies to all objects on Earth and in space.Last verified on 13-03-2026', 0, 0, 0, 1790968053130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b2ca4504b54bf47c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In which one of the following reactions do the two compounds exchange radicals/ions?', '{"A":"Double Displacement","B":"Decomposition","C":"Combination","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Double Displacement Reaction: Two compounds exchange ions or radicals to form new compounds.General form: AB + CD → AD + CB.Example: Na₂SO₄ + BaCl₂ → BaSO₄ + 2NaClAdditional information:Decomposition: Single compound breaks into two or more simpler substances.Combination (Synthesis): Two or more substances combine to form one compound.Last verified on 13-03-2026', 0, 0, 0, 1790968053130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e00c3c035d2a0a79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The smallest particle of any substance having all properties of that molecules is called?', '{"A":"An atom","B":"A molecule","C":"A compound","D":"An element"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A molecule is the smallest particle of a substance that retains its chemical properties.It is made of two or more atoms chemically bonded together.Examples of molecules: H₂O, O₂, CO₂, NH₃, CH₄.Additional information:An atom is the smallest unit of an element.A compound is a substance formed when different elements combine chemically.Last verified on 13-03-2026', 0, 0, 0, 1790968053168) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c9c57e5fba0d60e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What can be deduced from the symbol ⁴₂He?', '{"A":"Helium occurs as a diatomic molecule","B":"An atom of helium contains two electrons","C":"Helium has a proton (atomic) number of 4","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The symbol ⁴₂He indicates helium has 2 protons (atomic number = 2) and mass number = 4.In a neutral atom, the number of electrons = protons, so helium has 2 electrons.Last verified on 13-03-2026', 0, 0, 0, 1790968053168) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f32f892f95fba680', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Scientists who forecasting weather by continuously tracking and predicting the path of tornadoes, hurricanes or floods are called?', '{"A":"Geologists","B":"Meteorologists","C":"Astronomers","D":"Oceanographers"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Meteorologists are scientists who study the atmosphere and weather conditions.They forecast tornadoes, hurricanes, floods, and other weather events using satellites, radar, and computer models.Their work helps in early warning systems and disaster management.Last verified on 12-03-2026', 0, 0, 0, 1790968053168) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_89de6bb1eab28ce1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'LED stands for _____?', '{"A":"Light Emitting Diode","B":"Laser Emitting Device","C":"Low Energy Device","D":"Liquid Emitting Display"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LED (Light Emitting Diode) is a semiconductor device that emits light when electric current passes through it.It is widely used in lighting, displays, electronic indicators, and screens.Additional information:Energy efficiency: Up to 90% more efficient than traditional bulbsFirst discovery: H. J. Round – 1907Early research: Oleg Losev – 1927Practical LED development: James R. Biard – 1961First commercial production: October 1962 (Nick Holonyak)Last verified on 12-03-2026', 0, 0, 0, 1790968053168) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eb581c89e631d7a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The molecular model of DNA which suggests the basic mechanism replication was proposed by?', '{"A":"James Watson and Francis Crick","B":"Charles Darwin and Gregor Mendel","C":"Louis Pasteur and Robert Koch","D":"Albert Einstein and Max Planck"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The molecular structure (double-helix model) of DNA was proposed in 1953.This model explained how DNA replicates and carries genetic information in living organisms.The discovery was made by James Watson and Francis Crick, two molecular biologists.Last verified on 11-03-2026', 0, 0, 0, 1790968053168) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c1700f3731a6498a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'An instrument that enables us to see distant objects is called?', '{"A":"Telescope","B":"Microscope","C":"Oscilloscope","D":"Laparoscope"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Telescope is an optical instrument used to observe distant objects such as stars, planets, and galaxies.It collects and magnifies light or other forms of electromagnetic radiation.The term “telescope” was coined in 1611 by the Greek mathematician Giovanni Demisiani.Last verified on 10-03-2026', 0, 0, 0, 1790968053168) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a47bf861262ef476', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Law of conservation of mass was given by ____?', '{"A":"Antoine Lavoisier","B":"Joseph Black","C":"Mikhail Lomonosov","D":"Jean Stas"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Antoine Lavoisier, a French chemist, is credited with discovering the law of conservation of mass in 1789 (1785).He demonstrated that matter cannot be created or destroyed in a chemical reaction, only transformed from one substance to another.Last verified on 10-03-2026', 0, 0, 0, 1790968053168) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4745825f1afdba93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The relation of Torque is?', '{"A":"Torque is measured in candela","B":"Torque and candela are unrelated physical quantities.","C":"Torque is directly proportional to candela.","D":"Torque is inversely proportional to candela."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Torque and candela measure completely different physical quantities. Torque (τ) is the rotational equivalent of force: τ = Force × Lever arm. Its SI unit is Newton-meter (N·m). Candela (cd) is the SI unit of luminous intensity (brightness of light).Last updated on 09-03-2026', 0, 0, 0, 1790968053168) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03e8b53126c8babc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Covalent Bond is formed between two _____?', '{"A":"Non-metals","B":"Metalloids","C":"Metals","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A covalent bond is formed between two non-metal atoms. Examples: Molecule formation like H₂O and CO₂.Properties: Generally results in lower melting/boiling points compared to ionic compounds.These atoms achieve stability by sharing one or more pairs of valence electrons to fill their outer shellsLast updated on 09-03-2026', 0, 0, 0, 1790968053206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_250a8d1c626170e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Animals that eat only animals are called _____?', '{"A":"Insectivores","B":"Carnivores","C":"Omnivores","D":"Herbivores"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carnivores are animals that eat only meat, primarily from other animals.Examples of carnivores include lions, tigers, bears, wolves, and sharks.Additional information:Animals that eat plants exclusively are herbivores.Animals that eat both plants and meat are called omnivores.Last verified on 07-03-2026', 0, 0, 0, 1790968053206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b8e71fe63252aa03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Amphibians lay their eggs in/on _____?', '{"A":"Water","B":"Nest","C":"Mountains","D":"Land"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amphibians are animals that live both in water and on land.Most amphibians lay their eggs in water because their eggs do not have a protective shell.Examples of Amphibians: Frog, Toad, Salamander, Newt, CaecilianLast verified on 07-03-2026', 0, 0, 0, 1790968053206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c3afce87ea654457', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Protons and neutrons are collectively known as _____?', '{"A":"Nucleotides","B":"Nucleons","C":"Isotopes","D":"Positrons"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Protons and neutrons form the nucleus of an atom.Together, they are called nucleons because they are nuclear particles.Additional information: Nucleons determine the mass of an atom.Isotopes are atoms of the same element with different number of neutrons.Last verified on 07-03-2026', 0, 0, 0, 1790968053206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d2ca6ffb29e183c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is a fossil fuel? Lava ,Quartz ,Coal', '{"A":"Lava","B":"Quartz","C":"Coal","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Coal is a fossil fuel because it is formed from the remains of dead plantsIt is a major source of energy.Used for electricity generation and industrial processes.Additional information Lava: This is molten rock that has reached the Earth''s surface during a volcanic eruption.Quartz: This is a naturally occurring mineral composed of silicon and oxygen (silica)Last updated on 06-March-2026', 0, 0, 0, 1790968053206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8871cbfd8b4f9ddf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Ribosomes are the centre for _____?', '{"A":"Protein synthesis","B":"Photosynthesis","C":"Respiration","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ribosomes are known as the "protein factories" of the cell.They assemble amino acids into proteins according to mRNA instructions.Last verified on 12-02-2026', 0, 0, 0, 1790968053206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f12ddc6274290dbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following items is the source of "proteins"?', '{"A":"Sugar","B":"Butter","C":"Meat","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Protein foods come from both animal and plant sources.Animal sources include seafood, meat, poultry, and eggs.Plant sources include beans, peas, lentils, nuts, seeds, and soy products.These foods help in body growth and tissue repair.Protein is an essential nutrient.Last verified on 12-02-2026', 0, 0, 0, 1790968053206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0e79699456a9ba24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Enzymes are organic catalysts. They are mainly _______ in nature.', '{"A":"Fats","B":"Proteins","C":"Starch","D":"Carbohydrates"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Enzymes are biological catalysts that speed up chemical reactions in living organisms without being consumed.They are mainly made of proteins.They are highly specific to their reactions.Additional information:Some enzymes require cofactors like vitamins or metal ions to function.Examples: Amylase (breaks starch), Lipase (breaks fats), Protease (breaks proteins).Last verified on 11-02-2026', 0, 0, 0, 1790968053206) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_32e6c7dc5f92dbc3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Spider, ticks, and mites belong to which class?', '{"A":"Insecta","B":"Arachnida","C":"Crustacea","D":"Myriapoda"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Arthropods are divided into different classes based on body structure, legs, and antennae.Spiders, ticks, and mites have eight legs and no antennae, which classifies them differently from insects.These belong to the class Arachnida.Last verified on 11-02-2026', 0, 0, 0, 1790968053242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3b772b2d3cca608b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which resources are non-renewable?', '{"A":"Geo thermal","B":"Fossil fules","C":"Solar","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Non-renewable energy sources:OilNuclear energyPetroleumNatural gas & coalRenewable sources of energy:Solar energyWind energyHydroelectric powerBiomass energyGeothermal energyTidal energyLast verified on 11-02-2026', 0, 0, 0, 1790968053242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a22d425588890ef6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'An ovary after fertilization changes into ______?', '{"A":"Embryo sac","B":"An ovule","C":"Fruit","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After fertilization, the ovary develops into a fruit, enclosing the seeds.Meanwhile, each ovule inside the ovary develops into a seed.Last verified on 11-02-2026', 0, 0, 0, 1790968053242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e8ab1bebc66d3bda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The primary function of the ozone layer is ______?', '{"A":"To protect the Earth from harmful UV rays / It safeguards earth from harmful UV radiation","B":"To trap heat in the atmosphere","C":"To regulate the Earth''s temperature","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ozone layer absorbs and blocks the majority of the Sun’s harmful ultraviolet (UV) radiation.This protection helps prevent skin cancer, cataracts, and damage to ecosystems.Last verified on 09-02-2026', 0, 0, 0, 1790968053242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a68cdfae689f6f29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Scalar quantities have  ______ and suitable unit.', '{"A":"Magnitude","B":"Direction","C":"Both a and b","D":"None of them"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scalar quantities are physical quantities that have only magnitude (amount or size) but no direction.Examples of scalar quantities include:MassTemperatureTimeEnergyDistanceLast verified on 07-02-2026', 0, 0, 0, 1790968053242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5124a93ff97f8cd0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Flame cells are commonly found in _____?', '{"A":"Coelenterate","B":"Plateleminthes (Planaria)","C":"Annelida","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Flame cells are specialized excretory organs in flatworms (Planaria (Platyhelminthes)They remove waste and excess water from the body.Called “flame cells” because cilia inside them flicker like a flame.Part of the protonephridial system in invertebrates.Last verified on 07-02-2026', 0, 0, 0, 1790968053242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e214d3e5591fdbb3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The age of the earth is __________?', '{"A":"3.5 million","B":"4.54 million","C":"4.5 billion","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Earth was formed about 4.5 billion years ago.Additional information:Method Used: Radiometric datingOldest Materials: Meteorites and ancient Earth rocksScientific Consensus: Supported by geology and astronomyLast verified on 16-01-2026', 0, 0, 0, 1790968053242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bff7801ddcf86228', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Crossing over involves exchange of genetic material between ______?', '{"A":"Chromatids of non-homologous chromosomes","B":"Sister chromatids of same chromosome","C":"Non-sister chromatids of homologous chromosomes","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Crossing over is the exchange of genetic material between non-sister chromatids of homologous chromosomes.Occurs during prophase I of meiosis.Increases genetic variation in gametes.Ensures diverse traits in offspring.Essential for evolution and natural selection.Last verified on 06-02-2026', 0, 0, 0, 1790968053242) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a7f6208aec7c2c79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Amount of water vapour in air is regarded as _____?', '{"A":"Humidity","B":"Pressure","C":"Mildness","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Humidity is the amount of water vapor present in the air.It affects weather, climate, and comfort levels.High humidity can make the air feel hotter, low humidity feels drier.Measured using a hygrometer.Important in agriculture, meteorology, and human health.Last verified on 05-02-2026', 0, 0, 0, 1790968053281) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_56bae295842c87ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Grapes cultivation is called _____?', '{"A":"Pomology","B":"Viticulture","C":"Olericulture","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Viticulture specifically refers to grape cultivation.Uses of grapes: Fresh fruit, juice, wine, raisinsAdditional information:Pomology → study and cultivation of fruits in generalOlericulture → cultivation of vegetablesLast verified on 25-01-2026', 0, 0, 0, 1790968053281) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bc7524dd8aea1372', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following gases is commonly used as a refrigerant in domestic refrigerators for cooling?', '{"A":"Freon/ammonia","B":"Neon","C":"Spirit","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Refrigerants are gases used in refrigerators to absorb heat and provide cooling.Freon (CFCs) and ammonia are commonly used in domestic and commercial refrigeration.They evaporate at low temperatures, absorbing heat from the fridge interior.Last verified on 03-02-2026', 0, 0, 0, 1790968053281) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_378086562f56d3ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Chromosomes are made up of _______?', '{"A":"DNA only","B":"DNA and RNA","C":"Proteins only","D":"DNA and Proteins"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chromosomes are made up of:Nucleic acid (DNA or RNA)Proteins (histones and non-histone proteins)A chromosome is made up of proteins and DNA organized into genes.Each cell normally contains 23 pairs of chromosomes.', 0, 0, 0, 1790968053281) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a33ee6836615cfa6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Citrus fruits are considered rich in ______?', '{"A":"Vitamin B","B":"Vitamin C","C":"Vitamin D","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Citrus fruits are rich in Vitamin C, which is essential for immunity.Vitamin C also helps in wound healing, collagen formation, and iron absorption.Citrus fruits include oranges, lemons, limes, and grapefruits.Last verified on 25-01-2026', 0, 0, 0, 1790968053281) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_059fd27bc9ad943f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The macronutrient which regulate opening and closing of stomata and reduce water loss from the leaves?', '{"A":"Potassium","B":"Phosphorus","C":"Sulphur","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Stomata are tiny pores on leaf surfaces that control gas exchange and water loss.Their opening and closing is regulated by certain nutrients.Additional information:Adequate potassium improves drought tolerance and water-use efficiency in crops.Crops like wheat, rice, and sugarcane respond strongly to potassium fertilization.Last verified on 01-02-2026', 0, 0, 0, 1790968053281) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3598abdc743bd493', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which instrument is used to measure the wind direction?', '{"A":"Hygrometer","B":"Anemometer","C":"Galvanometer","D":"Wind Vane"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A wind vane (also called a weather vane) shows the direction from which the wind is blowing.Usually installed on rooftops or meteorological stations.Works with a rotating pointer that aligns with the wind direction.Last verified on 01-02-2026', 0, 0, 0, 1790968053281) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ff4db5f571fc4f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Hydrometer is used to determine _____?', '{"A":"Specific gravity of gases","B":"Specific gravity of liquids","C":"Specific gravity of solids","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A hydrometer is an instrument used to measure the specific gravity of liquids.It works based on the principle of buoyancy.It is widely used to test milk, alcohol, and battery acid.Commonly used in laboratories and industries.Last verified on 30-01-2026', 0, 0, 0, 1790968053281) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c425a4da6d150717', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Rearing of honeybees is?', '{"A":"Mori culture","B":"Sericulture","C":"Apiculture","D":"Silviculture"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Apiculture is the practice of rearing honeybees for honey and wax production.Helps in pollination and increasing crop yields.Honey, beeswax, and propolis are valuable products from apiculture.Additional information:Sericulture → Rearing of silk worms.Silviculture → Cultivation of trees and forests.Last verified on 30-01-2026', 0, 0, 0, 1790968053314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3405e93d9ba340aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Response of plants to touch is called _____?', '{"A":"Mechanoreception","B":"Geotropism","C":"Thigmotropism","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plants can respond to various stimuli like light, gravity, and touch.The response of plants to touch is called thigmotropism.It is commonly seen in climbing plants and vines, which coil around supports.Last verified on 23-01-2026', 0, 0, 0, 1790968053314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e612dd6684c2485', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The first process in Petroleum refinery is known as ____?', '{"A":"Distillation","B":"Improve Octane Number","C":"Reforming","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first process in a petroleum refinery is Distillation.It is also known as Fractional Distillation.This process separates crude oil into various fractions or types of hydrocarbons, based on their boiling points and molecular weights.Additional information:The processes in a petroleum refinery:CrackingReformingIsomerizationHydrotreatingHydrocrackingCatalytic CrackingAlkylationLast verified on 22-01-2026', 0, 0, 0, 1790968053314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_99b9596024ee70ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '"Southern Cross" which is the constellation found in the southern region of the night sky consists of?', '{"A":"3 stars","B":"5 stars","C":"2 stars","D":"6 stars"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Southern Cross is also known as Crux.The constellation primarily consists of four bright stars that form a cross shape.The Four Main Stars:Alpha Crucis (Acrux): The brightest, at the bottom.Beta Crucis (Mimosa): Forms the crossbeam.Gamma Crucis (Gacrux): The northernmost star.Delta Crucis (Imai): Also part of the crossbeam. The Fifth Star:Epsilon Crucis (Ginan): Often added to complete the pattern, as seen on the flags of Australia, Brazil, and New Zealand,', 0, 0, 0, 1790968053314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5789f87adc6a18b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Compounds having the same molecular formula but different structures are called ______?', '{"A":"Isomers","B":"Isotopes","C":"Polymers","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Compounds with the same molecular formula but different arrangements of atoms are called isomers.Isomers can have different chemical and physical properties despite having the same number of atoms.Additional information:Example of isomers: C₂H₆O → Ethanol (CH₃CH₂OH) and Dimethyl ether (CH₃OCH₃)Isomerism is classified into structural isomers and stereoisomers.Last verified on 20-01-2026', 0, 0, 0, 1790968053314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3c6d0cbffb0f3ded', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Sugar present in DNA is _____?', '{"A":"Deoxyribose","B":"Glucose","C":"Fructose","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DNA (Deoxyribonucleic Acid) contains the sugar deoxyribose, which is a five-carbon sugar.It forms the backbone of the DNA molecule along with phosphate groups.Additional information:Sugars in nucleic acids:DNA – DeoxyriboseRNA – RiboseGlucose – energy source in cellsFructose – sugar in fruitsGalactose – sugar in milkLast verified on 19-01-2026', 0, 0, 0, 1790968053314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_18166a0613dbfb48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'When HIV identified?', '{"A":"1985","B":"1988","C":"1983","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HIV (Human Immunodeficiency Virus) was first identified in 20 May 1983By researchers Luc Montagnier and Françoise Barré-Sinoussi in France.Their discovery linked HIV to AIDS, leading to significant advancements in understanding and managing the disease.', 0, 0, 0, 1790968053314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4d95e222776a897d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is H5N1?', '{"A":"Virus","B":"Disease","C":"Bacteria","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation H5N1 is a type of influenza virusCauses a highly infectiousAlso known as avian influenza.Occurs mainly in birds, is highly contagious among birds, and can be deadly, especially in domestic poultry', 0, 0, 0, 1790968053314) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bdaf4b5f4ffd1d60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The atmospheric layer in which we live is called the?', '{"A":"Stratosphere","B":"Troposphere","C":"Thermosphere","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The troposphere is the lowest layer of Earth’s atmosphere.It extends from the Earth’s surface up to about 8–15 km (varies with latitude).All weather phenomena like rain, clouds, and storms occur in this layer.It contains approximately 75–80% of the atmosphere’s mass.The temperature in the troposphere decreases with altitude.', 0, 0, 0, 1790968053346) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cdbb1541562f2f68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Sunlight is composed of ?', '{"A":"Three colors","B":"Five colors","C":"Seven colors","D":"Ten colors"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sunlight is composed of a spectrum of light A spectrum revealed by Isaac Newton using a prismThat includes seven colors, which are (ROYGBIV)RedOrangeYellowGreenBlueIndigoViolet', 0, 0, 0, 1790968053346) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b966ca16a0ba0eaf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is meant by Etymology?', '{"A":"The study of the names given to insects","B":"The study of the origins of words and how they have changed over time","C":"The study of language politeness","D":"The study of words which sound similar to one another"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Etymology is the study of the origin of words. At its most basic level, etymology is the study of a word''s historyEtymology involves tracing the history, evolution, and origin of words.', 0, 0, 0, 1790968053346) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2c596f48e253b87c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Sedimentary rocks are _______?', '{"A":"Porous","B":"Hard","C":"Rough","D":"Brittle"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sedimentary rocks are rocks formed by the deposition and compression of sediments over time.Also called stratified rocks because they are formed in layers (strata).Often porous, meaning they have small holes (pores) that can contain water or other fluids.Additional information:Cover about 75% of the Earth''s surface.Examples: Sandstone, Limestone, Shale.Usually softer and less dense than igneous rocks.Last verified on 17-01-2026', 0, 0, 0, 1790968053346) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64da831292970abf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The yeast used in baking bread is a?', '{"A":"Fungus","B":"Plant","C":"Seed","D":"Bacteria"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The yeast used in baking bread is a single-celled fungus, Specifically, a strain of Saccharomyces cerevisiae, It''s a living microorganism that ferments sugars in dough, producing gases that cause bread to expand.', 0, 0, 0, 1790968053346) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_82ffe1873a3ec5e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Famous social website Facebook was founded by ____?', '{"A":"Elon Musk","B":"Steve Jobs","C":"Bill Gates","D":"Mark Zekerburg"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Founder: Mark ZuckerbergFounded in: February 4, 2004Headquarters: Menlo Park, California, USAUsers (2023): Over 3 billion monthly active usersParent Company: Meta Platforms Inc.Last verified on 16-01-2026', 0, 0, 0, 1790968053346) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ef9addd8e9569593', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Breakbone fever is communicated by a mosquitos; it is another name of ____?', '{"A":"Malaria","B":"Epilepsy","C":"Dengue","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Breakbone fever is another name for Dengue.It is a viral disease transmitted by Aedes mosquitoes.It causing severe joint and muscle pain.', 0, 0, 0, 1790968053346) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6f25e2207dd07a9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Scientist Chadwick in 1932 discovered?', '{"A":"Proton","B":"Neutron","C":"Electron","D":"Positron"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation James Chadwick is known for his discovery of the neutron in 1932. Proton: Protons were discovered by Ernest Rutherford, before neutrons.Electron: Electrons were discovered by J.J. Thomson, much earlier than protons or neutrons.Positron: A positron is the antiparticle of an electron, and it was discovered by Carl Anderson in 1932.', 0, 0, 0, 1790968053346) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_29bb8d1fae618e24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Amnesia is related to ______?', '{"A":"Loss of sight","B":"Loss of hearing","C":"Loss of memory","D":"Sleeping sickness"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amnesia is a common term used to describe memory loss.Loss can be temporary or permanent, but "amnesia" usually refers to temporary diversity.Causes include head and brain injuries, certain medications, alcohol, traumatic events, or conditions such as Alzheimer''s disease.', 0, 0, 0, 1790968053377) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a681cb8660b4f5c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'To every action there is always an equal and opposite reaction. This is the statement of ____?', '{"A":"Newton first law of motion","B":"Newtons second law of motion","C":"Newton’s Third Law of Motion","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The statement "To every action there is always an equal and opposite reaction" is Newton''s Third Law of Motion. This law states that for every interaction between two objects, a pair of forces is produced—these forces are equal in magnitude and opposite in direction, acting on the interacting objects.', 0, 0, 0, 1790968053377) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_70b8a652c172777e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the Diameter of Earth?', '{"A":"15742  km","B":"14742 km","C":"13742 km","D":"12756 km"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Earth is the third planet from the Sun and the only astronomical object known to harbor life.Radius: 6,371 kmMass: 5.972 × 10^24 kgDistance from Sun: 149.6 million kmDensity: 5.51 g/cm³Orbital period: 365 days', 0, 0, 0, 1790968053377) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fb6bfa0c6013d33e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Nuclear fission is?', '{"A":"Joining nuclei","B":"Splitting heavy nucleus into smaller nuclei","C":"Neutron absorption","D":"None  of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nuclear fission is the splitting a heavy nucleus into smaller nuclei. The word "fission" means splitting, so in nuclear fission, a large, unstable nucleus is split apart into smaller nuclei, releasing energy in the process.', 0, 0, 0, 1790968053377) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66a496325a1399ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Steel is more elastic than Rubber because ______?', '{"A":"Its density is high","B":"Ratio of stress to strain is more","C":"Ratio of stress to strain is less","D":"It is a metal"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Steel is more elastic than rubber because the ratio of stress to strain is more for steel.This indicates that steel deforms less under the same amount of stress compared to rubber, making it more elastic.', 0, 0, 0, 1790968053377) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2d5a8a62281ee50b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is the most elastic material? Steel, Rubber, Sponge, Glass', '{"A":"Steel","B":"Rubber","C":"Glass","D":"Sponge"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Steel is most elastic among the rubber, steel, glass and sponge. Steel having the most steep linear stress-strain curve among all.A stiffer material will have a higher elastic modulus.', 0, 0, 0, 1790968053377) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_284b355cfaaf12a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The triple point of water is _____?', '{"A":"373.16k","B":"273.16k","C":"285.16k","D":"300.16k"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The triple point of water is the unique temperature and pressure at which water coexists in all three phases — solid, liquid, and gas — in equilibrium.Temperature: 273.16 KelvinThis is used as a fundamental fixed point in defining the Kelvin temperature scale.', 0, 0, 0, 1790968053377) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c652a1db6746b94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Scientific name of Human (Man) is ____?', '{"A":"Homo sapiens","B":"Mono sapiens","C":"Bio sapiens","D":"Cosmopolitan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Homo sapiens is the scientific (binomial) name of modern humans.It means "wise man" in Latin, classified under genus Homo and species sapiens.', 0, 0, 0, 1790968053377) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5825d88626d6a1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The least count of Vernier caliper is _____?', '{"A":"0.1cm","B":"0.2mm","C":"0.01mm","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The least count of a Vernier caliper is 0.02mm.It is the smallest measurement that can be accurately read using the instrument.It is derived from the difference between one main scale reading and one Vernier scale reading.It is commonly used to accurately measure outside diameters of shafts, thicknesses of various parts, diameters of holes or rings, internal dimensions of hollow jobs, and depths of holes or steps.', 0, 0, 0, 1790968053409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a616cffa9af0c4a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The tibia and fibula are bones found in the _____?', '{"A":"Leg","B":"Face","C":"Arm","D":"Skull"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The tibia (shin bone) and fibula are the two long bones of the lower leg.They run parallel to each other between the knee and the ankle.', 0, 0, 0, 1790968053409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e87238a3f418a7a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Wind always blows from area of ______?', '{"A":"High pressure to low pressure","B":"Low pressure to high pressure","C":"Only low pressure","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wind blows from areas of high pressure to areas of low pressure.This is because air molecules move from areas of higher concentration (high pressure) to areas of lower concentration (low pressure) to equalize the pressure difference.This movement of air is what we feel as wind.', 0, 0, 0, 1790968053409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_74448c7dbe591f75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'An imaginary line that divides the globe into two halves is called _____?', '{"A":"Equator","B":"Tropic","C":"Meridian","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Equator is an imaginary line that divides the Earth into the Northern and Southern Hemispheres.It lies equidistant from the North and South Poles.', 0, 0, 0, 1790968053409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_567489963fa9515e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who invented dynamite?', '{"A":"Dr. Alfred B. Nobel","B":"H. W. Seeley","C":"Lionel Lukin","D":"Roger Bacon"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alfred Nobel was a chemist from Sweden. Dynamite was invented by Alfred Nobel in the 1860s.He is also the founder of the Nobel PrizeHe also invented Nitro-glycerine in 1875.Alfred Nobel Born: October 21, 1833, Stockholm, SwedenAlfred Nobel Died: on December 10, 1896, in Sanremo, ItalyAlfred Nobel Full name: Alfred Bernhard NobelAdditional InformationThe first Noble Prize was awarded on 10th December 1901The first Noble Prize was awarded in Stockholm, Sweden.', 0, 0, 0, 1790968053409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a607eb65991561a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Water has maximum density at _____?', '{"A":"2°C","B":"3°C","C":"4°C","D":"5°C"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Water has maximum density at 4°C.When Water is in its Solid form (Ice) below 0°C.', 0, 0, 0, 1790968053409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6de678e85b705574', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who was the first to invent Airplane?', '{"A":"Wright Brothers","B":"Aero Brothers","C":"William Brothers","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Wright Brothers, Orville and Wilbur, invented and flew the first successful airplane.This historic flight took place on December 17, 1903, in Kitty Hawk, North Carolina.', 0, 0, 0, 1790968053409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_579bc4ed208fc0a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In which object, form sharp and dark shadows?', '{"A":"Transparent","B":"Translucent","C":"Opaque","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Opaque objects form sharp and dark shadows because they block all light from passing through, creating a clear and defined shadow.', 0, 0, 0, 1790968053409) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b225a7631238b20f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The melting of ice is an example of ______?', '{"A":"Chemical change","B":"Permanent change","C":"Physical change","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Melting of ice changes only the state from solid to liquid.No new substance is formed, so it''s a physical and reversible change.', 0, 0, 0, 1790968053443) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da796562861fd5d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Temporary hardness of water is due to the presence of dissolved salts of _______?', '{"A":"Ca(NO₂)","B":"CaSO₄","C":"Ca(HCO₃)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Temporary hardness of water is caused by dissolved bicarbonates of calcium and magnesium.It can be removed by boiling, which decomposes Ca(HCO₃)₂ into insoluble carbonate.', 0, 0, 0, 1790968053443) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_359c9688a84b31e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following mineral is used in cement industry and plaster of Paris?', '{"A":"Marble","B":"China clay","C":"Fire clay","D":"Gypsum"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plaster of Paris changes into gypsum on mixing with water It is commonly called P.O.P. is calcium sulfate hemihydrate.The chemical formula of plaster of Paris is CaSO4.1/2 H2OCrystals of gypsum are produced when Plaster of Paris is mixed with water Gypsum is calcium sulfate dihydrate and a mineral used in cement manufacturing.It helps in controlling the rate of hardening of the cement.', 0, 0, 0, 1790968053443) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_14d6f8e5c7657c41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Electrical charge is measured in unit of _________?', '{"A":"Ohm","B":"Coloumb","C":"Ampere","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SI unit of electric charge is the coulomb, represented by the symbol C.One coulomb is the amount of charge that passes through a conductor carrying one ampere of current for one second.It''s also equal to the charge of about 6.24 quintillion electrons or protons.', 0, 0, 0, 1790968053443) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_857906a483a7e1ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Brass is an alloy of ______?', '{"A":"Zinc and copper","B":"Zinc and iron","C":"Copper and gold","D":"Zinc and gold"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Brass is an alloy made by combining copper and zinc.It is commonly used for decorative items, musical instruments, and fittings due to its strength and resistance to corrosion.Bronze is an alloy consisting primarily of copper, commonly with about 12-12.5% tin.', 0, 0, 0, 1790968053443) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f33adc35383fca65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'CNG stands for _______?', '{"A":"Composed Natural Gas","B":"Compressed Neutral Gas","C":"Compressed Natural Gas","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CNG stands for Compressed Natural GasMethane is the main component of CNG the modern use of CNG as a fuel source began in the 1930s, American physicist Dr. J.P. Farley discovered that natural gas could be compressed to a high-pressure natural gas became a transport fuel during the First World War', 0, 0, 0, 1790968053443) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_00d9e7005f6666d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A person who studies rocks and soils is called _____?', '{"A":"Geologist","B":"Archaeologist","C":"Geophysicist","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geologists are scientists who study a planet''s solid features, like soil, rocks, and minerals.while The study of the general physical characteristics of rocks is called Lithologypetrology is a branch of geology that is concerned with the structure, composition, and distribution of rocks.petrogenesis deal with the study of the origin of rock******ND30-12-2022', 0, 0, 0, 1790968053443) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45094647e8e93a4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The study related to animals is called:', '{"A":"Zoology","B":"Botany","C":"Chemistry","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zoology, branch of biology that studies the members of the animal kingdom and animal life in general.', 0, 0, 0, 1790968053443) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_559c2d7ec27170d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which animal is known as the "King of the Jungle"?', '{"A":"Lion","B":"Bear","C":"Tiger","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The lion is often called the "King of the Jungle."Due to its powerful presence, strength, and symbolic leadership.However, it primarily lives in grasslands and savannas, not jungles.', 0, 0, 0, 1790968053476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_57be2ae4d9ad2a33', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The rod cells of retina are responsible for vision in?', '{"A":"Bright light","B":"Dim light","C":"Summary atmosphere","D":"Shiny atmosphere"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The rod cells of the retina are responsible for vision in dim light or at night (scotopic vision), Providing black and white, low-resolution vision, and contributing to peripheral vision. They are more numerous and more sensitive to light than cone cells, but they cannot detect color or fine details.', 0, 0, 0, 1790968053476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75de429291d0efbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following uses its wings to swim in the water? Parrot, Crow, Duck, Penguin', '{"A":"Parrot","B":"Crow","C":"Duck","D":"Penguin"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Penguins are the birds which do not fly but swim to go from one place to another. Penguins have flippers which help them swim underwater.Penguin means پنکھ دار بحری پرندہ', 0, 0, 0, 1790968053476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b1392691b83e045b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following organisms are invertebrate? Birds, Amphibians, Reptiles, Worms', '{"A":"Birds","B":"Amphibians","C":"Reptiles","D":"Worms"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An invertebrate is an animal without a backbone. Worms, like earthworms, are classified as invertebrates. They lack a backbone and are found in various environments.', 0, 0, 0, 1790968053476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_78847fd5cc488a7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following animal is called the “ship of the desert”?', '{"A":"Lion","B":"Camel","C":"Horse","D":"Elephant"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The camel is called the “ship of the desert” Because it travels easily on sand.It can survive long periods without water, making it ideal for desert transport.Last updated 25-07-2026 by NA', 0, 0, 0, 1790968053476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f82beec1cc76dd8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The freezing point of water on a centigrade scale is?', '{"A":"0°C","B":"1°C","C":"-1°C","D":"5°C"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The freezing point of water is 0°C (zero degrees Centigrade). The boiling point of water on the Centigrade scale (also known as the Celsius scale) 100°C (one hundred degrees Centigrade).', 0, 0, 0, 1790968053476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_efe9eb4031587ac6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Air is the example of a/an ______?', '{"A":"Element","B":"Solution","C":"Mixture","D":"Compound"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Air is a mixture of different gases.Primarily consisting of nitrogen (78%), oxygen (21%), and trace amounts of other gases.', 0, 0, 0, 1790968053476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6144679ae35ad94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'How many Muscles are there in the human body?', '{"A":"638","B":"641","C":"639","D":"637"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are around 639 skeletal muscles.The three main types of muscle include skeletal, smooth, and cardiac.The sartorius muscle is a thin, long, superficial muscle in the anterior compartment of the thigh.', 0, 0, 0, 1790968053476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_746d67e2d061e34b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The breathing centre of human body is?', '{"A":"Lungs","B":"Ears","C":"Nose","D":"Brain"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The breathing centre of human body is lungs.Lungs are two soft spongy large balloon like organ located in the chest.The delicate lungs are protected by a cage of bones. This cage is called the ribcage.', 0, 0, 0, 1790968053511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d7db8298137164bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is used in semiconductors?', '{"A":"Silicon","B":"Aluminum","C":"Copper","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Silicon is a metalloid with properties ideal for controlling electrical current.It''s the most widely used material in semiconductor devices like transistors and chips.', 0, 0, 0, 1790968053511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_02e84495936cb591', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following Muslim Scientists discovered the radius of the earth?', '{"A":"Abu Rayhan A-Biruni","B":"Ibn-ul-Haitham","C":"Jabir Bin Halyan","D":"Muhammad Bin Zakariya"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Calculating the radius of the earth over a thousand years ago required a lot of imagination. The 10th-century Persian mathematician Abu Rayhan al-Biruni used simple trigonometric results to estimate the radius and circumference of the EarthND_16_7_2023', 0, 0, 0, 1790968053511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc239fba6a8b459d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one of the following is non-biodegradable material? Plastic, Manure, Wood, Cotton', '{"A":"Plastic","B":"Manure","C":"Wood","D":"Cotton"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plastic is a synthetic material that is resistant to decomposition and can take hundreds or even thousands of years to break down.It is a non-biodegradable material.The examples of non-biodegradable materials such as:Inorganic materials (glass, ceramics, heavy metals)Synthetic materials (styrofoam, plastic bags, other plastic things)Hazardous materials (detergents, toxic chemicals)Industrial waste (empty cans, electricity wires, fused bulbs, broken machine parts)', 0, 0, 0, 1790968053511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_79193a0f97625b7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Animals that eat both plants and animals are known as?', '{"A":"Omnivores","B":"Herbivores","C":"Carnivores","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Omnivores are animals that eat both plants and animals.They have adaptations that allow them to digest and extract nutrients from a wide variety of food sources, including fruits, leaves, insects, small animals, and even carrion.Examples of omnivores include humans, bears, pigs, chimpanzees, and raccoons.', 0, 0, 0, 1790968053511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25025fbc0531bfc5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'LPG stands for _____?', '{"A":"Liquefied Pressure Gass","B":"Liquefied Per Gram","C":"Liquefied Petroleum Gas","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation LPG stand for Liquefied Petroleum Gas*****In order to supply fuel efficiently to the populace, we have four LPG Storage and Bottling Plants, one each in Karachi, Lahore, Dhurnal, and Akora Khattak.LPG is used as a fuel gas in heating appliances, cooking equipment, and vehiclesLPG is prepared by refining petroleum or "wet" natural gas, LPG was first produced in 1910 by Walter O. Snelling.', 0, 0, 0, 1790968053511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e27cbc98c036d314', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'RNA stands for ______?', '{"A":"Ribonucleic Acid","B":"Ready Nucleic Acid","C":"Ribo Nuclear Acid","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RNA stands for Ribonucleic Acid, a molecule essential for protein synthesis and gene expression.It is composed of ribose sugar, phosphate, and nitrogenous bases — hence the name ribo + nucleic acid.', 0, 0, 0, 1790968053511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1034bd2f1e9299b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '_____ waves used by the Radars.', '{"A":"Sound","B":"Light","C":"Radio","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RADAR is an acronym for Radio Detection and Ranging.The system works by transmitting high-frequency radio waves, or microwaves (which are a type of radio wave), toward an object.The waves bounce off the object, and a receiver in the radar system detects the reflected energy, known as an echo.By measuring the time delay between sending and receiving the signal, the system can calculate the distance and velocity of the object.', 0, 0, 0, 1790968053511) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_33905c6be9ae26ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which uranium atoms undergo fission readily?', '{"A":"U²³⁶","B":"U²³⁸","C":"U²³⁵","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Uranium-235 (U²³⁵) is a fissile isotope, meaning it readily undergoes nuclear fission when struck by a neutron.It is commonly used in nuclear reactors and atomic bombs for this reason.', 0, 0, 0, 1790968053547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_efb106898d79f8b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following has the highest surface tension?', '{"A":"Glycerol in water","B":"Detergent in water","C":"Soap in water","D":"Water"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surface Tension: "The property of the surface of a liquid that allows it to resist an external force, due to the cohesive nature of its molecules."', 0, 0, 0, 1790968053547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_966844509b6d3308', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Magnesium keep on burning in _____?', '{"A":"N₂ as will as CO₂","B":"N₂","C":"CO₂","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Burning magnesium reacts with N₂ to form magnesium nitride (Mg₃N₂).It also burns in CO₂, breaking it down to MgO and C.', 0, 0, 0, 1790968053547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3995ef9932d06a56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which food item contains 360 calories per grams and is high in carbohydrates?', '{"A":"Rice","B":"Eggs","C":"Butter","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rice is rich in carbohydrates and provides about 360 calories per 100 grams.It is a major energy source in diets around the world due to its high carbohydrate content.', 0, 0, 0, 1790968053547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4fb4f2a9ad03351c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The metal commonly used in storage batteries ____?', '{"A":"Lead","B":"Copper","C":"Iron","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A lead-acid battery consists of a negative electrode made of spongy or porous lead. The lead is porous to facilitate the formation and dissolution of lead.', 0, 0, 0, 1790968053547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7e53af05d70cf518', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The material used for bleaching paper pulp is ____?', '{"A":"Lime","B":"Sodium","C":"Caustic Soda","D":"Sodium hypochlorite"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The material used for bleaching paper pulp is sodium hypochlorite.It acts as an effective bleaching agent.It helping to remove color and impurities from the pulp.', 0, 0, 0, 1790968053547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_89debf02ccbe8ac4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Colour of the plants is green due to the presence of _______?', '{"A":"Carbon dioxide","B":"Chlorophyll","C":"Urea","D":"Oxygen"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Colour of the plants is green due to the presence of Chlorophyll۔Chlorophyll absorbs certain wavelengths of light within the visible light spectrum.Chlorophyll is the green color pigment which absorbs wavelength from sunlight.Since the synthesis of food occurs in the presence of sunlight, it is called photosynthesis.', 0, 0, 0, 1790968053547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c4b339069b1fcda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the below particle has a negative charge?', '{"A":"Proton","B":"Electron","C":"Neutron","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The charges of Proton, Electron, Neutron respectively are:Proton: Positive charge (+1)Electron: Negative charge (-1)Neutron: Neutral charge (0)', 0, 0, 0, 1790968053547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75c94853f4ad07ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is a neutral particle?', '{"A":"Alpha particle","B":"Neutron","C":"Electron","D":"Proton"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The neutron is a neutral particle, which is stable only in the confines of the nucleus of the atom.', 0, 0, 0, 1790968053586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bc24a1a2c18adccb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'At which place the motion of a simple pendulum will be slowest?', '{"A":"Karachi","B":"K2","C":"Murree","D":"Lahore"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The slower motion of a pendulum is due to a longer period, which is related to the weaker gravitational force at higher altitudesK2, being a very high mountain, has a significantly lower value of acceleration Due to gravity, cities like Karachi, Murree, or Lahore result in a slower pendulum motion.', 0, 0, 0, 1790968053586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c6d18a08034fcfc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Fishes breathe with their _____?', '{"A":"Lungs","B":"Gills","C":"Skin","D":"Nostrils"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fishes breathe with their Gills.Gills are feathery organs full of blood vessels. A fish breathes by taking water into its mouth and forcing it out through the gill passagesمچھلی اپنے منہ میں پانی لے کر سانس لیتی ہے اور اسے گل کے راستے سے باہر نکالتی ہے۔', 0, 0, 0, 1790968053586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9bdda7ba0f9cd270', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '1KWh = _______J?', '{"A":"3.6 MJ","B":"3.6 GJ","C":"3.63J","D":"3.6KJ"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 kilowatt-hour (kWh) is equivalent to 3.6 million joules (MJ).As it represents the energy used when 1 kilowatt of power is consumed for 1 hour.1 kWh = 3.6 × 10⁶ J (3.6 MJ)1 J = 1 watt-second1 MJ = 10⁶ J', 0, 0, 0, 1790968053586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fcbcddd73b7db737', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the another name for Baking Soda?', '{"A":"Sodium chloride","B":"Potassium nitrate","C":"Sodium bicarbonate","D":"Calcium carbonate"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The chemical formula of baking soda is NaHCO₃, which stands for sodium bicarbonate.The chemical name of baking soda is sodium hydrogen carbonate or sodium bicarbonate (NaHCO3).Sodium bicarbonate is non flammableBaking soda is basic in nature.', 0, 0, 0, 1790968053586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_56e0d790d37beb8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Ammonia Solvay process is used for the manufacture of _____?', '{"A":"Potash alum","B":"Caustic soda","C":"Washing soda","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Solvay process is an industrial method for producing sodium carbonate (washing soda).It involves ammonia, carbon dioxide, and sodium chloride as key reactants.', 0, 0, 0, 1790968053586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5a99e6c82920b7d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is a man-made substance?', '{"A":"Rubber","B":"Plastic","C":"Steel","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plastic is a synthetic material made from polymers.It primarily derived from petrochemicals.Plastic is entirely man-made.It is widely used due to its versatility and durability.', 0, 0, 0, 1790968053586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7a369338a2ec6b5e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'It is difficult to cook on mountains because of?', '{"A":"High atmospheric pressure","B":"Low atmospheric pressure","C":"Low temperature","D":"Lack of oxygen"}', 'B', NULL, 0, 0, 0, 1790968053586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b15e1c43c64480e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following has a coordinate bond?', '{"A":"NH₃BF₃","B":"H₂O","C":"CaO","D":"NaCl"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In NH₃BF₃, nitrogen donates a lone pair of electrons to boron.It forming a coordinate bond, where both electrons in the bond come from the same atom.', 0, 0, 0, 1790968053622) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2b3d8fa6160dffc1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The sweetest sugar is ______?', '{"A":"Glucose","B":"Sucrose","C":"Fructose","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fructose is the sweetest natural sugar.It is found in fruits, honey, and high-fructose corn syrup.', 0, 0, 0, 1790968053622) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9c3d9cf697a73950', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Hydrocarbons which burn with smoky flame are called?', '{"A":"Aliphatic","B":"Alicyclic","C":"Aromatic","D":"Aldehyde"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aromatic hydrocarbons contain a high carbon-to-hydrogen ratio, leading to incomplete combustion.This causes them to burn with a smoky flame.', 0, 0, 0, 1790968053622) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e449a3db7da0677d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'During cellular respiration NADH2 produces ______?', '{"A":"5 ATP","B":"2 ATP","C":"3 ATP","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Each NADH₂ molecule, when oxidized in the electron transport chain, yields about 3 ATP.This is part of oxidative phosphorylation during cellular respiration.', 0, 0, 0, 1790968053622) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e8882ae86c884c5d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Pneumonia is caused by inflammation of', '{"A":"Lungs","B":"Liver","C":"brain","D":"legs"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pneumonia is a form of acute respiratory infection that affects the lungsThe lungs are made up of small sacs called alveoli, which fill with air when a healthy person breathes***ND2-2-2023', 0, 0, 0, 1790968053622) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b60bd61450419c49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which cloud is likely to cause heavy rainfall?', '{"A":"Strato-cumulus","B":"Nimbo-stratus","C":"Cirro cumulus","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nimbo-stratus clouds are most likely to cause heavy rainfall.These are thick, dark, and low-lying clouds that often cover the sky. They are associated with continuous, steady precipitation.', 0, 0, 0, 1790968053622) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3e15b53fea59275f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The axis of rotation of the Earth is tilted at an angel of?', '{"A":"23.5°","B":"23.0°","C":"23.08°","D":"24.30°"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Earth is tilted at an angle of 23.5 degrees.This tilt is responsible for the changing of the seasons and the difference in the amount of sunlight reaching a given point on the surface during the course of a year.The tilt varies between 22.1 and 24.5 degrees in a cycle that averages about 40,000 years.', 0, 0, 0, 1790968053622) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e330f034122cb2ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Lunar eclipse does not occur every month because _____?', '{"A":"The orbits of the Earth and the Moon are slightly tilted relative to each other.","B":"The moon''s orbit is not all the time in the same plane as the earth.","C":"The sun''s orbit is not always at the same plane as the moon.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Moon’s orbit is tilted about 5° to the Earth’s orbital plane (the ecliptic).Because of this tilt, the Earth, Moon, and Sun do not align perfectly every month — so a lunar eclipse happens only occasionally.', 0, 0, 0, 1790968053622) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ff1e7c355f5017f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'LPG mainly contains _____?', '{"A":"Methane, Ethane and Hexane","B":"Methane, Butane and Propane","C":"Methane, Hexane and Nonane","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Liquefied Petroleum Gas (LPG) is primarily a mixture of propane (C3H8) and butane (C4H10).These gases are compressed and liquefied for easy storage and transport.', 0, 0, 0, 1790968053654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b3435b38b1e45e3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who was the first to measure the earth''s radius?', '{"A":"Eratosthenes","B":"Copernicus","C":"Al-Beruni","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Eratosthenes was the first person to calculate the Earth''s radius in the 3rd century B.C.E.He was a Greek astronomer who lived in Alexandria, Egypt.Eratosthenes''s calculation of the Earth''s radius was 6,366 km, which is close to the modern value of 6,378 km.', 0, 0, 0, 1790968053654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2e60f68c74c6d1b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Soap and detergents remove the dirt from cloths due to ______?', '{"A":"Capillary action","B":"Osmosis","C":"Diffusion","D":"Lowering of inter-facial tension"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When the soap is in the form of micelles then it has the ability to clean the oily dirt which gets accumulated at the centre. These micelles remain as colloidal solutions. Therefore, the dirt from the cloth is easily washed away.', 0, 0, 0, 1790968053654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_acb5b8d250fe979f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following vitamins serves as a hormone precursor?', '{"A":"Vitamin A","B":"Vitamin C","C":"Vitamin D","D":"Vitamin K"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin D serves as a hormone precursor, as it is converted into a hormone in the body.Cholesterol also serves as a precursor of vitamin D and steroid hormones.', 0, 0, 0, 1790968053654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_412599ee2e4d2143', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'RADAR stands for ______?', '{"A":"Radio Adaptor Detection and Ranging","B":"Radio Diagnosing and Ranging","C":"Radio Detection and Ranging","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term RADAR was coined in 1940 by the United States Navy It is an acronym for "radio detection and ranging".It is a radiodetermination method used to detect and track aircraft, ships, spacecraft, guided missiles, motor vehicles, map weather formations, and terrain.', 0, 0, 0, 1790968053654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_72f96a7aa9140a93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one is a start codon? AUG, UAA, UAU, UUC', '{"A":"AUG","B":"UAA","C":"UAU","D":"UUC"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AUG is the start codon in mRNA that signals the beginning of protein synthesis.It also codes for the amino acid methionine.', 0, 0, 0, 1790968053654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a7bbc67c7bb69ca2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Botanical name for potato is?', '{"A":"Solanum melongena","B":"Cassia fistula","C":"Solanum tubersum","D":"Zea mays"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The following table provides the botanical names for a variety of familiar plants: Rice : Oryza sativaApple : Malus domesticaCarrot : Daucus carotaCoconut : Cocos nuciferaCucumber : Cucumis sativusGinger : Zingiber officinaleMango : Mangifera indicaOak tree : QuercusOnion : Allium cepaPotato : Solanum tuberosumWheat : Triticum aestivumRose : RosaSunflower : Helianthus annuusTomato : Solanum lycopersicum', 0, 0, 0, 1790968053654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_647d3d579b18d4fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following phyla of animals is/are exclusively marine?', '{"A":"Echinodermata","B":"Porifera","C":"Mollusca","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Echinodermata (e.g., starfish, sea urchins) is the only phylum that is exclusively marine with no freshwater or terrestrial species.Porifera (sponges) and Mollusca (snails, octopuses) include both marine and freshwater species.', 0, 0, 0, 1790968053654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fee16014fd013827', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What does Mycology study?', '{"A":"Insects","B":"Fungus (Fungi)","C":"Sound","D":"Minerals"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mycology studies fungus.It is the branch of biology focused on the study of fungi.Including their genetic and biochemical properties.', 0, 0, 0, 1790968053686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5148cabaa927c4f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The shortest distance between two points is called?', '{"A":"Distance","B":"Speed","C":"Displacement","D":"Velocity"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shortest distance between two points is called displacement.Displacement is a measure of the straight-line distance between two points. It is a vector quantity.Key Point: The longest distance between two points is called the circumference (if the points are on a circle) or a diagonal (if the points are on a polygon or a rectangle).', 0, 0, 0, 1790968053686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ffd9e3f5643ea099', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Special theory of relativity was given by ___?', '{"A":"Newton","B":"Albert Einstein","C":"Darwan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The theory of relativity usually encompasses two interrelated theories by Albert Einstein: They were proposed and published in 1905 and 1915E =mc2 C in this equation, the velocity of light', 0, 0, 0, 1790968053686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cf6ad58877b38184', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The clouds float in atmosphere because of _____?', '{"A":"Low Temperature","B":"Low Velocity","C":"Low Pressure","D":"Less Density"}', 'D', NULL, 0, 0, 0, 1790968053686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_61af90faf506f70a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Bronze is an alloy of _____?', '{"A":"Copper and Nikal","B":"Copper and Tin","C":"Copper and Steel","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bronze is mainly made of copper with about 12–12.5% tin as the primary additive.It is stronger and harder than pure copper, making it useful for tools, weapons, and sculptures.', 0, 0, 0, 1790968053686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e6c435ff05880dee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is Dry Ice?', '{"A":"Solid oxygen","B":"Solid Nitrogen","C":"Solid Carbon dioxide","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dry ice is a solid form of carbon dioxide...."Dry ice" is solid, frozen carbon dioxide, which is sublimated at a chilly -78.5 °C (-109.3°F).Dry ice is used primarily as a cooling agent.Dry ice does not melt into a liquid when heated instead, it changes directly into a gas.ND16-8-2023', 0, 0, 0, 1790968053686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2e1a97e29c409d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The second major form of Hepatitis is _____?', '{"A":"Hepatitis C","B":"Hepatitis A","C":"Hepatitis B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hepatitis B is the second major type of viral hepatitis after Hepatitis A.It affects the liver.It can lead to chronic infection and cirrhosis.', 0, 0, 0, 1790968053686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ad1a3609182af1c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is SI unit of Torque (Moment)?', '{"A":"Nm","B":"N/m","C":"N","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Unit of torque: newton metre (N m) Torque is a vector quantity.The direction of the torque vector depends on the direction of the force on the axis', 0, 0, 0, 1790968053686) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7dd3b07e7bffe8cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The longest day on earth is observed on?', '{"A":"21 May","B":"20 July","C":"21 June","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Summer Solstice happens once every year. Summer Solstice is on 21 June, also known as the longest day of the year.22 December night is the longest night of the year.21 June day the longest day of the year.', 0, 0, 0, 1790968053715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af9d783bf8a469b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The percentage of water in whole Milk is about _____?', '{"A":"70%","B":"87%","C":"75%","D":"90%"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Milk is approximately 87% water and 13% solids.The solids include fats, proteins, vitamins, and minerals.', 0, 0, 0, 1790968053715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5ce7456860a3a71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The most important stimulus for tea leaves is _____?', '{"A":"Brucine","B":"Caffeine","C":"Phyenylalanine","D":"Theine"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Caffeine occurs naturally in the tea plant, Camellia sinensis, so all brewed tea contains some caffeine. Tea leaves contain 3.5% caffeine, while Coffee beans have 1.1–2.2%.', 0, 0, 0, 1790968053715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2de1f2544f8e3c3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which method is used to separate components of mixture?', '{"A":"Filtration","B":"Sublimation","C":"Distillation","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The homogeneous mixture of two or more than two components is called Solution.Filtration separates solids from liquids using a filter.Sublimation & Distillation separate components based on phase changes (solid to gas & liquid boiling points).', 0, 0, 0, 1790968053715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8f317d6b3bf8dc3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Cooking oil can be converted into vegetable ghee by the process of ____?', '{"A":"Hydrogenation","B":"Oxidation","C":"Distillation","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hydrogenation is a chemical process that adds hydrogen to unsaturated fats in cooking oil, solidifying it into ghee.This process increases the oil''s melting point and shelf life.It turning liquid oil into a semi-solid form.', 0, 0, 0, 1790968053715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d46ad81f62a592db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the factor effect of boiling water?', '{"A":"Air pressure","B":"Temperature","C":"Pressure","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For water, the boiling point is 100ºC at a pressure of 1 atmThe boiling point of water decreases at higher altitudes due to Low atmospheric pressureThe boiling point of water increases with increased atmospheric pressureThe boiling point of water decreases with decreased atmospheric pressureND17-1-2023', 0, 0, 0, 1790968053715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_edbe6c4ca1f65ae8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Sunlight is made of how many colours?', '{"A":"6 colours","B":"5 colours","C":"7 colours","D":"4 colours","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sunlight is composed of the following seven colours:1. Violet2. Indigo3. Blue4. Green5. Yellow6. Orange 7. RedND06-08-2023', 0, 0, 0, 1790968053715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_42601ec4d369fb75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The function of the nosepiece in a microscope is to ______?', '{"A":"Change the magnification of objective lenses","B":"Move the stage up and down","C":"Sharpen the image","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The nosepiece in a microscope holds the objective lenses.It allows the user to rotate and switch between different magnification levels.It helps adjust the zoom or magnification by changing the objective lens in use.', 0, 0, 0, 1790968053715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dc5c92355d4726e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A capacitor is a device used to store _____?', '{"A":"Electricity","B":"Magnet","C":"Electric charge","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A capacitor is a device used to store electrical charge and electrical energy. It consists of at least two electrical conductors separated by a distance.It is widely used in electronic circuits for filtering, timing, and energy storage.', 0, 0, 0, 1790968053748) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_28c06da68b980ea3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The breathing and heartbeat are controlled/regulates by?', '{"A":"Endometrium","B":"Medulla oblongata","C":"Hypothalamus","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The medulla or the midbrain is responsible for important bodily functions such as heartbeat and breathing, It is also responsible for hand-eye coordination and depth perception.', 0, 0, 0, 1790968053748) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e058affeb51669c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Electronic configuration of K is _____?', '{"A":"[He] 4s¹","B":"[Ar] 4s¹","C":"[Ar] 4s²","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Potassium (K, atomic number 19) has 19 electrons.Its configuration: 1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹, which is [Ar] 4s¹ in shorthand.', 0, 0, 0, 1790968053748) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_946f295e7c98c6bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The number of amino-acids found in most of the proteins?', '{"A":"170","B":"25","C":"40","D":"20"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Most proteins are made up of 20 different amino acids. These 20 amino acids are commonly referred to as the standard or proteinogenic amino acids. While other amino acids exist, they are not typically found in the primary structure of proteins that make up most living organisms.', 0, 0, 0, 1790968053748) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bff399500f23c396', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In ________ ammonia is the chief excretory waste.', '{"A":"Fish","B":"Mammals","C":"Turtles","D":"Reptiles"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In fish, ammonia is the chief excretory waste. Fish excrete ammonia directly into the water through their gills. Ammonia is toxic, but since fish live in water it gets diluted quickly, making it safe for excretion in this form.', 0, 0, 0, 1790968053748) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f048352569a4d2b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The process of movement of water/solvent molecules from a region of higher concentration to a region of lower concentration through a semipermeable membrane is called ________?', '{"A":"Induction","B":"Transportation","C":"Conduction","D":"Osmosis"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Osmosis is the movement of water molecules through a semipermeable membrane from an area of higher water concentration to lower concentration.It is a vital process in biological systems for maintaining cell balance.', 0, 0, 0, 1790968053748) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ea879bbb1a7df80', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'On Earth surface water covers ______ area.', '{"A":"50%","B":"60%","C":"71%","D":"80%"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Water covers approximately 71% of the Earth''s surface.Additional informationLand Coverage: The remaining 29% of the Earth''s surface consists of land, including continents and islands.Water Distribution: About 96.5% of Earth''s water is held in the global oceans as saltwater', 0, 0, 0, 1790968053748) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17e66cdf39d8377f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Sea water can be purified by the process of _____?', '{"A":"Distillation","B":"Evaporation","C":"Filtration","D":"Fractional distillation"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Distillation is the process of heating sea water to produce steam and then condensing it back into liquid form, leaving impurities behind.This method effectively removes salts and other contaminants, making the water safe for use.', 0, 0, 0, 1790968053748) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6031c6c40ece2911', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'An endothermic reaction is one in which _____?', '{"A":"Heat is absorbed","B":"Heat is evolved","C":"Heat is converted into electricity","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In endothermic reactions, energy in the form of heat is taken in from the surroundings.Examples include photosynthesis and melting of ice, where heat is absorbed to proceed.In an exothermic reaction, energy (heat) is released/evolved to the surroundings.Examples include combustion of fuels and respiration.', 0, 0, 0, 1790968053778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_961295c2646b7f9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The loss of water from the plants in the form of small droplets through hydathodes is known as _____?', '{"A":"Stomal transpiration","B":"Guttation","C":"Lenticular transpiration","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Guttation is the exudation of liquid water droplets from the edges of leaves through special pores called hydathodes.It usually occurs at night or early morning when soil moisture is high and transpiration is low.', 0, 0, 0, 1790968053778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ef1a1e74a4ece5cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Food is normally digested in the _____?', '{"A":"Large intestine","B":"Stomach","C":"Small Intestine","D":"Mouth"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The majority of nutrient absorption in the digestive system occurs in the small intestine, Where the final stages of digestion take place. This organ''s structure, featuring villi and microvilli, creates a large surface area optimized for absorbing digested nutrients and most water into the bloodstream.', 0, 0, 0, 1790968053779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_99d0a59919c7480d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A freely falling object is an example of _____?', '{"A":"Newton’s First Law","B":"Newton’s Second Law","C":"Archimedes’ Law","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The motion of a free-falling object can be described by Newton''s second law of motion, force (F) = mass (m) times acceleration (a)Newton''s second law of motion states that F = ma, or net force is equal to mass times acceleration.The other name for Newton''s second law is the law of force and acceleration.', 0, 0, 0, 1790968053779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c996e4207755bb07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Vertical columns in the periodic are called _____?', '{"A":"Rows","B":"Periods","C":"Groups","D":"Blocks"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vertical columns in the periodic table are called groups.Horizontal rows are called periods.', 0, 0, 0, 1790968053779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a3f6d2912a4ae62b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'How many millimeters are there is one centimeter?', '{"A":"100","B":"50","C":"10","D":"20"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 meter (m) = 1000 millimeters (mm)1 meter (m) = 100 centimeters (cm)1 centimeter (cm) = 10 millimeters (mm)1 millimeter (mm) = 0.1 centimeters (cm)1 kilometer (km) = 1000 meters (m)', 0, 0, 0, 1790968053779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7dc216a8091211f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Spectrometer is used  for measurement for _____?', '{"A":"Photons","B":"Laser/Wavelength","C":"Line spectra","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A spectrometer is an instrument used to measure the properties of light over a specific portion of the electromagnetic spectrum, especially to analyze line spectra produced by atoms or molecules.It helps identify elements or compounds by detecting their unique emission or absorption lines in the spectrum.A spectrometer is an instrument used to measure the wavelength of light (or other electromagnetic radiation) by dispersing it into a spectrum.It is commonly used to analyze the spectral lines of elements, which correspond to specific wavelengths.', 0, 0, 0, 1790968053779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_58a1c3689155e2b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The projectile and circular motion are examples of motion in _____ dimension(s).', '{"A":"Two","B":"Three","C":"Four","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Projectile motion occurs in a plane (e.g., vertical and horizontal directions), so it is two-dimensional (2D).Circular motion also occurs in a plane (e.g., x-y plane) and is two-dimensional, even if the circle is in 3D space, its path is confined to a plane.', 0, 0, 0, 1790968053779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e156127fe6cca83', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Glass is a _____?', '{"A":"Cooled wax","B":"True solid","C":"Super cooled liquid","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Glass is amorphous.It lacks a definite crystalline structure.It behaves like a supercooled liquid, flowing extremely slowly over time.', 0, 0, 0, 1790968053816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_276694632499347b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '1 radian is equal to _____?', '{"A":"54°","B":"57.3°","C":"45°","D":"90°"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 radian ≈ 57.3 degrees, based on the formula: 1 radian = 180/𝜋 degrees.It is a standard angular measurement in mathematics and physics.', 0, 0, 0, 1790968053816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af31eff859dc477c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Earth complete one rotation on its axis in _______?', '{"A":"23 hours and 30 mints","B":"23 hours and 56 mints and 4.9 seconds","C":"24 hours","D":"24 hours and 1 mints and 10 seconds"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Earth takes approximately 23 hours, 56 minutes, and 4.9 seconds to complete one rotation on its axis,It is called a sidereal day.This is the time it takes for the Earth to rotate once relative to the fixed stars.The extra 4 minutes is due to the Earth''s slightly ellipsoidal shape and the effects of the Moon''s gravitational pull.', 0, 0, 0, 1790968053816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_395cb4c25cc569f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Kilowatt is the unit of _________?', '{"A":"Voltage","B":"Resistance","C":"Power","D":"Current"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kilowatt-hour is the unit of ENERGY.Watt or Kilowatt is the unit of power.Kilowatt-hour (KWh) is a unit of Electrical Energy.We know that, Power×time=Energy⇒ Kilo-Watt×Hour=Energy1KWh is electrical energy consumed when an electrical equipment of power 1 KiloWatt is operated for 1 Hour.', 0, 0, 0, 1790968053816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c1ad891d96b1fe8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'HIV is not transmitted through ______? Saliva, Surgical instruments, Semen, Sexual contact', '{"A":"Saliva","B":"Surgical instruments","C":"Semen","D":"Sexual contact"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HIV (Human Immunodeficiency Virus) is not transmitted through saliva. The virus cannot be spread through casual contact like kissing, sharing utensils, or exposure to saliva. The primary modes of HIV transmission are:Surgical instruments (if contaminated with infected blood and not properly sterilized).Semen (during sexual contact or other exposure to genital fluids).Sexual contact (unprotected anal, vaginal, or oral sex).Saliva contains enzymes and inhibitors that make HIV transmission highly unlikely, even in deep kissing.', 0, 0, 0, 1790968053816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d5bd54a48efae6f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Head of arthropods contains _____?', '{"A":"Brain","B":"Compound eyes","C":"Antenna","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The head of arthropods bears the brain (ganglia), compound eyes, and antennae for sensing.These structures help in coordination, vision, and environmental detection.', 0, 0, 0, 1790968053816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1fd7e3188549658f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The traditional method of crossing of different varieties of plants is called ______?', '{"A":"Gene cloning","B":"Genetic engineering","C":"Hybridization","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hybridization is the traditional method of crossing different plant varieties to produce improved traits.It is widely used in agriculture for higher yield, disease resistance, and better quality.', 0, 0, 0, 1790968053816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_63ecff5b3ee9eb8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Twins produced from a single fertilized egg are called _____?', '{"A":"Different","B":"Similar","C":"Identical","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Identical twins develop when a single fertilized egg splits into two embryos.They share the same genetic material.They are always of the same sex.', 0, 0, 0, 1790968053816) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8056de05dedf43ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Farming of honey bees is called _____?', '{"A":"Apiculture","B":"Sericulture","C":"Lac culture","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Apiculture is the practice of beekeeping to produce honey, beeswax, and other bee-related products.It involves managing bee colonies in artificial hives for commercial and ecological benefits.', 0, 0, 0, 1790968053848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a7ad79aa28080177', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Wheatstone bridge is used to determine the _____?', '{"A":"Charge","B":"Current","C":"Resistance","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Wheatstone bridge is an electrical circuit designed to measure unknown resistance accurately.It works by comparing it with the known resistances in a balanced condition.', 0, 0, 0, 1790968053848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_609f4b65509b7c82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Doppler''s effect is applicable to _____?', '{"A":"Sound waves","B":"Light waves","C":"Transverse waves","D":"Both sound and light waves"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Doppler effect is applicable to all types of waves, including sound waves, light waves, and even water waves. It describes the change in frequency or wavelength of a wave when there is relative motion between the wave source and the observer.', 0, 0, 0, 1790968053848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_61db81f310f081e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Motion along a line is called motion in ______?', '{"A":"Three dimensions","B":"One dimension","C":"Two dimensions","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Motion along a straight line occurs in one dimension only.Examples include a car moving on a straight road or a free-falling object.', 0, 0, 0, 1790968053848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e84e69199715742a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What does Angstrom measure?', '{"A":"Length of light waves (Distance approx)","B":"Intensity of light","C":"Speed of wind","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Angstrom (Å) measures very small distances, especially wavelengths of light and atomic-scale lengths.It is equal to 10^-10 meters, or 0.1 nanometers. Therefore, among the given options, angstrom is used to measure the length of light waves.It is also used to measure other microscopic dimensions, such as: The size of atoms and moleculesThe lengths of chemical bondsThe arrangement of atoms in crystals', 0, 0, 0, 1790968053848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d9a990f9657f567f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Molar Mass of water (H₂O) is?', '{"A":"14g","B":"16 g","C":"18 g","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Molar mass: 18.01528 g/molWater freezes at 0 degrees Celsius and 32 degrees Fahrenheit.Boiling point: 100 °CDensity: 997 kg/m³Formula: H2OND25-7-2023', 0, 0, 0, 1790968053848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa809590742107c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'It is commonly known as caustic soda?', '{"A":"Magnesium hydroxide","B":"Sodium hydroxide","C":"Calcium Hydroxide","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sodium hydroxide is commonly known as caustic soda.It is a strong base used in soap making and other chemical industries.', 0, 0, 0, 1790968053848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_46a6703c2335f7f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Example(s) of primary pollutants is/are _____?', '{"A":"CO","B":"SO₂","C":"NO₂","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Primary pollutants are emitted directly into the air from sources like vehicles and industries.Examples include carbon monoxide (CO), sulfur dioxide (SO₂), and nitrogen dioxide (NO₂).', 0, 0, 0, 1790968053848) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30f76c806ad6befc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Number of moles of solute dissolved in per liter of solution is called _____?', '{"A":"Mole fraction","B":"Molarity","C":"Molality","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Molarity (M) is defined as the number of moles of solute per liter of solution.It is widely used in chemistry to express solution concentration.', 0, 0, 0, 1790968053883) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1f813a0bc7d63e6c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The spreading of fragrance or scent in air is due to _____?', '{"A":"Diffusion","B":"Low density","C":"Effusion","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fragrance spreads because its molecules move from a region of high concentration to low concentration in air.This natural mixing of particles without external force is called diffusion.', 0, 0, 0, 1790968053883) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f39470d6d7b38c16', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following nobel gases is not present in atmosphere? Rn, He, Ne, Ar', '{"A":"Rn","B":"He","C":"Ne","D":"Ar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Radon (Rn) is a radioactive gas formed from the decay of uranium and radium found in rocks and soil.He (Helium): Helium is present in trace amounts in the atmosphere.Ne (Neon): Neon is also present in trace amounts in the atmosphere.Ar (Argon): Argon is the most abundant noble gas in Earth''s atmosphere, making up about 0.93% of the air.', 0, 0, 0, 1790968053883) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5abfe3a5ab9706ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'An exothermic reaction is one in which _____?', '{"A":"Heat is absorbed","B":"Heat is evolved","C":"Heat is converted into electricity","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An exothermic reaction releases energy into the surroundings as heat or light.Heat released: Energy moves outward.Surroundings warm: Temperature rises.Negative enthalpy: Delta H < 0Lower product energy: Reactants hold more energy.Additional information:In an endothermic reaction, heat is absorbed from the surroundings.Examples include photosynthesis and melting of ice.', 0, 0, 0, 1790968053883) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_368c668478f3a9ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Use of vaccines, which stimulate the production of antibodies in the body is called _____?', '{"A":"Artificially induced active immunity","B":"Auto response immunity","C":"Passive immunity","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vaccines contain weakened or inactive pathogens that stimulate the body to produce its own antibodies.Since immunity develops by artificial means (vaccination), it is called artificially induced active immunity.', 0, 0, 0, 1790968053883) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d158c957f1d8a853', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Biotic components of ecosystems are _____?', '{"A":"Fungi","B":"Animals & plants","C":"Microorganisms","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Biotic components are the living organisms in an ecosystem, including plants, animals, fungi, and microorganisms.They interact with each other and with abiotic components (like water, soil, air) to sustain the ecosystem.', 0, 0, 0, 1790968053883) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8d33c588aa10b0ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '______ are flowering plants which produce seeds enclosed in carpel.', '{"A":"Zygote","B":"Angiosperms","C":"Gymnosperms","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Angiosperms are flowering plants that produce seeds enclosed within a carpel/fruit.In contrast, gymnosperms have naked seeds not enclosed by a fruit.', 0, 0, 0, 1790968053883) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3605abdd5ac2ddb3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Prevention of Poliomyelitis (Polio) is possible with _____?', '{"A":"Vaccination (IPV & OPV)","B":"Medication","C":"Gene therapy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Polio can be effectively prevented through vaccines: Oral Polio Vaccine (OPV) and Inactivated Polio Vaccine (IPV).There is no cure or medication for polio, only prevention through immunization.', 0, 0, 0, 1790968053883) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0886a61bc4c9b300', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Birds possess a thick muscular structure used for crushing food called _____?', '{"A":"Oral cavity","B":"Gizzard","C":"Vocal cord","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The gizzard is a thick, muscular part of a bird’s stomach that grinds and crushes food.Birds often swallow small stones to help the gizzard in grinding food efficiently.', 0, 0, 0, 1790968053919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6d09f91e3c4c6e70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Scientific name of cotton is _____?', '{"A":"Gossypium hirsutum","B":"Triticum turgidum L.","C":"Allium cepa","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gossypium hirsutum is the scientific name of upland cotton, the most widely cultivated cotton species.The following table provides the botanical names for a variety of familiar plants: Wheat : Triticum aestivumApple : Malus domesticaCarrot : Daucus carotaCoconut : Cocos nuciferaCucumber : Cucumis sativusGinger : Zingiber officinaleMango : Mangifera indicaOak tree : QuercusOnion : Allium cepaPotato : Solanum tuberosumRice : Oryza sativaRose : RosaSunflower : Helianthus annuusTomato : Solanum lycopersicum', 0, 0, 0, 1790968053919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c7ccd01864d7935c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'AIDS spread by _____?', '{"A":"Infected needles & syringes","B":"Homosexuality","C":"Immoral way of life","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AIDS is caused by HIV.It spreads through infected needles, sexual contact, and unsafe practices.It is not transmitted by casual contact like touching or sharing food.', 0, 0, 0, 1790968053919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d1e4b82eecc81fbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Aquatic arthropods respire through _____?', '{"A":"Gills","B":"Book lungs","C":"Spiracles","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aquatic arthropods like crabs, prawns, and some aquatic insects use gills to extract oxygen from water.Gills provide a large surface area for gas exchange in an aquatic environment.', 0, 0, 0, 1790968053919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9ac5dac3701c0fab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Geotropism is a tropic movement of plants in response to _____?', '{"A":"Water","B":"Light","C":"Gravity","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geotropism is the growth response of plants toward or away from gravity.Roots show positive geotropism (grow downward) and shoots show negative geotropism (grow upward).', 0, 0, 0, 1790968053919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0fe6735ce8d701b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Unit of Mass is?', '{"A":"Kg","B":"Km","C":"W","D":"N"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Metric System of Measurements uses the mass units: gram (g), kilogram (kg), and tonne (t). 1000 g = 1 kg. 1000 kg = 1 tonne.Mass was first defined in 1795Symbol: M', 0, 0, 0, 1790968053919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f49a1dcbaeee430', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Transformer is used to _______?', '{"A":"Decrease DC voltage","B":"Increase DC voltage","C":"Increase and decrease AC voltage (Steps up or steps down A.C. voltage)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A transformer can increase (step-up) or decrease (step-down) the voltage of alternating current (AC).It''s widely used in power transmission to reduce energy loss over long distances.', 0, 0, 0, 1790968053919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_95c08267d75ecd2e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A book lying on a horizontal table is in ______ equilibrium.', '{"A":"Dynamic","B":"Static","C":"Stable","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The book is at rest with no net force or motion, so it is in static equilibrium.Since any small push won’t topple it, it is also considered stable equilibrium on a flat surface.', 0, 0, 0, 1790968053919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_242e9985eef9fce9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'We use driving mirrors to be convex instead of plane as they _____?', '{"A":"Show wider view","B":"One exact idea of distant object","C":"Producer magnified image","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Convex mirrors diverge light rays, giving a wider field of view, helpful in traffic.They form diminished, virtual, and upright images, making distant vehicles visible clearly.', 0, 0, 0, 1790968053955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e39b48756e124069', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of these is the most widely used nitrogenous fertilizer in Pakistan?', '{"A":"Ammonium sulphate","B":"Ammonium chloride","C":"Urea","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Urea is the most widely used nitrogenous fertilizer in Pakistan due to its high nitrogen content (46%).It is cheap, effective, and easily available compared to other nitrogen fertilizers.', 0, 0, 0, 1790968053955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7afc3bc05a080efa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Organic compounds are insoluble in _____?', '{"A":"Ether","B":"Petroleum","C":"Water","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Most organic compounds are non-polar, so they dissolve in non-polar solvents like ether, petroleum, and benzene.Water is polar, so organic compounds are generally insoluble in it.', 0, 0, 0, 1790968053955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1326ca6231d2db19', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one of the following substance is used as de-coloring agent?', '{"A":"Silica gel","B":"H₂SO₄ [concentrated]","C":"Animal charcoal","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Animal charcoal (activated charcoal) is used to remove color from solutions, especially in sugar refining.It works by adsorbing colored impurities effectively.', 0, 0, 0, 1790968053955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3c4670134dbf3109', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In Sindh the desert ecosystem is called _____?', '{"A":"Thar","B":"Thal","C":"Cholistan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Thar Desert is the main desert ecosystem in Sindh, extending into Rajasthan (India).It is characterized by arid climate, sand dunes, and sparse vegetation.', 0, 0, 0, 1790968053955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_790d583dcd43a51c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Enzymes are made of _____?', '{"A":"Carbon","B":"Protein","C":"Silica","D":"Oil"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An enzyme is a biological catalyst and is almost always a protein.Enzymes are organic catalysts. A large protein enzyme molecule is composed of one or more amino acid chains called polypeptide chains. ******', 0, 0, 0, 1790968053955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_85dfc3d18d8bf3f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The English name of Triticum aestivum L. is _____?', '{"A":"Wheat","B":"Turnip","C":"Onion","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The following table provides the botanical names for a variety of familiar plants: Wheat : Triticum aestivumApple : Malus domesticaCarrot : Daucus carotaCoconut : Cocos nuciferaCucumber : Cucumis sativusGinger : Zingiber officinaleMango : Mangifera indicaOak tree : QuercusOnion : Allium cepaPotato : Solanum tuberosumRice : Oryza sativaRose : RosaSunflower : Helianthus annuusTomato : Solanum lycopersicum', 0, 0, 0, 1790968053955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a969ce827e3ae1bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'How many pairs of spinal nerves are there in the human spinal cord?', '{"A":"31 pairs","B":"24 pairs","C":"36 pairs","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are 31 pairs of spinal nerves (62 nerves) that originate from the spinal cord.These include 8 cervical, 12 thoracic, 5 lumbar, 5 sacral, and 1 coccygeal nerve pairs.', 0, 0, 0, 1790968053955) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f363fd62d33412a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Canine teeth are very large in _____?', '{"A":"Omnivores","B":"Herbivores","C":"Carnivores","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carnivores have very large canine teeth for tearing flesh.In herbivores, canines are reduced or absent.Omnivores have moderate-sized canines.', 0, 0, 0, 1790968053988) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e10c14914f62619', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '_____ is the term used for all liquids and gases.', '{"A":"Liquid medium","B":"Gaseous medium","C":"Fluid","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term fluids refers to both liquids and gases, as they can flow.Liquids specifically are also classified under fluids because of their ability to take the shape of a container.', 0, 0, 0, 1790968053988) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e304bb92d8bdc3e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A red object when seen through a thick blue glass appears _____?', '{"A":"Green","B":"Red","C":"Black","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A red object reflects only red light.A blue glass absorbs red light, so no light passes through → the object looks black.', 0, 0, 0, 1790968053988) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea1bf9d46070ab12', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The change of position of a body in a particular direction is _____?', '{"A":"Acceleration","B":"Distance","C":"Displacement","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Displacement is the change in position of a body in a specific direction (a vector quantity).Distance is the total path covered without considering direction.', 0, 0, 0, 1790968053988) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1033690a2b3f0040', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'First law of Thermodynamics is the law of conservation of _____?', '{"A":"Specific heat","B":"Energy","C":"Temperature","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The First Law of Thermodynamics states that energy can neither be created nor destroyed, only transformed from one form to another.Hence, it is essentially the law of conservation of energy.', 0, 0, 0, 1790968053988) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7faf1eaf19b5c27d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the SI unit of impedance?', '{"A":"Henry","B":"Hertz","C":"Ampere","D":"Ohm"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SI unit of impedance is the ohm (Ω). Impedance, like resistance, is measured in ohms.It can be represented as a complex number.', 0, 0, 0, 1790968053988) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62209e90473ef017', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The correct value of 0°C on the Kelvin scale is _______?', '{"A":"273.15K","B":"273K","C":"272.95K","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Kelvin scale is related to Celsius by: K = °C + 273.15.Thus, 0°C = 273.15 K, which is the absolute temperature reference point.', 0, 0, 0, 1790968053988) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_20d942cd0c0d7a56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Curie is the unit of ______?', '{"A":"Resistivity","B":"Conductivity","C":"Radioactivity","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Curie (Ci) is a unit that measures the rate of radioactive decay.1 Curie = 3.7 × 10¹⁰ disintegrations per second.', 0, 0, 0, 1790968053988) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8af306807acd2603', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What will be the products of CaCO₃ + 2HCl →?', '{"A":"CaCl₂ + H₂O + CO₂","B":"CaCl₂ + 2H₂O + CO₂","C":"CaCl₂ + H₂ + CO₂","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Calcium carbonate + hydrochloric acid → calcium chloride (CaCl₂), water (H₂O), and carbon dioxide (CO₂).This is a neutralization + decomposition type reaction of an acid with a carbonate.', 0, 0, 0, 1790968054021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e5376d5284cc7c8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '_____ has low viscosity.', '{"A":"Acetone","B":"Water","C":"Ethyl alcohol","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Viscosity means resistance to flow; lower viscosity = flows more easily.Acetone is less viscous than water, glycerine, and ethyl alcohol, so it flows fastest.', 0, 0, 0, 1790968054021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ab21c2d0d93f8fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Phototropism is a tropic movement of plants in response to _____?', '{"A":"Light","B":"Gravity","C":"Water","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Phototropism is the directional growth of plants in response to light.Example: Shoots bend toward light to maximize photosynthesis.', 0, 0, 0, 1790968054021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9770fa768071b592', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In plants, downward translocation of minerals takes place through _____?', '{"A":"Xylem","B":"Phloem","C":"Cortex","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In plants, xylem mainly transports water and minerals upward.Phloem carries organic food and minerals both upward and downward, enabling downward translocation.', 0, 0, 0, 1790968054021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03e2895db007a86a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The smallest structural and functional unit of life is ______?', '{"A":"Cell","B":"Atom","C":"Tissue","D":"Organ"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cell is the smallest unit of life.Cells are called ‘structural’ and ‘functional’ units for a reason. Cells are made of molecules which are in turn made up of atoms. “Cell is the unit of LIFE” is that a cell is the smallest living entity in a living system.', 0, 0, 0, 1790968054021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d287ab4d8fb3915', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '_____ is the longest stage of mitosis.', '{"A":"Telophase","B":"Prophase","C":"Metaphase","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prophase involves chromosome condensation and spindle formation, which takes the most time.It is the longest stage of mitosis.', 0, 0, 0, 1790968054021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ba87a77c756d70d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The coldest place on the earth “Vostok” is situated in _____?', '{"A":"Antarctica","B":"Asia","C":"Europe","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vostok Station is located in Antarctica.It is the coldest place on Earth.Temperatures there can drop below –89°C.', 0, 0, 0, 1790968054021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4b717af875af50a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'All of the following are organic compounds except _____?', '{"A":"Water","B":"Alcohol","C":"Chloroform","D":"Ethane"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Water (H₂O) is an inorganic compound as it does not contain carbon-hydrogen (C-H) bonds.Alcohol, chloroform, and ethane are organic compounds because they contain carbon atoms bonded to hydrogen.', 0, 0, 0, 1790968054021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6294a862ba77a5dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Molarity of pure water is ______?', '{"A":"1","B":"18","C":"55.6","D":"6"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Molarity is calculated by dividing the number of moles of solute by the volume of solution in liters. Therefore, the molarity of pure water is approximately 55.56 moles/L, or approximately 55.5 M.', 0, 0, 0, 1790968054063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c9e05d8ad819fd6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Movement of an organism as a whole from place to place is called ______?', '{"A":"Locomotion","B":"Respiration","C":"Transpiration","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Locomotion is the movement of the whole organism from one place to another.Example: Walking, running, or swimming in animals.', 0, 0, 0, 1790968054063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dab1825fcb24a107', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Agrochemicals used in agriculture are commonly called ______?', '{"A":"Fertilizers","B":"Pesticides","C":"Insecticides","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agrochemicals include fertilizers (to enhance soil nutrients) and pesticides (to control pests and diseases).Together, they improve crop yield and protection.', 0, 0, 0, 1790968054063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d88728bf241e5572', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Earthworms are ______ in habit.', '{"A":"Scavenger","B":"Nocturnal","C":"Diurnal","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Earthworms are nocturnal.They remain in burrows during the day and come out at night to feed.They are detritivores, feeding on decaying organic matter in soil.', 0, 0, 0, 1790968054063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b2a1d50e3b8c0654', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A group of cells having common origin and performing an identical function are called ______?', '{"A":"System","B":"Tissue","C":"Organs","D":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A tissue is a group of cells with a common origin that work together to perform the same function.Examples: muscle tissue, nervous tissue, xylem, phloem.', 0, 0, 0, 1790968054063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea884fbae94b1c27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Animal which captures and readily kills living animals for its food is called?', '{"A":"Parasite","B":"Scavenger","C":"Predator","D":"Mammal"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PredatorCarnivores are meat-eating organisms, most often animals.Carnivores that hunt other animals are called predators.Hunted animals are called prey. The animal diet determines where in the food chain, a series of organisms that provide energy and nutrients to other organisms.', 0, 0, 0, 1790968054063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac5f7efdfbfa6f4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following uranium isotopes is used in nuclear reactions?', '{"A":"92 U-238","B":"92 U-235","C":"92 U-234","D":"92 U-233"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The uranium isotope used in nuclear reactions is 92 U-235. Uranium-235 is a fissile isotope, meaning it can undergo nuclear fission when struck by a neutron, Releasing energy and more neutrons to sustain a chain reaction. While Uranium-238 is the most abundant isotope of uranium, It is not fissile and requires a more complex process to be utilized in nuclear reactions.', 0, 0, 0, 1790968054063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e0e74e7f12a153f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The real gases show deviation from ideal behavior at _____?', '{"A":"Low temperature and high pressure","B":"High temperature and low pressure","C":"Low temperature and low pressure","D":"High temperature and high pressure"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Real gases show deviation from ideal behavior at low temperature and high pressure.Due to increased intermolecular forces and reduced volume available for gas molecules, which contradicts the assumptions of ideal gas behavior.', 0, 0, 0, 1790968054063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9ee0395cdf80af8f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is measured by an ammeter?', '{"A":"Sound waves","B":"Electric current (small current)","C":"Gas pressure","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An ammeter is an instrument used to measure small electric current in a circuit.It typically measures current in amperes (A).It is connected in series with the circuit.The potentiometer is used to measure emf. A meter bridge is used to measure the electrical resistance.', 0, 0, 0, 1790968054095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d52b6489cc554323', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which material provide shield against gamma rays?', '{"A":"Wood","B":"Lead","C":"Water","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lead is commonly used as a shield against gamma rays.Due to its high density.It effectively absorbs and blocks gamma radiation.', 0, 0, 0, 1790968054095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75353fc8687db719', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which algae take part in building coral reefs along with coral animals are?', '{"A":"Red algae","B":"Brown algae","C":"Green algae","D":"Diatoms"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Coralline red algae are the type of algae that play a role in building coral reefs, along with coral animals. These algae secrete and deposit calcium carbonate.It helps to cement the reef structure together.', 0, 0, 0, 1790968054095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f1786c13e5bde1a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The purest form of water is obtained from _____?', '{"A":"Rain water","B":"Sea water","C":"Acid rain","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rainwater is formed through evaporation and condensation, a natural distillation process that leaves most impurities and salts behind. This process effectively purifies the water, making it the purest form found in nature.', 0, 0, 0, 1790968054095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b3d4fa4bdff74b23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Nautical mile is a unit of distance used in _____?', '{"A":"Road mile","B":"Astronomy","C":"Navigation","D":"Measuring the boundaries of a nation"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A nautical mile is a unit of length used in air, marine, and space navigation, and for the definition of territorial waters.A nautical mile equals 1.852 km.It is used in air and sea travel.It is based on the Earth’s circumference, making it ideal for navigation.', 0, 0, 0, 1790968054095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_170512861cbdb66e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the unit of measurement of Inductance?', '{"A":"Henry","B":"Watt","C":"Light","D":"Tesla"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The unit of measurement for inductance is the henry (H).It is the International System of Units (SI) unit.The henry is named after Joseph Henry, the physicist who independently discovered inductance.', 0, 0, 0, 1790968054095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d83c0da7b5d100dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Magnetic field is measured by _____?', '{"A":"Flux meter","B":"Magnetometer","C":"Galvanometer","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A magnetometer is specifically designed to measure the strength and direction of a magnetic field.Flux meter measures magnetic flux.Galvanometer measures electric current.', 0, 0, 0, 1790968054095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d390b4ac17df15bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The sky appears blue because ______?', '{"A":"Scattering of light from atmosphere","B":"Blue light is scattered the most","C":"Blue light is absorbed","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sky looks blue due to Rayleigh scattering of sunlight by air molecules.Among visible colors, blue light is scattered the most because of its shorter wavelength.', 0, 0, 0, 1790968054095) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aedce933817d4b1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Internal friction of fluid is called ______?', '{"A":"Surface tension","B":"Viscosity","C":"Resistance","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Viscosity is the internal friction that resists the relative motion of fluid layers.It measures how “thick” or resistant to flow a fluid is.', 0, 0, 0, 1790968054127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bfea9a141c5f37c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The first book of physics was written by _____?', '{"A":"Kelvin","B":"Faraday","C":"Aristotle","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aristotle (384–322 BC) wrote Physica, considered the first systematic book on physics.It dealt with motion, elements, and natural laws, laying the foundation of classical science.', 0, 0, 0, 1790968054127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8d4a102ba09ff39b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following contains four significant figures?', '{"A":"0.035","B":"1.035","C":"0.0010","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rule 1: Non-zero digits are always significant. In the number 1.035, the digits 1, 3, and 5 are all non-zero and therefore significant.Rule 2: Zeros between non-zero digits are significant. The zero between the 1 and the 3 is a captive zero, which means it is significant. This gives a total of four significant figures (1, 0, 3, 5).', 0, 0, 0, 1790968054127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a0b27141dac1f355', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Sea weeds are important source of _____?', '{"A":"Bromine","B":"Iron","C":"Iodine","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seaweeds, especially brown algae, accumulate iodine from seawater.They are the primary natural source of iodine used in medicine and industry.', 0, 0, 0, 1790968054127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b0ce2ee6ec1cbacd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Formula of heavy water is _____?', '{"A":"D₂O","B":"DO₂","C":"H₂O","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Heavy water, also known as Deuterium Oxide (D₂O).It is used as a neutron moderator in nuclear reactors.Due to its ability to slow down neutrons without absorbing them', 0, 0, 0, 1790968054127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_81a1f66fbe758bb2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Isotonic solutions have some _____?', '{"A":"Molarity","B":"Molar concentration","C":"Normality","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Isotonic solutions have equal osmotic pressure, which depends on molar concentration of solute particles.Thus, solutions with the same molar concentration (not just molarity/normality) are isotonic.', 0, 0, 0, 1790968054127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_db90766412c330a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'By which process does the smell of cooking spread to all the rooms in a house?', '{"A":"Decomposition","B":"Displacement","C":"Diffusion","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Diffusion is the process by which gas molecules move from an area of higher concentration (kitchen) to lower concentration (other rooms).This random molecular motion spreads the smell of cooking throughout the house.', 0, 0, 0, 1790968054127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62f89a32f54f2a70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one is the heaviest particle?', '{"A":"Neutron","B":"Electron","C":"Proton","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A neutron is slightly heavier than a proton, while an electron is much lighter.This extra mass makes the neutron the heaviest among the three fundamental particles.', 0, 0, 0, 1790968054127) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07eff576b324db70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The actual location or place where an organism lives and reproduce is ____?', '{"A":"Habitat","B":"Ecosystem","C":"Community","D":"Population"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A habitat is the specific place where an organism lives and reproduces.It provides the food, water, shelter, and conditions necessary for survival.', 0, 0, 0, 1790968054159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6da8d7a621319258', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'If molar concentration of a reactant "A" is one, then rate of the reaction of "A" will be ______?', '{"A":"Equal to rate constant","B":"Greater than rate constant","C":"Less than rate constant","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For a first-order reaction, rate r = k[A].If [A] = 1 M, then rate = k × 1 = k, so the rate equals the rate constant.', 0, 0, 0, 1790968054159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8add8ad82eb3fbb1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Equilibrium constant expression in non-aqueous medium can be applied to _____?', '{"A":"An aqueous solution of sucrose","B":"An aqueous solution of table salt","C":"An aqueous solution of fructose","D":"A solution of kerosene"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An equilibrium constant expression can be applied to an aqueous solution of table salt.An equilibrium constant expression is used for reversible reactions where the concentrations of reactants and products reach a constant state. Table salt (sodium chloride) dissociates into Na+ and Cl- ions in water, and this dissociation can be considered a reversible reaction. Thus, the equilibrium constant can be applied to this system.', 0, 0, 0, 1790968054159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_01476cb59dcf4a62', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Buffer is a solution which?', '{"A":"Has constant pH","B":"Resist change in its pH","C":"Consists of a strong acid and a strong base","D":"Contains salts of strong acids and strong bases"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A buffer is a solution that resists change in its pH. A buffer solution is composed of a weak acid and its conjugate base (or a weak base and its conjugate acid). When a small amount of a strong acid or base is added to a buffer, The added ions react with the components of the buffer to maintain a relatively constant pH.', 0, 0, 0, 1790968054159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b0309b9863db57af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'All of the following are covalent network crystals except? SiO2, Graphite, S8, Diamond', '{"A":"SiO2","B":"Graphite","C":"S8","D":"Diamond"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SiO₂, Graphite, and Diamond have covalent network structures, where atoms are bonded in a continuous network.S₈ is a molecular crystal, consisting of discrete S₈ molecules held together by weak Van der Waals forces.', 0, 0, 0, 1790968054159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0022d5fe96ab51e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Crystals in which lattice points are occupied by metal ions are?', '{"A":"Ionic crystals","B":"Covalent crystals","C":"Molecular crystals","D":"Metallic crystals"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Crystals in which lattice points are occupied by metal ions are a) Ionic crystals. Ionic crystals are formed by the electrostatic attraction between positively charged metal cations and negatively charged anions. These ions are arranged in a regular lattice structure.', 0, 0, 0, 1790968054159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f1650cb21765ac5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Two metallic conductors have the same value of resistivity. These conductors can be differentiated from the values of their?', '{"A":"Temperature coefficient","B":"Resistance","C":"Conductance","D":"Conductivity"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If two metallic conductors have the same resistivity, they can be differentiated based on their temperature coefficient. The temperature coefficient of resistivity indicates how much the resistivity of a material changes with a temperature change.Materials with the same resistivity can have different temperature coefficients, meaning their resistance will change differently as temperature changes.', 0, 0, 0, 1790968054159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ff7b89457f4e1306', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The negative gradient of electric potential is also called?', '{"A":"Potential energy","B":"Electric field intensity","C":"Electric potential energy","D":"Electron volt"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The negative gradient of electric potential is called Electric field intensity. Gradient:In general, a gradient represents the rate of change of a function for a given variable. In the context of electric fields, the gradient of electric potential indicates how quickly the potential changes as you move in a particular direction. Negative gradient:The "negative" part signifies that the electric field points in the direction of decreasing potential.', 0, 0, 0, 1790968054159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5fba5beacfbca7e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is correct for all transverse waves? They will involve the oscillation of the atoms, They can all be polarized, They can travel through a vacuum', '{"A":"They will involve the oscillation of the atoms","B":"They can all be polarized","C":"They can travel through a vacuum","D":"Both (a)&(c) are correct"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Transverse waves involve oscillations perpendicular to the direction of travel and can be polarized, while they do not necessarily require a medium to travel (e.g., light waves).', 0, 0, 0, 1790968054191) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0090c8eb610f3a22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The value of Boltzmann''s constant is _____?', '{"A":"1.38 × 10²³ J/K","B":"1.38 × 10−²³ J/K","C":"1.38 × 10²³ K/J","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Boltzmann''s constant (k_B) is a fundamental constant in physics.The value of Boltzmann''s constant is 1.38 × 10^(-23) J/K.', 0, 0, 0, 1790968054191) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a930add54b6471cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The time rate of change of magnetic flux has the same dimension as that of _____?', '{"A":"Current","B":"Resistance","C":"Magnetic induction","D":"Potential difference"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The time rate of change of magnetic flux has the same dimensions as that of potential difference (or electromotive force - EMF).', 0, 0, 0, 1790968054191) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8f82e2d6f98d3440', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Endometriosis will cause Infertility in _____?', '{"A":"Male","B":"Female","C":"Both A and B","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Endometriosis is a condition where tissue similar to the lining of the uterus grows outside the uterus. This tissue can cause pain and infertility, primarily in women. There is very strong evidence linking endometriosis to female infertility. Studies show that a significant portion of women with infertility also have endometriosis. While endometriosis can rarely occur in men, it is not considered a significant cause of infertility in males.', 0, 0, 0, 1790968054191) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc38ee281daf11d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Compared with the few days before ovulation, which hormone is released in increased quantities three days after ovulation?', '{"A":"FSH","B":"LH","C":"Oestrogen","D":"Progesterone"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After ovulation, the ruptured follicle forms a structure called the corpus luteum, which produces large amounts of progesterone. This hormone is crucial for preparing the uterine lining for potential pregnancy if fertilization occurs.', 0, 0, 0, 1790968054191) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f848751eada96118', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following best explains why hemophilia is more common in males than in females?', '{"A":"It is caused by a dominant autosomal gene","B":"It is a Y-linked disorder","C":"It is inherited as an X-linked recessive trait","D":"It is more often acquired later in life due to liver disease"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hemophilia is most often caused by a mutation in a gene on the X chromosome (either the F8 gene for hemophilia A or F9 for hemophilia B).Males have one X and one Y chromosome (XY), so if their single X chromosome carries the defective gene, they will have hemophilia.Females have two X chromosomes (XX), so a mutation would have to occur in both copies of the gene for them to show symptoms, which is much less common. If only one X has the mutation, they are typically carriers.', 0, 0, 0, 1790968054191) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8654549faff18e72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the causative organism of syphilis?', '{"A":"Treponema pallidum","B":"Mycoplasma pneumoniae","C":"Neisseria gonorrhoeae","D":"Chlamydia trachomatis"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Treponema pallidum is a spirochete bacterium that causes syphilis. This is the correct answer as confirmed by multiple sources.', 0, 0, 0, 1790968054191) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e904f05002420e73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The genotype for the height of an organism is written as Tt. What conclusion may be drawn?', '{"A":"The allele for height has at least two different genes","B":"There are at least two different alleles of the gene for height","C":"There are two different genes for height each having a single allele","D":"There is one allele for height with two different forms."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The genotype Tt represents two different alleles of the same gene:T = dominant allele (e.g., tall)t = recessive allele (e.g., short)This means the organism is heterozygous for the height gene — it has two different alleles (T and t) of one gene.', 0, 0, 0, 1790968054191) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_871702763657c0af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Testosterone, estrogen, and progesterone are hormones of _____?', '{"A":"Steroid nature","B":"Amino acid nature","C":"Protein nature","D":"Polypeptide nature"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Testosterone, estrogen, and progesterone are derived from cholesterol, making them steroid hormones.They are lipid-soluble, diffuse through membranes, and regulate reproduction.', 0, 0, 0, 1790968054228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03b240bd020208e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The bronchioles are located at the end of the bronchi and terminate in the _____?', '{"A":"Lungs","B":"Alveoli","C":"Alveolar sac","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alveoli:Bronchioles terminate in tiny air sacs called alveoli. These are the primary sites for gas exchange in the lungs. Alveolar sac:Alveoli are clustered together to form alveolar sacs.These sacs are the functional units of the lung where oxygen and carbon dioxide exchange occurs.', 0, 0, 0, 1790968054228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_97aa9b2b64319c7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following hepatitis is transmitted by fecal route? Hepatitis A, Hepatitis B, Hepatitis C, Hepatitis D', '{"A":"Hepatitis A","B":"Hepatitis B","C":"Hepatitis C","D":"Hepatitis D"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hepatitis A is primarily spread through contaminated food or water that has been in contact with infected feces, meaning it''s transmitted through the fecal-oral route.', 0, 0, 0, 1790968054228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d5d7172b490b5035', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A device used to measure potential difference is called ______?', '{"A":"Galvanometer","B":"Ammeter","C":"Voltmeter","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation - A voltmeter measures the potential difference (voltage) between two points in a circuit. - It is always connected in parallel to the component. - The SI unit of potential difference is the Volt (V). - Potential difference is the work done per unit charge to move a charge between two points. - Formula: V = W / Q - V = potential difference (volts) - W = work done (joules) - Q = charge (coulombs) - A voltmeter has high resistance so it doesn''t draw current from the circuit.', 0, 0, 0, 1790968054228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_572f44d04af40930', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'All of the following are viruses except? SARS, FIV, HIV, Mycoplasma', '{"A":"SARS","B":"FIV","C":"HIV","D":"Mycoplasma"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mycoplasma is a type of bacteria, not a virus. It lacks a cell wall, which makes it resistant to certain antibiotics. Bacteria are capable of independent replication, unlike viruses which need a host cell. SARS, FIV, and HIV are all viruses: SARS stands for Severe Acute Respiratory Syndrome, FIV for Feline Immunodeficiency Virus, HIV for Human Immunodeficiency Virus. These are all viruses that infect specific hosts and require a host cell to replicate their genetic material.', 0, 0, 0, 1790968054228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ff525858eea1b486', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Co-enzymes are derived from _____?', '{"A":"Vitamins","B":"Minerals","C":"Hormones","D":"Both A and B"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Most coenzymes are actually vitamins or derived from vitamins, meaning they are essential organic compounds needed in small amounts for normal metabolism', 0, 0, 0, 1790968054228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba8a7ef129f36c20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'An enzyme without its cofactor is called _____?', '{"A":"Active site","B":"Co-enzyme","C":"Prosthetic group","D":"Apoenzyme"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An enzyme without its cofactor is called an apoenzyme. Apoenzymes are the inactive protein component of an enzyme, requiring a cofactor to become catalytically active and form a holoenzyme.', 0, 0, 0, 1790968054228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7c5ff8309c6fa643', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The covalent bond between glucose and fructose is called ____?', '{"A":"Glycosidic bond","B":"Peptide bond","C":"Ester bond","D":"Hydrogen bond"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The covalent bond between glucose and fructose, forming sucrose, is called a glycosidic bond, specifically a 1-2 glycosidic linkage. This bond is formed through a dehydration reaction where a water molecule is removed when the two monosaccharides join.', 0, 0, 0, 1790968054228) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_923a21cfb3733c6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'All of these are disaccharides except for? Maltose, Lactose, Sucrose, Fructose', '{"A":"Maltose","B":"Lactose","C":"Sucrose","D":"Fructose"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A disaccharide is a sugar molecule composed of two monosaccharides joined together. Fructose is a monosaccharide (a single sugar unit), not a disaccharide. Therefore, it is the exception among the given options.', 0, 0, 0, 1790968054260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e41998c4e7071ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The synthesis of glycogen is known as _____?', '{"A":"Gluconeogenesis","B":"Glycogenolysis","C":"Glycolysis","D":"Glycogenesis"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The synthesis of glycogen is known as glycogenesis. This process involves the conversion of glucose into glycogen, primarily in the liver and muscle tissues, for storage and later use as an energy source.', 0, 0, 0, 1790968054260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_54d998d24166a925', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Damage to cerebellum as a result of head injury will lead to _____?', '{"A":"Poor coordination of movements","B":"Lack of temperature control","C":"Irregular heartbeat","D":"Inability to recognize visual stimuli"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Damage to the cerebellum as a result of injury most likely causes poor coordination of movements. The cerebellum is primarily responsible for coordinating muscle movements, balance, and fine motor control. So, damage to this area would lead to clumsiness, an unsteady gait, and difficulty with precise movements.', 0, 0, 0, 1790968054260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0a48aa661fa2bddf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The excited state which persists for unusually longer period of time is called?', '{"A":"Ground state","B":"Ionized state","C":"Metastable state","D":"Ordinary excited state"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A metastable state is an excited state of an atom or molecule that has a significantly longer lifetime compared to other excited states, but is still shorter than the ground state. This means that an electron in a metastable state can stay in that state for a relatively long time before transitioning back to a lower energy level.', 0, 0, 0, 1790968054260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3123884a160417c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The direct or indirect source for food, shelter, clothing, fuel for humans is ______?', '{"A":"Environment","B":"Water","C":"Land","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Land directly or indirectly provides humans with food, shelter, clothing, and fuel.It supports agriculture, forestry, and habitation, making it a primary resource.', 0, 0, 0, 1790968054260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_be9eef627750386f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is commonly known as horse-tail?', '{"A":"Calamites","B":"Sphenopsida","C":"Equisetum","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Equisetum (Sphenopsida) is commonly called horse-tail due to its brush-like appearance.It belongs to Pteridophytes.It is a living fossil.It is found near wetlands.', 0, 0, 0, 1790968054260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_61297360e4e7695e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Air at the sea level is dense. This is the practical application of ______?', '{"A":"Boyles Law","B":"Charles Law","C":"Avogadros Law","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Air is dense at sea level. This is an application of Boyle''s law.As per Boyle’s law : d=PM/ RT∴ d∝pAt sea level, the pressure of the atmosphere is high. Hence air is denser.', 0, 0, 0, 1790968054260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2248afe6e17208f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Contact process is used to manufacture _____?', '{"A":"Nitric acid","B":"Hydrochloric acid","C":"Sulfuric acid","D":"Acetic acid"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Contact process is a well-established industrial method for producing sulfuric acid.Sulfur dioxide is oxidized to sulfur trioxide with the help of a catalyst, which then reacts with water to form sulfuric acid.', 0, 0, 0, 1790968054260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1fd41e7750b876c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Ground water is called :', '{"A":"Water under the Surface of Earth","B":"Water above the Surface of Earth","C":"Both A and B","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790968054290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b18e8ece3f59173b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The principle of transformer is _____?', '{"A":"Mutual induction","B":"Ampere''s law","C":"Motional e.m.f","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A transformer works on the principle of mutual induction, where a changing current in the primary coil induces a voltage in the secondary coil.This is based on Faraday''s Law of Electromagnetic Induction, which states that a changing magnetic field produces an electromotive force (emf).', 0, 0, 0, 1790968054290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_69ea90d03f2d590d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Alkyl halide can be dehalogenated to alkene in the presence of ______?', '{"A":"KOH (aq)","B":"KOH (alc)","C":"Alkanes","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alkyl halides undergo dehydrohalogenation in the presence of alcoholic KOH to form alkenes.The alcoholic KOH acts as a strong base, removing HX from the alkyl halide.', 0, 0, 0, 1790968054290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c9c4573d9d4c5542', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The location of genes in chromosomes is called its_______?', '{"A":"Locus","B":"Alewives","C":"Genotype","D":"Homorygous"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A locus is the fixed position of a gene on a chromosome.Allele refers to alternative forms of a gene found at the same locus.', 0, 0, 0, 1790968054290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_04907a01883462fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The normal rate of breathing per minute in an adult is _____?', '{"A":"20 to 25 times","B":"15 to 20 times","C":"12 to 14 times","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A healthy adult normally breathes about 15–20 times per minute at rest.This rate can increase with exercise or decrease during sleep.', 0, 0, 0, 1790968054290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c59d2eba953034d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '"Gastric juice" is a secretion of the glands present in the ______?', '{"A":"Gall Bladder","B":"Kidneys","C":"Stomach","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gastric juice, containing hydrochloric acid and digestive enzymes.It is secreted by the glands in the stomach to aid in food digestion.', 0, 0, 0, 1790968054290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c11cb32552b9e154', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Scorpions and spiders belong to which class?', '{"A":"Insecta","B":"Crustacea","C":"Arachnida","D":"Myriapoda"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scorpions and spiders both belong to the class Arachnida.This class includes arachnids, which are characterized by having eight legs and lacking antennae.', 0, 0, 0, 1790968054290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_20c81475d472f89d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A man pushes a wall but fails to displace it. He does _____?', '{"A":"No work","B":"Negative work","C":"Maximum positive work","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Work is done only when a force produces displacement.Since the wall does not move, displacement = 0 → Work = 0.', 0, 0, 0, 1790968054290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b0d26d5e549b9891', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'All the insects have _____ pairs of legs.', '{"A":"Six","B":"Three","C":"Four","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All insects have three pairs (six total) of legs, which are attached to the thorax.This is a key characteristic distinguishing insects from other arthropods.', 0, 0, 0, 1790968054320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a676150a4f1fa087', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which scientist gave the Lock and Key Model?', '{"A":"Louis Pasteur","B":"Emil Fischer","C":"Robert Hooke","D":"Watson and Crick"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Emil Fischer proposed the lock and key model in 1894 to explain enzyme-substrate specificity.According to this model, the enzyme''s active site fits the substrate exactly like a key fits into a lock.', 0, 0, 0, 1790968054320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1a1aea8c9d69ea9b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Whatson- Crack Model suggested that DNA replication is___?', '{"A":"Conservative","B":"Duplicated","C":"Sami-Conservative","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Watson-Crick model suggested that DNA replication is semi-conservative, Meaning that each original DNA strand serves as a template to synthesize a new complementary strand, This results in two DNA molecules, each containing one original strand and one newly synthesized strand.', 0, 0, 0, 1790968054320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a09c6c5d6a0420d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The function of oesophagus in digestive system is to ____?', '{"A":"Absorb nutrients from food","B":"Mix food with digestive enzymes","C":"Pass the food to the Stomach","D":"Store food temporarily"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The oesophagus is a muscular tube that connects the pharynx (throat) to the stomach.Its main function is to transport food from the pharynx to the stomach through peristalsis (wave-like muscle contractions).', 0, 0, 0, 1790968054320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3bb481185cb7e6d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The initial setting time of Hydraulic Lime is', '{"A":"30 minutes","B":"60 minutes","C":"90 minutes","D":"120 minutes"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790968054320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_498168d663098482', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Reaction at anode is called?', '{"A":"Oxidation","B":"Reduction","C":"Redox","D":"Decomposition"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The reaction at the anode is called oxidation.In electrochemical cells, the anode is where oxidation occurs, meaning the substance loses electrons. This contrasts with the cathode, where reduction (gain of electrons) takes place.', 0, 0, 0, 1790968054320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b04775a4018b2dd2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'These are the two most common elements in the earth crust?', '{"A":"Nitrogen and silicon","B":"Oxygen and Silicon","C":"Silicon and nitrogen","D":"Silicon and phosphorous"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The two most common elements in the Earth''s crust are:Oxygen (O) – about 46.6% by weightSilicon (Si) – about 27.7% by weightTogether, they form most of the silicate minerals, which make up the majority of the crust. Last updated 14-feb-2026', 0, 0, 0, 1790968054320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c9a9c3641d51d361', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The density of water is ________?', '{"A":"2 g/cm3","B":"1.5 g/cm3","C":"1 g/cm3","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The density of pure water at standard temperature (4°C) is 1 g/cm³ or 1000 kg/m³.This value serves as a reference for measuring the density of other substances.', 0, 0, 0, 1790968054320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_823b80b860056ec1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The process of removing salts and other impurities from seawater to make it suitable for drinking and irrigation is called?', '{"A":"Water purification","B":"Water recycling","C":"Water harvesting","D":"Water Desalination"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Desalination is the process by which the dissolved mineral salts in water are removed.', 0, 0, 0, 1790968054351) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64d276f5efc62346', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who discovered the law of attraction and repulsion in electric charges?', '{"A":"Einstein","B":"Coulumb","C":"Gullelio","D":"Newton"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Charles-Augustin de Coulomb, a French physicist, discovered the law of attraction and repulsion in electric charges in the 18th century.His law, known as Coulomb''s Law, states that the force between two charges is directly proportional to the product of their charges and inversely proportional to the square of the distance between them.', 0, 0, 0, 1790968054351) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_71d809a208a60f7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which color is produced by adding together yellow and cyan?', '{"A":"Blue","B":"Red","C":"Pink","D":"Green"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In subtractive color mixing (like inks/paints), yellow + cyan = green.This is because both overlap to reflect green light while absorbing others.', 0, 0, 0, 1790968054351) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a66ab54ffe1b6bbd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which organism causes rust of wheat?', '{"A":"virus","B":"Bactria","C":"P. triticina Eriks.","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rust diseases of wheat, the most common these days is called leaf or brown rust and is caused by P. triticina Eriks.', 0, 0, 0, 1790968054351) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5f05b636f78bad8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Empirical formula of Glucose is _____?', '{"A":"CHO","B":"CH","C":"C6H6","D":"CH2O"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The empirical formula of glucose is CH2O.This represents the simplest whole-number ratio of the elements in glucose.It has a molecular formula of C6H12O6.', 0, 0, 0, 1790968054351) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d8cb76d09724019b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The SI Unit of volume is _____?', '{"A":"m³","B":"m²","C":"n²","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790968054351) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_825587f837e92e95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The unit of luminous intensity in SI system is _____?', '{"A":"Lumen (lm)","B":"Watt (W)","C":"Candela (cd)","D":"Lux (lx)"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Candela (cd) is the SI unit of luminous intensity.It is defined as the luminous intensity of a monochromatic source that emits light at a frequency of 540 x 10^12 Hz with a luminous efficiency of 683 lm/W.', 0, 0, 0, 1790968054351) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_27744bba3de0ba9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The SI unit of charge is ________?', '{"A":"Ohm","B":"Coulomb","C":"Ampere","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The coulomb, also written as its abbreviation ''C'', is the SI unit for electric charge. One coulomb is equal to the amount of charge from a current of one ampere flowing for one second. One coulomb is equal to the charge on 6.241 x 1018 protons.***', 0, 0, 0, 1790968054351) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5022d882b8be8b3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Following are examples of convex mirrors except ____?', '{"A":"Rear-view mirror","B":"Dentist mirror","C":"Blind Corner mirror","D":"Security mirror"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dentist mirrors are typically concave mirrors.The examples of convex mirrors:Rear-view mirrorsBlind Corner mirrors Security mirrors', 0, 0, 0, 1790968054382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bef635f02bc9ae1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The boiling point of water decreases at higher altitudes is due to', '{"A":"Low temperature","B":"Low atmospheric pressure","C":"High temperature","D":"High atmospheric pressure","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The boiling point of water decreases at higher altitudes due to Low atmospheric pressureIt takes less energy to raise water to the boiling point when air pressure is lower. Because there is less energy and thus less heat at a higher altitude, water will boil at a lower temperature.ND17-1-2023', 0, 0, 0, 1790968054382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7e6bb0f1c11eae31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The change in Entropy is zero for _____?', '{"A":"Reversible isobaric processes","B":"Reversible adiabatic processes","C":"Reversible isothermal processes","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a reversible adiabatic process, no heat is exchanged with the surroundings (Q = 0), so the change in entropy (ΔS) is zero.Entropy change is linked to heat transfer, and since no heat enters or leaves, entropy remains constant.', 0, 0, 0, 1790968054382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c2c7e525dddd3eff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The distance covered by a unit of time is called?', '{"A":"Force","B":"Speed","C":"Momentum","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The distance traveled by a body in unit time is called the speed of the body.S.I. unit of speed is meter per second (ms−1).ND11623', 0, 0, 0, 1790968054382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_208de9df060dd24a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The fourth state of matter is ____?', '{"A":"Plasma","B":"Steam","C":"Gas","D":"Matteroid"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plasma is the fourth state of matter, following:SolidsLiquidsGasesIt consists of ionized gases with equal numbers of positively and negatively charged particles.', 0, 0, 0, 1790968054382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ccacdf5cda1e1b36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Second highest layer of Earth''s atmosphere is _______?', '{"A":"Troposphere","B":"Stratosphere","C":"Mesosphere","D":"Thermosphere"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The stratosphere is the second layer of Earth''s atmosphere as you go upwards, lying above the troposphere and below the mesosphere.The layers of the Earth''s atmosphere, in order from the surface, are:Troposphere (up to about 12 km/7.5 miles)Stratosphere (up to about 50 km/31 miles)Mesosphere (up to about 85 km/53 miles)Thermosphere (up to about 600 km/373 miles)', 0, 0, 0, 1790968054382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5ca631c4feca12f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Lactometer is used to measure which of the following?', '{"A":"Milk","B":"Honey","C":"Ship","D":"Air"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lactometer is used for milk**A lactometer is an instrument that is used to check for the purity of milk by measuring its density. lactometer works on the principle of gravity of milk.', 0, 0, 0, 1790968054382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3110c5d7f645b743', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'To clean the ice from the roads during winter season, which of the following is used?', '{"A":"Chlorine","B":"Salt","C":"Iodine","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salt lowers the freezing point of water, causing ice to melt even in low temperatures.This process, called freezing point depression, helps keep roads safe in winter.', 0, 0, 0, 1790968054382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_05a03edb91d704f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the process of artificial rain?', '{"A":"Cloud baring","B":"Cloud seeding","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The process of artificial rain is called cloud seeding.It involves dispersing substances into the atmosphere to encourage precipitation from clouds.', 0, 0, 0, 1790968054416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_84934842a31fe7f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Cusecs is a unit to measure the amount of water released from the reservoir. It stands for ______?', '{"A":"Cubic centimeters per second","B":"Cubic meter per seconds","C":"Cubic centimeters gallons per second","D":"Cubic centimeters light per second"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cubic is a measure of flow rate.Cusec is the short form for cubic meter per seconds/cubic feet per seconds.Cusec is generally used to measure the flow rate. 1 Cusec is equal to 28.317 litres.', 0, 0, 0, 1790968054416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0e5dc828f75aaeed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'One centimeter is equal to ______?', '{"A":"1/1000 meter","B":"1/100 meter","C":"1/10 meter","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 centimeter = 0.01 meter, which is 1/100 of a meter.It is a standard unit of length in the metric system.', 0, 0, 0, 1790968054416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5e26b8a742dc7e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Diamonds are made up of _______?', '{"A":"Platinum","B":"Carbon","C":"Helium","D":"Methane"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Diamond is an allotrope of carbon.Hence, it is made up of carbon.Diamond is a very expensive ornament.It is composed of a single element carbon.', 0, 0, 0, 1790968054416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2610388d8a53ff7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following gases is dissolved in water?', '{"A":"Oxygen","B":"Carbon dioxide","C":"Nitrogen","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gases can dissolve in water. The dissolving of a gas in water depends on the interaction between the molecules of the gas and the water molecules.Oxygen, Carbon dioxide, and Nitrogen are mostly soluble gases in water.', 0, 0, 0, 1790968054416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_20cefdf7c152160b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'How many colors are there in rainbow?', '{"A":"2","B":"4","C":"5","D":"7"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation How is the Rainbow formed? 5 marksRainbow:"A rainbow is a meteorological and optical phenomenon that is caused by the reflection, refraction, and dispersion of light in water droplets"Color of Rianbow:The colors of the rainbow are:Redorangeyellowgreenblueindigoand violet.Rainbow formed:When sunlight hits a rain droplet, some of the light is reflected.The electromagnetic spectrum is made of light with many different wavelengths, and each is reflected at a different angle.Thus, the spectrum is separated, producing a rainbow.', 0, 0, 0, 1790968054416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_98d069631cc3ef02', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which type of fire, extinguisher uses for petroleum fire?', '{"A":"Solid","B":"Liquid","C":"Foam","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For petroleum fires, the extinguisher type used is Foam.Foam extinguishers effectively smother the fire by cutting off the oxygen supply to the flammable liquid.They also provide a cooling effect, helping to prevent re-ignition of the petroleum.', 0, 0, 0, 1790968054416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_341472faeae0bb42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The process of making copies of DNA is called?', '{"A":"Transcription","B":"Replication","C":"Mutation","D":"Translation"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Replication is the process by which a cell makes an exact copy of its DNA before cell division, ensuring that the new cell receives a complete set of genetic instructions.This process is crucial for the transmission of genetic information from one generation of cells to the next.', 0, 0, 0, 1790968054416) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_879cb01f0b12706f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is used to make cosmetics?', '{"A":"Sulphur","B":"Petroleum Jelly","C":"Wax","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Petroleum jelly is commonly used in cosmetics for moisturizing and protecting skin.It forms a barrier that locks in moisture, making it ideal for creams, lip balms, and lotions.', 0, 0, 0, 1790968054445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5b8974194a49d36f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which mosquito transmits viruses of dengue fever in humans?', '{"A":"Anopheles","B":"Culex","C":"Aedes","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Aedes mosquito, especially Aedes aegypti, is the primary vector of dengue fever.Anopheles transmits malaria.Culex transmits other diseases like West Nile virus.', 0, 0, 0, 1790968054445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd54e77cf4917658', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Electrocardiography (ECG or EKG) is used for the diagnosis of the ailment of the _____?', '{"A":"Brain","B":"Heart","C":"Liver","D":"Kidneys"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ECG (Electrocardiogram) is a test used to measure the electrical activity of the heart.It is commonly used for the diagnosis of heart-related ailments, such as:Arrhythmias (irregular heart rhythms)Coronary artery diseaseCardiac arrestsHeart failure', 0, 0, 0, 1790968054445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_02c88b892f2c612f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Wright brothers are famous for ______?', '{"A":"Invention  of Airplane","B":"Discovery of Aviation","C":"Discovery of TV","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Wright brothers completed the world''s first successful controlled powered flight in 1903The Wright brothers name are: Orville Wright and Wilbur Wright They were American inventors and aviation pioneers.', 0, 0, 0, 1790968054445) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_65e8d7acf6d522d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the full form of AIDS?', '{"A":"Acquired immunodeficiency syndrome","B":"Accepted immunodeficiency syndrome","C":"Acquired immunodeficiency symptoms","D":"Accepted immunodeficiency symptoms"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aids way to spread is TouchAIDS stands for Acquired Immunodeficiency Syndrome.HIV stands for Human Immunodeficiency Virus.HIV attacks the immune system of the body AIDS virus has single-stranded RNAAIDS is not a genetic disorder', 0, 0, 0, 1790968054446) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6eedc9307ca951f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A fuse wire (fuse) is used to _____?', '{"A":"Prevent damage due to unusually high voltage","B":"Convert AC into DC","C":"Convert DC into AC","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A fuse wire is designed to protect electrical devices by melting when the current exceeds a safe level, preventing damage from high voltage or short circuits.It acts as a safety device, breaking the circuit and stopping the flow of excessive current.Fuse wires are made of materials with a low melting point, like tin or lead alloy.', 0, 0, 0, 1790968054446) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b02b572c8637c53b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Mass per unit volume is called?', '{"A":"Volume","B":"Density","C":"Meter","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mass per unit volume of a substance is called density (density = mass/volume).The formula of Density is: D=m/v****Here D is density,M is mass &V is Volume.Density is commonly expressed in units of grams per cubic centimeter.The standard units are kg/m³', 0, 0, 0, 1790968054446) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eaf4d81cf13f9528', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Carrot is a good source of which?', '{"A":"Vitamin D","B":"Vitamin C","C":"Vitamin A","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carrot is a good source of Vitamin A. Deficiency of Vitamin A causes nigh blindness.', 0, 0, 0, 1790968054446) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aaa8791136bd2aed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'It is dangerous to sleep under trees at night because plants give out _____?', '{"A":"Carbon monoxide","B":"Less oxygen","C":"More oxygen","D":"Carbon dioxide"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At night, trees switch from photosynthesis to respiration, releasing carbon dioxide instead of oxygen.This can increase CO2 levels around the tree, which may be harmful to breathe in for prolonged periods.There''s no photosynthesis (which produces oxygen) during the night.During the day, trees perform photosynthesis, taking in carbon dioxide (CO2) and releasing oxygen (O2).', 0, 0, 0, 1790968054476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_be385c5076669004', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In a railway track, two rails are joined end to end with a gap tin between them because?', '{"A":"Steel can be saved","B":"Accidents due to contraction in winter can be avoided","C":"Air gaps are necessary for bearing the weight of running train","D":"Accidents due to expansion in summer can be avoided"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Railway tracks are made of steel, which expands in summer heat. The gaps between rails allow space for this expansion, preventing the tracks from buckling or derailing trains.', 0, 0, 0, 1790968054476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6423b356fd48bf67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Guglielmo Marconi invented _____?', '{"A":"Television","B":"Camera","C":"Radio","D":"Tape recorder"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Guglielmo Marconi was an Italian inventor and electrical engineer who is credited with the invention of the radio.His work on long-distance radio transmission and the development of Marconi''s law revolutionized wireless communication in the early 20th century.', 0, 0, 0, 1790968054476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75c2c4669a5d5885', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Pulse beat is measured from ____?', '{"A":"Artery","B":"Capillary","C":"Vein","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pulse beat is measured from an artery because it reflects the rhythmic pumping of the heart.Common sites include the radial artery (wrist) and carotid artery (neck).', 0, 0, 0, 1790968054476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a2a3335f573e13ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the condition commonly known as "lockjaw" caused by?', '{"A":"Diphtheria","B":"Pertussis","C":"Tetanus","D":"Meningitis"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tetanus is a bacterial infection that can cause muscle stiffness and spasms.It particularly in the jaw muscles, leading to the characteristic symptom of "lockjaw".', 0, 0, 0, 1790968054476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62f34fc2ac7e7447', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'An instrument is used to measure altitude of an object from sea level?', '{"A":"Altimeter","B":"Barometer","C":"Hygrometer","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Altimeters:Function:It primarily measures altitude by detecting changes in atmospheric pressure. Aviation use:Pilots heavily rely on altimeters to determine their aircraft''s height above sea level during flight. Types:There are different types of altimeters including pressure altimeters and radio altimeters.', 0, 0, 0, 1790968054476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_74accff40e490494', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of following is used in pencils as a lubricant?', '{"A":"Graphite","B":"Argon","C":"Helium","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Graphite is a crystalline form of the element carbon. It consists of stacked layers of graphene. Graphite occurs naturally and is the most stable form of carbon under standard conditions.', 0, 0, 0, 1790968054476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_58c987390c8a0439', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Ozone Layer restricts which one of the following?', '{"A":"Infrared Rays","B":"Ultraviolet Rays","C":"X-Rays","D":"Gamma Rays"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ozone layer in the stratosphere absorbs and restricts ultraviolet (UV) radiation from the sun.It protecting life on Earth from harmful UV rays.', 0, 0, 0, 1790968054476) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bb107fd45736a9ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Steel is measured in _____?', '{"A":"Kilograms","B":"Litres","C":"Meters","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Steel, being a solid metal, is measured by weight.The standard unit for measuring steel is kilograms or tons, depending on the quantity.', 0, 0, 0, 1790968054507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_78226836fcb46a0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Reproduction is very important to the survive of _______?', '{"A":"Bacteria","B":"Species","C":"Fungi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Reproduction ensures the continuation of a species by passing genetic material to offspring.It maintains biodiversity and helps species adapt to environmental changes.', 0, 0, 0, 1790968054507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9b5e97897e5fdb5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Enzymes are responsible for assembly of _____?', '{"A":"Carbohydrate","B":"Nucleic Acid","C":"Protein","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Enzymes (e.g., ribosomes, polymerases) catalyze the assembly of proteins from amino acids during translation.While enzymes assist in building various biomolecules, their most direct and universal role is in protein synthesis.', 0, 0, 0, 1790968054507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ceb9d7e2005cbb1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Mitosis is divided into _____?', '{"A":"Cytokinesis","B":"Karyokinesis","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mitosis Stages:Karyokinesis: Division of the nucleus (prophase, metaphase, anaphase, telophase).Cytokinesis: Division of the cytoplasm (occurs after karyokinesis).', 0, 0, 0, 1790968054507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bcd0b10b55a35d50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Omnivores that eat only _____?', '{"A":"Only plants","B":"Only animals","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Omnivores are animals that eat both plants and animals.They have adaptations that allow them to digest and extract nutrients from a wide variety of food sources, including fruits, leaves, insects, small animals, and even carrion.Examples of omnivores include humans, bears, pigs, chimpanzees, and raccoons.Only plants: Herbivores (e.g., cows).Only animals: Carnivores (e.g., lions).', 0, 0, 0, 1790968054507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4bc8e7688d16fc8a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following has the lowest melting point?', '{"A":"Zinc","B":"Lead","C":"Tin","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tin has the lowest melting point (~232°C) among.Zinc (~419°C)Gold (~1064°C)Lead (~327°C)', 0, 0, 0, 1790968054507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_54f61bb368500fbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Mushrooms belong to which of the following groups?', '{"A":"Algae","B":"Fungi","C":"Bacteria","D":"Protozoa"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fungi: Mushrooms are a type of fungi.Algae: Mostly aquatic and photosynthetic, not related to mushrooms.Bacteria: Microscopic organisms, not related to mushrooms.Protozoa: Single-celled organisms, unlike multicellular mushrooms.', 0, 0, 0, 1790968054507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_73f213a0df0fbf8b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The cross product of two vectors is negative vector when _____?', '{"A":"They are perpendicular vectors","B":"They are parallel vectors","C":"They are anti parallel vectors","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cross product (A × B) is a vector whose magnitude is given by:| A × B | = |A||B| sinθIts direction follows the right-hand rule.', 0, 0, 0, 1790968054507) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6cf43407c01f4791', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The cross product of two vectors does not obey ______?', '{"A":"Associative law","B":"Communicative law","C":"Distributive law","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cross product of two vectors A × B ≠ B × A; in fact, A × B = –(B × A), so it is not commutative.However, it does obey the distributive law over addition, and associative law applies with scalar multiplication but not for three vector cross products.', 0, 0, 0, 1790968054542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4d4ae70b58a0a3c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Matter having no definite shape and volume is called _____?', '{"A":"Liquid","B":"Solid","C":"Gas","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gas: No definite shape or volume – Expands to fill any container.Example: Oxygen, CO₂.Solid: Fixed shape and volume (e.g., iron).Liquid: Fixed volume, no fixed shape (e.g., water).', 0, 0, 0, 1790968054542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_be5755bf956deef0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'All elements are made up of small indivisible, indestructible particles called atoms is given by _____?', '{"A":"Bohr","B":"Atom","C":"Dalton","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation John Dalton proposed the Atomic Theory in the early 1800s, stating that all elements are made of indivisible atoms.He described atoms as indestructible and identical for each element, laying the foundation of modern chemistry.', 0, 0, 0, 1790968054542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed0f93f0fa37a183', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What does a Seismograph record?', '{"A":"Heatbeat","B":"Earthquake","C":"Rain","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A seismograph is an instrument used to detect and record earthquakes.It consists of a mass attached to a fixed baseDuring an earthquake, the base moves and the mass does not.', 0, 0, 0, 1790968054542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_84df6378140d0c50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'When blue litmus paper dipped acids, its colour change to ____?', '{"A":"Pink","B":"Blue","C":"Yellow","D":"Red"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When blue litmus paper is dipped in an acid, it turns red.This is because the acid changes the color of the litmus paper from blue to red.Note: When red litmus paper is dipped in a base, it turns blue.', 0, 0, 0, 1790968054542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0822fbbd778c07b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Animals feeding on plants are called _____?', '{"A":"Detritivores","B":"Herbivores","C":"Omnivores","D":"Carnivores"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Herbivores: These animals eat only plants. The word "herbivore" comes from the Latin words "herba" (meaning plant) and "vorare" (meaning to eat).Detritivores: These animals eat decaying organic matter.Omnivores: These animals eat both plants and animals. Carnivores: These animals eat only meat.', 0, 0, 0, 1790968054542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fae95feab162b09d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Biological system of nomenclature is given by _____?', '{"A":"Gregor Mendel","B":"Charles Darwin","C":"Carolus Linnaeus","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carolus Linnaeus developed the binomial nomenclature system for naming organisms.Each species is given a two-part Latin name: Genus and Species (e.g., Homo sapiens).', 0, 0, 0, 1790968054542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_36c0baa85c4b4448', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What divides the Earth into the Northern and the Southern Hemispheres?', '{"A":"South Pole","B":"Moon","C":"Equator","D":"North Pole"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Equator is an imaginary line that divides the Earth into the Northern and Southern Hemispheres.It lies at 0° latitude.It is equidistant from the North and South Poles.', 0, 0, 0, 1790968054542) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dcdc6415fd2c26a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Special enzyme used to cut DNA are called _____?', '{"A":"Hydrolase","B":"Endonucleases","C":"Phosphorylases","D":"Esterase"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The special enzyme used to cut DNA at specific sequences is called a restriction enzyme or restriction endonuclease. These enzymes are crucial for various molecular biology techniques like genetic engineering and DNA fingerprinting. They recognize specific sequences within the DNA and cleave the molecule at those sites.', 0, 0, 0, 1790968054572) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e9f67a53725589c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A type of transpiration occurring through the stems of plants by special openings?', '{"A":"Cuticular","B":"Lenticular","C":"Stomatal","D":"Dermal"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The type of transpiration occurring through special openings in plant stems is called lenticular transpiration. These openings, known as lenticels, are small pores in the bark of woody stems and allow for gas exchange and water vapor loss.', 0, 0, 0, 1790968054572) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_40495c107178428c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The process of ATP generation on thylakoid membranes _____?', '{"A":"Glycolysis","B":"Oxido-reduction","C":"Respiration","D":"Chemiosmosis"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chemiosmosis is the process where ATP is generated by using the energy stored in a proton gradient across a membrane. In the context of photosynthesis, this proton gradient is established across the thylakoid membrane in the chloroplast.', 0, 0, 0, 1790968054572) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d8f0fabd689016c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In echinoderms, water enters in canals through sieve like cells called _____?', '{"A":"Madrepore","B":"Pits","C":"Pores","D":"Plasmodesmata"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In echinoderms, water enters the water vascular system through a sieve-like structure called the madreporite. This structure, often a small, light-colored plate, acts as an opening to the internal water-filled canals. Water then flows through a series of canals, including the stone canal and radial canals, eventually reaching the tube feet.', 0, 0, 0, 1790968054572) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cfd53a04d367bffc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In bryophyte, the dominant generation is _____?', '{"A":"Sporophyte","B":"Angiosperms","C":"Gametophyte","D":"Saprophyte"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In bryophytes, the gametophyte generation is dominant. This means the leafy, green, haploid structure that is typically seen is the gametophyte, which is the most visible and longest-lived part of the bryophyte life cycle. The diploid sporophyte is generally smaller and dependent on the gametophyte for survival.', 0, 0, 0, 1790968054572) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e9ba6cb13f8fb184', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'All vascular plants are placed in the which group?', '{"A":"Bryophyta","B":"Tracheophyta","C":"Eukaryoteae","D":"Gymnospermae"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tracheophyta includes all vascular plants that have specialized tissues (xylem and phloem) for water and nutrient transport.It includes ferns, gymnosperms, and angiosperms, but not bryophytes (which are non-vascular).', 0, 0, 0, 1790968054572) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7e58234789e16604', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The mode of movement in zooflagellates is ______?', '{"A":"Cilia","B":"Flagella","C":"Pseudopods","D":"Pilli"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The primary mode of movement in zooflagellates is flagellar movement. Zooflagellates, also known as flagellates, are protozoa that use one or more flagella for locomotion. These flagella are whip-like appendages that propel the organism through their environment.', 0, 0, 0, 1790968054572) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d4d296cf314f5e01', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The accessory pigment used by cyanobacteria?', '{"A":"Phycoerythrin","B":"Glycogen","C":"Phycobilins","D":"Chlorophyll a"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cyanobacteria utilize phycobilins, specifically phycocyanin (blue) and phycoerythrin (red), as accessory pigments in addition to chlorophyll a. These pigments help cyanobacteria absorb light across a wider range of wavelengths than chlorophyll a alone, enhancing their photosynthetic efficiency.', 0, 0, 0, 1790968054572) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fbde84c2839ca07e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The single stranded RNA viruses causing tumors are an example of ______?', '{"A":"Retrovirus","B":"Pox virus","C":"Pro virus","D":"Bacteriophage"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Retroviruses are single-stranded RNA viruses that use reverse transcriptase to convert RNA into DNA.Some retroviruses can cause tumors by integrating into the host genome and disrupting normal cell regulation.', 0, 0, 0, 1790968054603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_746bc291a8c96cc2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following organelle is not present in viruses?', '{"A":"DNA","B":"Protein coat","C":"Collar","D":"Ribosomes"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Viruses lack organelles like ribosomes, mitochondria, and Golgi apparatus. They are simple particles composed of genetic material (DNA or RNA) and a protein coat. They need to infect a host cell to use the host''s ribosomes to replicate.', 0, 0, 0, 1790968054603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3332c7b6883b19d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The plastids having color other than green?', '{"A":"Chloroplasts","B":"Chromoplasts","C":"Leucoplasts","D":"Amyloplasts"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation These plastids contain pigments other than chlorophyll, giving them colors like yellow, orange, and red. They are responsible for the vibrant colors in fruits, flowers, and mature leaves.', 0, 0, 0, 1790968054603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_05374c7d74b32fa8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'f-block elements are also called ______?', '{"A":"Inner transition elements","B":"Non-typical transition elements","C":"Outer Transition elements","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation F-block elements are also known as inner transition elements. They include the lanthanides and actinides and are located at the bottom of the periodic table, separated into two rows. This placement is due to their electron configuration, where the "n-2" f orbitals are being filled.', 0, 0, 0, 1790968054603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ae9e71492617a0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Lime is used for ______?', '{"A":"For refining of metals","B":"In paper industry","C":"As dehydrating agents","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lime (CaO or Ca(OH)₂) is used in metal refining, paper manufacturing, and as a dehydrating agent in chemical processes.Its versatility makes it valuable in multiple industrial applications.', 0, 0, 0, 1790968054603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_96f628014f5a0c42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The shielding effect across the period _______?', '{"A":"Increases","B":"Decrease","C":"Moderate","D":"Same"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shielding effect decreases across a period.This is because the increasing nuclear charge is not fully counterbalanced by the same number of inner electrons, resulting in a weaker shielding effect.', 0, 0, 0, 1790968054603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_135201a4c028d3db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following statement is not correct? (a) Sigma bond is weaker than a pi bond (b) Sigma bond is stronger than a pi bond (c) Double bond is stronger than a single bond (d) Double bond is shorter than a single bond', '{"A":"Sigma bond is weaker than a pi bond","B":"Sigma bond is stronger than a pi bond","C":"Double bond is stronger than a single bond","D":"Double bond is shorter than a single bond"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The incorrect statement is "sigma bond is weaker than a pi bond" because a sigma bond is stronger than a pi bond.Sigma bond: Formed by direct head-on overlap of orbitals, resulting in a strong bond. Pi bond: Formed by sideways overlap of p orbitals, resulting in a weaker bond compared to a sigma bond.', 0, 0, 0, 1790968054603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7a6914c1a6c4d526', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Biosphere includes _____?', '{"A":"Atmosphere","B":"Hydrosphere","C":"Lithosphere only","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The biosphere includes all of these: the Atmosphere, the Hydrosphere, and the Lithosphere. The biosphere is the zone on Earth where life exists, encompassing the living organisms and their interactions with the surrounding environment, including the atmosphere, hydrosphere (water bodies), and lithosphere (land).', 0, 0, 0, 1790968054603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_675cf1769d673831', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Molecular crystal are generally ______?', '{"A":"Hard","B":"Soft","C":"Unstable","D":"Stable"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Molecular crystals are generally soft and stable. They are composed of molecules held together by relatively weak intermolecular forces, which results in them being easily deformed and having low melting points. While they are generally stable under normal conditions, they can become unstable under extreme temperatures or pressures.', 0, 0, 0, 1790968054630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8a5c66aa42c17fdb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Methyl ketones, are characterized by _____?', '{"A":"Tollen''s agent","B":"Gringnard reagent","C":"Iodoform test","D":"Fehling solution"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The iodoform test is a chemical reaction used to identify the presence of a methyl ketone group (CH3-CO-) in a compound. When a methyl ketone reacts with iodine and sodium hydroxide, it produces a yellow precipitate of iodoform. This makes the iodoform test a reliable way to detect methyl ketones.', 0, 0, 0, 1790968054630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a4c61625dde42cd9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'When alcohol is made to react with alkyl magnesium halide, the product is _____?', '{"A":"Epoxide","B":"Alkane","C":"Alkene","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When an alcohol reacts with an alkyl magnesium halide (Grignard reagent), the product is an alkane. The Grignard reagent acts as a strong base, removing the acidic hydrogen from the alcohol''s hydroxyl group (-OH) and forming a new carbon-hydrogen (C-H) bond, thus creating an alkane. The other product is a magnesium alkoxide salt.', 0, 0, 0, 1790968054630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45ee782c5c6524d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Aromatization of n-heptane gives?', '{"A":"Naphthalene","B":"Benzene","C":"Methyl cyclohexane","D":"Toluene"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The aromatization of n-heptane primarily yields toluene. This process involves the dehydrogenation and cyclization of n-heptane, facilitated by catalysts like Cr2O3/Al2O3 at elevated temperatures, forming a benzene ring with a methyl substituent.', 0, 0, 0, 1790968054630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_54e8d26d9f9c4b33', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Sabatier-Sender''s reaction can be used  to prepare _____?', '{"A":"Alkynes","B":"Alkenes","C":"Alkanes","D":"Nome of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sabatier-Senderens reaction is a hydrogenation reaction, meaning it adds hydrogen to unsaturated hydrocarbons (alkenes and alkynes) to convert them into saturated hydrocarbons (alkanes).', 0, 0, 0, 1790968054630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_11a1e3e3bf6276de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '27 grams of Al will react completely with how much mass of O2 to produce Al₂O₃?', '{"A":"8 g","B":"16 g","C":"32 g","D":"24 g"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Balanced equation:4Al + 3O₂ → 2Al₂O₃Molar masses: Al = 27 g/mol, O₂ = 32 g/mol108 g Al reacts with 96 g O₂ → 27 g Al reacts with 24 g O₂.Proportion:96/108 × 27 = 24 g', 0, 0, 0, 1790968054630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f74c6990cac0c94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The comparative rates at which the solutes moves in the paper chromatography depends upon ______?', '{"A":"Size of paper","B":"Rf values","C":"Size of chromatographic tank","D":"Temperature of experiment"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The comparative rates at which solutes move in paper chromatography depend on Rf values. Rf values (retention factors) represent the ratio of the distance traveled by a solute to the distance traveled by the solvent front on the paper. Since different solutes have different polarities and affinities for the mobile and stationary phases, they will travel at different speeds, resulting in unique Rf values. Therefore, the comparative movement of solutes is directly related to their Rf values.', 0, 0, 0, 1790968054630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5d45b0c0c0fe09f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The unit of electric field intensity other than N/C is ______?', '{"A":"V/C","B":"V/m","C":"V/A","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Electric field intensity is defined as force per unit charge (N/C) or potential difference per unit distance (V/m).So, V/m is an equivalent.It is commonly used unit for electric field intensity.', 0, 0, 0, 1790968054630) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75ba2732895e00df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The term "RC" has same unit as that of _______?', '{"A":"Energy","B":"Capacitance","C":"Time","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The product RC (Resistance × Capacitance) gives the time constant in an RC circuit.Its unit is Ohm × Farad = seconds (s), which is the unit of time.', 0, 0, 0, 1790968054659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6dda8b88ed1238f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The prefix femto refers to _____?', '{"A":"10¹²","B":"10⁻¹²","C":"10⁻¹⁵","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Femto (f) is a prefix in the metric system that represents 10⁻¹⁵ (one quadrillionth).It is commonly used in physics and chemistry, such as femtoseconds (fs) = 10⁻¹⁵ seconds.', 0, 0, 0, 1790968054659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8d7c265ed8829a01', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The intestinal parasite causes amoebic dysentery in humans is _____?', '{"A":"Trichonymphas","B":"Pelomyxa palustris","C":"Entamoeba histolytica","D":"Apocomplexans"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The intestinal parasite that causes amoebic dysentery in humans is Entamoeba histolytica.Amoebic dysentery is a disease caused by the protozoan parasite Entamoeba histolytica.', 0, 0, 0, 1790968054659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3029f446218a72ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The term lodicules refers to _____?', '{"A":"Bract","B":"Bracteoles","C":"Perianth","D":"Calyx"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lodicules are small, scaly structures found at the base of a grass flower. They are essentially modified parts of the perianth, which is the non-reproductive part of a flower. The perianth consists of sepals and petals (or tepals if they are undifferentiated). In grasses, the perianth is reduced and modified into these small scales called lodicules.', 0, 0, 0, 1790968054659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed85f0604ec99d07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The total transpiration takes place through cuticle is ______?', '{"A":"5 - 7 %","B":"1 - 7 %","C":"5 - 8 %","D":"2 - 5 %"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This refers to the loss of water through the cuticle, the waxy layer on the surface of leaves. Sources consistently state that approximately 5-7% of total transpiration occurs via the cuticle.', 0, 0, 0, 1790968054659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_435d0eb0dcf96869', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Cyclosis and amoeboid movements are because of _______?', '{"A":"Centrioles","B":"Microfilaments","C":"Intermediate filaments","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Microfilaments (mainly made of actin) are responsible for cell movements like cyclosis (cytoplasmic streaming) and amoeboid movement.They help in changing cell shape, enabling movement in amoebas and streaming in plant cells.', 0, 0, 0, 1790968054659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5d2ca2cf07f71bb0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Break down of alveoli of lungs is called ______?', '{"A":"Asthma","B":"Tuberculosis","C":"Emphysema","D":"Lungs cancer"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The breakdown of alveoli in the lungs is called Emphysema. Emphysema is a lung condition where the small air sacs (alveoli) are damaged, causing them to break down and merge into larger spaces, reducing the surface area available for gas exchange.', 0, 0, 0, 1790968054659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_337e05be238113db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Family of sweet pea is _____?', '{"A":"Fabaceae","B":"Solanaceae","C":"Rosaceae","D":"Poaceae"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sweet peas are annual climbing plants with fragrant, butterfly-shaped flowers. They are part of the genus Lathyrus within the Fabaceae family. The name Lathyrus is derived from the Greek word for "pea," and odoratus means "scented". They are cultivated for their beautiful and fragrant flowers.', 0, 0, 0, 1790968054659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1b7458169a4909a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In the protostomes, the blastopore forms the _____?', '{"A":"Mouth","B":"Brain","C":"Anus","D":"Excretory pore"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A protostome is an animal where the first opening that forms during embryonic development (the blastopore) becomes the mouth.While the second opening develops into the anus.', 0, 0, 0, 1790968054689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5ac41a8f9aa19b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Amount of NaOH required to prepare 250 cm³ of 1 M solution is?', '{"A":"10 g","B":"6 g","C":"2 g","D":"4 g"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To prepare 250 cm³ (or 250 mL) of a 1 M NaOH solution, you need 10 grams of NaOH. This is because the molar mass of NaOH is 40 g/mol, and a 1 M solution contains 1 mole of solute per liter of solution. Therefore, 250 mL (0.25 L) of a 1 M solution would require 0.25 moles of NaOH, which translates to 10 grams (0.25 moles * 40 g/mol).', 0, 0, 0, 1790968054689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3446e5c505d50fb5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The unit of rate constant for zero order reaction is _____?', '{"A":"dm⁻³ s⁻¹","B":"mole dm⁻³ s⁻¹","C":"dm⁻³  mole⁻¹ s⁻¹","D":"mole s⁻¹"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct unit of the rate constant for a zero-order reaction is mol dm⁻³ s⁻¹ or mol L⁻¹ s⁻¹. Zero-order reactions have a rate that is independent of the concentration of reactants. Therefore, the rate constant (k) will have the same units as the reaction rate, Which are typically expressed as concentration per unit time.In this case, since the concentration unit is mol/L (or mol/dm³), The rate constant unit becomes mol dm⁻³ s⁻¹ or mol L⁻¹ s⁻¹.', 0, 0, 0, 1790968054689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c779f17e8ad65fec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Standard enthalpy change is measured at _____?', '{"A":"298°K","B":"273°C","C":"273°K","D":"373°K"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Standard enthalpy change is measured at a defined pressure of 101 kPa (or 1 bar, according to Testbook.com) and a temperature of 298 K (25°C).', 0, 0, 0, 1790968054689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_346123dc4ffd2baa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Stronger the oxidizing agent, greater is the _____?', '{"A":"Oxidation potential","B":"Redox potential","C":"Reduction potential","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A strong oxidizing agent has a greater Reduction potential. An oxidizing agent readily accepts electrons, which corresponds to a high reduction potential. A higher reduction potential indicates a greater tendency for a substance to be reduced (gain electrons) and thus act as an oxidizing agent.', 0, 0, 0, 1790968054689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f45c95d81100a9f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Ionic solids are characterized by _____?', '{"A":"Good conductivity","B":"High vapour pressure","C":"Solubility in polar solvents","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ionic solids (like NaCl) are generally soluble in polar solvents (like water) due to strong ion-dipole interactions.They are poor conductors in solid state but conduct when molten or dissolved, and they have low vapor pressure.', 0, 0, 0, 1790968054689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f476d8b65fd283e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Quantum numbers for 2p orbitals are _____?', '{"A":"n = 2, I = 0","B":"n = I, 1 = 0","C":"n = 1, I = 2","D":"n = 2, I = 1"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For 2p orbitals, the principal quantum number (n) is 2.The azimuthal quantum number (l) for a p-orbital is 1.So, n = 2, l = 1 is correct.', 0, 0, 0, 1790968054689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab0b3184fa72bd08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one of the following is not an isomorphous pair?', '{"A":"Na₂CO₃, CaCO₃","B":"NaF, MgO","C":"K₂SO₄, K₂Cr₂O₇","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The pair that is not isomorphous is Na₂CO₃, CaCO₃. While both compounds have similar chemical formulas.The difference in ionic radii between sodium and calcium leads to different crystal structures, making them not isomorphous.', 0, 0, 0, 1790968054689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_81f12285bc98bbc8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The range of the projectile is maximum when it is projected at an angle of ______?', '{"A":"20°","B":"30°","C":"45°","D":"60°"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is the longest distance covered by the object during projectile motion.When the angle of projection is 45°, the maximum horizontal range is obtained.', 0, 0, 0, 1790968054720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a789483d041974f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '73.650 rounded up to one decimal is ______?', '{"A":"73.6","B":"73.7","C":"74","D":"73.65"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 73.650 rounded up to one decimal place is 73.7. When rounding up, if the digit to the right of the desired decimal place is 5 or greater, You increase the digit in the desired decimal place by one. Since 5 in the hundredth place is greater than or equal to 5, the tenths place digit (6) is increased to 7.', 0, 0, 0, 1790968054720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cbd4aa6905bc1dcd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '100 radians are equal to _____?', '{"A":"57.3°","B":"573°","C":"5730°","D":"5.73°"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To convert radians to degrees, you multiply the number of radians by 180/π. 100 radians multiplied by 180/π is approximately 5729.58 degrees, which rounds to 5730 degrees.', 0, 0, 0, 1790968054720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e738a48f793188b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The working carburetor of a car uses ______?', '{"A":"Equation of continuity","B":"Gravitational law","C":"Bernoulli''s theorem","D":"Stoke''s theorem"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A carburetor uses the principle of Bernoulli''s equation, which states that as the speed of a fluid increases, its pressure decreases. In a carburetor, air flows through a constricted section called a venturi. This increased airflow creates a lower pressure area, which then draws fuel from the fuel reservoir into the air stream, effectively mixing them.', 0, 0, 0, 1790968054720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a9c62a8fea5075e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'One complete round trip of a vibrating body is called ______?', '{"A":"Amplitude","B":"Vibration","C":"Frequency","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation One complete round trip (back and forth motion) of a vibrating body is called a vibration.It represents a single cycle of motion in oscillatory systems like sound waves or springs.', 0, 0, 0, 1790968054720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_43ac80faaa7eb892', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which type of signals are used by sonar?', '{"A":"Radio wave","B":"Light waves","C":"Sound waves","D":"Microwaves"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sonar (Sound Navigation and Ranging) uses sound waves to detect and locate objects underwater. It works by emitting sound pulses into the water And listening for the echoes that bounce back from objects like submarines, fish, or the seafloor.Sonar is commonly used in navigation, fishing, and underwater exploration.', 0, 0, 0, 1790968054720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c830770df178729', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The dot product of a vector with itself is equal to?', '{"A":"Zero","B":"A","C":"2A","D":"A²"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The dot product of a vector with itself is equal to the square of its magnitude, or |A|². The dot product of two vectors A and B is defined as: A · B = |A| |B| cos θ, where θ is the angle between the vectors. When a vector is dotted with itself, the angle θ becomes 0 (since the vectors are parallel), and cos 0 = 1. Therefore, A · A = |A| |A| cos 0 = |A|².', 0, 0, 0, 1790968054720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b7b07900932b34bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Where are Irregular Bones found in the human body?', '{"A":"Hands only","B":"Arms and Legs","C":"Spine, Face, and Hip","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Irregular bones have complex shapes that don’t fit into other categories like long or flat bones.They are found in the spine (vertebrae), face (facial bones), and hip (pelvis).', 0, 0, 0, 1790968054720) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d66ec6604521079', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Optical fiber operates on the principle of ______?', '{"A":"Laser technology","B":"Photo-electric","C":"Total internal reflectance","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Optical fibers transmit data as light signals.The signal is confined within the fiber due to the phenomenon where light hits a medium boundary.It is completely reflected back.', 0, 0, 0, 1790968054752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b43f08dc47ce087', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Bile Juice is secreted by _____?', '{"A":"Pancreas","B":"Stomach","C":"Kidneys","D":"Gall Bladder"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bile juice is produced by the liver.It is stored in the gall bladder.From the gall bladder, it is released into the small intestine.Bile juice aids digestion.', 0, 0, 0, 1790968054752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3161cb7cdb9b16e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Ductless gland are known as ______?', '{"A":"Sweat glands","B":"Endocrine glands","C":"Exocrine glands","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Endocrine glands are ductless glands that release hormones directly into the bloodstream.In contrast, exocrine glands (e.g., sweat and salivary glands) have ducts to release secretions.', 0, 0, 0, 1790968054752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5181b857e254a7a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Time period of seconds pendulum is ______ second.', '{"A":"1","B":"0.1","C":"2","D":"0.5"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A seconds pendulum is defined as a pendulum with a time period of 2 seconds — 1 second for a swing in one direction and 1 second for the return.It completes one full oscillation in 2 seconds, making it useful for regulating clocks.Additional Information:1 second → Half oscillation of a seconds pendulum0.1 second → Very fast oscillating system2 seconds → Time period of a seconds pendulum0.5 second → Faster pendulum, shorter length than seconds pendulum', 0, 0, 0, 1790968054752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e3866893bec67072', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is a unit of length?', '{"A":"Liter","B":"Kilogram","C":"Meter","D":"Second"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Meter is the SI unit of length.It is used to measure distance or height.Additional Information:Liter = unit of volumeKilogram = unit of massSecond = unit of time', 0, 0, 0, 1790968054752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bef2435fb4da0854', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The most dangerous type of radiation Is?', '{"A":"Alpha radiation","B":"Beta radiation","C":"Gamma radiation","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gamma radiation is the most dangerous type of radiation. it has high energy and can penetrate most materials, including human tissue. It is highly penetrating and can cause significant biological damage.', 0, 0, 0, 1790968054752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_680ad758d305bad3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Polythene is formed when polymers of ethene combined together. The polythene is classified as which one of the following type of plastic?', '{"A":"Elastic polymers","B":"Thermoplastic","C":"Thermosetting","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Polythene is a thermoplastic because it softens when heated and can be reshaped.It is formed by polymerization of ethene molecules.', 0, 0, 0, 1790968054752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_89b2728c82d0a655', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Greenhouse effect is an environmental problem which is caused by increasing amount of ________ in the atmosphere.', '{"A":"Oxygen","B":"Argon","C":"Nitrogen","D":"Carbon Dioxide"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The greenhouse effect is an environmental problem caused by the increasing amount of carbon dioxide (CO2) in the atmosphere.Primarily due to human activities such as burning fossil fuels, deforestation, and land-use changes.This excess CO2 traps heat and leads to global warming and climate change.', 0, 0, 0, 1790968054752) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d7994829e60ee5ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which is the lowest layer of atmosphere?', '{"A":"Troposphere","B":"Stratosphere","C":"Mesosphere","D":"Exosphere"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Troposphere is the lowest layer of the atmosphere where all weather phenomena occur and where we live.Exosphere is the outermost layer, gradually merging into space, containing very thin air and satellites.', 0, 0, 0, 1790968054785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2598384f9b1293f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which layer near the surface of earth is called?', '{"A":"Thermosphere","B":"Troposphere","C":"Mesosphere","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The troposphere is the lowest layer of Earth''s atmosphere. The Layers of atmosphere are: the troposphere, stratosphere, mesosphere and thermosphere.', 0, 0, 0, 1790968054785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c95252a14b51cfcd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Infants (children) should be immunized with BCG (Bacille Calmette-Guerin) vaccines against?', '{"A":"Malaria","B":"Tuberculosis","C":"Measles","D":"Hepatitis"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation BCG (Bacille Calmette-Guerin) vaccine is primarily used to protect against Tuberculosis (TB).It is typically administered to infants and children in countries with high TB prevalence.', 0, 0, 0, 1790968054785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_97d6e476f6842e8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A place of living according to particular environment of living things is _____?', '{"A":"Ecosystem","B":"Habitat","C":"Community","D":"Population"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A habitat is the natural environment in which a living thing resides.Including all the living and non-living factors that affect its survival and growth.', 0, 0, 0, 1790968054785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2891c987422ea536', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A body is said to be in _____ if it changes its position with respect to its surroundings or due to another body.', '{"A":"Motion","B":"Unchanged","C":"Rest","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Motion occurs when a body changes its position relative to another body or its surroundings.It can be described in terms of displacement, velocity, and acceleration.', 0, 0, 0, 1790968054785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3dd3c29dcf8cedd5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which system is responsible to communicate and coordinate for the body functions?', '{"A":"Circulatory System","B":"Respiratory System","C":"Digestive System","D":"Nervous System"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The nervous system is the body system that controls and coordinates the functions of all other organ systems.It allowing for integration and regulation of various bodily functions.It consists of the brain, spinal cord, nerves, and sensory organs.', 0, 0, 0, 1790968054785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0eedf8849250549f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Tyndall effect is used to distinguish between ______?', '{"A":"Solutes and Solvents","B":"Liquids and Solids","C":"Solutions and Colloids","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Tyndall effect is the scattering of light by particles in a colloid, making the path of light visible.True solutions do not scatter light, so this effect helps distinguish colloids from solutions.', 0, 0, 0, 1790968054785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_786ae5b56d896f75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A sphygmomanometer is used to check _____?', '{"A":"Blood pressure","B":"White blood cells","C":"Sugar level","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We can measure our blood pressure on our own using a digital blood pressure monitor for automated readings or an instrument called a sphygmomanometer for manual readings.A sphygmomanometer also known as a blood pressure monitor, is a device used to measure blood pressure.', 0, 0, 0, 1790968054785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_29851ae0dd4e837d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The voice box is also called _____?', '{"A":"Larynx","B":"Pharynx","C":"Windpipe","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The larynx is commonly known as the voice box because it houses the vocal cords.It is responsible for producing sound.It is located in the throat.', 0, 0, 0, 1790968054819) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_97cddc4526bc7013', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'How many bones are found in the human skull in total?', '{"A":"20","B":"21","C":"22","D":"23"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The number of bones in a human skull is 22The human skull is generally considered to consist of twenty-two boneseight cranial bones fourteen facial skeleton bones**while300 bones are there in a newborn infant.The human hand has 27 bonesND07-3-2023', 0, 0, 0, 1790968054819) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f62c6771c78e923b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The layers of atmosphere are divided into ____ layers.', '{"A":"3","B":"4","C":"5","D":"6"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Atmosphere is divided into Five layers/parts:TroposphereStratosphereMesosphereThermosphereExosphere', 0, 0, 0, 1790968054819) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b2278155a6578430', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Zoological name of butterfly is ______?', '{"A":"Pieris Rapae","B":"Musca Domenstrica","C":"Fells Cactus","D":"Hystrix leucura"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pieris Rapae is scientific name given to butterfly.Pieris Rapae is derived from a Greek word. Pieris Rapae means Radish.', 0, 0, 0, 1790968054819) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0792aa3a36d04b39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Teflon is a polymer of which monomer?', '{"A":"Ethylene","B":"Propylene","C":"Tetrafluoroethylene","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The chemical formula for tetrafluoroethylene is C₂F₄.Key points about Teflon:Chemical name: Polytetrafluoroethylene (PTFE)Monomer: TetrafluoroethyleneNotable property: Highly non-stick surface, often used in cooking utensils', 0, 0, 0, 1790968054819) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6d090edb93d3289', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'According to the modern system of taxonomy, living organisms have been classified into?', '{"A":"Five Kingdoms","B":"Three Kingdoms","C":"Four Kingdoms","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The modern system of taxonomy classifies living organisms into five kingdoms: Monera, Protista, Fungi, Plantae, and Animalia.This classification, proposed by Robert Whittaker in 1969, is based on cell structure, mode of nutrition, and complexity.', 0, 0, 0, 1790968054819) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0369d3ea1247a720', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What natural disaster can occur if an earthquake happens under the sea?', '{"A":"Tsunami","B":"Cyclone","C":"Tornado","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Undersea earthquakes displace a large volume of water, generating powerful sea waves.This sudden movement creates a tsunami, which can travel across oceans at high speeds.', 0, 0, 0, 1790968054819) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e7625e448e8bf0dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Ability to be hammered into sheet is called malleability. Which one of the following metals is most malleable?', '{"A":"Gold","B":"Platinum","C":"Silver","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gold is the most malleable metal, which means it can be beaten into thin sheets or shapes without breaking.Gold is a soft, ductile metal with a high degree of plasticity, making it easy to work with.It can be hammered, rolled, or bent into various forms without cracking or shattering.', 0, 0, 0, 1790968054819) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eb591df8de5811ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Decrease in strength of signal is known as?', '{"A":"Tuning","B":"Modulation","C":"Attenuation","D":"Amplification"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Attenuation refers to the decrease in strength or intensity of a signal as it travels through a medium or is processed by a system. This can occur due to various factors such as resistance, impedance, or absorption, and can affect the quality and fidelity of the signal.', 0, 0, 0, 1790968054853) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f5077c92d8ecf1d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which metal is used in the florescent tubes and bulb of thermometer?', '{"A":"Mercury","B":"Iron","C":"Copper","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mercury (Hg) is used in thermometers.Because it expands and contracts consistently with temperature changes.It providing accurate readings.It also emits ultraviolet light in fluorescent tubes when electrically excited.', 0, 0, 0, 1790968054853) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c86dca86f3099eea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Chemically antibodies are _____?', '{"A":"Proteins","B":"Lipids","C":"Starches","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Antibodies are specialized proteins produced by the immune system.They help identify and neutralize foreign substances like bacteria and viruses.', 0, 0, 0, 1790968054853) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4dfeeeea648c9176', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Thalassemia is due to abnormality in _____?', '{"A":"Lymphatic fluid","B":"Hemoglobin","C":"Platelets","D":"White blood cells"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thalassemia is a genetic blood disorder caused by an abnormality in hemoglobin production.It leads to reduced oxygen-carrying capacity of red blood cells.', 0, 0, 0, 1790968054853) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66c35f16c4aac43d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Typhoid and cholera are examples of which type of diseases?', '{"A":"Airborne","B":"Water borne","C":"Food borne","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cholera means ہیضہTyphoid means ایک قسم کا بخارTyphoid and cholera spread through contaminated water, especially in areas with poor sanitation.They are classic examples of water-borne diseases caused by bacteria like Salmonella typhi and Vibrio cholerae.', 0, 0, 0, 1790968054853) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8454145305787311', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The worm with unsegmented body includes ______?', '{"A":"Earthworm","B":"Tapeworm","C":"Flatworm","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Flatworms (phylum Platyhelminthes) have unsegmented, flat bodies.Earthworms and tapeworms have segmented bodies.', 0, 0, 0, 1790968054853) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a646f14e0a08acd7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'How many percentages of fresh water present on earth?', '{"A":"0.04%","B":"2.5%","C":"2.2%","D":"3%"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 3% of Earth''s water is fresh water.2.5% of that fresh water is unavailable because it is:Locked in glaciers and polar ice capsPresent in the atmosphere and soilToo deep underground to extract affordablyOnly 0.5% of Earth''s water is available as usable fresh water for human use.', 0, 0, 0, 1790968054853) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4ddae6bdf2ebaccc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The coldest region in atmosphere is ______?', '{"A":"Mesosphere","B":"Stratosphere","C":"Troposphere None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mesosphere is the coldest layer of the atmosphere, with temperatures dropping as low as -90°C.It lies above the stratosphere and below the thermosphere.', 0, 0, 0, 1790968054853) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d2413ee1fba721a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'About 50% of Earth crust, including the water on Earth and atmosphere is ______?', '{"A":"Oxygen","B":"Salts","C":"Plasma","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Priestly discover oxygen in 1776.Oxygen makes up about 46-50% of the Earth''s crust by weight, mainly in the form of oxides and silicates.It is also a major component of water (H₂O).It is abundant in the atmosphere as O₂.', 0, 0, 0, 1790968054885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd12e58076ff9d57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who is considered the founder of meteorology?', '{"A":"Einstein","B":"Plato","C":"Aristotle","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aristotle is widely considered the founder of meteorology.He first used the term "meteorology" in the fourth century BC, although his work on weather was based on observation and lore rather than modern scientific methods.', 0, 0, 0, 1790968054885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1d8bcb8aba04db31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Electrocardiogram (ECG) is a diagnostic tool/test that is routinely used to assess the electrical and muscular function of ______?', '{"A":"Liver","B":"Lungs","C":"Heart","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Electrocardiogram (ECG) records the electrical activity of the heart.It helps diagnose heart conditions like arrhythmias, heart attacks, and other cardiac issues.', 0, 0, 0, 1790968054885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dc2370d2707bac5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is not a primary color?', '{"A":"Orange","B":"Red","C":"Green","D":"Blue"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Three Primary Colors : Red, Yellow, Blue.Three Secondary Colors : Orange, Green, Violet.Six Tertiary Colors : Red-Orange, Yellow-Orange, Yellow-Green, Blue-Green, Blue-Violet, Red-Violet,which are formed by mixing a primary with a secondary.', 0, 0, 0, 1790968054885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2096c81082e18559', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following substances is used in match sticks?', '{"A":"Phosphorus","B":"Zinc","C":"Sulphur","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Red Phosphorus is the primary substance used in matchsticks Additional information:Sulphur: Only acts as a secondary fuel in the match head to keep the flame burning.Zinc: Completely unused in the chemical composition of standard matches.Last updated 18-07-2026 by NA', 0, 0, 0, 1790968054885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2f290455ff54df20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Whale is a _____?', '{"A":"Mammal","B":"Fish","C":"Ruminant","D":"Sea Monster"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Whales are marine mammals.It belonging to the order Cetacea.This also includes dolphins and porpoises.They breathe air, give birth to live young, and produce milk to feed their offspring, like all mammals.', 0, 0, 0, 1790968054885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c8c98d4539fb52cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The distance between the focal point and optical centre is called?', '{"A":"Focal length","B":"Optical centre","C":"Principal axis","D":"Principal focus"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The distance between the optical center and the principal focus is called the focal length of the lens. A positive focal length indicates that a system converges light, while A negative focal length indicates that the system diverges light.', 0, 0, 0, 1790968054885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1cfd234339832a4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Snail belongs to which of the following phylum?', '{"A":"Annelida","B":"Arthropoda","C":"Mollusca","D":"Echinodermata"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Snails are mollusks, belonging to the phylum Mollusca.They typically have a soft body and, in many cases, an external shell.', 0, 0, 0, 1790968054885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_513475d818112e47', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is Cartography?', '{"A":"Art of dancing","B":"Art of making maps and charts","C":"Art of drawing sketches","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cartography is the science and art of creating maps to represent geographical areas.It includes designing, drawing, and interpreting maps for navigation and study.', 0, 0, 0, 1790968054915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f7d7b6fba5fc4612', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Reflex action in the body is controlled by ______?', '{"A":"Spinal cord","B":"Frontal lob","C":"Medulla","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The central nervous system (CNS) controls reflex actions.Reflex actions are quick, involuntary responses to a stimulus that don''t require prior thought.Examples of reflex actions include blinking and the withdrawal of a body part from a hot object.', 0, 0, 0, 1790968054915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8bb48c0a31d852cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In Fahrenheit scale the freezing point of water is ______?', '{"A":"30°F","B":"32°F","C":"34°F","D":"100°F"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the Fahrenheit scale:The freezing point of water is 32°FThe boiling point of water is 212°F', 0, 0, 0, 1790968054915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0b45a191300b6388', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is used to synthesize bleaching powder?', '{"A":"Aluminium hydroxide","B":"Calcium hydroxide","C":"Magnesium hydroxide","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bleaching powder is synthesized by reacting chlorine gas with calcium hydroxide (Ca(OH)₂).The chemical formula of bleaching powder is Ca(OCl)Cl.', 0, 0, 0, 1790968054915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5658e9f24c8aba75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which nutrient is maximally used for raising field crops?', '{"A":"Nitrogen","B":"Calcium","C":"Potash","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nitrogen is the most extensively used nutrient for field crops as it promotes leaf and stem growth, especially in cereals.It is essential for photosynthesis and overall plant development.', 0, 0, 0, 1790968054915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_99ba65b25f8963a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Heavy water used in Nuclear reactors is also called?', '{"A":"pH-7","B":"Deuterium Oxide","C":"Tritium Oxide","D":"Distilled Water"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Heavy water, also known as Deuterium Oxide (D₂O).It is used as a neutron moderator in nuclear reactors.Due to its ability to slow down neutrons without absorbing them.', 0, 0, 0, 1790968054915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fe133595ee6a7d1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Fossil fuel are formed from the remain of plants and animals in _____?', '{"A":"Absence of Oxygen","B":"Presence of Sunlight","C":"Presence of Oxygen","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fossil fuels form from remains of plants and animals over millions of years. The absence of oxygen prevents the complete decay of organic matter. Under heat and pressure, these remains transform into coal, oil, or natural gas. Presence of oxygen would lead to oxidation and decomposition instead of fossil fuel formation.Last updated on 06-March-2026', 0, 0, 0, 1790968054915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7a0c143054d3e8d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following can be stored for centuries without spoiling?', '{"A":"Milk","B":"Honey","C":"Water","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Honey has natural antibacterial properties and low moisture, preventing spoilage.Archaeologists have found edible honey in ancient Egyptian tombs, thousands of years old.', 0, 0, 0, 1790968054915) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9b3132d33f8805e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Electromagnetic waves travel with _____?', '{"A":"Speed of light","B":"Speed of wind","C":"Speed of earth","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All electromagnetic waves travel at the same speed through empty spaceElectromagnetic waves are formed between electrical and magnetic fields due to vibrations.Electromagnetic waves travel with the speed of light in free space.The speed of light is 3*10^8 m/sHence, Electromagnetic waves travel at the speed of 3*10^8 m/s.', 0, 0, 0, 1790968054948) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_12134fb268b48049', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Hemodialysis means cleaning of ______?', '{"A":"Veins","B":"Blood","C":"Nerves","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hemodialysis is a medical procedure that filters and cleans the blood using a machine when the kidneys fail to perform this function effectively.It removes waste, toxins, and excess fluids from the bloodstream.', 0, 0, 0, 1790968054948) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_149b618a2d00f449', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'All weathers are mainly caused by _____?', '{"A":"Ocean waves","B":"Heating from the Sun","C":"Moon light","D":"Movement of the Earth"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All weather patterns are mainly caused by heating from the Sun.It drives the movement of air and water in the atmosphere, influencing temperature, precipitation, and wind patterns.', 0, 0, 0, 1790968054948) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e51d65f781ca6687', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'An alloy used in making heating elements for electric heating devices (electric heater) is ______?', '{"A":"Chromium","B":"Graphite","C":"Tungsten","D":"Nichrome"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nichrome, an alloy of nickel and chromium.It is used because of its high resistance and ability to withstand high temperatures without oxidizing.', 0, 0, 0, 1790968054948) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2d241e2deae98c33', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is another name for the second law of motion?', '{"A":"Law of Intertia","B":"Law of Acceleration","C":"Law of Motion","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The other name for Newton''s second law is the law of force and acceleration.while The third law is also known as the law of action and reaction. The law of inertia is another name for Newton''s first law.', 0, 0, 0, 1790968054948) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e6abea56121a1bd1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who invented the Steam Engine?', '{"A":"Bessel","B":"James Watt","C":"Faraday","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation James Watt, a Scottish engineer, patented improvements to the steam engine in 1781.He significantly enhancing its efficiency and power, and revolutionizing industry and transportation.', 0, 0, 0, 1790968054948) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45e75b21f8fdf6a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Muslim scientist and philosopher Ibn-al-Haytham made his most famous contribution to the field of _______?', '{"A":"Medicine","B":"Poetry","C":"Optics","D":"Mathematics"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ibn al Haytham is known as the Father of Optics.His contributions to the field of optics through his monumental seven-volume work, Kitab al-Manazir (Book of Optics), compiled between 1011-1021 AD.', 0, 0, 0, 1790968054948) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3d2c2a26a5fd49dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The most abundant metal in the Earth''s crust is _____?', '{"A":"Aluminum","B":"Iron","C":"Carbon","D":"Silicon"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aluminum is the most abundant metal in the Earth''s crust.It comprising about 8% of its weight.It is primarily found in the form of bauxite ore.', 0, 0, 0, 1790968054948) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b1f74dc5ae2885eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The steam-engine was invented ____?', '{"A":"Thomas Savery","B":"Wilson","C":"James Chadwick","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thomas Savery is considered the inventor of the first commercially used steam-powered device.In 1698, he patented a steam-powered pump designed to remove water from mines.', 0, 0, 0, 1790968054981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f5b311bac816209f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The microscope is used to study _____?', '{"A":"Small and near objects","B":"Large objects","C":"Distant objects","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A microscope is designed to magnify tiny, close-up objects that are not visible to the naked eye.It helps in studying small details of specimens like cells, microorganisms, and other minute structures.', 0, 0, 0, 1790968054981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ecf1280c2b8c2bbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In desert, mirage is an optical illusion by ______?', '{"A":"Reflection","B":"Refraction","C":"Total internal reflection","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A mirage occurs when light bends due to varying air temperatures, causing total internal reflection.This makes distant objects appear as if they are reflected in water, commonly seen in deserts.', 0, 0, 0, 1790968054981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f4965c0ddd168d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the average adult pulse rate?', '{"A":"60-80","B":"100-200","C":"500-570","D":"10-30"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 60-80 is the normal pulse rate of adult. *** A normal resting heart rate for adults ranges from 60 to 100 beats per minute. A normal resting heart rate should be between 60 to 80 beats per minute, but it can vary from minute to minute. ***', 0, 0, 0, 1790968054981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_017cec0a136ed9c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Humans have ______ pairs of chromosomes.', '{"A":"20 pairs","B":"40 pairs","C":"23 pairs","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The human cell contains 46 chromosomes.These are organized into 23 pairs, where each parent contributes one chromosome to each pair, resulting in a total of 46 chromosomes in most human cells.This number includes 22 pairs of autosomes and 1 pair of sex chromosomes, determining an individual''s sex (XX for females and XY for males).NOTE: DON''T BE CONFUSED about the pair and number of Chromosomes in the Human bodyTotal Chromosomes: 46Pairs of Chromosomes: 23', 0, 0, 0, 1790968054981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0beef1636b703059', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The term Aqua means ______?', '{"A":"Water","B":"Marsh","C":"Alloy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aqua is a greenish-blue color, often thought of as the shade of water.Aqua, water in Latin, is a variation of cyan that sits between green and blue in the color wheel.Aqua means پانیWater means پانی', 0, 0, 0, 1790968054981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7bf4263807b8e03b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The rate of decomposition of plants and animals is lowest in which of the following habitats?', '{"A":"Grassland","B":"Rainforest","C":"Desert","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Decomposition is slow in deserts due to low moisture and extreme temperatures.Lack of water limits microbial activity, reducing the breakdown of organic matter.', 0, 0, 0, 1790968054981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4e94d53660632f72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The flame used in cutting and welding of metals is ______?', '{"A":"Polythene","B":"Oxyacetylene","C":"Ethylene","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oxyacetylene flame is used in welding and cutting metals due to its high temperature.It provides a flame temperature of about 3200°C, making it suitable for industrial applications.', 0, 0, 0, 1790968054981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9c28de31868f19ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The earth has ______ types of movements at the same time.', '{"A":"4","B":"3","C":"5","D":"2"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Earth moves in two primary motions: Rotation (spinning on its axis) and Revolution (orbiting around the Sun).Rotation causes day and night, while revolution leads to seasons.', 0, 0, 0, 1790968055014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5ecd60205bc912c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Basically, environmental pollution is of _____?', '{"A":"Three types","B":"Two types","C":"Four types","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The three types of pollution are:Air Pollution: Harmful substances released into the air, like carbon monoxide and sulfur dioxide.Water Pollution: Contamination of water sources with pollutants such as industrial waste and sewage.Land Pollution: Degradation of land through activities like deforestation and improper waste disposal.', 0, 0, 0, 1790968055014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8a0d4f1ec16c2b81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Renal Tubules consists of _____?', '{"A":"Distal Convoluted Tubule","B":"Loop of Henle","C":"Proximal convoluted tubule","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Proximal convoluted tubule (PCT) reabsorbs nutrients and water.Loop of Henle helps concentrate urine by reabsorbing water and salts.Distal convoluted tubule (DCT) plays a role in ion balance and pH regulation.', 0, 0, 0, 1790968055014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a18b1036c7b92205', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A continuous (constant) and directed (specific direction) movement of ocean water is known as ______?', '{"A":"Cyclone","B":"Floods","C":"Tsunami","D":"Ocean Currents"}', 'D', NULL, 0, 0, 0, 1790968055014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c6b5392d7f1f6dbf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The most common and simple technique of chromatography is _____?', '{"A":"Paper Chromatography","B":"Ion exchange Chromatography","C":"Thin layer Chromatography","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Paper chromatography.Most common and simplest techniqueNeeds minimal equipmentEasy to performUses paper as the stationary phase and solvent as the mobile phaseSeparates components by their affinity for the two phases', 0, 0, 0, 1790968055014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7597e8913b25d898', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The relationship between two organisms where both are benefited and neither is harmed is called _____?', '{"A":"Parasitism","B":"Mutualism","C":"Predation","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mutualism is a symbiotic relationship where both organisms benefit from each other. Example: Bees and flowers—bees get nectar for food, and flowers get pollinated.', 0, 0, 0, 1790968055014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b0cdc590eaa91e3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A camera uses a _______ to form an image on a piece of film at the back.', '{"A":"Convex lens","B":"Concave lens","C":"Diverging lens","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A convex lens is thicker at the centre than at the edges. A camera uses a convex lens to focus light rays and form an image on a piece of film or a digital sensor at the back, capturing the scene in front of it.', 0, 0, 0, 1790968055014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_776fe1738363a7f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'COVID-19 is caused by?', '{"A":"Injection","B":"Virus","C":"Bacteria","D":"Mosquito"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation COVID-19 is caused by a virus, specifically the SARS-CoV-2 virus.The first infections with SARS-CoV-2 appeared in Wuhan in 2019.', 0, 0, 0, 1790968055014) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c348b6120807b335', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Isotopes have the same ______?', '{"A":"Atomic number","B":"Atomic mass","C":"Neutrons","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Isotopes of an element have the same atomic number (number of protons).It means they have the same chemical properties and are considered the same element.', 0, 0, 0, 1790968055050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab67b655f50c7955', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The organisms whose genes are modified are called ______?', '{"A":"FC organisms","B":"OP organisms","C":"TB organisms","D":"GM organisms"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Genetically Modified (GM) organisms have their DNA altered for desired traits. They are used in agriculture, medicine, and research.', 0, 0, 0, 1790968055050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc00aec245e56a7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who discovered that Malarias transmitted by mosquito?', '{"A":"Edward Jenner","B":"Alexander Fleming","C":"Louis Pasteur","D":"Ronald Ross"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ronald Ross was a medical doctor who received the Nobel Prize for Physiology or Medicine in 1902 for his work on the transmission of malaria.He belonged to the British.', 0, 0, 0, 1790968055050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed209a839ac1eae6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Richter Scale is used for measuring?', '{"A":"Rainfall","B":"Magnitude of velocity","C":"Magnitude of earthquakes","D":"Water level in the dam"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The intensity of earthquake is measured by Richter Scale.Richter Scale was invented in 1935.', 0, 0, 0, 1790968055050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a6d6df168c99fdc3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which component of diet helps in preventing constipation?', '{"A":"Carbohydrates","B":"Fiber","C":"Fats","D":"Proteins"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fiber is a key component in foods that help relieve constipation.It is a major part of stool.It adds bulk to the stool, aiding in smoother digestion.Fiber supports the microbiome, maintaining a healthy balance of bacteria in the digestive tract.High-fiber recipes offer additional digestive benefits beyond constipation relief.', 0, 0, 0, 1790968055050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0a60a1b769d37710', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which part of the donor''s eye is utilized in eye donation?', '{"A":"Lens","B":"Cornea","C":"Retina","D":"All of these","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When someone receives an “eye transplant,” they are given a donor cornea, the clear front part of the eye.The corneal transplant requires a functioning retina and optic nerve to restore vision.ND12_8_2023', 0, 0, 0, 1790968055050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d897ebbe2e28d02a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'One of the following is the respiratory controlling center?', '{"A":"Medulla","B":"Thymus","C":"Brain","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The medulla oblongata controls respiration by regulating the breathing rate and depth.It sends signals to the respiratory muscles to maintain oxygen and carbon dioxide levels in the blood.', 0, 0, 0, 1790968055050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_629cbf16126f7475', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Birds are thought to have descended from the ancient reptiles known as _____?', '{"A":"Archosaurs","B":"Pterosaurs","C":"Pterodactyls","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Archosaurs were a group of ancient reptiles that included dinosaurs, crocodiles, and the ancestors of birds.Modern birds evolved from theropod dinosaurs, which were a subgroup of archosaurs.', 0, 0, 0, 1790968055050) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_435b3014a43484f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In the inner ear of fishes, the ______ detects rotational movements.', '{"A":"Semicircular canal","B":"Sacculus","C":"Eustachian tube","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Semicircular canals are responsible for detecting rotational movements and balance in fishes.They contain fluid and sensory hair cells that respond to movement.', 0, 0, 0, 1790968055086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd9b0baa2ec275c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Bauxite is an ore of _____?', '{"A":"Steel","B":"Iron","C":"Aluminum","D":"Copper"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bauxite is the most important ore of aluminum which contains only 30–54% alumina.The rest is a mixture of silica, various iron oxides, and titanium dioxide along with trace amounts of zinc, phosphorous, nickel, vanadium etc.', 0, 0, 0, 1790968055086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da720b7d6f5a9fb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one of the following constants is not related to radiation?', '{"A":"Boltzmann’s constant","B":"Solar constant","C":"Stefan’s constant","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Boltzmann''s constant is primarily related to thermodynamics and kinetic theory, not directly to radiation.Solar, Stefan’s, and Wien’s are directly associated with radiation laws and phenomena.', 0, 0, 0, 1790968055086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1fee4034fb3ad295', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which is the most abundant mineral in human body?', '{"A":"Potassium","B":"Calcium","C":"Sodium","D":"Magnesium","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Calcium is the most abundant mineral in the human body,calcium makes up 1.5 to 2% of the total body weight.Approximately 1,200 g of calcium is present in the body of an adult humanmore than 99% of that amount is found in bones.***ND11-12-2022', 0, 0, 0, 1790968055086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_677161579d5e4abe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Fathom is the unit of measurement of ______?', '{"A":"Sound","B":"Depth","C":"Distance","D":"Frequency"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fathom is used to measure the depth of water or the length of a nautical rope or cable. A fathom is six feet, or 1.8288 meters.', 0, 0, 0, 1790968055086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ff1aa5e0886e364a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Entomology is the science that studies?', '{"A":"Behavior of human beings","B":"Insects","C":"Scientific terms","D":"The formation of rocks","E":"Plants"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation علم الحشرات، وہ علم جو حشرات کی ساخت سے تعلق رکھتی ہےEntomology Insects: کیڑے مکوڑے یا حشرات ****Entomology is the study of insects and their relationship to humans, the environment, and other organisms.RK12-12-22', 0, 0, 0, 1790968055086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_098ba3026294c76c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one of the following waves are used by the common TV remote control?', '{"A":"Infrared waves","B":"Radio waves","C":"TV waves","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation TV remote controls use infrared (IR) waves to communicate with the television.Infrared waves are invisible to the human eye but can be detected by sensors in the TV.', 0, 0, 0, 1790968055086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3f77635449f50ce3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Peripatus is the junction between ______?', '{"A":"Molluscs and asterias","B":"Molluscs and hexapods","C":"Arthropods and annelids","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Peripatus is considered a transitional organism between arthropods and annelids.This showing characteristics of both groups.It is a type of velvet worm.It providing insights into the evolutionary link between these two major groups of animals.', 0, 0, 0, 1790968055086) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9415bce6c73f34ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following enzymes catalyzes the hydrolysis of starch into sugars?', '{"A":"Sucrose","B":"Catalase","C":"Maltase","D":"Amylase"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amylase is an enzyme that catalyzes the hydrolysis of starch into sugars.All amylases are glycoside hydrolases.It is used in breadmaking.Additional information:Protease: is an enzyme that catalyzes proteolysis.Lipase:Is an enzyme that catalyzes the hydrolysis of fats.Peptidase:is an enzyme that breaks down peptides into amino acids.', 0, 0, 0, 1790968055152) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d161ae0e0356ffff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following contact point metals has the highest melting point?', '{"A":"Tungsten","B":"Silver","C":"Copper","D":"Gold"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tungsten has the highest melting point among these metals.It is used in high-temperature applications due to its ability to withstand extreme heat.', 0, 0, 0, 1790968055152) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_67ac306bd4b499de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The outermost layer of skin is known as ______?', '{"A":"Cartilage","B":"Ligament","C":"Epiglottis","D":"Epidermis","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The epidermis is the outermost layer of the skin.It providing a barrier against environmental damage.It consists of keratinized cells that help prevent water loss and protect against pathogens.', 0, 0, 0, 1790968055152) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f51231cb63731f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Theory of mutation was given by?', '{"A":"Albert Einstein","B":"Hugo de Vries","C":"Flemming","D":"Haldane","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Mutation theory was proposed by Hugo de Vries.Hugo Marie de Vries was a botanist from the Netherlands.', 0, 0, 0, 1790968055152) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cfe0d9a2782da152', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Graphite is used in nuclear reactors ______?', '{"A":"As a fuel","B":"As a lubricant","C":"For reducing the velocity of neutrons","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Graphite is used in nuclear reactors as a neutron moderator.It slows down high-energy neutrons to thermal energies to maintain the chain reaction efficiently.', 0, 0, 0, 1790968055152) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_70ee2d7df54f69f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which substance is known as Oil of Vitriol?', '{"A":"Nitric acid","B":"Hydrochloric acid","C":"Phosphoric acid","D":"Sulfuric acid"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sulfuric acid is a mineral acid composed of the elements sulfur, oxygen and hydrogen.It is a colorless, odorless and viscous liquid that is miscible with water.', 0, 0, 0, 1790968055152) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9ef3530a3ee5972d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A mobile phone sends and receives messages through ?', '{"A":"Sound waves","B":"Microwaves","C":"U/V waves","D":"Radio waves"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mobile phones communicate using radio waves.These waves are a type of electromagnetic radiation.Signals are sent to and received from cell towers (base stations).', 0, 0, 0, 1790968055152) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a3aa121792dfbff1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'During winter in cold countries, the __________ is mixed to melt the ice on the icy roads.', '{"A":"Water","B":"Salt","C":"Chlorine","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salt is spread on icy roads in winter to lower the freezing point of water, causing ice to melt.This makes roads safer by preventing the formation of thick ice.', 0, 0, 0, 1790968055152) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cfe48c0339e9804c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Each day human a body breathes in __________ liters of air.', '{"A":"55 to 10k","B":"15k to 17k","C":"10k to 15k","D":"15k to 20k"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A normal, healthy human breathes about 11,000 litres of air in a daybreathe air by the process of breathing Additional information:The average adult at rest inhales and exhales something like 7 or 8 liters of air per minute.Last updated question by NA on 28 April 2026', 0, 0, 0, 1790968055194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_807b3eef4abe1e80', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The wind is caused by ______?', '{"A":"Revolution of Earth","B":"Difference of Pressure","C":"Difference of Temperature","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wind is caused by the difference in atmospheric pressure between two areas.Air moves from high-pressure to low-pressure regions, creating wind.', 0, 0, 0, 1790968055194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9fa9e0ba63f406ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which two primary colours are mixed to make purple?', '{"A":"Red and green","B":"Red and blue","C":"Red and yellow","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Purple is created by mixing the primary colors red and blue.This combination results in a secondary color on the color wheel.', 0, 0, 0, 1790968055194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c4ddacdf03e67762', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Most of the weather phenomena take place in which of the following layers of the atmosphere?', '{"A":"Mesosphere","B":"Ionosphere","C":"Stratosphere","D":"Troposphere"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Most of the weather phenomena take place in the Troposphere layers of the atmosphere***Almost all the water vapor in the atmosphere is contained in the troposphere. All weather-related phenomena such as the formation of clouds, rain, fog, winds, and storm take place in the troposphere.', 0, 0, 0, 1790968055194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_de00d4f6eb0c5709', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The duration of day and night at North and South Poles is ______?', '{"A":"3 months","B":"5 months","C":"4 months","D":"6 months"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The poles experience six months of the day and six months of the night. This is since earth is tilted on its axis. Also, due to this, each pole is tilted towards and away from the sun for about six months. When the North Pole is tilted towards the sun, it has continuous daylight.', 0, 0, 0, 1790968055194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0c1b4f1a20da02e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Property of a substance to absorb moisture from air on exposure, is called?', '{"A":"Osmosis","B":"Deliquescence","C":"Efflorescence","D":"Desiccation"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Deliquescence is the property of a substance to absorb moisture from the air on exposure.This resulting in the formation of a solution or a liquid.This occurs when a substance has a high affinity for water.It can absorb it from the surrounding environment.', 0, 0, 0, 1790968055194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4a67cc7220ea56b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Green vegetables are good source of _______?', '{"A":"Vitamin and Minerals","B":"Starch","C":"Protein","D":"Fat"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fruit and vegetables are a good source of vitamins and mineralsVitamins: A, C, K, E, B vitamins (especially Folate).Minerals: Iron, Calcium, Potassium, Magnesium.Fiber: Aids in healthy digestion and keeps you feeling full.Antioxidants: Carotenoids, polyphenols, and chlorophyll fight cell damage.', 0, 0, 0, 1790968055194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc2e44fe148a832b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following has the maximum calorific value?', '{"A":"Carbohydrate","B":"Fats","C":"Proteins","D":"Vitamins"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1 g of fat provides 37 kJ of energy on oxidation while 1 g of carbohydrate on oxidation gives 17 kJ of energy. Hence, fat has the highest calorific value.Food componentEnergy densitykJ/gkcal/gFat379Ethanol (drinking alcohol)297Proteins174Carbohydrates174Organic acids133Polyols (sugar alcohols, sweeteners)102.4Fiber82ND23-4-2023', 0, 0, 0, 1790968055194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e28d5af8b8f3300c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The key function of the kidneys is _____?', '{"A":"Removal of excess carbon dioxide from blood","B":"Pumping blood to the heart","C":"Removal of excess water from blood","D":"Removal of urea and other nitrogenous wastes from blood"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A primary function of the kidneys is Regulation of fluids, electrolytes and acid-base balance Kidneys maintain water balance. They regulate electrolytes (Na⁺, K⁺, Cl⁻). Control blood pH via acid-base regulation. Remove metabolic wastes from blood. Essential for homeostasis.Last updated question01 March 2026', 0, 0, 0, 1790968055235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_483abe39494deadc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The difference in the duration of day and night increases as one moves from?', '{"A":"West to east","B":"East and west of the prime meridian","C":"Poles to equator","D":"Equator to poles"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation As you move from the equator towards the poles, the latitude increases (up to 90 degrees). The further you go from the equator in any direction, the difference between the duration of the day and night at different times of the year will be bigger.Additional information there are two points in the year when day and night are approximately equal in duration. This is called an equinox.The equinoxes occur around:March 20th-21st September 22nd-23rd each year.', 0, 0, 0, 1790968055235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6f458aa39d00ebdf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'One nautical mile per hour is equal to how many knots?', '{"A":"1.25 knots","B":"1.75 knots","C":"1.5 knots","D":"1 knot"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation One nautical mile per hour is equal to 1 knot.One nautical mile is equal to 6,076 feet (1,852 meters/kilometers).It is defined as exactly 1,852 meters (6,076 ft; 1.151 mi).', 0, 0, 0, 1790968055235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0fd4db9d88b6fa6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Experience to sunlight results in formation of ______?', '{"A":"Vitamin A","B":"Vitamin C","C":"Vitamin E","D":"Vitamin D"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Exposure to sunlight triggers the production of vitamin D in the skin.Specifically, ultraviolet B (UVB) rays from the sun interact with a compound called 7-dehydrocholesterol, converting it into vitamin D3 (cholecalciferol).Vitamin D is essential for calcium absorption, bone health, and immune system regulation.', 0, 0, 0, 1790968055235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_84b3f6dd5e6505f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Mobile phones use which waves?', '{"A":"Microwaves","B":"Sound waves","C":"Radio waves","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mobile phones primarily use radio waves to transmit and receive signals for communication.These waves are part of the electromagnetic spectrum and facilitate wireless connectivity.', 0, 0, 0, 1790968055235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_38894ad0d831708f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Physiotherapy deals with _____?', '{"A":"Immobility of joints and muscles","B":"Heart disease","C":"Brain damage","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790968055235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_711550619990129b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Friction can be reduced by changing over from _____?', '{"A":"Sliding to rolling","B":"Rolling to sliding","C":"Potential energy to kinetic energy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Friction can be reduced by changing from sliding to rolling.Replace sliding friction with rolling element friction.Such as with the use of rolling element bearings.', 0, 0, 0, 1790968055235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8031431f0fd0d7b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Humidify of the atmosphere is measured by an instrument called?', '{"A":"Barometer","B":"Hygrometer","C":"Carbohydrates","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Humidity in the air was measured by a Hygrometer.****A hygrometer is an instrument used to measure relative humidity.Humidity is the measure of the amount of moisture in the air.A psychrometer is an example of a hygrometer.hygrometer.***The humidity in the air tells us about the ratio of Water vapors in the air', 0, 0, 0, 1790968055235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cdf8b29551622493', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the escape of water molecules from surface called?', '{"A":"Evaporation","B":"Condensation","C":"Crystallization","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Evaporation happens when a liquid turns into a gas. It can be easily visualized when rain puddles “disappear” on a hot day or when wet clothes dry in the sun. In these examples, the liquid water is not actually vanishing—it is evaporating into a gas, called water vapor.', 0, 0, 0, 1790968055307) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0ff30f010dbd3a59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Duodenum Jejunum is a part of _____?', '{"A":"Liver","B":"Kidney","C":"Large intestine","D":"Small intestine"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The small intestine is the longest part of the digestive system. It extends from the stomach (pylorus) to the large intestine (cecum).It consists of three parts: duodenum, jejunum and ileum.', 0, 0, 0, 1790968055307) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_84e59391bc8fa34c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The luminous body emits _____?', '{"A":"Waves","B":"Light","C":"Energy","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A luminous body emits light, as it produces its own visible radiation (e.g., the Sun or a lamp).Light emitted by luminous bodies enables us to see objects and is a form of electromagnetic radiation.', 0, 0, 0, 1790968055307) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7e6ae978651ecea7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which mushroom is not edible?', '{"A":"Amanita phalloides","B":"Oyster mushroom","C":"Straw mushroom","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amanita phalloides, also known as the death cap.It is highly toxic and not edible, causing severe poisoning and death if consumed.Oyster mushrooms and straw mushrooms are safe to eat and commonly used in cooking.', 0, 0, 0, 1790968055307) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_853ae6e3a341ad1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Bats can also fly in the dark because they are capable of taking the help of ______?', '{"A":"Ultraviolet Waves","B":"Ultrasonic Waves","C":"Electromagnetic Waves","D":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bats can also fly in the dark because they are capable of taking the help of Ultrasonic Waves ***concept:They are guided by ultrasonic waves produced by them. Bats are guided by ultrasonic waves which they produce and enable them to fly in the dark', 0, 0, 0, 1790968055307) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_450dca50c14ea34c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following may cause flu?', '{"A":"Bacteria","B":"Virus","C":"Plant","D":"Fungi"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The flu is caused by an influenza virusFlu Risk Factors · chronic lung diseases such as asthmaND2-03-2023', 0, 0, 0, 1790968055307) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7de56282fefdfd19', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '“Dosimeter” is a device used to measure?', '{"A":"High Temperature","B":"Head radiation","C":"The speed of wind","D":"Radiation for safety purpose"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A radiation dosimeter is a device that measures dose uptake of external ionizing radiation. It is worn by the person being monitored when used as a personal dosimeter, and is a record of the radiation dose received.', 0, 0, 0, 1790968055307) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b033eab691d651e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Diaphragm in human body assists in _____?', '{"A":"Respiration","B":"Digestion","C":"Excretion of waste","D":"Circulation of blood"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The diaphragm is a muscle that plays a crucial role in respiration.It helping to expand and contract the lungs for breathing.', 0, 0, 0, 1790968055307) ON CONFLICT(id) DO NOTHING;
