INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b3f63c65ea4b0070', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Our earth is divided into how many climate zones?', '{"A":"Three","B":"Two","C":"Four","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geographers broadly divide the Earth into three separate climate zones: Tropical (near the Equator)Temperate (north and south of the Equator)Polar (the farthest Northern and Southern regions)', 0, 0, 0, 1790968055344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3c4ae65d32040c50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is called the fine filament growing from skin?', '{"A":"Hair","B":"Nails","C":"Virus","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hair is a fine filament composed of keratin that grows from follicles in the skin.It serves various purposes, including protection, regulation of body temperature, and sensory input.', 0, 0, 0, 1790968055344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_062c04d269279dc5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is meant by Apiary?', '{"A":"Place where butterflies are kept","B":"Place for breeding silkworms","C":"Place where bees are kept","D":"Place where dogs are kept"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An apiary is a place where bees are kept.It typically for beekeeping and honey production.It consists of multiple beehives maintained by beekeepers.', 0, 0, 0, 1790968055344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ca1068a657c52aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Metacarpal bones are located in which part of the human body?', '{"A":"Skull","B":"Hands","C":"Chest","D":"Feet"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Metacarpal bones are the five long bones found in the hand, connecting the wrist (carpal bones) to the fingers (phalanges).They form the structure of the palm and provide support for finger movements.', 0, 0, 0, 1790968055344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e60b86301426f050', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What are Cyclones?', '{"A":"Sudden Heavy floods","B":"No rain for a long time","C":"Heavy showers","D":"Winds and rains","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cyclones are usually accompanied by high rainfall.heavy showers mean: A period of heavy rainCyclones mean ایک قسم کی طوفانheavy showers زیادہ بارش/ بھاری بارشND16-3-2023', 0, 0, 0, 1790968055344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6eb5e2631546855e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Bodies which are usually fall from sky to the earth are called?', '{"A":"Meteorites","B":"Planets","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A meteoroid is a small rocky or metallic body in outer space.Bodies that usually fall from the sky to the Earth are called Meteorites.These are small particles from space that enter Earth''s atmosphere and survive to land on its surface.', 0, 0, 0, 1790968055344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_72d8511c5ce5b293', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Due to which deficiency, a child has weak bones?', '{"A":"Vitamin A","B":"Vitamin D","C":"Vitamin B","D":"Vitamin C"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The human hand has 27 bones:the carpals or wrist accounts for 8the metacarpals or palm contain fivethe remaining fourteen are digital bones; fingers and thumb.while The number of bones in a human skull is 22300 bones are there in a newly born infant.', 0, 0, 0, 1790968055344) ON CONFLICT(id) DO NOTHING;
