INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_69f4bdab635091df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The number of bones in a newborn baby is ____?', '{"A":"206","B":"250","C":"300","D":"360"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A newborn infant has about 300 bones.It fuse to form the 206 bones typical in adults.The human skull has 22 bones.The hand contains 27 bones.', 0, 0, 0, 1790968055385) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd2e5e2064c5a650', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following salts is the main cause of permanent hardness of water?', '{"A":"Magnesium bicarbonates","B":"Magnesium carbonates","C":"Magnesium sulphate","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The permanent hardness of water is caused by Chloride, Nitrates, Calcium and Sulphates of Magnesium Permanent Hardness is not precipitated by boiling It is removed by ZeoliteAdditional Information:The Presence of Calcium and Magnesium Bicarbonates causes temporary hardness of water Temporary hardness can be removed by boiling the water', 0, 0, 0, 1790968055385) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_33c7e290365e8554', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Air is a mixture of _______?', '{"A":"Solid","B":"Liquid","C":"Gas","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Air is a homogeneous mixture of the gaseous substances nitrogen, oxygen, smaller amounts of other substances.ND26-9-2023', 0, 0, 0, 1790968055385) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f0e07294bc959d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Polio is caused by _____?', '{"A":"Bacteria","B":"Virus","C":"Fungus","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Polio, or poliomyelitis, is a disabling and life-threatening disease caused by the poliovirus. The virus spreads from person to person and can infect a person''s spinal cord, causing paralysis (can''t move parts of the body).***The Polio vaccine was invented by___? Jonas SalkWhich country launched a polio vaccine drive after 1988 in April 2022? IsraelND10-3-2023', 0, 0, 0, 1790968055385) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_00ecf917b5b57710', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Movement of earth material as a unit along a curved surface is called?', '{"A":"Slump","B":"Mud out","C":"Lava","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Slumps are different from flows because, although the material under the slump may act like a liquid, the actual material that slides downhill stays solid.', 0, 0, 0, 1790968055385) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a1b1ab1d12486954', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In the early period which endemic is called black death?', '{"A":"Sars","B":"Liporasy","C":"Plague","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the early period, the endemic known as the "Black Death" is the plague.The plague is a pandemic disease that devastated Europe in the 14th century, killing an estimated 75 to 200 million people, approximately 30-60% of Europe''s population.', 0, 0, 0, 1790968055385) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_408ddbca0e8d47f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Ronald Ross discovered the cause of _____?', '{"A":"Polio","B":"AIDS","C":"Malaria","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Malaria is caused by Plasmodium parasites. The parasites are spread to people through the bites of infected female Anopheles mosquitoes, called "malaria vectors.', 0, 0, 0, 1790968055427) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_24def25db3a91666', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The hardest thing present in human body is ______?', '{"A":"Skull bones","B":"Dental enemal","C":"Ribs","D":"Femur"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tooth enamel is the white, visible part of the tooth and it is also the hardest part of the human body. The main mineral composition is hydroxyapatite, a crystalline of calcium phosphate.', 0, 0, 0, 1790968055427) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a88cff2459c0bb50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Nonstick cooking utensils are coated with _____?', '{"A":"Teflon","B":"PVC","C":"Polystyrene","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nonstick cooking utensils are coated with Teflon.It is a material that prevents food from sticking.Due to its non-reactive and heat-resistant properties.', 0, 0, 0, 1790968055427) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed270afaee2f2d97', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The core of Optical Fiber is made of _______?', '{"A":"Plastic","B":"Glass","C":"Plastic coating","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An optical fiber is a flexible, transparent fiber made by drawing glass or plastic To a diameter slightly thicker than that of a human hair.', 0, 0, 0, 1790968055427) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_254868638999bc22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The potential of pure water is ____?', '{"A":"Zero","B":"1","C":"2","D":"3"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The water potential of pure water is zero (0).It is taken as a standard reference point.Pure water has no dissolved solutes.Chemical formula: H2OMolar mass: 18.01528(33) g/molMelting point: 0.00 °C (32.00 °F; 273.15 K) [b]Boiling point: 99.98 °C (211.96 °F; 373.13 K)Last updated by NS on 20-April-2026', 0, 0, 0, 1790968055427) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9af6a569457e9e8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following female mosquitos is the cause of Dengue fever?', '{"A":"Aedes Aegypteis","B":"Anophilies","C":"Barinohils","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dengue viruses are spread to people through the bites of infected Aedes species mosquitoesThe mosquito becomes infected when it takes the blood of a person infected with the virus. After about one week, the mosquito can then transmit the virus while biting a healthy person.24', 0, 0, 0, 1790968055427) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3a8f58769b7cdaef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Snowfall is required from alleviation of mountain ______?', '{"A":"36 - 38 degree","B":"30 - 34 degree","C":"38 - 40 degree","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When outside temperatures are low and there is moisture in the air, small ice crystals are formed. On their own they are tiny, but when they collide they stick to each other and make snowflakes. When lots of these particles join together they get heavier and once they are heavy enough they fall to the ground as snow.', 0, 0, 0, 1790968055427) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16b995d2a6c0ceff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'John Logie Baird Is known for his invention of ______?', '{"A":"Radio","B":"Laptop","C":"Mobile Phone","D":"Television"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation John Logie Baird, a Scottish inventor, is best known for inventing the world''s first working television system in the 1920s.He revolutionizing communication and entertainment.', 0, 0, 0, 1790968055427) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_44a5040b310881a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The most naturally event in Nutrient Cycle is _____?', '{"A":"Secondary Production","B":"Nutrient Cycle","C":"Primary Production","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nutrient Cycle is the most natural event in the context of nutrient cycling.It refers to the continuous process by which nutrients are exchanged between the environment, plants, and animals.This process includes various events such as primary production, decomposition, and nutrient uptake.', 0, 0, 0, 1790968055468) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b1ac4e6ac0bd3334', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The process by which metal surface is coated with thin layer of zinc is called _____?', '{"A":"Vulcanising","B":"Electroplating","C":"Galvanizing","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The process of applying a zinc coating to iron or steel to prevent rusting is called galvanizing. This helps protect the metal from corrosion.', 0, 0, 0, 1790968055468) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10d02939e2886e03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Dr Abdus Salam of Pakistan was one of the contributed of the unification of:', '{"A":"Electromagnetic force and gravitational force","B":"Electromagnetic force and weak nuclear force","C":"Gravitational force and weak nuclear force","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790968055468) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_05e8c07b0cc6a5c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is not a natural fibre?', '{"A":"Silk","B":"Jute","C":"Cotton","D":"Rayon"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rayon is a semi-synthetic fiber made from cellulose, derived from wood pulp or other plant materials, but it undergoes extensive chemical processing.', 0, 0, 0, 1790968055468) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_82f61b0501858d95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Distant objects can be seen with the help of ____?', '{"A":"Microscope","B":"Telescope","C":"Spectroscope","D":"Chronometer"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Distant objects can be seen with the help of the TelescopeThey produce an image that is larger than the image that can be seen with the unaided eye.Telescopes gather far more light than the eye,It allows dim objects to be observed with greater magnification and better resolution.', 0, 0, 0, 1790968055468) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1265c25117abbc6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Natural Rubber is obtained from ______?', '{"A":"Animal Waste","B":"A special kind of tree","C":"A kind of fish","D":"Water weeds"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Natural rubber is made by extracting a liquid sap, called latex. Latex is gathered from the trees by making a cut in the bark and collecting the runny sap in cups. This process is called tapping. Largest Country produced Natural rubber 1 Thailand 2 Indonesia 3 Vietnam 4 India', 0, 0, 0, 1790968055468) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2eda9fef7cedd09f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Mirage is an example of _____?', '{"A":"Reflection of light","B":"Refraction of light","C":"Scattering of light","D":"Total internal reflection of light"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mirage is an example of: refraction of light total internal reflectionExampleWhen the reflected light ray reaches our eyes, it appears as coming from the sky or tree. This inverted image creates an optical illusion of the presence of water or the presence of islands etc.', 0, 0, 0, 1790968055468) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d5e4fab8fab74cba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'One of the following is not the layer of the earth’s Globe?', '{"A":"Crust","B":"Mantle","C":"Core","D":"Stratosphere"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The stratosphere is a layer of Earth''s atmosphere. Stratosphere is the second layer of the atmosphere as you go upward.', 0, 0, 0, 1790968055468) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_869e48ba63533be2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Induced fit model of enzyme activity suggests that an enzyme ______?', '{"A":"Usually belongs to non-regulatory enzyme","B":"Cannot modify its active sites","C":"Can catalyze related reaction","D":"Can bind to a single substrate"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An enzyme changes shape to fit the substrate.The enzyme''s active site is flexible, not rigidThe enzyme changes conformation when the substrate bindsLike a hand fitting a gloveDiffers from the fixed lock-and-key model', 0, 0, 0, 1790968055528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a8975d4646e6547d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Stainless steel is an alloy of ______?', '{"A":"Iron and Manganese","B":"Iron, Chromium and Zinc","C":"Iron, Carbon and Nickel","D":"Iron, Chromium and Nickel"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Stainless steel is a alloys that contain a minimum of approximately 11% chromium, a composition that prevents the iron from rusting and also provides heat-resistant properties.', 0, 0, 0, 1790968055528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d160b40762382ae4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'How many lenses does a pinhole camera use?', '{"A":"1","B":"2","C":"3","D":"No lens"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A pinhole camera works without lenses. It uses a small aperture (pinhole) to project an inverted image of the scene onto the opposite surface.', 0, 0, 0, 1790968055528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fda5ecc58e70e29e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the capacity of Lungs?', '{"A":"5 liters","B":"7 liters","C":"6 liters","D":"9 liters","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The lungs are located on either side of the breastbone in the chest cavity Among healthy adults, the average lung capacity is about 6 liters.AGM 30.4.23', 0, 0, 0, 1790968055528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a720ced30da19886', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The maximum deposition of DDT will occur in _____?', '{"A":"Seagull","B":"Cerebellar","C":"Crab","D":"Phytoplankton"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Due to biomagnification, DDT (Dichlorodiphenyltrichloroethane) accumulates more in organisms higher up the food chain. Seagulls, being top predators, experience the highest deposition of DDT.', 0, 0, 0, 1790968055528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9bbddc71600c0ea0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The over-cooking of food should be avoided because it _____?', '{"A":"Makes the food difficult to digest","B":"Reduces the nutritive value of food","C":"Increases the nutrition value of food","D":"Makes the food toxic"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Overcooking can lead to a reduction in the nutritional value of food.It especially water-soluble vitamins like vitamin C and B vitamins.As they can be lost in the cooking water or destroyed by heat.', 0, 0, 0, 1790968055528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ef3983b357cd3c00', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one of the following is a Metal?', '{"A":"Gypsum","B":"Mercury","C":"Limestone","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Symbol of mercury: HgAtomic number: 80Boiling Point: 356.7 C', 0, 0, 0, 1790968055528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b0962cdc576401e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the most significant environmental risk associated with hazardous waste?', '{"A":"Increased use of land for landfills","B":"Destruction of Habitat","C":"Air pollution","D":"Contamination of Ground water"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The most serious environmental effect posed by hazardous wastes is Contamination of Groundwater.Toxic substances from hazardous waste can seep into the soil and contaminate underground water sources.It affecting ecosystems and human health.', 0, 0, 0, 1790968055528) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_02056509f42d5992', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Scotograph is an instrument for _____?', '{"A":"Magnifying small objects","B":"Adding the blind to write","C":"Testing the heartbeat","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scotograph is an instrument used for aiding the blind to write.It helps visually impaired individuals in forming letters and words by providing a tactile guide.', 0, 0, 0, 1790968055568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a50368672211887a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Tooth decay is caused by ____?', '{"A":"Salt","B":"Sugar","C":"Calcium","D":"Fluorine"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Tooth Decay” due to the deficiency of Fluorine.Tooth decay occurs when foods containing carbohydrates sugars and starches are left on the teeth.', 0, 0, 0, 1790968055568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c00fed29157c7c3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which part of human body is affected by Hepatitis C?', '{"A":"Kidney","B":"Pancreas","C":"Liver","D":"Spleen"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hepatitis C is a liver infection caused by the hepatitis C virus. Hepatitis C is often described as “acute,” meaning a new infection, or “chronic,” meaning long-term infection.ND13-1-2023', 0, 0, 0, 1790968055568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6ed7c360ee00f52a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A camera uses a ________ to form an image.', '{"A":"Condenser lens","B":"Concave lens","C":"Convex lens","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A camera uses a convex lens to focus light and form a clear image on the sensor or film.The convex lens converges light rays to produce a sharp image.', 0, 0, 0, 1790968055568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_052ea2e21bf191e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In the word GPS, letter G stands for ____?', '{"A":"Geographic","B":"General","C":"Global","D":"Geostationary"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation GPS stands for Global Positioning System, a network of satellites orbiting the Earth.It provide location information and timing signals to GPS receivers on the ground.', 0, 0, 0, 1790968055568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a566646d0af26d3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Decibel is the unit which can be used to measure the ____?', '{"A":"Sensation","B":"Intensity of sound pressure","C":"Vision","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Decibels measure sound intensity (amplitude)Sound is energy that travels in waves. It can be measured in two ways: frequency and amplitude.', 0, 0, 0, 1790968055568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c9e601131c359cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What form of uranium is most commonly used in fission?', '{"A":"Uranium-238","B":"Uranium-234","C":"Uranium-235","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nuclear power plants primarily use a specific type of uranium 235 for nuclear fission because its atoms are easily split apart.*******Uranium''s most stable isotope, uranium-238, has a half-life of about 4,468,000,000 years.Uranium-238 is not fissile, but is a fertile isotope, because after neutron activation it can produce plutonium-239, another fissile isotope.', 0, 0, 0, 1790968055568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f33b47416fbbbffb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In plants, the process of pollination enables in _______?', '{"A":"Photosynthesis","B":"Fertilization","C":"Gymnosperm","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pollination in plants enables fertilization.During this process, pollen from the male part of the flower reaches the female part.This leads to the production of seeds.', 0, 0, 0, 1790968055568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6475e353366664a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which radiation is least penetrating?', '{"A":"Alpha rays","B":"Beta rays","C":"Gamma ray","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alpha rays, or alpha particles, are the least penetrating form of radiation.They consist of two protons and two neutrons.Making them relatively large and heavy compared to beta and gamma rays.', 0, 0, 0, 1790968055618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7cba6866c63d49eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is the principle of primary health care (PHC)?', '{"A":"Diagnostic technologies","B":"Equality","C":"Privatization","D":"Community participation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Community Participation in PHC involves involving:local communities in decision-making, planning, delivery of health services, recognizing their valuable insights and fostering effective, context-specific healthcare interventions.It recognizes that communities possess valuable knowledge about their health needs and priorities', 0, 0, 0, 1790968055618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6ff095c3f3e4cabd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which poisoning retards putrefaction?', '{"A":"Mercury","B":"Phosphorus","C":"Arsenic","D":"Lead"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Certain poisonous substances in the body can delay the process of putrefaction. They include:Carbolic acid (Phenol)Arsenic and antimonyStrychnineNux vomica (plant)Zinc chloride, ZnCl2MorphineAconitinePutrefaction is referred the breaking down of the body of an animal post-mortem', 0, 0, 0, 1790968055618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62aa857adf4c0d65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following actions is involuntary?', '{"A":"Breathing deeply","B":"Pumping of blood","C":"Walking quickly","D":"Solving a math problem"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The pumping of blood is an involuntary action, meaning it occurs automatically without conscious control.The heart pumps blood throughout the body without us having to think about it.Involuntary actions are those that occur without conscious control, such as:HeartbeatBreathing (although we can control it voluntarily to some extent)DigestionReflexesVoluntary actions are those that require conscious control, such as:WalkingTalkingWritingSolving math problems', 0, 0, 0, 1790968055618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90719a4c1f25ed8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The person who inhales cigarette smoke indirectly is known as?', '{"A":"Active smoker","B":"Passive smoker","C":"Chain smoker","D":"Social smoker"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A passive smoker inhales smoke from others'' cigarettes.It often in enclosed spaces.It can lead to similar health risks as active smoking.', 0, 0, 0, 1790968055618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_56ead136eee096be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Superposition Theorem is applicable to ______?', '{"A":"Nonlinear Circuits","B":"Linear Response Only","C":"Digital Circuits","D":"Time-Varying Signals"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Superposition Theorem is applicable to linear response only.It states that in a linear circuit with multiple sources.The response (voltage or current) can be calculated by summing the responses due to each source independently.', 0, 0, 0, 1790968055618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5f84fa173399d8fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'UJT has_____ Junctions?', '{"A":"One","B":"Two","C":"Three","D":"Four"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Unijunction Transistor (UJT) has one junction.It is commonly used in triggering circuits for thyristors and other semiconductor devices.', 0, 0, 0, 1790968055618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f246e1272fe4234d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is not a type of capacitor?', '{"A":"Ceramic Capacitor","B":"Film Capacitor","C":"Polar Capacitor","D":"Electrolytic Capacitor"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Polar Capacitor is not a type of capacitorA polar capacitor is NOT a type of capacitor because it does not exist in the classification of capacitors. a capacitor is a device that stores electrical energy.****', 0, 0, 0, 1790968055618) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa518fc4a03ce629', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Boiling of an egg is a _____?', '{"A":"Chemical change","B":"Physical change","C":"Both A and B","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Boiling an egg involves a chemical change.Because it alters the egg’s proteins, changing its structure and making it solidify.', 0, 0, 0, 1790968055656) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c95075e0b1ee94a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which layer of the Earth is considered the most important?', '{"A":"Crust","B":"Mantle","C":"Outer Core","D":"Inner Core"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mantle is crucial as it plays a key role in geological processes a such as plate tectonics, which affect earthquakes, volcanoes, and the formation of mountain ranges.The structure of the earth is divided into four major components:the crust,the mantle,the outer core,the inner core.', 0, 0, 0, 1790968055656) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0fa9606bf06f699b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which type of waves are used in Night Vision equipment?', '{"A":"Radio Waves","B":"Microwaves","C":"Infrared Wave","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Infrared waves are used in night vision equipment.They detect heat emitted by objects.It allowing visibility in low-light conditions.', 0, 0, 0, 1790968055656) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3566a129dbbf97f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A ______ is a semiconductor component that can either be used as switch or an amplifier.', '{"A":"Three pine shoe","B":"Transistor","C":"Reflector","D":"Dipole"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A transistor is a semiconductor component that can be used either as a switch or an amplifier.It controls the flow of electrical current in a circuit and is fundamental in electronic devices.', 0, 0, 0, 1790968055656) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d40d6f3659351b02', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Materials that block flow of electrons are called _____?', '{"A":"Insulators","B":"Super conductors","C":"Conductors","D":"Semi conductors"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Materials that block the flow of electrons are called insulators.They have high resistance and prevent electrical current from flowing through them.Such as rubber or glass.', 0, 0, 0, 1790968055656) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea9d2d9cf4e47fcb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In which year was Pluto removed from the category of planets?', '{"A":"2002","B":"2004","C":"2006","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to the International Astronomical Union, Pluto is still not an official planet in our solar system.Pluto was first discovered by a young research assistant Clyde Tombaugh in 1930.Pluto was demoted to dwarf planet status in 2006.Additional InformationThese are the 8 planets1. Mercury2. Venus3. Earth4. Mars5. Jupiter6. Saturn7. Uranus8. Neptune', 0, 0, 0, 1790968055657) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d279292ba19a9c8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What does lithosphere?', '{"A":"Rigid rocky outer layer of the earth","B":"Water surface of the earth","C":"Rock of the earth","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The lithosphere is a rigid, rocky outer layer of the Earth.It consisting of the crust and the solid outermost layer of the upper mantle.It extends to a depth of about 60 miles (100 km).', 0, 0, 0, 1790968055657) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b8d8111aa4e49d88', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is photometer?', '{"A":"Instrument for testing picture quality","B":"Instrument for measuring light intensity","C":"Instrument for measuring size of picture","D":"Instrument for testing colors of  picture"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A photometer is an instrument used to measure the intensity of light.It typically in units of luminous flux (lm) or illuminance (lux).It is commonly used in various fields such as photography, lighting design, and scientific research to quantify light levels.', 0, 0, 0, 1790968055657) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6345e15eb387590', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Molten rock that lies beneath the Earth''s surface is called?', '{"A":"Lava","B":"Magma","C":"Volcanic ash","D":"Geysers"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Magma: Hot liquid rock located deep underground inside the mantle or crustWhen this molten rock erupts or flows onto the Earth''s surface, it is known as lava', 0, 0, 0, 1790968055692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7cf3d5cd43b75abd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The most abundant elements in sea water are', '{"A":"Sodium and Potassium","B":"Sodium and Calcium","C":"Sodium and Chlorine","D":"Chlorine and lodine","E":"Magnesium and Sulphur"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The salt content in seawater is mainly due to the presence of sodium chloride i.e sodium and chlorine. The abundant element in seawater is chloride, which accounts for 1.94% of the total composition. Chloride is followed by 1.08% sodium, 0.04% potassium and a small amount of iodine.', 0, 0, 0, 1790968055692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_addc4712a3e60e94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Epistemology is the theory of _____?', '{"A":"The theory of the universe","B":"The theory of languages","C":"The theory of the earth","D":"The theory of knowledge"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Epistemology is the theory of knowledgeIt is the branch of philosophy It deals with the nature, origin, and scope of knowledge.The term ''epistemology'' was coined by James Fredrick FerrierIt comes from the Greek words "episteme'' (knowledge) and ''logos'' (theory)', 0, 0, 0, 1790968055692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a678ecaf739305cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Inert gases are ______?', '{"A":"Noble gases","B":"Hydrogen","C":"Nitrogen","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The noble gases are also called inert gases sometimes as they are monoatomic and chemically inert under normal conditions.', 0, 0, 0, 1790968055692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1578239b7a3578ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The red wire in a car battery is connected to', '{"A":"Positive terminal","B":"Negative terminal","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The red one is positive (+), the black one is negative (-). Never connect the red cable to the negative battery terminal or a vehicle with a dead battery', 0, 0, 0, 1790968055692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e1b39aadd8a3795', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A steel pin sinks in water while a far bigger ship floats, because Pit', '{"A":"displaces more water than its weight","B":"displace more water than its length","C":"Both A and B","D":"None Of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A piece of steel sinks in water because steel is denser than water. However, a steel ship is a hollow object made of steel and contains a lot of air in it. Due to presence of a lot of air in it, the average density of the ship becomes less than the density of water. Hence a ship floats in water.', 0, 0, 0, 1790968055692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f1c5cc106208049', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'contains more than average quality of which of the following?', '{"A":"Sugar","B":"Uric acid","C":"Urea","D":"Albumin"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A lab may test your urine for the presence of glucose and ketones( Both are forms of sugar) If either is present in the urine,Urine of a diabetes patient Diabetes can cause cloudy urine when too much sugar builds up in your urine. Your urine may also smell sweet or fruity. Diabetes canals lead to kidney complications or increase risk of infections of the urinary tract, both of which can also make your urine appear cloudy.', 0, 0, 0, 1790968055692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7882e7aab0942f17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is a vector quantity____?', '{"A":"Volume","B":"Power","C":"Electric Current","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An electric current is a stream of charged particles, such as electrons or ions, moving through an electrical conductor or space.AGM 25-12-2022**RY12-02-23', 0, 0, 0, 1790968055692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fdc0bdc902838aa0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Asteroids are found between the orbits of?', '{"A":"Saturn and Uranus","B":"Earth and Mars","C":"Mars and Jupiter","D":"Saturn and Jupiter"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The majority of known asteroids orbit within the asteroid belt between Mars and Jupiter, generally with not very elongated orbits.Asteroids are the rocky remnants of material leftover from the formation of the solar system and its planets approximately 4.6 billion years ago.', 0, 0, 0, 1790968055736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7a4a02742ff7b7e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is Graphology?', '{"A":"Study of Geography","B":"Study of Photography","C":"Study of Graph","D":"Study of Handwriting"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Graphology is the analysis of handwriting with attempt to determine someone''s personality traits. Graphology is the study of human personality through writing.****', 0, 0, 0, 1790968055736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bc18b401b304cf33', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The day and night are formed due to ''Earth'' rotation on its own axis from?', '{"A":"North to South","B":"South to North","C":"East to West","D":"West to East"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Earth rotates on its axis from west to east. Because of this, the Moon, the Sun and all other celestial objects appear to move from east to west across the sky.', 0, 0, 0, 1790968055736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5f7027889ab84ac8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is a cyclone?', '{"A":"A large-scale atmospheric system characterized by low pressure at its center and rotating wind patterns around it.","B":"A geological event involving the eruption of a volcano.","C":"A type of earthquake characterized by horizontal shaking.","D":"A celestial event involving the collision of two stars."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation the term cyclone is defined as. A system of winds that are rotating inwards to an area of low barometric pressureCyclones are created by the differences in air pressure.', 0, 0, 0, 1790968055736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6d4f7d4c7f779e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Soil pollution is caused by?', '{"A":"Aerosol","B":"Ozone","C":"Acid rain","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790968055736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_56bf5c403e20be51', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A Bar is System International unit to measure?', '{"A":"Temperature","B":"Energy","C":"Pressure","D":"Force"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The bar is a unit of pressure, equal to 100,000 Pa. The bar is not an SI unit, but is accepted for use with SI by BIPM - The International Bureau of Weights and Measures', 0, 0, 0, 1790968055736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f475aa194f4b02af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What gland is located just superior to the kidneys?', '{"A":"Pituitary","B":"Adrenal","C":"Pancreas","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adrenal glands, also known as suprarenal glands, are small, triangular-shaped glands located on top of both kidneys', 0, 0, 0, 1790968055736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eca6c7686c00ba3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The day and night are formed due to ''Earth'' rotation on its axis from?', '{"A":"North to south","B":"South to North","C":"West to East","D":"East to West","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All plants move Anticlockwise around SunAll plants move anticlockwise around their axis.Earth rotates its axis from West to EastThe rotation of the Earth gives the day and night', 0, 0, 0, 1790968055736) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_51b2a6d88152157a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following atmospheric layer is termed as a weather layer?', '{"A":"Thermosphere","B":"Stratosphere","C":"Mesosphere","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Troposphere. Known as the lower atmosphere, almost all weather occurs in this region.', 0, 0, 0, 1790968055772) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_955b8ba9cba014ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The most variable component of atmosphere is?', '{"A":"Water Vapour","B":"Nitrogen","C":"Oxygen","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The most variable of these is water vapor, which is the gas form of water (literally molecules of H2O moving around with the rest of the gases in the atmosphere).', 0, 0, 0, 1790968055772) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90524b5a2ea4495e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Warm and humid air ___ than dry air.', '{"A":"Lighter","B":"Heavier","C":"Equal in weight","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Moist air is lighter and less dense than dry air with the same temperature and pressure.', 0, 0, 0, 1790968055772) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_68e62ff40e3fce50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The upper part of the mantle above which the crust floats is called', '{"A":"Barysphere","B":"Lithosphere","C":"Asthenosphere","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The upper part of the mantle upon which the crust of the Earth floats is known as the Asthenosphere.', 0, 0, 0, 1790968055772) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9dc559b16e4486e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'A ''Cyclone'' is generated due to?', '{"A":"High temperature","B":"High humidity","C":"Low pressure","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cyclones are usually accompanied by high rainfall.heavy showers mean: A period of heavy rainCyclones mean ایک قسم کی طوفانheavy showers زیادہ بارش/ بھاری بارش', 0, 0, 0, 1790968055773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0487ef49a1ac385d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Soil Pollution is caused by what?', '{"A":"Aerosol","B":"Ozone","C":"Acid Rain","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Soil pollution is primarily caused by acid rain. Acid rain contains pollutants like sulfuric and nitric acids, which can degrade soil quality by altering its pH and harming plant life.', 0, 0, 0, 1790968055773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bfc3f968a677c80d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The location below the Earth''s surface where the Earthquake starts is called', '{"A":"Epicenter","B":"Hypocenter","C":"Tectonic Center","D":"All of these","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hypocenter is the point beneath the Earth’s surface where the vibrations of an earthquake originates and which corresponds to the location where the motion on a fault surface starts.', 0, 0, 0, 1790968055773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5515ec502bb67b92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the Density of Ice?', '{"A":"0.91 g/cm3","B":"2.91 g/cm3","C":"1.91 g/cm3","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The density of ice is 0.9168 g/cm 3. The density of water is 1 g/cm 3', 0, 0, 0, 1790968055773) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_72192ba4868479ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following type of mirrors can form an image larger than the object?', '{"A":"Convex","B":"Plane","C":"Concave","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When an object is placed between the focus and centre of curvature, the concave mirror can form an image larger than the actual object. ****Concave Mirror used for:Shaving mirrors.Head mirrors.Ophthalmoscope.Astronomical telescopes.Headlights.Solar furnaces.', 0, 0, 0, 1790968055814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a62703eac43a58ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Controlling rods inserted into the reactor are of which material?', '{"A":"Cadmium","B":"Magnesium","C":"Aluminum","D":"All of these","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cadmium rods are inserted in nuclear reacter to absorb the extra nucleons.Cadmium has a high thermal neutron absorption cross section. Therefore, cadmium rods will absorb neutrons, making them unavailable to cause fission. ****', 0, 0, 0, 1790968055814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91188b2f28005fc9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The term Xerostomia refers to_________?', '{"A":"Dry skin","B":"Dry mouth","C":"Dry nose","D":"Dry head","E":"Dry hands"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Xerostomia is dryness in the mouth.Xerostomia is also known as dry mouth.Xerostomia means منہ میں لعاب دہن کا نہ ہونا یا کم ہونا', 0, 0, 0, 1790968055814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1a921199b1227f4f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Genetically modified bacterium is produced when bacterium takes place in?', '{"A":"Muted DNA","B":"Old DNA","C":"Recombinant DNA","D":"Modified DNA","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Recombinant DNA is a technology scientists developed that made it possible to insert a human gene into the genetic material of a common bacterium. DNA stands for Deoxyribonucleic acid.', 0, 0, 0, 1790968055814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d214c1fc1c28131', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Agranulocytes (type of WBC) are formed in?', '{"A":"Red bone narrow","B":"Liver","C":"Lymphoid tissue","D":"Heart","E":"Brain"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agranulocytes are one type of white blood cell that contain no distinct granules in the cytoplasm. Agranulocytes originate from Lymphoid tissue, and their nucleus is not lobed.', 0, 0, 0, 1790968055814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a2b468cd66db92d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The stability of a structure against overturning is primarily influenced by the:', '{"A":"Material properties of the structure","B":"Quality of construction materials","C":"Architectural design of the structure","D":"Shape and size of the foundation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Studies have shown that the shape and size of the foundation pit have a significant influence on deformation and stability.', 0, 0, 0, 1790968055814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c7e64023c87cd5e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which admixture is commonly used in hot weather to extend the setting time of concrete?', '{"A":"Air-entraining admixture","B":"Retarding admixture","C":"Accelerating admixture","D":"Water-reducing admixture"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The admixtures slow down the initial rate of hydration of cement or prolong the setting of cement paste in concrete.Retarding admixtures are frequently required in hot weather conditions to facilitate delaying the setting time *****', 0, 0, 0, 1790968055814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b7af24500a2c72a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which structural analysis method is widely used for complex and irregularly shaped structures?', '{"A":"Matrix method","B":"Finite element method","C":"Moment distribution method","D":"Slope-defection method"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The finite element method (FEM) is a popular method for numerically solving differential equations arising in engineering and mathematical modeling.', 0, 0, 0, 1790968055814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_409c4159a7670b85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The process of reusing treated wastewater for non-potable purposes like irrigation and industrial processes in known as:', '{"A":"Water conservation","B":"Water purification","C":"Water desalination","D":"Water recycling"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Water reuse is the method of recycling treated wastewater for beneficial purposes, such as agricultural and landscape irrigation, industrial processes, toilet flushing, and groundwater replenishing', 0, 0, 0, 1790968055846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_629287d049755de9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is he recommended method to prevent plastic shrinkage cracking in concrete?', '{"A":"Using larger aggregate particles","B":"Increasing the cement content","C":"adding more water to the mix","D":"placing a wet burlap or using a fog spray during curing"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Many practical and proprietary methods exist to avoid plastic shrinkage cracking, including various curing methods, power floating, the use of cold water, shrinkage reducing admixtures, and fibres.Covering concrete with plastic sheets or wet burlap is the most common practical concrete curing method.', 0, 0, 0, 1790968055846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b9d9f4254df74883', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The process of replenishing groundwater by allowing water to percolate through the soil is known as:', '{"A":"Desalination","B":"Aquifer depletion","C":"Groundwater recharge","D":"Water privations"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ground water recharge includes recharge as a natural part of the hydrologic cycle and human-induced recharge, either directly through spreading basins or injection wells, or as a consequence of human activities such as irrigation and waste disposal.', 0, 0, 0, 1790968055846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_283314e08047ba58', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The head of water available for hydropower generation is calculated as the difference in water levels between the:', '{"A":"Water source and the dam","B":"Inlet and outlet of the powerhouse","C":"Dam and penstock","D":"Reservoir and turbine"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Head is the change in water levels between the hydro intake and the hydro discharge point.It is a vertical height measured in metres.', 0, 0, 0, 1790968055846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c191edbdfc00292', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In Structural design, the ratio of the applied load to the cross-sectional area of the structural member is known as:', '{"A":"Strain","B":"Stress","C":"Deflection","D":"Modulus of elasticity"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The third edition of the popular Structural and Stress Analysis provides the reader with a comprehensive introduction to all types of structural and stress analysis. ***', 0, 0, 0, 1790968055846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3f96fe2d5375219f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The point in a structure where the entire weight of the structure can be considered to act vertically downward is called the:', '{"A":"Point of equilibrium","B":"Center of mass","C":"Point of application","D":"Center of gravity"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The center of gravity of an object is where we can consider all of the weight of the object to be concentrated. This is a useful concept in physics and engineering.', 0, 0, 0, 1790968055846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b93b4bca4b92a516', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The process of preventing the degradation of water quality and the preservation of water resources for future generation is known as?', '{"A":"Water pollution","B":"Water conversation","C":"Water sustainability","D":"Water privatization","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Water conservation is the practice of using water efficiently to reduce waste and preserve this precious resource.****', 0, 0, 0, 1790968055846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_950dfc47abeccff0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the typical period for standard concrete to attain its full strength?', '{"A":"90 Days","B":"7 Days","C":"28 Days","D":"1 Day"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Concrete drying is a continuous and fluid event, and usually reaches its full effective strength after about 28 days.', 0, 0, 0, 1790968055846) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_93577d3d4b853e9b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In which layer of the atmosphere most clouds are formed?', '{"A":"Troposphere","B":"Stratosphere","C":"Mesosphere","D":"Exosphere"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The troposphere is the lowest layer of Earth''s atmosphere.Most of the mass of the atmosphere is in the troposphere.Most types of clouds are found in the troposphere, and almost all weather occurs within this layer.Major layers are tropospherestratospheremesospherethermosphere exosphere', 0, 0, 0, 1790968055882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a37319827ffb2aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The balloon is filled with:', '{"A":"Helium","B":"Oxygen","C":"Argon","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A balloon is filled with a gas called helium.whileA balloon filled with hydrogen gas moves in the upward directionND2-08-2023', 0, 0, 0, 1790968055882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_73cabafbeef9b730', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The sunlight can reach a depth of___________meters in the ocean', '{"A":"200","B":"300","C":"400","D":"450"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sunlight entering the water may travel about 1,000 meters into the ocean under the right conditions, but there is rarely any significant light beyond 200 meters. The ocean is divided into three zones based on depth and light level. The upper 200 meters of the ocean is called the euphotic, or "sunlight," zoneND5-07-2023', 0, 0, 0, 1790968055882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_80030c951bafe4df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Theodolite is used to measure?', '{"A":"Speed of light","B":"Blood pressure","C":"Horizontal and vertical angle","D":"Viscosity of liquid","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Theodolite is a precision optical instrument for measuring angles between designated visible points in the horizontal and vertical planes.Theodolite was invented by Leonard Digges (United Kingdom)*****', 0, 0, 0, 1790968055882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_36a3915a47234b73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'DNA is synthesized by enzyme known as', '{"A":"DNA polymerase","B":"Polymerase","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The enzyme that synthesizes DNA, DNA polymerase can only add nucleotides to an already existing strand or primer of DNA or RNA that is base paired with the template.ND5-07-2023', 0, 0, 0, 1790968055882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ff4cc2227c18886', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one of the following elements is found common in glass, cement, china clay and quartz?', '{"A":"Silicon","B":"Calcium","C":"Carbo","D":"All of these","E":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Silicon is an element found in glass, cement, China Clay and Quartz. Silicon is a chemical element with the symbol Si and atomic number 14.MUG 10-12-2022ND5-07-2023', 0, 0, 0, 1790968055882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7473d935971fc952', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Role of biotechnology in the production of food based on ___________?', '{"A":"Fermentation","B":"Digestion","C":"Respiration","D":"Decomposition"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Biotechnology can also be employed to develop functional foods with health-promoting properties and to reduce food waste while promoting sustainability in food production. Additives, enzyme processing, and fermentative processes are key techniques that can be used to improve food quality and shelf life.ND5-07-2023', 0, 0, 0, 1790968055882) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c9afc2cf8f7e4677', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The density of water is greatest at:', '{"A":"32°C","B":"0°C","C":"4°C","D":"100°C"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The density of water depends on temperature and salt content. Density is measured as mass (g) per unit volume (cc). Water has the highest density at 3.98 ° C and the lowest density at 0 ° C (freezing point).', 0, 0, 0, 1790968055882) ON CONFLICT(id) DO NOTHING;
