INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ec930c724f17d2d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following controls breathing and digestion?', '{"A":"Cerebellum","B":"Brain Stem","C":"Medulla","D":"Cerebrum"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The brain stem sits beneath your cerebrum in front of your cerebellum. Brain Stem connects the brain to the spinal cord and controls automatic functions such as breathing, digestion, heart rate and blood pressure.', 0, 0, 0, 1790968055915) ON CONFLICT(id) DO NOTHING;
