INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fac7cf22b1ceaf3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Asteroids are', '{"A":"Pieces of falling stars","B":"Satelite of other planet","C":"Rocks found on the moon","D":"Rocks under the sea","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Asteroids are rocky worlds revolving around the sun that are too small to be called planets. They are also known as planetoids or minor planets.', 0, 0, 0, 1790968055975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b94a58bb524fc022', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Processing of industrial household waste so that it can be reused is known as?', '{"A":"Renewing","B":"Reversing","C":"Recycling","D":"Rehabilitation"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Recycling is recovery and reprocessing of waste materials for use in new products. The basic phases in recycling are the collection of waste materials which may then themselves be recycled.', 0, 0, 0, 1790968055975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f9ed5c3171cd9a95', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The blue colour of the clear sky is due to?', '{"A":"Reflection of light","B":"Refraction of light","C":"Diffraction of light","D":"sSattering of light"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The blue colour of the sky is due to the scattering of light by the atmospheric particles.Light of shorter wavelengths scatters more than the light of longer wavelengths and the violet colour has a shorter wavelength, but our eyes are more sensitive to blue light. Hence, the colour of a clear sky is blue.', 0, 0, 0, 1790968055975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1d87532f809b4bc5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What does an airbag, used for the safety of a car driver, contain?', '{"A":"Sodium Bicarbonate","B":"Sodium Azide","C":"Sodium Nitrite","D":"Sodium Peroxide"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The driver-side airbag is a container containing about 50 grams of sodium azide. The passenger side container holds about 200 grams of sodium azide.', 0, 0, 0, 1790968055975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2e7d55839dd80909', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the reason for brown colour of rust?', '{"A":"Reduction","B":"Oxidation","C":"Both A & B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rust is iron oxide, which forms when iron or an alloy that contains iron is exposed to oxygen and moisture for a long time', 0, 0, 0, 1790968055975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ad7155868846b50f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Oil rises in a wick of oil lamp because of a property of matter, is called _____ .', '{"A":"Capillary action","B":"Condensation","C":"Respiration","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The oil in the wick of an oil lamp rises up due to capillary action. This effect is due to surface tension of liquids. The wick here acts as a capillary tube', 0, 0, 0, 1790968055975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0214a6c7c3014ee0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The weight of an object will be minimum when it is placed at', '{"A":"The center of the earth","B":"The Equator","C":"The South Pole","D":"The north pole"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The weight of an object is minimum when it is placed at the center of the earth because when an object is in the center, experiences gravitational pull from all directions & the weight of an object maximum on earth is on the poles', 0, 0, 0, 1790968055975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_32471ca405461ca7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Water soluble vitamins are', '{"A":"A","B":"B","C":"B&C","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are Two types of vitamins1. Water soluble2. Fat solubleBoth Vitamin B & C are water soluble vitamins', 0, 0, 0, 1790968055975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bc3683884ecf5ca0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Sensitive layer of the eye is:', '{"A":"Retina","B":"Sclerotic","C":"Choroids","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The retina is a thin layer of tissue that lines the back of the eye on the inside. It is located near the optic nerve. The purpose of the retina is to receive light that the lens has focused, convert the light into neural signals, and send these signals on to the brain for visual recognitionND_11_7-2023SH10-8-2023', 0, 0, 0, 1790968056011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c0f7bc214d1c03aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In solids molecules are_____?', '{"A":"Moving around freely","B":"Move around freely with little attraction","C":"Tightly packed","D":"Ionized"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The molecules are most tightly packed in solid state because of the strong intermolecular forces of attraction.', 0, 0, 0, 1790968056011) ON CONFLICT(id) DO NOTHING;
