INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c847c9d0e49d89b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Vexillology is the study of__________?', '{"A":"Flags","B":"Signals","C":"Vintage Cars","D":"Stamps"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vexillology is the study of flags. Vexillology comes from the Latin word vexilla "little sail" for flag. Vexillology means جھنڈوں کا مطالعہ', 0, 0, 0, 1790968056011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25bef589b9aa2268', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is Artificial Intelligence?', '{"A":"Artificial Intelligence is a field that aims to make humans more intelligent","B":"Artificial Intelligence is a field that aims to improve security","C":"Artificial Intelligence is a field that aims to develop intelligent machine","D":"Artificial Intelligence is a field that aims to mine the data"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Artificial Intelligence is a branch of Computer science, which aims to create intelligent machines so that machine can think intelligently in the same manner as a human does.Note: John McCarthy is recognized as the father of Artificial Intelligence due to his astounding contribution in the field of Computer Science.John McCarthy was an American computer scientist', 0, 0, 0, 1790968056011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_854a211d2cf1d42c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Name the embryologist who created ‘Dolly’ the first colon of sheep?', '{"A":"Curtist Youngs","B":"Albert Einstein","C":"Hugo de Vries","D":"Flemming","E":"Ian Wilmut"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dolly was the world''s first cloned sheep.Dolly was born on 5 July 1996. Dolly was a female domestic sheep, and the first mammal cloned from an adult somatic cell, using the process of nuclear transfer. Dolly was cloned by Ian Wilmut.', 0, 0, 0, 1790968056011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_82810ee37bc319a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In the process of sublimation ____', '{"A":"Solid turn into gas","B":"Liquid turn into gas","C":"Solid turn into liquid","D":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sublimation is the process in which a solid change directly into a gas.', 0, 0, 0, 1790968056011) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2fe987c2fb405c39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Contour is a measure of what?', '{"A":"Topography","B":"Rainfall","C":"Temperature","D":"Pressure","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A contour line is a line drawn on a topographic map to indicate ground elevation or depression.', 0, 0, 0, 1790968056047) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5b5701b0ef1c20ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one is the major ingredient of leather?', '{"A":"Carbohydrates","B":"Collagen","C":"Syntans","D":"None of these","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Leather is a durable and flexible material created by tanning animal rawhide and skins.The major ingredient of leather is Collagen. Leather can be used to make a variety of items, including clothing, footwear, handbags, furniture, tools sportsSH10-8-2023', 0, 0, 0, 1790968056047) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e7fd02a585b796c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Relative Humidity Depends on ------------?', '{"A":"Temperature","B":"Weather","C":"Location","D":"All of above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Relative Humidity Depends on temperature, weather, and location**Humidity in the air was measured by a Hygrometer***Concept Of Humidity: Important Information: Please read Carefully Humidity is the presence of water vapor in the atmosphere. The higher the rate of temperatures, weather, and (hot) place tend to be the more water vapor rises into the air, and the more humidity that area is.The lower the rate of temperatures, weather, and (cold) places tend to be the less water vapor rises into the air, and the less humidity that area is. **', 0, 0, 0, 1790968056047) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1d1ca196f462e37f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The term ''brown air'' is used for', '{"A":"Acid fumes","B":"Photochemical smog","C":"Sulphurous smog","D":"Industrial smog","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Photochemical smog which is mainly composed of ozone (O3), Peroxyacetyl nitrate (PAN) and Nox, is also known as ‘brown air’ where solar radiation is intense. In seasons of lesser solar radiation or areas, smog formation is incomplete and the air is referred to as grey air.', 0, 0, 0, 1790968056047) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_543498e0300f54b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Glass is made of the mixture of_________?', '{"A":"Sand and quartz","B":"Sand and silicates","C":"Quartz and mica","D":"Salt and quartz","E":"Sand and salt"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sand commonly used to make glass is comprised of small grains of quartz crystals, made up of molecules of silicon dioxide, which is also known as silica.', 0, 0, 0, 1790968056047) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b5b5990c5c23c4c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Biosensor is used to measure:', '{"A":"Salinity in urine","B":"Blood glucose level","C":"The body pH value","D":"Amount of hemoglobin","E":"Salinity in Urine"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A biosensor is a sensor exploiting a bio-molecule It is used to measure the presence of a certain substance in a liquid.Additional information:For example, biosensors include those used to detect viruses in the blood or measure glucose levels in the blood.These are mainly point-of-care applications, where direct results are important.', 0, 0, 0, 1790968056047) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cf9ab9d19871d56a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The seasonal contrasts are maximum in?', '{"A":"Low latitudes","B":"Mid-latitudes","C":"Sub tropics","D":"High latitudes"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seasonal contrasts are maximum in mid latitude.', 0, 0, 0, 1790968056047) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc30a43b329b0ddd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The image formed on the retina of the human eye is?', '{"A":"Real and upright","B":"Real and inverted","C":"Virtual and upright","D":"Real and enlarge"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The image formed at the retina of the human eye is real and inverted. Real and inverted is due to the presence of a convex lens in the eye.', 0, 0, 0, 1790968056047) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_621920585120c813', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Nervous system is affected by the shortage of?', '{"A":"Sodium","B":"Carbon","C":"Sulphur","D":"Oxygen"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nervous system is effected by the shortage of 1 Oxygen 2 Sulphur 3 Carbon 4 Sodium.', 0, 0, 0, 1790968056080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3b9d913d0dc9eca9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The biosphere is defined as:', '{"A":"Part of earth, water and atomsphere inhabited by living organisam","B":"Part of soil inhabited by animals and plants","C":"Atomspher in which life exists","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The biosphere is made up of the parts of Earth where life exists—all ecosystems. The biosphere is defined as the region on, above, and below the Earth''s surfaceThe biosphere is a zone on the surface of the earth where soil, water, and air combine to sustain life.Life can only occur in this zoneND-21-5-2023', 0, 0, 0, 1790968056080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a96b81cbead46f42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The hardness of a hammered metal of Aluminum is due to the presence of:', '{"A":"metalic bond","B":"ionic bond","C":"covelent bond","D":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Metallic bonds are the force of attraction between positive metal ions and valence electrons that are constantly moving around them.Metallic bonds occur among metal atoms.Whereas ionic bonds join metals to non-metals,metallic bonding joins a bulk of metal atoms. A sheet of aluminum foil and a copper wire are both places where you can see metallic bonding in action.ND-21-5-2023', 0, 0, 0, 1790968056080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f89ec70cbefc9540', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The extraction of metal from the ore is done by '' smelting'' which involves?', '{"A":"Heating and chemical reaction","B":"Heating and oxidation","C":"Heating and electrolysis","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Smelting is a metallurgical process used to extract metals from ores.The ore is heated to a high temperature.A reducing agent is often used to remove oxygen from the metal oxide.The metal is separated from the impurities (gangue).Example: Iron is extracted from iron ore by smelting in a blast furnace.', 0, 0, 0, 1790968056080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8265d8749cf828bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of following has two moons ?', '{"A":"Neptune","B":"Mars","C":"Saturn","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Number of moons in the planetsSaturn: 83Jupiter: 92Uranus: 27Neptune: 14Mars: 2Earth: 1Venus: 0Mercury: 0', 0, 0, 0, 1790968056080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e0b7c4fe2595fb0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Burning fossils fuels produces:', '{"A":"Oxygen","B":"Carbon dioxide","C":"Hydrogen","D":"None of these","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When fossil fuels are burned, they release large amounts of carbon dioxide, a greenhouse gas, into the air.ND18-5-2023', 0, 0, 0, 1790968056080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_97b1ddab43d65c5d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Increased levels of air pollution results in _______.', '{"A":"Soil erosion","B":"Global warming","C":"Respiratory problems","D":"All of the above","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Air pollutants such as ozone and particulate matter (PM) increase the amount and seriousness of lung and heart disease and other health problems.AGM 02.05.2023', 0, 0, 0, 1790968056080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0fecc39f3bdc1ee9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'In 1956, DNA polymerase was discovered from?', '{"A":"Cyanobacteria","B":"E. coli","C":"Helicobacter pylori","D":"Helicobacter","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation DNA polymerase is an enzyme that participates in the process of prokaryotic DNA replication. Discovered by Arthur Kornberg in 1956, it was initially characterized in E. coli. DNA stands for Deoxyribonucleic acidAGM 30.4.23', 0, 0, 0, 1790968056080) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d1b7efe0707ac641', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Vessels which are one celled?', '{"A":"Aorta","B":"Vein","C":"Artery","D":"Capillary","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Capillaries are very tiny blood vessels, that a single red blood cell can barely fit through them.Vessels which are one celled are called Capillaries.The largest blood vessel in the body is the Aorta.AGM 30.4.23', 0, 0, 0, 1790968056118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b2a2fb5cdd39f01', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Who invented Binomial Theorem?', '{"A":"Zahrawi","B":"Khuwarzimi","C":"Omar-Khayam","D":"Ibn-e-Sina","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Omer-Khayam was born in Iran in 1048 AD.Omer-Khayam was a poet, Mathematician & Astronomer. Omer-Khayam introduced modern Solar Hijri calendar, the Jalali calendar.Omer-Khayam was the first to develop the binomial theorem and determine binomial coefficients.*****AGM 30.4.23', 0, 0, 0, 1790968056118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af09fefb70150cb2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Demography studies what?', '{"A":"Births","B":"Deaths","C":"Hearts","D":"Both A & B","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Demography is the statistical study of human populations.Demography means مردم شماری کا علمAGM 30.4.23', 0, 0, 0, 1790968056118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bee426ad68d40228', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one is not a planet____?', '{"A":"Pluto","B":"Venus","C":"Earth","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to the International Astronomical Union, Pluto is still not an official planet in our solar system.Pluto was first discovered by a young research assistant Clyde Tombaugh in 1930.Pluto was demoted to dwarf planet status in 2006.Additional InformationThese are the 8 planets1. Mercury2. Venus3. Earth4. Mars5. Jupiter6. Saturn7. Uranus8. NeptuneAGM 30.4.23', 0, 0, 0, 1790968056118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6aed6f1df83e4094', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The state of the air and atmosphere at a particular place and time mcqs', '{"A":"Climate","B":"Season","C":"Weather","D":"Atmosphere","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Weather is a short-term phenomenon which describes the state of the atmosphere at a particular place and time. The climate of a place indicates the weather of a place over a long period of time.The difference between Weather and Climate is a measure of time.AGM 30.4.23', 0, 0, 0, 1790968056118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fb43fc015edc9185', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'How many lobes have both lungs?', '{"A":"4","B":"5","C":"6","D":"7"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 5 Lobes have both lungs**The right lung has three lobes and the left lung has two lobes.The left lung has a superior and inferior lobe, while the right lung has superior, middle, and inferior lobes.***Thin walls of tissue called fissures separate the different lobes.***EMT RESCUE 1122 Mcq', 0, 0, 0, 1790968056118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8305a9c5a553cfd0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'the near point of normal human eyes is?', '{"A":"25 cm","B":"21.5cm","C":"2.5 inch","D":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation the near point of normal human eyes is 25 cm***A normal eye can see objects clearly that are between 25 cm and infinity.The near point of the human eye is 25cm, which is defined as the shortest object distance that a typical eye is able to accommodate or to make the image fall on the retina.****The human eye consists of the following parts: Sclera, Retina, Cornea, Lens, Pupil, and Optic nerve.', 0, 0, 0, 1790968056118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c7d3d1656e685751', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which among following is rich in Ozone?', '{"A":"Mesophere","B":"Stratosphere","C":"Lonosphere","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The stratosphere is rich in Ozone. The rest of the layers might have ozone to a small extent but not to large extent.', 0, 0, 0, 1790968056118) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ecd8ec6316030336', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which is smallest in diameter', '{"A":"Jupiter","B":"Mercury","C":"Venus","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The smallest planet in terms of mass and volume is Mercury. With a diameter of 4,879 km and 3.3010 x 1023 kg, this small world weighs about one-twentieth the mass of the Earth and is about one-2.5th the diameter. In fact, Mercury is closer to our moon than Earth.', 0, 0, 0, 1790968056159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3fc2bf69d85851ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The word Insomnia means?', '{"A":"Deep sleep","B":"Light sleep","C":"Sleeping diorder","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Insomnia is a sleep disorder in which we have trouble falling and/or staying asleep. Such as,In Insomnia Difficulty falling asleepIn Insomnia Difficulty staying asleepIn Insomnia Difficulty returning to asleep after walkingInsomnia نیند نہ آنے کی بیماری', 0, 0, 0, 1790968056159) ON CONFLICT(id) DO NOTHING;
