INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c25d415bc2d0cba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of the following is known as ''Nearsightedness''?', '{"A":"Cataract","B":"Myopia","C":"Hypermetropia","D":"Presbyopia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Myopia is a common vision condition in which we can see objects near to us clearly, but objects farther away are blurry.Myopia means دورکی نظر کی کمزوری', 0, 0, 0, 1790968056159) ON CONFLICT(id) DO NOTHING;
