INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2257c1537d3946b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Humidity of the air', '{"A":"Decrease with the increase in atmospheric temperature","B":"Increase with the increase in atmospheric temperature","C":"does not show any consistent behavior with the change in atmospheric temperature","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation As the temperature rises, the air absorbs more water molecules and reduces relative humidity. As the temperature drops, the relative humidity rises. As the temperature approaches the dew point, the relative humidity increases.', 0, 0, 0, 1790968056194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8f542bd11a83710b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'What is the effect of global warming', '{"A":"Oxygen","B":"Carbon dioxide","C":"nitrogen","D":"none"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Global warming is increasing the surface of the earth.It increases carbon dioxide, methane, and other greenhouse gases in the atmosphere.ND-8-08-2023', 0, 0, 0, 1790968056194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3070b141ebd2a077', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The Green House Effect is caused by an excess of?', '{"A":"Carbon dioxide","B":"Carbon monoxide","C":"Carbon tetrachloride","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation IMPORTANT QUESTIONS AND INFORMATION RELATED TO "GREEN HOUSE EFFECT"Green House Effect means the Trapping of Solar energy due to atmospheric carbon dioxideThe greenhouse effect is a good thing.It warms the planet to its comfortable average of 57 degrees Fahrenheit (13.9 degrees Celsius)The greenhouse effect keeps life on earth, well, livable.The Green House Effect is caused by an excess of Carbon dioxideThe greenhouse effect causes Global warmingMethane gas is 80 times potent than CO2 in Green House EffectND2-03-2023ND25-2-2023', 0, 0, 0, 1790968056194) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6cae07464795e073', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Greenhouse effect causes', '{"A":"Global warming","B":"Cooling","C":"Planets to grow better","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The greenhouse effect causes global warmingWhen heat-trapping gases in Earth''s atmosphere absorb and re-emit outgoing infrared radiation, raising global temperaturesNatural Effect: Keeps Earth warm and supports life.Main Gases: CO₂, methane (CH₄), water vapor, and N₂O.Excess CO₂: Increases the greenhouse effect.Last updated 27-07-2026 by NA', 0, 0, 0, 1790968056194) ON CONFLICT(id) DO NOTHING;
