INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b07152a2194cd12e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Motion of planets follow _______ law.', '{"A":"Kepler law","B":"Hooke Law","C":"Newton Law","D":"None of these","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kepler''s law explains the motions of planets in the solar system.Kepler''s Laws of Planetary MotionThey describe how: (1) planets move in elliptical orbits with the Sun as a focus(2) a planet covers the same area of space in the same amount of time no matter where it is in its orbit(3) a planet''s orbital period is proportional to the size of its orbit (its semi-major axis).ND06-08-2023', 0, 0, 0, 1790968056402) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bdc69a520c314a31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The kingdom Protista includes:', '{"A":"Algae, Fungi, Virus, Bacteria","B":"Fungi, Protozoa, Bacteria","C":"Virus, Fungi Protozoa, Algae","D":"None of these","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kingdom Protista includes all eukaryotes that are not animals, plants, or fungi.Kingdom Protista is very diverse. It consists of both single-celled and multicellular organisms.ND6-08-2023', 0, 0, 0, 1790968056402) ON CONFLICT(id) DO NOTHING;
