INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0d8aa141296988ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The term Morphology in Biology deals with:', '{"A":"Study of human beings","B":"Study of form and structure of animals and plants","C":"study of formation of words","D":"Study of meaning","E":"none of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Morphology in Biology Study of the form and structure of animals and plantsThe field of morphology was developed by Johann Wolfgang von Goethe (1790) and independently by the German anatomist and physiologist Karl Friedrich Burdach (1800).whileMorphology in linguists deals with the Study of the formation of words.The term was first used in linguistics by August Schleicher in 1859ND2-08-2023', 0, 0, 0, 1790968056435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fbf42411142c351d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Different seasons are formed because', '{"A":"Of rotation of the earth around its axis","B":"Sun is moving around the earth","C":"Of revolution of the earth around the sun and on its orbit","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The earth`s spin axis is tilted with respect to its orbital plane. This is what causes the seasons. ND12_8_2023', 0, 0, 0, 1790968056435) ON CONFLICT(id) DO NOTHING;
