INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c01cf054c733ae2e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The ozone layer is present about 30miles (50km) in atmosphere above earth. The stratum (layer) of atmosphere in which ozone layer lies is called as', '{"A":"Exosphere","B":"Mesosphere","C":"Troposphere","D":"Ionosphere","E":"Stratosphere"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The stratosphere is a layer of Earth''s atmosphere. It is the second layer of the atmosphere as you go upward. It is present about 30miles (50km) in atmosphere above earth.', 0, 0, 0, 1790968056435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_05f5d9b3f4a48776', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which one of the following planets contains the Great Red Spot''?', '{"A":"Saturn","B":"Mars","C":"Jupiter","D":"Pluto"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The great red Spot is a hurricane in Jupiter''s southern hemisphere with purple-colored clouds that spin counterclockwise at wind speeds that exceed those in any hurricane on the earth. The excellent purple Spot has slowly changed over time, and is presently about 1.3 instances as huge as our planet.', 0, 0, 0, 1790968056466) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_357d6e6a1e40fdb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The season changes because of the ____________?', '{"A":"Moon is revolving round the earth","B":"Earth is revolving round its axis","C":"Earth is revolving around the sun","D":"Planet Mars is attracting the sun"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation موسم بدلتا ہے کیونکہ زمین سورج کے گرد گھوم رہی ہے۔Earth''s tilted axis causes the seasons. Throughout the year, different parts of Earth receive the Sun''s most direct rays. So, when the North Pole tilts toward the Sun, it''s summer in the Northern Hemisphere. And when the South Pole tilts toward the Sun, it''s winter in the Northern Hemisphere.', 0, 0, 0, 1790968056466) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5cbae19e225df60a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Mixture of sand and water can be separated by:', '{"A":"Condensation","B":"Sublimation","C":"Distillation","D":"Filtration"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Filtration is a process used to separate solids from liquids or gases using a filter medium that allows the fluid to pass through but not the solid. The fluid that passes through the filter is called the filtrate', 0, 0, 0, 1790968056466) ON CONFLICT(id) DO NOTHING;
