INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_402eec8810cac75a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Maximum portion of atmosphere on Earth is :', '{"A":"Oxygen","B":"Carbon","C":"Hydrogen","D":"Nitrogen"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dry air from Earth''s atmosphere contains 78.08% nitrogen, 20.95% oxygen, 0.93% argon, 0.04% carbon dioxide, and traces of hydrogen, helium, and other "noble" gases (by volume), but generally a variable amount of water vapor is also present, on average about 1% at sea level.', 0, 0, 0, 1790968056466) ON CONFLICT(id) DO NOTHING;
