INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e53cfcb1c481fc7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', '. Coal formation has four stages, its third stage is known as:', '{"A":"Bituminous","B":"Lignite","C":"Peat","D":"Anthracite"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are four stages in coal formation: peat, lignite, bituminous, and anthracite.', 0, 0, 0, 1790968056637) ON CONFLICT(id) DO NOTHING;
