INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a96e8353b1c0ae01', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The motion caused by earth quick travels outward from the focus ij the form of', '{"A":"Seismic waves","B":"Ultrasonic waves","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seismic waves are waves of energy that travel through Earth''s layers result of volcanic eruptions. large landslides and large man-made explosions that give out low-frequency acoustic energy.', 0, 0, 0, 1790968056805) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_441805df3d312ab1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'The point on Earth’s surface vertically above the focus of an earthquake is called:', '{"A":"Locus","B":"Epicenter","C":"Focus","D":"Flash Point"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The epicenter of an earthquake is the point on the earth''s surface vertically above the focus. Maximum damage is caused at the epicenter.زلزلے کا مرکز زمین کی سطح پر عمودی طور پر اوپر کی حیثیت سے ایک نقطہ ہے۔ زیادہ تر نقصان زلزلے کے مرکز پر ہوتا ہے۔', 0, 0, 0, 1790968056805) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3b1df35feb3a5891', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'There are how many types of Lunar Eclipse ?', '{"A":"4 types","B":"5 types","C":"3 types","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are three types of lunar eclipse: a total lunar eclipse, a penumbral lunar eclipse and a partial lunar eclipse. To understand the difference between them, we first need to understand how Earth''s shadow works.', 0, 0, 0, 1790968056805) ON CONFLICT(id) DO NOTHING;
