INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_246c9ed3d1c42bad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Which of these foods has the most calories?', '{"A":"One 4-inch diameter plain pancake","B":"Two slices of beefs","C":"One cup of cooked rice","D":"one 7- inch long carrot"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:Ctwo hundred caloriesA cup of white rice has approximately two hundred calories now no longer insignificant, thinking about it`s most customarily used as a small part of a bigger dish.', 0, 0, 0, 1790968056835) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_005754d3f92e1c29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Videotape used in camcorders to record audio and video signal employee:', '{"A":"Fine grains of copper","B":"Fine grains of Iron oxide","C":"Fine grains of Aluminum","D":"Fine grains of Silver"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Videotape is magnetic tape used for storing video and usually sound in addition. Information stored can be in the form of either an analog signal or digital signal.', 0, 0, 0, 1790968056867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_86d210d88ca1c6fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Vitamins is also known as cobalamin', '{"A":"Vitamin C","B":"Vitamin B12","C":"Vitamin A","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin B12 is a nutrient that helps keep the body''s nerve and blood cells healthy and helps make DNA, the genetic material in all cells. Vitamin B12 also helps prevent a type of anemia called Megaloblastic Anemia that makes people tired and weak', 0, 0, 0, 1790968056867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3c819dbdc2e7da7f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Water loss from leaves through stomata is called as:', '{"A":"Evapo-transpiration","B":"Respiration","C":"Evaporation","D":"Transpiration"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The loss of water vapor to the atmosphere through stomata is a passive process, meaning that metabolic energy in the form of ATP is not required for water movement. The energy driving transpiration is the difference in energy between the water in the soil and the water in the atmosphere.', 0, 0, 0, 1790968056867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_00acd0a06eabbf1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Water-soluble vitamins are not stored in the body __________?', '{"A":"vitamins B-complex","B":"vitamin C","C":"vitamin A","D":"vitamin D","E":"Options A & B"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation B-complex vitamins and vitamin C are water-soluble vitamins that are not stored in the body and must be replaced each day. These vitamins are easily destroyed or washed out during food storage and preparation.', 0, 0, 0, 1790968056867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_160d8138450f77fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Mangrove swamps serve all the following function.', '{"A":"Erosion protection for the coastline","B":"Prevention of Typhoid and hurricane damage","C":"Entrapment of sediment washed off land","D":"Nursery for many aquatic organisms","E":"All of these"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mangrove swamps serve all the following function 1. Erosion protection for the coastline, 2. Prevention of Typhoid and hurricane damage, 3. Entrapment of sediment washed off land, 4. Nursery for many aquatic organisms, gf', 0, 0, 0, 1790968056867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f94630ed7ca1f4a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Linking of ca+2 with calmodulin activates___ in the contraction cycle of smooth muscles', '{"A":"MLC phosphorylase","B":"MLC kinase","C":"MHC kinase","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Myosin light-chain kinase also known as MYLK or MLCK is a serine/threonine-specific protein kinase that phosphorylates a specific myosin light chain, namely, the regulatory light chain of myosin II.', 0, 0, 0, 1790968056867) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_250980b9d424ff8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_general', 'Life begets life has been confirmed by.', '{"A":"Louis pasteur","B":"Rutherford","C":"Charles diction","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Louis pasteur denied theory of spontaneous generation n explained that life comes from pre existing life sources. life did not come from presterilised flask but Louis Pasteur showed that in flask open to air, new living organisms appeared in the heat killed yeast culture.', 0, 0, 0, 1790968056867) ON CONFLICT(id) DO NOTHING;
