INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9860655060a6623c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Bio chemical reactions take place inside the cells of organisms due to :', '{"A":"Enzymes","B":"biochemical reactions","C":"both","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chemical reactions that take place inside living things are called biochemical reactions. An enzyme is a substance that acts as a catalyst in living organisms, regulating the rate at which chemical reactions proceed without itself being altered in the process.', 0, 0, 0, 1790968059459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ec4769bee6fb663a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Atomic reactor fuel is ?', '{"A":"Uranium","B":"Aluminum","C":"Chlorine","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Reactors use uranium for nuclear fuel. The uranium is processed into small ceramic pellets and stacked together into sealed metal tubes called fuel rods.', 0, 0, 0, 1790968059459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6bd3e7d690e4e3f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Atomic number of nitrogen is ____?', '{"A":"5","B":"6","C":"7","D":"8","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nitrogen is the chemical element with the symbol N and atomic number 7. It was first discovered and isolated by Scottish physician Daniel Rutherford in 1772. Symbol: NAtomic number: 7 Boiling point: -195.8 °C', 0, 0, 0, 1790968059459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e075dbb8c25896ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'An instrument use to measure gas pressure is called', '{"A":"Ammeter","B":"Galvanometer","C":"Barometer","D":"Manometer","E":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Manometer is a device to measure pressures. A common simple manometer consists of a U shaped tube of glass filled with some liquid.', 0, 0, 0, 1790968059459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c782f1a55567d7c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'An Acid is indicated by _____final color on litmus:', '{"A":"Red","B":"Orange","C":"Colorless","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation light blue litmus paper turning red under acidic conditions Red litmus paper turns blue under basic or alkaline conditions. Purple litmus paper is neutral.At pH levels of 0.0 to 4.5, the solution turns a red color; At pH levels of 8.3 to 14.0, it turns a blue color.', 0, 0, 0, 1790968059459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_318c06762564b2bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', '.___ is animo acid which is lost in cystic fibrosis', '{"A":"Methionine","B":"Alanine","C":"Phenylalanine","D":"Glycine"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An amino acid is an organic molecule that is made up of a basic amino group (−NH2), an acidic carboxyl group (−COOH), and an organic R group (or side chain) that is unique to each amino acid.', 0, 0, 0, 1790968059459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_02a5bec65db401de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'What is the difference between an explosion and combustion?', '{"A":"In the former it is violent and rapid creation with release of much heat energy while in the latter it is a generally slow reaction with release of less heat energy","B":"In the former nuclear reactions take place while in the latter burning takes place","C":"In the former it is a violent and rapid reaction with release of much heat of energy while in the latter it is a generally slow reaction with release of slow energy","D":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:AIn the former, it is violent and rapid creation with release of much heat energy while in the latter it is a generally slow reaction with release of less heat energy', 0, 0, 0, 1790968059459) ON CONFLICT(id) DO NOTHING;
