INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5f1c356db0c5148f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_chemistry', 'Small liquid drops assume spherical shape because:', '{"A":"Of adhesion","B":"Of the pressure from all sides","C":"Of the gravitational force","D":"The liquid tends to have minimum surface area dure to surface tension"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Spherical shape is because drop always tends to acquire minimum surface area due to the surface tension, and for a given volume, the surface area of sphere is minimum.', 0, 0, 0, 1790968059490) ON CONFLICT(id) DO NOTHING;
