INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_78ba9634faf790ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'As compared to plant cell animal cell is characterized the presence of :', '{"A":"Many small vacuoles","B":"A large vacuoles","C":"Penheral nucleus","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation plants cell have cell wall while animal cell have only cell membrane', 0, 0, 0, 1790968060430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2920c1a321c9b18c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'An artery is a vessel carrying :', '{"A":"Oxygenated blood","B":"Deoxygenated blood","C":"Blood to liver","D":"Blood to heart"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Arteries are blood vessels responsible for carrying oxygen-rich blood away from the heart to the body. Veins are blood vessels that carry blood low in oxygen from the body back to the heart for reoxygenation.', 0, 0, 0, 1790968060430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5206e68689f3f7dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The message received by and transmitted from the brain to the various parts of the body take the form of', '{"A":"Chemical impulse","B":"Nerve Impulse","C":"Automatic impulse","D":"Mechanical impulse"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:BElectric impulse also called Nerve impulse Messages in the form of electrical impulses are constantly moving back and forth between the brain and other parts of the body. A special cell called a neuron is responsible for sending these messages.', 0, 0, 0, 1790968060430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ca56de21cf4ff15', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Our body needs Vitamin E for:', '{"A":"Antioxidant","B":"Protection of cell walls","C":"Both","D":"Eyes","E":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The body also needs vitamin E to boost its immune system so that it can fight off invading bacteria and viruses.', 0, 0, 0, 1790968060430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_706beda609815e2d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Heart attack is caused due to:', '{"A":"Blood sugar","B":"Blood protein","C":"Blood urea","D":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hyperglycemia due to diabetes can damage blood vessels, the heart, and the nerves that control blood vessels. Over time, this damage can lead to heart disease. People with diabetes are more likely to develop heart disease earlier than people without diabetes.', 0, 0, 0, 1790968060430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b99a2d7b0488cc77', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'The function of liver is to', '{"A":"Promote respiration","B":"Promoter digestion of food","C":"Store glucose as glucogen","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AnswerCThe liver performs a relevant FUNCTION in retaining blood glucose levels. Following intake of food, extra glucose may be saved in the liver as glycogen . This is inspired through insulin release.', 0, 0, 0, 1790968060430) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0a8147a8f63640bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which vitamin deficiency causes Beriberi', '{"A":"Vitamin B1","B":"Vitamin A","C":"Vitamin C","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Found in many foods including yeast, cereal grains, beans, nuts, and meatWater soluble', 0, 0, 0, 1790968060461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5fd927d18ee77077', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Which vitamin deficiency leads to uncontrolled bleeding during an injury', '{"A":"Vitamin A","B":"Vitamin K","C":"Vitamin C","D":"Vitamin D"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Green leafy vegetables and intestinal bacteria are good source of vitamin K', 0, 0, 0, 1790968060461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_586c0a9bf10cb7e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Vitamin B12 is found in :', '{"A":"Fish","B":"Meat","C":"Both","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Vitamin B12 is naturally present in foods of animal origin, including fish, meat, poultry, eggs, and dairy products.', 0, 0, 0, 1790968060461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a8821516c312382e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Vitamin B 12 is founded in?', '{"A":"egg","B":"yogurt","C":"liver","D":"All"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation vitamin B12 found inFish and shellfish such as trout, salmon, tuna fish, and clams.Fortified breakfast cereal.Low-fat milk, yogurt, and cheese.Eggs.', 0, 0, 0, 1790968060461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62d99c8c87831062', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Vitamin C deficiency leads to ________?', '{"A":"Cancer","B":"Cold","C":"Scurvy","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scurvy is a state of dietary deficiency of vitamin C (ascorbic acid). The human body lacks the ability to synthesize and make vitamin C Depends on exogenous dietary sources to meet vitamin C needs.', 0, 0, 0, 1790968060461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7fa2f0bcc5f3e4e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Longest muscle in human body :', '{"A":"Sartorius","B":"Biceps","C":"Deltoid","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sartorius muscle is a thin, long, superficial muscle in the anterior compartment of the thigh.', 0, 0, 0, 1790968060461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed55f29d851caddf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'A Skeleton is made up of _____ that help to support the animals.', '{"A":"Meat","B":"Bones","C":"Tissues","D":"Molecules"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation skeleton ڈھانچہAdult Human Skeleton Is Made Up of 206 BonesDetails of skeleton bones', 0, 0, 0, 1790968060461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0617bbdf40be4cbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'In human body heart function as source of', '{"A":"Battery","B":"Electric Generator","C":"Charge","D":"Electromotive force"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The human heart is an organ that pumps blood throughout the body via the circulatory system, supplying oxygen and nutrients to the tissues and removing carbon dioxide and other wastes.', 0, 0, 0, 1790968060461) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ee3724ede4fe2084', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'In human being chances of heart attack can be prevented by', '{"A":"Taking antibiotics","B":"Taking vacancies","C":"Decreasing blood cholesterol level","D":"Increasing blood cholesterol level"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cholesterol is a waxy substance called a lipoprotein', 0, 0, 0, 1790968060491) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c85ad49a48b17c6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_biology', 'Human brain is devided into how many parts?', '{"A":"2","B":"4","C":"6","D":"None of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Human brain is divided into 3 parts.01. Fore Brain02. Middle Brain 03. Hin Brain', 0, 0, 0, 1790968060491) ON CONFLICT(id) DO NOTHING;
