INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eds_space', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Astronomy & Space', 'top_everyday_science', 158, 1790968060524) ON CONFLICT(id) DO UPDATE SET total_mcqs = 158;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_112a084f79601fe3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Nearest planet to the sun is/are _____?', '{"A":"Mercury","B":"Venus","C":"Mars","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mercury is the closest planet to the Sun, followed by Venus.Called an inner planet because it orbits inside Earth’s orbit.Number of moons: 0 (Mercury has no natural satellites).Size: Smallest planet in the solar system.Nickname: Swift Planet, due to its fast orbit around the Sun (≈88 days per orbit).Last verified on 17-03-2026', 0, 0, 0, 1790968060562) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e97cba5f17b26084', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The Hubble Space Telescope was invented by?', '{"A":"NASA and ESA jointly (John C. Mather & team involvement)","B":"Galileo Galilei","C":"Isaac Newton","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Hubble Space Telescope is a joint project of NASA (USA) and ESA (European Space Agency).It was launched in 1990 into low Earth orbit.Scientists like John C. Mather contributed to its development and research.It is used for observing distant galaxies and space objects.Last verified on 08-06-2026', 0, 0, 0, 1790968060562) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f46ed455ace10b26', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'According to distance earth is the _____ closest planet to the sun.', '{"A":"Second","B":"First","C":"Third","D":"Fourth"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Earth is the third planet from the Sun in our solar system.The order of the planets starting closest to the Sun is:MercuryVenusEarthMarsJupiterSaturnUranusNeptuneLast verified on 27-09-2026', 0, 0, 0, 1790968060562) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_848f4e8afa7ca0ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which of the following is called "Blue Planet"?', '{"A":"Saturn","B":"Earth","C":"Jupiter","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Earth is called the Blue Planet.About 71% of Earth''s surface is covered by water.Water makes Earth appear blue from space.Earth is the third planet from the Sun.Earth’s natural satellite is the MoonLast updated: NA on 26-09-2026', 0, 0, 0, 1790968060562) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_357f761bacf619fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which planet is second from the Sun?', '{"A":"Jupiter","B":"Mars","C":"Uranus","D":"Venus"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Position: 2nd planet from the Sun.Distance: About 108 million km from the Sun.Order: Mercury → Venus → Earth.Temperature: Hottest planet in the Solar System.Reason: Thick atmosphere traps heat through the greenhouse effect.', 0, 0, 0, 1790968060562) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_334d900868d61fd3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Light year is a unit of _____?', '{"A":"Light","B":"Distance","C":"Time","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Light Year is the distance that light can travel in one year.The distance light travels in one year is known as light year.1 light year is equal to 9.5 x 10¹²km.Last verified on 30-03-2026', 0, 0, 0, 1790968060562) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aa1ce7b1e27b99d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which planet in our solar system rotates on its side, giving it a unique axial tilt of about 98 degrees?', '{"A":"Uranus","B":"Venus","C":"Jupiter","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Uranus is the planet in our solar system that rotates on its sideRotates on its side (axial tilt ~98°), appearing to spin sideways7th planet from the Sun3rd-largest planet in the solar systemVery cold and windyHas faint rings and more than two dozen small moonsLast updated by NS on 06-09-2026​', 0, 0, 0, 1790968060562) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c809f97537f1217b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'What type of reaction takes place in sun?', '{"A":"Fusion reaction","B":"Nuclear  reaction","C":"Both A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main reaction occurring in the Sun''s core is nuclear fusion.In fusion, hydrogen nuclei combine to form helium, releasing a huge amount of energy.This energy is responsible for the Sun''s light and heat.The Sun''s primary fusion process is the proton–proton chain reaction.Last verified on 01-09-2026', 0, 0, 0, 1790968060562) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_234e764b48e6c67d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The nearest planet to the Earth is ______?', '{"A":"Moon","B":"Venus","C":"Mercury","D":"Mars"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Venus comes closest to Earth when it is between Earth and the Sun. Minimum distance: about 24 million miles (≈ 38 million km). This close approach occurs roughly every 584 days. Additional Information: Mercury can be about 33 million miles away when Venus is on the far side of the Sun.Last verified on 17-01-2026', 0, 0, 0, 1790968060607) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_22c821f145cd69ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Who was the first person/man in Space?', '{"A":"Yuri Gagarin","B":"Neil Armstrong","C":"Alexei Leonov","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First man who travelled in Space was Yuri Gagarin in 1961.Yuri Gagarin was a Soviet pilot and cosmonaut.He aboard the first successful crewed spaceflight, became the first human to journey into outer space.Additional information:First man who Walk in Space was Alexei Leonov in 1965.First man who Walk on Moon was Neil Armstrong in 1969.Last verified on 10-03-2026', 0, 0, 0, 1790968060607) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a6282c0cd9aa41c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Gravity was discovered by ______?', '{"A":"Galileo Galilei","B":"Isaac Newton","C":"Albert Einstein","D":"Johannes Kepler"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Isaac Newton formulated the law of universal gravitation, explaining how gravity works.He famously described gravity after observing an apple fall from a tree.', 0, 0, 0, 1790968060608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_140d8118730b1674', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The light from the Sun reaches to earth is about?', '{"A":"5 min 20 sec","B":"6 min 20 sec","C":"7 min 20 sec","D":"8 min 20 sec"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sunlight travels at the speed of light (~3 × 10⁸ m/s).Takes 8 minutes 20 seconds on average to reach Earth.Sunlight takes approximately 499 seconds to travel from the Sun to Earth.Distance traveled: 150 million km from Sun to Earth.Moonlight takes only 1.3 seconds to reach Earth.Last verified on 13-03-2026', 0, 0, 0, 1790968060608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_758c7788af643c37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which planet is known as Morning and Evening Star?', '{"A":"Mercury","B":"Venus","C":"Jupiter","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Venus is called the Morning Star and Evening Star.It is the second closest planet to the Sun.It is the brightest planet and the hottest planet in the Solar System.It has no natural moon (satellite).It is also known as the "Black Planet".Last verified on 21-07-2026', 0, 0, 0, 1790968060608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c6250c9581fbf05b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'A unit of length equal to the average distance between the earth and sun is called?', '{"A":"Light year","B":"Parallax","C":"Astronomical unit","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Astronomical Unit (AU) is the average distance between the Earth and the Sun.It is a standard unit used to measure distances within the Solar System.1 AU = 149,597,870.7 km1 AU = 92,955,807.3 milesLight travels 1 AU in: About 8 minutes 20 secondsLast verified on 21-07-2026', 0, 0, 0, 1790968060608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f227e087eca41bb5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The planet of the solar system which has maximum numbers of Moon/Satellites?', '{"A":"Jupiter","B":"Venus","C":"Saturn","D":"Uranus"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Saturn is the second-largest planet in the solar system.Ganymede (Moon of Jupiter) is the largest satellite in the solar system.Planets and Natural Satellites:Mercury: 0Venus: 0Earth: 1 (Moon)Mars: 2 (Deimos, Phobos)Jupiter: 95Saturn: 274Uranus: 27Last verified on 02-05-2026', 0, 0, 0, 1790968060608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e35f0603b905d8e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Mercury is the only elemental metal that at room temperature is _____?', '{"A":"Gas","B":"Solid","C":"Liquid","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mercury is the only elemental metal that at room temperature is Liquid.Mercury (Hg) is the only metal that remains liquid at room temperature (about 25°C).Additional information:Chemical Symbol: HgAtomic Number: 80Melting Point: −38.83°CBoiling Point: 356.73°CLast verified on 20-07-2026', 0, 0, 0, 1790968060608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d7052775abc3d596', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Most of the energy produced by the Sun is due to ______?', '{"A":"Chemical reaction","B":"Nuclear fission","C":"Nuclear Fusion (Fusion of Hydrogen)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Most of the energy produced by the Sun is due to Nuclear Fusion (Fusion of Hydrogen).In the Sun''s core, hydrogen nuclei fuse to form helium, releasing a huge amount of energy.This energy is emitted as light and heat.Nuclear fusion has powered the Sun for about 4.6 billion years.Last verified on 20-07-2026', 0, 0, 0, 1790968060642) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_76bb0d340d8f17ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The age of Universe is ____?', '{"A":"100 million years","B":"1 million year","C":"13.8 billion years","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The age of the Universe is approximately 13.8 billion years.Additional information:Age of the Earth: ≈ 4.54 billion yearsAge of the Solar System: ≈ 4.6 billion yearsAge of the Milky Way: ≈ 13.6 billion yearsBig Bang: Occurred about 13.8 billion years agoLast verified on 20-07-2026', 0, 0, 0, 1790968060642) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd711e1bc9e05a1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Who was the first man to set foot on the moon?', '{"A":"Buzz Aldrin","B":"Yuri Gagarin","C":"Neil Armstrong","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Neil Armstrong was the first human to set foot on the Moon on July 20, 1969, during NASA''s Apollo 11 mission.His famous words upon landing were, "That''s one small step for man, one giant leap for mankind."Additional information:Neil Alden Armstrong was died on August 25, 2012.He was born on August 5, 1930.Last verified on 01-04-2026', 0, 0, 0, 1790968060642) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4d2699d429688a42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Satellite system that has speed equal to the revolving speed of earth is ______?', '{"A":"Polar satellite","B":"Geostationary satellite","C":"Global positioning satellite","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A geostationary satellite orbits the Earth at a speed that matches the Earth''s rotation.It staying fixed above the same point on the Earth''s surface.This allows it to maintain a constant position relative to the Earth.Last verified on 03-07-2026', 0, 0, 0, 1790968060642) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_09e8efbd306655e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which is the hottest planet in our solar system?', '{"A":"Venus","B":"Neptune","C":"Mars","D":"Jupiter"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The hottest planet in our solar system is Venus.Additional information:The black planet is called Venus.The second-closest planet to the Sun is Venus.Slowest Rotating PlanetNo moonSimilar in size to EarthLast verified on 30-03-2026', 0, 0, 0, 1790968060642) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4993c77234611f1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which is the farthest planet in our solar system?', '{"A":"Uranus","B":"Mercury","C":"Mars","D":"Neptune"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Neptune is the farthest planet.It was visited by the spacecraft Voyager 2.It''s is a very windy place.It has six rings.It has 14 moons.Last verified on 24-06-2026', 0, 0, 0, 1790968060642) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5bb7fbc3d76c5249', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which of the following Planet has the smallest diameter?', '{"A":"Venus","B":"Earth","C":"Mercury","D":"Mars"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mercury is the smallest planet in our solar system.Mercury with a diameter of 4,879 km (3031.67 mi).Nearest Planet to Sun.Fastest Planet.Last verified on 23-06-2026', 0, 0, 0, 1790968060642) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91e7c33138d12583', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which one among the following planets is known as the Red Planet?', '{"A":"Jupiter","B":"Venus","C":"Mars","D":"Mercury"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mars is known as the Red Planet due to its reddish appearance.Its surface contains iron oxide (rust) which gives it a red color.It is the 4th planet from the Sun in the solar system.Mars has two small moons: Phobos and Deimos.Mars is often called the “planet of future exploration”.Last verified on 12-06-2026', 0, 0, 0, 1790968060642) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e96c22b03841c8f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'According to the scientists, how many galaxies are there in the Universe?', '{"A":"10 million","B":"100 million","C":"10 billion","D":"100 billion"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to scientists, the universe has about 100 billion galaxies.Earlier estimates from the Hubble Space Telescope suggested similar numbers.Modern studies show it may be between 100–200 billion galaxies.Some older estimates even suggested up to 2 trillion galaxies (later revised).Last verified on 06-06-2026', 0, 0, 0, 1790968060680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e8592e82431831f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The largest planet of the solar system is _____?', '{"A":"Earth","B":"Mars","C":"Jupiter","D":"Saturn"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest planet in our solar system is Jupiter.5th planet79 known moons (Maximum number of moons)The Great Red Spot is a prominent featureGiant planet and the fastest-rotating planet Rotates approximately once every 10 hours.Age is about 4.603 billion years.Additional informationMercury is the smallest planet of the solar system.*****Last updated 07-09-2026 by NA', 0, 0, 0, 1790968060680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b7179eb875eec13a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'A light year is a _____ unit.', '{"A":"Speed","B":"Time","C":"Length","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A light year is the distance that light travels in one year.It is used to measure vast distances in space.Light moves at approximately 299,792 km per second.One light year ≈ 9.46 trillion kilometers (5.88 trillion miles).Last verified on 17-03-2026', 0, 0, 0, 1790968060680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1dbad160ab3c9218', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which is the coldest planet in the Solar System?', '{"A":"Uranus","B":"Neptune","C":"Venus","D":"Pluto"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Planet: UranusType: Ice GiantTemperature: Around −224°C (coldest recorded)Position from Sun: 7th planetComposition: Hydrogen, helium, methaneDiscovered: William Herschel in 1781Last verified on 16-05-2026', 0, 0, 0, 1790968060680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_700b55910bf54017', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which planet revolves clockwise around Sun from Earth?', '{"A":"Jupiter","B":"Neptune","C":"Venus","D":"Murcury"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Planet: VenusRotation direction: Clockwise (retrograde)Rotation period: ~243 Earth daysRevolution period: ~225 Earth daysUnique fact: Day is longer than its yearIt is the brightest planet.Last verified on 16-05-2026', 0, 0, 0, 1790968060680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_01a1d34c40de33cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Our solar system is located in which galaxy?', '{"A":"Magellanic Clouds","B":"Milky Way Galaxy","C":"Silky Way","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Our Solar System is located in the Orion Arm of the Milky Way galaxy.It including the Sun and eight planets.It consists of about 100–400 billion stars along with large amounts of gas and cosmic dust.Additional information:The Milky Way is a spiral galaxy with a diameter of about 100,000 light-years.The nearest large galaxy to the Milky Way is Andromeda, located about 2.5 million light-years away.Last verified on 11-03-2026', 0, 0, 0, 1790968060680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a89a65689216ad12', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The Sun has temperature of around _____?', '{"A":"3000 °C","B":"6000 °C","C":"4000 °C","D":"5000 °C"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sun is a star at the center of our solar system with a surface temperature of about 6000 °C (Sun’s core is even hotter, ~15 million °C).It provides light and heat, essential for life on Earth.The Sun’s energy drives weather, photosynthesis, and climate.Last verified on 18-03-2026', 0, 0, 0, 1790968060680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6fd28e92670a2590', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Titan is the biggest satellite of?', '{"A":"Saturn","B":"Venus","C":"Jupiter","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Titan is the largest moon of Saturn.It is also the second-largest moon in the solar system after Ganymede.It has a thick atmosphere mainly of nitrogen.Titan is larger than the planet Mercury in size.Last verified on 02-05-2026', 0, 0, 0, 1790968060680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9accde403346da99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The position of the earth in its orbit, when it is at its greatest distance causing summer in the Northern Hemisphere is _____?', '{"A":"Apogee","B":"Perigee","C":"Aphelion","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aphelion is the point in Earth''s orbit when it is farthest from the Sun, which occurs around early July.This distance contributes to the seasonal variations, including summer in the Northern Hemisphere.Last verified on 26-04-2026', 0, 0, 0, 1790968060717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e906aec710cb364b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The distance between Earth and Moon is ______?', '{"A":"3,50,000km","B":"3,60,100km","C":"3,72,000km","D":"3,84,400km"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Average Distance: 3,84,400 kmOrbit Period: 27.3 daysMoon Diameter: 3,474 kmEarth Diameter: 12,742 kmClosest Point (Perigee): ~363,300 kmFarthest Point (Apogee): ~405,500 kmLast verified on 01-04-2026', 0, 0, 0, 1790968060717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8638b393454224f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The natural satellite of Earth is known as ______?', '{"A":"Sun","B":"Asteroid","C":"Moon","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Moon is Earth’s only natural satellite.Diameter – 3,474 kmDistance from Earth – 384,400 kmOrbital period – 27.3 daysSurface gravity – 1/6th of EarthFirst human landing – Apollo 11, 1969Last verified on 18-03-2026', 0, 0, 0, 1790968060717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2508750e88164a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'What is the number of planets in the solar system?', '{"A":"10","B":"8","C":"9","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total planets: 8Inner planets: Mercury, Venus, Earth, Mars (4)Outer planets: Jupiter, Saturn, Uranus, Neptune (4)Pluto reclassified: 2006 (IAU decision)Largest planet: JupiterSmallest planet: MercuryLast verified on 01-04-2026', 0, 0, 0, 1790968060717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a718d3888c1ea094', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The diameter of Jupiter is eleven times the diameter of ______?', '{"A":"Earth","B":"Mars","C":"Mercury","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jupiter''s diameter is about 11 times the diameter of Earth.Jupiter is the largest planet in our solar system.Last verified on 30-03-2026', 0, 0, 0, 1790968060717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_42bdbddd5aed4b2d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Saturn has _____ moons.', '{"A":"82","B":"274","C":"97","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Saturn is the second-largest planet in the solar system.Ganymede (Moon of Jupiter) is the largest satellite in the solar system.Planets and Natural Satellites:Mercury: 0Venus: 0Earth: 1 (Moon)Mars: 2 (Deimos, Phobos)Jupiter: 95Saturn: 274Uranus: 27Last verified on 30-03-2026', 0, 0, 0, 1790968060717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66af129aa6f58057', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The brightest star visible in the sky without a telescope is?', '{"A":"Altair","B":"Aretonus","C":"Regulus","D":"Sirius"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sirius means صبح کا ستارہSirius, also called the Dog Star.It is the brightest star in the night sky visible without a telescope.It is located in the constellation Canis Major.It is about 8.6 light-years from Earth.Last verified on 19-03-2026', 0, 0, 0, 1790968060717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e9cd2a42b4b597f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The maximum number of electrons K orbit possesses?', '{"A":"2","B":"4","C":"6","D":"8"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The K orbit, also known as the first electron shell.It can hold a maximum of 2 electrons.The L orbit, also known as the second electron shell.It can hold a maximum of 8 electrons.The M orbit, also known as the third electron shell.It can hold a maximum of 18 electrons.Last verified on 19-03-2026', 0, 0, 0, 1790968060717) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9b847f64d0881a51', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The Halley''s comet can be seen after every _______ years.', '{"A":"46","B":"76","C":"16","D":"06"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Comets: huge masses of snow and rocks that revolve around the Sun in orbits.Comets: have huge glowing tails.Halley''s Comet was last seen in: 1986Halley''s Comet will be next seen in: 2062Last verified on 18-03-2026', 0, 0, 0, 1790968060756) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_414f8d83f7d4e42c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'What was the name of NASA’s spaceflight landed first humans on the moon in 1969?', '{"A":"Apollo 11","B":"Apollo 10","C":"Apollo 12","D":"Apollo 5"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Apollo 11 was the mission that successfully landed astronauts.Neil Armstrong and Buzz Aldrin on the moon on July 20, 1969.Last verified on 15-03-2026', 0, 0, 0, 1790968060756) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_87f7ce8769b68c09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The Sun is a _______?', '{"A":"Planet","B":"Element","C":"Asteroid","D":"Star"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sun is a star. There are lots of stars, but the Sun is the closest one to Earth. It is the center of our solar system. The Sun is a hot ball of glowing gases.The sun is composed of layers made up almost entirely of hydrogen and helium.Last verified on 13-03-2026', 0, 0, 0, 1790968060756) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_83e59bda9a78da22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'What is the gravity of moon as compared to the Earth?', '{"A":"1/6th of Earth","B":"1/5th of Earth","C":"1/4th of Earth","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Moon''s surface gravity is about 1/6th as powerful or about 1.6 meters per second. The Moon''s surface gravity is weaker because it is far less massive than Earth. A body''s surface gravity is proportional to its mass, but inversely proportional to the square of its radius.Last verified on 13-03-2026', 0, 0, 0, 1790968060756) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_041555588724a60b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Who used telescope first time in the history to observe Jupiter, Saturn and Venus?', '{"A":"Thomas Harriot","B":"Galileo - Galilei","C":"Aristotle","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The telescope was first used for astronomical observations in the early 17th century.Galileo Galilei first used an improved telescope in 1609 to observe planets like Jupiter, Saturn, and Venus.He discovered four large moons of Jupiter (Io, Europa, Ganymede, and Callisto).Last verified on 11-03-2026', 0, 0, 0, 1790968060756) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b49b3ad425be1628', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Ozone layer protect us from the harmful _______ of the Sun.', '{"A":"Heat","B":"Cold","C":"Ultraviolet rays","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ozone layer acts as Earth’s natural sunscreen, protecting life from the sun’s harmful ultraviolet (UV) radiation.UV radiation can cause skin cancer, eye damage, and harm to plants and animals.Additional information:Chemical Formula: O₃ (three oxygen atoms)Layer Location: Stratosphere, 15–40 km above EarthFunction: Absorbs UV-B and UV-C rays from the SunDepletion Causes: Air pollution, CFCs, industrial chemicalsProtection Measures: Reduce CFC use, ozone-friendly productsLast verified on 09-03-2026', 0, 0, 0, 1790968060756) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d7dc49cf5b06c4e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Why mercury is used as a thermometric fuild?', '{"A":"High M. P","B":"High B.P","C":"Stable coefficient of expansion","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mercury is used as a thermometric fluid Because it has several ideal properties like:High Boiling Point (B.P)Low Freezing Point (not high M.P)Stable and Uniform Coefficient of ExpansionVisibility and Non-wettabilityLast updated on 06-March-2026', 0, 0, 0, 1790968060756) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f8fc4cd50470a7c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which one of the following is a non-luminous object(s)? Sun, Stars, Moon, Fireflies', '{"A":"Sun","B":"Stars","C":"Moon","D":"Fireflies"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Non-luminous objects do not produce their own light; they are visible because they reflect light from other sources.The Moon is non-luminous; it reflects sunlight.Luminous objects like the Sun, stars, and fireflies produce their own light.Last verified on 06-03-2026', 0, 0, 0, 1790968060756) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ad68dfa894e09fcf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which type of vitamin is used for human body through sun?', '{"A":"Vitamin K","B":"Vitamin B","C":"Vitamin C","D":"Vitamin D","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sunlight is a good source of vitamin D.When our skin is exposed to sunlight, it produces vitamin D, It is essential for bone health, immune function, and the regulation of calcium levels in the blood.Deficiency of Vitamin D results in Rickets.', 0, 0, 0, 1790968060779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5881bec20963a2c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Our galaxy (Milky Way Galaxy) is _____ in shape.', '{"A":"Irregular","B":"Spiral","C":"Elliptical","D":"Circular"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Our Milky Way Galaxy is a barred spiral galaxyLooks like a rotating pinwheel from above or below, with a bright disk and spiral arms. Meaning it has a central bar-shaped structure, extending outwards like a giant pinwheel, with our solar system located on one of these arms', 0, 0, 0, 1790968060779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_93e1cf0562c897d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The Study of Universe it''s origin, nature and evaluation is called?', '{"A":"Astronomy","B":"Archaeology","C":"Geography","D":"Cosmology"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The study of the universe''s origin, nature, and evolution is called CosmologyEdwin Powell Hubble is called the father of Cosmology.The term cosmology was first used in English in 1656 in Thomas Blount''s Glossographia, with the meaning of "a speaking of the world"', 0, 0, 0, 1790968060779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6223527b64740c78', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Study of life in outer space is _____?', '{"A":"Exobiology","B":"Astrobiology","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The study of life in outer space focuses on the origin, evolution, and possibility of life beyond Earth.Two terms are commonly used: Exobiology and Astrobiology.Additional information:Exobiology specifically studies life beyond Earth.Astrobiology combines biology, chemistry, and astronomy to study life in the universe.Last verified on 16-01-2026', 0, 0, 0, 1790968060779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6e1cde97acd6b06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The most brightest planet is ______?', '{"A":"Sun","B":"Mercury","C":"Venus","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Venus is the brightest planet in the night sky.Due to its thick cloud cover that reflects sunlight strongly.It is often called the “Evening Star” or “Morning Star.”Additional information:Distance from Sun: ~108 million kmDiameter: 12,104 kmOrbital Period: 225 Earth daysAtmosphere: Thick CO₂ clouds, very reflectiveLast verified on 15-01-2026', 0, 0, 0, 1790968060779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e7a20d58a7adf1ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Heat of sun reaches the earth by ________?', '{"A":"Convection","B":"Radiation","C":"Conduction","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Heat from the Sun reaches Earth through radiationIt is the transfer of energy via electromagnetic waves (like infrared, visible light, UV) Sunlight takes an average of 8 minutes and 20 seconds to travel from the Sun to the Earth.', 0, 0, 0, 1790968060779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd7c5a31cf8bcd4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Light from Sun travels a distance before it reaches Earth', '{"A":"50 Million km","B":"100 Million km","C":"150 Million km","D":"200 Million Km"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Light from Sun travels a distance of 150 Million km before it reaches EarthDistance: ~93 million miles (150 million km) on average.Speed of Light: ~186,282 miles/second (300,000 km/s) in a vacuum.Travel Time: Approximately 8 minutes, 20 seconds (or 500 seconds).', 0, 0, 0, 1790968060779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_caec5d914c7f1513', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which planet moves fastest around the sun?', '{"A":"Venus","B":"Jupiter","C":"Mercury","D":"Mars"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The planet that moves around the Sun at the largest speed is Mercury***Mercury is the fastest planet, which speeds around the sun at 47.87 km/s.In miles per hour, this equates to a whopping 107,082 miles per hour.', 0, 0, 0, 1790968060779) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_77b69168e3039815', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which planet is the least dense?', '{"A":"Mercury","B":"Mars","C":"Saturn","D":"Earth"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SaturnRinged Planet for SaturnWhich planet is the least dense? SaturnWhich of the following planet has rings around its surface? SaturnNumber of moons in Saturn: 83whileThe planet which has the highest density is? EarthND5-5-2023', 0, 0, 0, 1790968060807) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7ae07872ba546a30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which of the following is the lightest metal? Mercury Lithium Lead Silver', '{"A":"Mercury","B":"Lithium","C":"Lead","D":"Silver"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lithium is the lightest metal.Density of 0.534 g/cm³. It is an alkali metal, The third element on the periodic table,It is soft enough to be cut with a knife.Uses: Due to its low density and high reactivity, it''s used in aircraft and, famously, in the production of batteries for electric vehicles and consumer electronics.', 0, 0, 0, 1790968060807) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_675aa9815e086046', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The time light takes from Sun to reach Earth is _____?', '{"A":"8 minutes","B":"25 minutes","C":"45 minutes","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Studies show that it takes an average of 8 minutes and 20 seconds for sunlight to move from the sun to the earth. Sunlight moves at the speed of light. You can see that the distance of the sun from the earth = 149.6 x 106 km.Photons emitted from the surface of the sun need to traverse the vacuum of the universe to reach our eyes.', 0, 0, 0, 1790968060807) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ae043014031a265', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'When the moon seems to be getting bigger, it is called the?', '{"A":"Gibbous moon","B":"Waning moon","C":"Waxing moon","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Waxing moon refers to the phase when the visible portion of the moon is increasing.It moving from new moon towards full moon.', 0, 0, 0, 1790968060807) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc93e2df4af8d839', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'When was the Pakistan Space and Upper Atmosphere Research Commission (SUPARCO) established?', '{"A":"1957","B":"1962","C":"1961","D":"1971"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pakistan Space and Upper Atmosphere Research Commission (SUPARCO) was established in 1961.It was originally formed as a Committee in 1961 and gained Commission status in 1981.The SUPARCO is Pakistan''s national space agency and is responsible for the development of space technology and its peaceful applications in the country.It is headquartered in Islamabad and has technical facilities in Karachi, Lahore, Multan, Quetta, Peshawar and Gilgit.', 0, 0, 0, 1790968060807) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_42160efa6fe6d5bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'To arrange Jupiter, Venus, Mars, and Earth according to their positions:', '{"A":"Jupiter, Venus, Mars, and Earth","B":"Venus, Earth, Mars, and Jupiter","C":"Earth, Venus, Mars and Jupiter,","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Explanation:1. Venus is the closest planet to Earth.2. Earth is the second planet.3. Mars comes after Earth in the order of planets from the Sun.4. Jupiter is the fifth planet from the Sun and the largest planet in our solar system.', 0, 0, 0, 1790968060807) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9c617d6f585c1f9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which planet is closest to the sun?', '{"A":"Venus","B":"Mercury","C":"Earth","D":"Jupiter"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mercury is mostly made up of iron.It''s surface covered with craters.It has no atmosphere and no moons.It''s closest to the sun.It''s smallest planet.', 0, 0, 0, 1790968060807) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd515b477d365fe6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', '_______ is the biggest planet of our solar system?', '{"A":"Mercury","B":"Mars","C":"Jupiter","D":"None of these"}', 'C', NULL, 0, 0, 0, 1790968060807) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dca468d5f846337c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The study about celestial objects of the universe is called?', '{"A":"Geometry","B":"Geography","C":"Archaeology","D":"Astronomy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The telescope is undoubtedly the most important investigative tool in astronomy.A celestial body that revolves around a planet is known as a natural satellite.', 0, 0, 0, 1790968060832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5486e6d5647bd9a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'All planets of the solar system have moons except?', '{"A":"Earth and Mars","B":"Venus and Mercury","C":"Jupiter and Saturn","D":"Uranus and Neptune"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Venus and Mercury are the only planets in the solar system that do not have any natural satellites or moons.Likely due to their proximity to the Sun and gravitational influences.', 0, 0, 0, 1790968060832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_04c50cf962f9e26e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which of the following is called the Green Planet?', '{"A":"Earth","B":"Jupitar","C":"Uranus","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Uranus is four times the size of the Earth.Uranus appears greenish in color.Because of the large amount of methane gas present in its atmosphere.', 0, 0, 0, 1790968060832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d2254052474e2c4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Solar (Sun) Eclipse occurs when _______?', '{"A":"The moon comes between earth and sun","B":"The Sun comes between earth and moon","C":"The Sun comes between earth and earth","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A solar eclipse can only take place during the phase of the new moonwhen the moon passes directly between the sun and Earth and its shadows fall upon Earth''s surface.', 0, 0, 0, 1790968060832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5f1abc3316832cbb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which of the following planets have only one moon?', '{"A":"Earth","B":"Jupiter","C":"Venus","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Planets and Natural Satellites:Mercury: 0Venus: 0Earth: 1 (Moon)Mars: 2 (Deimos, Phobos)Jupiter: 95Saturn: 274Uranus: 27', 0, 0, 0, 1790968060832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6a4b926fee42662', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The Planet which revolves slowly around the Sun is _____?', '{"A":"Mercury","B":"Mars","C":"Neptune","D":"Earth"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The planet that revolves the slowest around the Sun is Neptune.It takes Neptune approximately 165 Earth years to complete one orbit around the Sun.This slow movement is due to Neptune''s large distance from the Sun, which is nearly 4.5 billion kilometers.Neptune is the farthest planet.It was visited by the spacecraft Voyager 2.It''s is a very windy place.It has six rings.It has 14 moons.', 0, 0, 0, 1790968060832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4dc496eb224d0f8a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Name the scientist who first declare that the Earth revolves around the Sun?', '{"A":"Newton","B":"Galileo","C":"Copernicus","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The scientist who first discovered that the earth revolves around the sun was Copernicus.Earth''s Rotational Theory:Rotation can be defined as the spin of Earth on its own axis from west to east direction.It must also be noted that the speed of rotation of the earth is not constant throughout latitudes.It differs at different latitudes.', 0, 0, 0, 1790968060832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7da9011377fde26b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which planet has similar size as Earth?', '{"A":"Venus","B":"Mars","C":"Uranus","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation VenusEight planets in the solar systemVenus is the hottest planet in the solar systemThe black planet is called VenusThe second closest planet to the sun is VenusWhich is the slowest Rotating Planet? VenusWhich planet has no moon? VenusNumber of moons in Venus: 0Which planet has a similar size to Earth? VenusND5-5-2023', 0, 0, 0, 1790968060832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8295895bb4883fdd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The four rocky planets at the center of the solar system Mercury, Venus,  Earth and Mars are known as the _____?', '{"A":"Terrestrial planets","B":"Outer planets","C":"Gas giants","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Terrestrial planets are rocky planets, including Earth, Mars, Venus, and Mercury.These planets have solid, rocky surfaces.Unlike gas giants which are composed mainly of gases.', 0, 0, 0, 1790968060855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_47f6b786717aeefe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Mercury is used in thermometers because ______?', '{"A":"It remains liquid at ordinary temperatures","B":"It has uniform expansion (expand uniformly)","C":"It is opaque and visible","D":"It does not stick to glass","E":"All of the above"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mercury remains liquid at a wide range of temperatures, has uniform expansion.It is easily visible due to its opacity.It does not stick to glass, allowing accurate and consistent readings in thermometers.', 0, 0, 0, 1790968060855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1916646531ac5e05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The release of energy from the sun is the result of _____?', '{"A":"Fusion reaction","B":"Nuclear Fusion","C":"Nuclear Fission","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Solar energy is created by nuclear fusion that takes place in the sun. Fusion occurs when protons of hydrogen atoms violently collide in the sun''s core and fuse to create a helium atom. This process, known as a PP (proton-proton) chain reaction**ND17-1-2023', 0, 0, 0, 1790968060855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9efd5f3b99e8db75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which is the largest among the following? Earth, The Sun ,Solar System, Galaxy', '{"A":"Earth","B":"The Sun","C":"Solar System","D":"Galaxy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A galaxy is a gravitational system of stars, star remnants, interstellar gas, dust, and dark matter.Earth: diameter of approximately 12,742 kilometers (7,918 miles)The Sun: diameter of approximately 1,392,684 kilometers (865,374 miles)Solar System: diameter of approximately 9.2 billion kilometers (5.7 billion miles)Galaxy (Milky Way): diameter of approximately 100,000 to 200,000 light-years (9.461 × 10^17 to 1.884 × 10^18 kilometers)', 0, 0, 0, 1790968060855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_41c8d7f670bef28b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Gravitational force of the moon ______?', '{"A":"Gives rise to tides in the sea","B":"Gives energy to the sea","C":"Taxes energy from the sea","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The moon’s gravitational pull attracts ocean water, causing high and low tides.This effect is strongest on the side of Earth facing the moon.', 0, 0, 0, 1790968060855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0ac519deb9f2d71b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which law explains why rockets move forward in space?', '{"A":"Newton’s First Law","B":"Newton’s Second Law","C":"Newton’s Third Law","D":"Law of Gravitation"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rockets move forward in space due to Newton''s Third Law of Motion, which states that for every action, there is an equal and opposite reaction. When a rocket engine burns fuel, it expels hot gases out of the nozzle. This expelled gas exerts a force downwards, and in reaction.The rocket experiences an equal force upwards, propelling it forward.', 0, 0, 0, 1790968060855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_717a5e768b0cb3c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Chemical symbol of Mercury is ______?', '{"A":"Fe","B":"Na","C":"Hg","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The atomic weight of Mercury (Hg) is 200.59 unified atomic mass units (u), as listed on the periodic table.Key Information:Symbol: Hg (from Latin Hydrargyrum)Atomic Number: 80Standard Atomic Weight: 200.592 u (often rounded to 200.59 u).', 0, 0, 0, 1790968060855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ccfce30fb543adb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The resolving power of telescope depends on ______?', '{"A":"Diameter of objective lens","B":"Focal length of eye-lens","C":"Focal length of objective lens","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The resolving power of a telescope is its ability to produce separate images of two closely spaced objects, like two distant stars.It is directly proportional to the diameter (aperture) of the objective lens or mirror.', 0, 0, 0, 1790968060855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_715a029cd7370013', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The orbits of planets around the sun, or of satellites around the earth can be _____?', '{"A":"Parabolic and hyperbolic","B":"Circular and elliptic (oval)","C":"Circular and hyperbolic","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The orbits of planets around the Sun and satellites around Earth are typically circular or elliptical, as per Kepler''s laws of planetary motion.These two types of orbits are the most common in celestial mechanics.', 0, 0, 0, 1790968060879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03c42571cd7bd291', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Velocity of electron will be maximum in which orbit?', '{"A":"1st","B":"2nd","C":"3rd","D":"4th"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The velocity of an electron is maximum in 1st shell because according to Bohr''s modelSo we have velocity of electron = 2.188 ×10^6 m/s. By calculation, we gained velocity= 1.094×10^6 m/s.So it is determined that the velocity is decreased as we move from lower to higher shell', 0, 0, 0, 1790968060879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_179ff3e0428079d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The melting point of mercury is ______?', '{"A":"-39°C","B":"0°C","C":"-100°C","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mercury is a chemical element It is commonly known as quicksilver. It is the only metal to remain in liquid form at room temperature. Droplets of liquid mercury are shiny and silver-white with a high surface tension, appearing rounded when on flat surfacesSymbol: HgAtomic number: 80Melting point: -38.83 °CBoiling point: 356.7 °CCAS ID: 7439-97-6Atomic mass: 200.59 u', 0, 0, 0, 1790968060879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_43cfc8a2293a90cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'A light year is related to ____?', '{"A":"Time","B":"Distance","C":"Frequency","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Light year refers to speed of light expressed in miles per year(it is about ten trillion kilometers or six trillion miles).Light year is a unit of distance.Light Year: the distance that light can travel in one year. The distance light travels in one year is known as the light year.1 light year is equal to 9.5 x 10^12 kmND11-07-2023', 0, 0, 0, 1790968060879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eb50548e734ea01f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The energy emitted from the sun is supposed to be due to:', '{"A":"Nuclear fission","B":"Nuclear fusion","C":"Both a &b","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The energy emitted by the sun is primarily due to nuclear fusion reactions in its core. Specifically, hydrogen atoms are fused into helium atoms, releasing a tremendous amount of energy in the process. This energy is then radiated outwards as light and heat.', 0, 0, 0, 1790968060879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b8bcb071f42cddf7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', '1 light year =?', '{"A":"8.46 trillion km","B":"6.46 trillion km","C":"9.46 trillion km","D":"7.46 trillion km"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Detailed AnswerOne light year is equal to the distance that light travels in one year (it is about ten trillion kilometers or six trillion miles). A light year is a unit of distance. The distance light travels in one year is known as light year. A light-year is a unit of length used to express astronomical distances and measures about 9.46 trillion kilometers (9.46 x 1012 km) or 5.88 trillion miles (5.88 x 1012 mi)', 0, 0, 0, 1790968060879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5f61adb99a9ca965', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'A celestial body revolves around a planet is known as?', '{"A":"Cornets","B":"Meteors","C":"Moon","D":"Asteroids"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A celestial body that revolves around a planet is known as a satelliteWhich can be natural (like the Moon) or artificial (like the International Space Station).A celestial body that revolves around a planet is known as a moon.Moons are natural satellites orbiting planets and can vary in size and composition.', 0, 0, 0, 1790968060879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0c67b226b905e16b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The ozone layer protects the earth from rays sent by the sun?', '{"A":"Radioactive rays","B":"Infrared rays","C":"Gamma rays","D":"Ultraviolet rays"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The stratospheric ozone layer is Earth''s “sunscreen” protecting living things from too much ultraviolet radiation from the sun.Oxygen layer in the atmosphereOzone protects us from the harmful ultraviolet radiation of the sun.Ozone formula: O3The ozone layer lies approximately 15-40 kilometers (10-25 miles) above the Earth''s surface, in the stratosphere.The ozone layer is depleting: Air pollutionND17-7-2023', 0, 0, 0, 1790968060879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c0dfb660b90186c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which planet is called the Sister of the Earth?', '{"A":"Mars","B":"Neptune","C":"Jupiter","D":"Venus"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Venus is known as Earth''s sister planet because both planets are a lot similar to each other.Mars is called the brother of the Earth.', 0, 0, 0, 1790968060898) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_83667897a1348126', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which is the outermost planet in the solar system?', '{"A":"Neptune","B":"Pluto","C":"Uranus","D":"Both A and B"}', 'D', NULL, 0, 0, 0, 1790968060898) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7b42cb6582182061', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which gas saves us from the harmful ultraviolet radiations coming from the sun?', '{"A":"Carbon Dioxide","B":"Oxygen","C":"Nitrogen","D":"Ozone"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ultraviolet rays are filtered through Ozone Layer.The ozone layer, often known as ozone shield is a part of Stratosphere.', 0, 0, 0, 1790968060898) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a78f584eff0925d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The most abundant element in the universe is called?', '{"A":"Oxygen","B":"Helium","C":"Hydrogen","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hydrogen is the most abundant element in the universe.it is about 75 percent of its normal matter and was created in the Big Bang.Additional information:Oxygen is the most abundant element in the earth`s crust.Calcium is the most abundant mineral in the human body.', 0, 0, 0, 1790968060898) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dbed7d18584b50e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Solar system was discovered by _____?', '{"A":"Copernicus","B":"Newton","C":"Galileo","D":"Kepler"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The main idea of the solar system was proposed by the Polish astronomer Nicolaus Copernicus (1473-1543).who said that "the Sun is the centre of the Universe" and made the planets move around it in perfect circles (in his book entitled, "On the Revolution of the Celestial Spheres", written in Latin and published in 1543)', 0, 0, 0, 1790968060898) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0ed6c694e47a421f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The light from the sun reaches the earth after 8.3 minutes whereas the light reflected from the moon reaches us in ______?', '{"A":"1 second","B":"1.5 seconds","C":"2 seconds","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The average distance between the Moon and Earth is about 384,400 km, and light travels at 300,000 km/s.Using the formula time = distance/speed, light takes approximately 1.28 to 1.5 seconds to reach Earth from the Moon.', 0, 0, 0, 1790968060898) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f561604add7000a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'When oxygen tension is 115 mm of mercury then hemoglobin saturation is _____?', '{"A":"100%","B":"98%","C":"78%","D":"68%"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When oxygen tension is 115 mm of mercury, hemoglobin saturation is 100%. At high oxygen tensions (like 100 mm Hg and above), essentially all available hemoglobin binding sites are occupied by oxygen molecules, resulting in complete saturation.', 0, 0, 0, 1790968060898) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d5975792e4d5a2c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'NASA''s Perseverance Rover landed at Mars on ______?', '{"A":"21 Feb 2021","B":"20 Feb 2021","C":"19 Feb 2021","D":"18 Feb 2021"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Perseverance landed on Feb. 18, 2021. is a car-sized Mars rover designed to explore the Jezero crater on Mars as part of NASA''s Mars 2020 mission. It was manufactured by the Jet Propulsion Laboratory and launched on July 30, 2020As of 23 July 2023, Perseverance has been active on Mars for 861 sols.', 0, 0, 0, 1790968060898) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd8a70c73f6921f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which planet rotates so slowly (slowest rotating planet) on its axis that its one day is almost equal to one year of the earth?', '{"A":"Mars","B":"Jupiter","C":"Venus","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation VenusEight planets in the solar systemVenus is the hottest planet in the solar system.The black planet is called Venus.The second closest planet to the sun is Venus.Number of moons in Venus: 0Venus planet has a similar size to EarthVenus takes about 243 Earth days to complete one rotation on its axis (one Venus day).It orbits the Sun in about 225 Earth days, making its day longer than its year.', 0, 0, 0, 1790968060922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3c3cf8ba26aa4eac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Geo stationary satellites keep pace with the earth and complete one orbit in ______?', '{"A":"Two days","B":"One day","C":"Three days","D":"Six days"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A geostationary satellite orbits the Earth once every 24 hours, matching the Earth''s rotation.This keeps it fixed over the same spot on the equator, making it ideal for communication and weather monitoring.', 0, 0, 0, 1790968060922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_24657c68cf516271', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Less than one percent of Earth’s water is fresh water but Ocean contains what percent of the total water of planet Earth?', '{"A":"99%","B":"89%","C":"77%","D":"97%"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation About 97% of the Earth''s water is contained in the oceans, which is saltwater.The remaining 3% is freshwater, but most of it is frozen in glaciers and polar ice caps.Only about 0.3% of the Earth''s water is freshwater that is readily available for human consumption, agriculture, and other uses.', 0, 0, 0, 1790968060922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b4aa7853036e5041', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which of following is used to measure the distance between planet and stars?', '{"A":"Light year","B":"Staller mile","C":"Centimeter","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A light year is the distance light travels in one year — about 9.46 trillion kilometers.It is commonly used to measure vast distances between stars and galaxies.Astronomers use an effect called parallax to measure distances to nearby stars. Parallax is the apparent displacement of an object because of a change in the observer''s point of view.', 0, 0, 0, 1790968060922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17f395ac43403808', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'The Mars has____ moons.', '{"A":"3","B":"4","C":"5","D":"2"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Number of moons in the planets:Mercury: 0Venus: 0Earth: 1Mars: 2Jupiter: 95Saturn: 146Uranus: 27Neptune: 14', 0, 0, 0, 1790968060922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75a6d321dbaa00bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Which planet has no moon?', '{"A":"Venus","B":"Neptune","C":"Mars","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Venus is the hottest planet in the solar system.Venus has no moons.The "black planet" is Venus.The second closest planet to the sun is Venus.The slowest-rotating planet is Venus.Venus is similar in size to Earth.Additional information:Eight planets in the solar system: MercuryVenusEarthMarsJupiterSaturnUranusNeptune', 0, 0, 0, 1790968060922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_666e3f2631b85573', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'A radio transmission from an astronaut on the moon will be received how much later on the Earth? (The million meters from the Earth).', '{"A":"1.27s","B":"0.38s","C":"0.25s","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The distance between the Earth and the Moon is approximately 384,000 kilometers (384 million meters).Using the speed of light (c = 3 × 10⁸ m/s), time = distance/speed = 384 × 10⁶ / 3 × 10⁸ = 1.27 seconds.', 0, 0, 0, 1790968060922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e1b08e764accee87', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'According to Big Bang Theory, the Universe began about ___ billion years ago.', '{"A":"10 – 20","B":"10 – 30","C":"20 – 30","D":"20 – 25"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to Big Bang Theory, the Universe began about 10-20 billion years ago.Big Bang theory explains Origin of Universe .At the time of the big bang Time was zero.', 0, 0, 0, 1790968060922) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ca4bb63754765df7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'According to the Big Bang theory, the universe is _____?', '{"A":"Stationary","B":"Expanding","C":"Contracting","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to the Big Bang theory, the universe is expanding.The universe is currently 13.8 billion years old.According to Big Bang Theory, the Universe began about 10-20 billion years ago.Big Bang theory explains Origin of Universe.At the time of the big bang, Time was zero.', 0, 0, 0, 1790968060949) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c352d6e1d92e7402', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Venus indicated the direction of ____?', '{"A":"West","B":"South","C":"North","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Venus, often called the "Evening Star" or "Morning Star," appears in the western sky after sunset.Venus is the brightest planet.It has an atmosphere but no moons.It''s identical in size, chemistry and gravity.It has volcanoes, mountains and sand.It''s also called Sister Planet of the Earth.', 0, 0, 0, 1790968060949) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c073a9b57f058e6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_space', 'Phases of the moon occur because _____?', '{"A":"We can see only that part of moon which reflects light towards us","B":"Our distance from the moon keeps changing","C":"The shadow of earth covers only a part of moon surface","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Phases of the moon occur because we can see only that part of the moon which reflects light towards us.The changing shape of the bright part of the Moon that we see is called its phase.The moon is illuminated because it reflects the light from the sun. The part of the moon facing the sun is lit up.The part facing away from the sun is in darkness.', 0, 0, 0, 1790968060949) ON CONFLICT(id) DO NOTHING;
