INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_96e419237428b991', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'Study of living animals diseases', '{"A":"Epidemiology","B":"Ecology","C":"Seismology","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Epidemiology, the study of epidemics, is sometimes defined as the medical aspect of ecology, for it is the study of diseases in animal populations.', 0, 0, 0, 1790968061814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ae3c1be11edf0918', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', 'which of the following is the study of society social interaction patterns of social relationships and culture of everyday life?', '{"A":"Anthropology","B":"Archaeology","C":"Sociology","D":"Human geography"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sociology is the study of groups and group interactions, societies and social interactions, from small and personal groups to very large groups.', 0, 0, 0, 1790968061843) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1dbd686d5479fdf5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_branches', '___ is a branch of science which deals with.', '{"A":"Light","B":"Motion","C":"Sound","D":"All"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The branch of science concerned with the nature and properties of matter and energy. The subject matter of physics includes mechanics, heat, light and other radiation, sound, electricity, magnetism, and the structure of atoms."', 0, 0, 0, 1790968061843) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eds_botany', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Botany & Zoology', 'top_everyday_science', 63, 1790968061873) ON CONFLICT(id) DO UPDATE SET total_mcqs = 63;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9bcae0d18b359b0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Which tree has aerial roots?', '{"A":"Neem tree","B":"Mango tree","C":"Banyan tree","D":"Peepal tree"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Banyan tree is famous for developing aerial roots from its branches.These roots grow downward and may become supporting trunks.Because of its multiple root-like structures.Last verified on 04-09-2026', 0, 0, 0, 1790968061902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_414d02f4f4b62e30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The age of a tree is determined by its ______?', '{"A":"Height","B":"Rings (Number of Annual rings)","C":"Crown","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The age of a tree is determined by its Rings (Number of Annual Rings).Each annual ring generally represents one year of growth.Counting the rings on the trunk helps determine the tree''s age.The study of tree rings is called Dendrochronology.Last verified on 20-07-2026', 0, 0, 0, 1790968061902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6759c6a2bdd0eeb4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Who proposed the Theory of Evolution?', '{"A":"Charles Darwin","B":"Herbert Spencer","C":"Mendel","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Theory proposed by: Charles DarwinBook published: 1859Book name: On the Origin of SpeciesKey concept: Natural SelectionVoyage that inspired him: HMS Beagle expedition (1831–1836)Last verified on 21-06-2026', 0, 0, 0, 1790968061902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f1ce0c5431766a83', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Ornithology is the science which deals with ____?', '{"A":"Study of birds","B":"Study of bones","C":"Study of heart","D":"Study of smells"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ornithology is the branch of zoology that deals with the study of birds.It includes bird behavior, classification, and migration patterns.Scientists who study birds are called ornithologists.Last verified on 10-06-2026', 0, 0, 0, 1790968061902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_59f3711257bff37b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The process of photosynthesis produces glucose and ______?', '{"A":"Carbon dioxide","B":"Oxygen","C":"Water","D":"Carbo monoxide"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Photosynthesis produces glucose and oxygen.Green plants use sunlight, water, and carbon dioxide.This process occurs in chloroplasts using chlorophyll.Glucose is used as food for energy and growth.Oxygen is released as a byproduct into the atmosphere.Last verified on 10-03-2026', 0, 0, 0, 1790968061902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1e4cf501b8ad638c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Which organs of plants are also called as food factory of plant?', '{"A":"Roots","B":"Stems","C":"Leaves","D":"Flowers"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Leaves are called the food factory of plants.They prepare food through the process of Photosynthesis.Chlorophyll in leaves absorbs sunlight to make food.Photosynthesis uses Carbon dioxide (CO₂), Water (H₂O), and Sunlight.Food produced is mainly Glucose, which provides energy to the plant.Last verified on 13-03-2026', 0, 0, 0, 1790968061902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ebb147f228009d24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Chlorophyll is a green substance that is present in _____?', '{"A":"Mitochondria","B":"Nucleus","C":"Chloroplast","D":"Golgi Apparatus"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chlorophyll is the green pigment responsible for photosynthesis in plants.It captures sunlight and converts it into chemical energy to make food.Additional information:Plants use chlorophyll to produce glucose and oxygen through photosynthesis.Chloroplasts contain chlorophyll a and b, which absorb sunlight.Last verified on 22-01-2026', 0, 0, 0, 1790968061902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_266ef3c147384eb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The movement of materials/sugar from the leaves to other tissues of the plant is called?', '{"A":"Translocation","B":"Photosynthesis","C":"Respiration","D":"Transpiration"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Translocation is the process by which food made in the leaves moves to other parts of the plant through the phloem.In plants, food is produced in the leaves through photosynthesis.This prepared food must be transported to other parts like roots, stems, and fruits.Last verified on 16-03-2026', 0, 0, 0, 1790968061902) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e87d421666b91bf6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Scientific/botanical name of Rice plant is _____?', '{"A":"Daucus carota","B":"Oryza sativa","C":"Malus domestica","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The following table provides the botanical names for a variety of familiar plants: Rice : Oryza sativaApple : Malus domesticaCarrot : Daucus carotaCoconut : Cocos nuciferaCucumber : Cucumis sativusGinger : Zingiber officinaleMango : Mangifera indicaOak tree : QuercusOnion : Allium cepaPotato : Solanum tuberosumWheat : Triticum aestivumRose : RosaSunflower : Helianthus annuusTomato : Solanum lycopersicum', 0, 0, 0, 1790968061930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_36563fd98a1f046f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'In plant cells, which organelle performs photosynthesis and contains chlorophyll?', '{"A":"Mitochondria","B":"Chloroplast","C":"Nucleus","D":"Endoplasmic Reticulum"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chloroplast is the plant cell organelle that performs photosynthesis.It contains chlorophyll, the green pigment that captures sunlight to produce food (glucose) for the plant.Additional information:Mitochondria: Powerhouse of the cell, produces energy via respirationNucleus: Controls cell activities and stores DNALast verified on 11-02-2026', 0, 0, 0, 1790968061930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_08c9babaef9fa6b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Which plant hormone stimulates the ripening of fruit and inhabits plant growth?', '{"A":"Abscisic acid","B":"Ethylene","C":"Auxin","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ethylene is a gaseous plant hormone that stimulates fruit ripening.It can inhibit vegetative growth in some plants.It is naturally produced by fruits like apples and bananas during maturation.Additional information:Abscisic acid helps in seed dormancy and stress response.Auxin mainly promotes cell elongation and growth.Last verified on 30-01-2026', 0, 0, 0, 1790968061930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f867b60f082ef628', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The outer layer of the seed coat is called _____?', '{"A":"Plumule","B":"Radicle","C":"Testa","D":"Teginen"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The seed coat protects the embryo inside the seed.The outermost layer of the seed coat is called Testa.It acts as a barrier against mechanical damage, pathogens, and water loss.Additional information:Testa may have hair, wax, or spines in some seeds.Plays a role in seed dormancy and protection.Last verified on 25-01-2026', 0, 0, 0, 1790968061930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea4f8e4f933c7a4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Chlorophyll is present in ______?', '{"A":"Virus","B":"Algae","C":"Animals","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chlorophyll is a compound that is called a Chelate.Photosynthesis depends on the presence of chlorophyll for the absorption of light.Additional information:There are about six closely related chlorophylls:chlorophyll achlorophyll bchlorophyll cchlorophyll dchlorophyll echlorophyll fLast verified on 22-01-2026', 0, 0, 0, 1790968061930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_70a95e14e6188148', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Study of the evolution of man as an animal is known as?', '{"A":"Archaeology","B":"Chronology","C":"Ethnology","D":"Anthropology"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The study of humans has multiple branches focusing on biology, culture, and history.Anthropology specifically studies the evolution and biological development of humans.It examines humans as part of the animal kingdom and their physical, social, and cultural traits.Last verified on 22-01-2026', 0, 0, 0, 1790968061930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_04ca625588dbd533', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'A part of maize seed that contains stored food is called?', '{"A":"Embryo","B":"Endosperm","C":"Seed coat","D":"Cotyledon"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The endosperm is the main storage tissue in maize seeds.It containing nutrients like starch, proteins, and oils.It support the growth of the embryo during germination.Last verified on 22-01-2026', 0, 0, 0, 1790968061930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c6aab335872c3272', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Which of the following animals are warm-blooded? Birds, Reptiles, Fish, Amphibians', '{"A":"Birds","B":"Reptiles","C":"Fish","D":"Amphibians"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Elephants, bears, chickens, monkeys, cows, wolf, birds, etc. are warm blooded animals Warm blooded means گرم خون والا', 0, 0, 0, 1790968061930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7393d1bde4bc33bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The bird that lays the largest egg is?', '{"A":"Cranes","B":"Bald-eagle","C":"Ostrich","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Female ostriches lay the largest eggs of any living bird. These gigantic birds are the biggest birds on the planet.', 0, 0, 0, 1790968061961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_230f6afec162a93b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'During the daytime for the photosynthesis, plants require ______?', '{"A":"O2","B":"N2","C":"CO2","D":"H2"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During the daytime, plants require Carbon Dioxide (CO2) for photosynthesis.Which is the process by which they produce glucose and oxygen.', 0, 0, 0, 1790968061961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4e38d3d5b44e17b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'By which plant produce sugar and starch by means of sunlight, which is from?', '{"A":"Photosynthesis","B":"Fertilization","C":"Hibernation","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plants produce sugar and starch using sunlight through photosynthesis.It is a process where light energy converts carbon dioxide and water into glucose and oxygen.', 0, 0, 0, 1790968061961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ee0ba97ee0833c2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Which of the following is the green part of flower?', '{"A":"Carpel","B":"Sepal","C":"Petal","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sepal is usually the green part of a flower that protects the bud before it opens.It forms the outermost whorl and supports the petals when in bloom.', 0, 0, 0, 1790968061961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c82ad1f1061725e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Recognize the factor which does not affect the process of photosynthesis?', '{"A":"O2","B":"CO2","C":"H20","D":"Light"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oxygen is a byproduct of photosynthesis.It not a factor that affects the process.', 0, 0, 0, 1790968061961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bab8ba889dd42587', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Age of the tree can be determined by _____?', '{"A":"By thickness of the bark","B":"By bulk of the tree","C":"By counting the number of rings on its stem/trunk","D":"By numbers of leaves"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The age of a tree is determined by counting its growth rings.They are visible in the cross-section of the stem.Each ring represents one year of growth.', 0, 0, 0, 1790968061961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e20e64af54e646e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Chlorophyll is required for the process of ______?', '{"A":"Photosynthesis","B":"Osmosis","C":"Respiration","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chlorophyll is the green pigment in plants that captures sunlight for photosynthesis.It helps convert carbon dioxide and water into glucose and oxygen.', 0, 0, 0, 1790968061961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0774f2b8dd2395fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'According to Lamarckism, the basis of evolution is _____?', '{"A":"Inheritance of acquired characteristics","B":"Mutation","C":"Natural selection","D":"Survival of the fittest"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lamarckism proposes that traits acquired during an organism’s life can be passed to offspring.This was Lamarck’s explanation for the evolution of species.', 0, 0, 0, 1790968061961) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ca5a03119ebc65ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Which one of the following is a true fish?', '{"A":"Sea fish","B":"Dogfish","C":"Cuttlefish","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sea fish are true fishes, belonging to the class Pisces with gills and fins.Dogfish is a true fish as it belongs to the class Chondrichthyes (cartilaginous fish).Jellyfish is a cnidarian, and Cuttlefish is a mollusk, so neither are true fish.', 0, 0, 0, 1790968061990) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_63b43af2794ce23b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The process of Plant making food using sunlight is called?', '{"A":"Respiration","B":"Germination","C":"Photosynthesis","D":"Filtration"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The process where plants use sunlight to create their food is called photosynthesis. During photosynthesis, plants convert light energy, water, and carbon dioxide into glucose, a sugar they use for energy, and oxygen, which is released into the atmosphere', 0, 0, 0, 1790968061990) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_24899bddd24a17bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Darwin’s theory of natural selection is based on _____?', '{"A":"Survival of fittest","B":"Over production","C":"Struggle for survival","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Darwin''s theory of natural selection is based on the following key principles:Overproduction: Organisms produce more offspring than can survive.Struggle for survival: Resources are limited, leading to competition among individuals.Survival of the fittest: Individuals with advantageous traits are more likely to survive and reproduce.These elements collectively explain how species evolve over time through natural selection.', 0, 0, 0, 1790968061991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7dfba2c86b3d2af4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Pathogenic fungi damaging the crops can be controlled by _____?', '{"A":"Herbicides","B":"Fungicides","C":"Insecticides","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fungicides are chemicals used to control fungal infections in crops.Herbicides target weeds.Insecticides target insects.', 0, 0, 0, 1790968061991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cdf39e4c1f7222f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Best efficiency of photosynthesis is present in _____?', '{"A":"C-4 plants","B":"C-3 plants","C":"CAM plants","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation C-4 plants (e.g., maize, sugarcane) have a special pathway that minimizes photorespiration.This makes them more efficient in photosynthesis under high light intensity, temperature, and low CO₂ conditions.', 0, 0, 0, 1790968061991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cbb47fd12292f0c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Naked seed plants are called _____?', '{"A":"Angiosperms","B":"Gymnosperms","C":"Bryophytes","D":"Pteridophytes"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gymnosperms are plants with "naked seeds," meaning their seeds are not enclosed within a fruit. This group includes conifers like pine trees.', 0, 0, 0, 1790968061991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_34451901d7432796', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Fruit development without fertilization and seed formation is called ______?', '{"A":"Gymnosperm","B":"Parthenocarpy","C":"Regeneration","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Parthenocarpy is the development of fruit without fertilization.Such fruits are seedless, e.g., banana, seedless grapes.', 0, 0, 0, 1790968061991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0f71e7730bf7b475', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The species which are becoming near to extinction are called ____?', '{"A":"Wild","B":"Endangered","C":"Threatened","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Species facing imminent extinction are called endangered. Specifically, an endangered species is at very high risk of extinction soon, either globally or within a specific region.', 0, 0, 0, 1790968061991) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cecca15ac12f28ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'In plant cells excess of glucose is converted into ______?', '{"A":"Starch","B":"Galactose","C":"Glycogen","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In plants, excess glucose is stored in the form of starch, an insoluble polysaccharide.Glycogen is the storage form in animals.Cellulose forms structural cell walls.', 0, 0, 0, 1790968062021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa12bd6e2ee90f5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'In all plants, the major sites of photosynthesis are----.', '{"A":"Leaves","B":"roots","C":"stems","D":"All of the above"}', 'A', NULL, 0, 0, 0, 1790968062021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2342cb49958f23ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The yellowing of leaves due to lack of chlorophyll is called ______?', '{"A":"Glazing","B":"Necrosis","C":"Bleaching","D":"Chlorosis"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The yellowing of leaves due to lack of chlorophyll is called chlorosis. This condition occurs when the green pigment, chlorophyll, is reduced or absent in the leaves, causing them to turn yellow.', 0, 0, 0, 1790968062021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_255f96302dccb018', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The metal ion present in the porphyrin ring of chlorophyll?', '{"A":"Fe","B":"Ca","C":"Mg","D":"Na"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chlorophyll, the pigment responsible for photosynthesis in plants, features a porphyrin ring structure at its core. This ring is composed of four smaller pyrrole rings linked by methine bridges. A magnesium ion is centrally located within this porphyrin ring, held in place by bonds with nitrogen atoms from the pyrrole rings.', 0, 0, 0, 1790968062021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_add2c7125154f10f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Members of the one species inhabiting an area ______?', '{"A":"Population","B":"Community","C":"Species","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A population refers to all individuals of the same species living in a specific geographic area.It is different from a community, which includes multiple species.', 0, 0, 0, 1790968062021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2b0dacbfdf099779', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Parasitic fungi directly absorb the nutrient form the living host cytoplasm by _____?', '{"A":"Haustoria","B":"Roots","C":"Rhizoids","D":"Gametangia"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Haustoria are specialized structures produced by parasitic fungi.They penetrate the host cells and absorb nutrients directly from the cytoplasm.', 0, 0, 0, 1790968062021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_659707b59eb371da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Iodine dissolves in water in the presence of KI due to formation of which of the following species?', '{"A":"I₂","B":"I⁻","C":"I₃","D":"I₁"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When iodine dissolves in water in the presence of KI, it forms the I₃⁻ ion.Iodine (I₂) is not very soluble in water on its own due to its non-polar nature. However, when added to an aqueous solution of potassium iodide (KI), The iodide ions (I⁻) react with the iodine molecules to form a triiodide ion (I₃⁻), which is more soluble in water. This complex ion is the reason why iodine''s solubility significantly increases in the presence of KI.', 0, 0, 0, 1790968062021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac3e4342202f9da2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The male reproductive part of the flower is called?', '{"A":"Stamen","B":"Pistil","C":"Carpel","D":"Anther"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The male reproductive part of a flower is called the Stamen.It consists of two parts:Anther (produces pollen grains)Filament (supports the anther)', 0, 0, 0, 1790968062021) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52ae82a76342da13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Who is the author of “The Origin of Species”?', '{"A":"Charles Darwin","B":"Pope","C":"Hardy","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Origin of Species” is a work of scientific literature by Charles Darwin It was published on 24 November 1859,The book is considered to be the foundation of evolutionary biology.ND5-5-2023', 0, 0, 0, 1790968062049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_86c83ba2bfdac9a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'There is a pore on seed coat, it is called _____?', '{"A":"Radicle","B":"Testa","C":"Plumule","D":"Micropyle"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Micropyle is a small pore in the seed coat that allows water and air to enter for germination. It also facilitates the passage of the pollen tube during fertilization.', 0, 0, 0, 1790968062049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa497688900a1950', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The Cave Squeaker, an endangered species of Frog, found in which country?', '{"A":"Zimbabwe","B":"Egypt","C":"Iceland","D":"Argentina"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cave squeaker (Arthroleptis troglodytes) is a species of frog in the family Arthroleptidae.It is endemic to the Chimanimani Mountains in Zimbabwe.', 0, 0, 0, 1790968062049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c8856a7e6abcc342', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Who gave the theory of Evolution By Natural Selection?', '{"A":"Edward Teller","B":"Charles Darwin","C":"Charlas Babbage","D":"Einstein","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Origin of species using Natural Selection was the work of Charles Darwin.It was published on 24 November 1859,..Charles Darwin''s discoveries included.four different species of giant ground sloth (some of the largest land mammals ever to have lived), a gomphothere, and the remains of an extinct horse.ND16-8-2023', 0, 0, 0, 1790968062049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b29628e7357b0213', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The biggest species of the cat family is _______?', '{"A":"Leopard","B":"Lion","C":"Tiger","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tiger, (Panthera tigris), the largest member of the cat family (Felidae)whileThe rusty-spotted cat (Prionailurus rubiginosus) is one of the cat family''s smallest membersND5-07-2023', 0, 0, 0, 1790968062049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc3b9af008decabe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Photosynthesis in plants takes place faster in _____?', '{"A":"White light","B":"Darkness","C":"Red light","D":"Yellow light"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Photosynthesis in plants occurs faster in white light.Because it contains all the wavelengths necessary for the process.', 0, 0, 0, 1790968062049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dc900ddc160e7084', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Zoology is the branch of?', '{"A":"Physical science","B":"BIO Science","C":"Mathematical Science","D":"Life Science","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zoology is derived from two Greek words; Zoo means an animal, and Logos means to study.', 0, 0, 0, 1790968062049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ae9e6a0a17c3f09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Cells that are responsible for Photosynthesis in plants?', '{"A":"Mesophyll cells","B":"Mesenchyme cells","C":"chloroplast","D":"all of these","E":"none of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Photosynthesis takes place in the chloroplast.The chlorophyll present in the chloroplast traps the light from the sun and carries out the process.', 0, 0, 0, 1790968062049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03eeba5e55c3890e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The species which we belong to is?', '{"A":"Homosapien","B":"aranthropus robustus","C":"Homoerectus","D":"all of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All people living today belong to the species Homo sapiens', 0, 0, 0, 1790968062078) ON CONFLICT(id) DO NOTHING;
