INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7503469c149c140b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Ecology is an environment in the same way as a Histology is to:', '{"A":"Fossils","B":"History","C":"Tissues","D":"Hormones"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ecology is the scientific study that is related to the environment which includes both living and non-living factors. Histology is the scientific and clinical study of cells, organs and tissues based on the observation under the surface of microscope.', 0, 0, 0, 1790968062078) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c422546217e6b65c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Higher reducing sugar in Fruit Jelly may result in crystallization of:', '{"A":"Fructose","B":"Glucose","C":"Sucrose","D":"None of these","E":"all of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Higher reducing sugar in Fruit Jelly may result in the crystallization of glycerolThe addition of glycerol and glucose syrup increased the equilibrium moisture content and reduced sugar crystallization significantly.ND06-08-2023', 0, 0, 0, 1790968062078) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d899f0aedbfac554', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Chlorophyll is a, an:', '{"A":"A green pigment found in the plants","B":"Halogen acid","C":"A chloro-organic compound","D":"Element"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chlorophyll is a compound that is called a Chelate. Photosynthesis depends on the presence of chlorophyll for the absorption of light.There are about five closely related chlorophylls:chlorophyll achlorophyll bchlorophyll cchlorophyll dchlorophyll echlorophyll f', 0, 0, 0, 1790968062078) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e7ea0ea623e37d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Method of growing terrestrial plant?', '{"A":"Hydroponics","B":"Photosynthesis","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A terrestrial plant is a plant that grows on, in, or from land.', 0, 0, 0, 1790968062108) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d39c90abc3afcb40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'An animal that has ability to eat and survive on both plant and animal matter is called :', '{"A":"Frugivore","B":"Herbivore","C":"Carnivore","D":"Omnivore","E":"None"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An omnivore is an animal that has the ability to eat and survive on both plant and animal matter.', 0, 0, 0, 1790968062108) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_85de893550d7d065', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Turmeric is obtained from which part of the plant', '{"A":"Flower","B":"Root","C":"Stem","D":"Fruit"}', 'B', NULL, 0, 0, 0, 1790968062108) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5f39793743029fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'The two branches of a plant gives two different fruits, tomatoes and brinjals, this can be explained', '{"A":"By nature''s freak","B":"By hybridization","C":"By grafting one with the other","D":"None  of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Answer:CGrafting is the process of joining two different plant parts together to create a new plant. Grafting allows you to combine the characteristics of two plants into one plant. Grafting was performed when Brinjar seedling 25 was 30 days old and Tomato 22 was 25 days old. Brinjar rhizome IC111056 tends to develop two branches in about 5 percent of seedlings. Finishing was done by side or splicing method with diagonal cuts of 5-7 mm in the rootstock and scion.', 0, 0, 0, 1790968062108) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e8286f9b8ac2c87', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Male part in flower is ?', '{"A":"Stigma","B":"Ovri","C":"Stamen","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The stamen is the male reproductive organ. It consists of a pollen anther and a long supporting filament.', 0, 0, 0, 1790968062108) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f0b7e0a627980592', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'Which of the following diseases is caused by insect bites?', '{"A":"Asthma","B":"Scurry","C":"Pneumonia","D":"None of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dengue is caused by insect bites.', 0, 0, 0, 1790968062108) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2838990c5a931721', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eds_botany', 'why we should not sleep under tree at night:', '{"A":"Carbon di oxide","B":"Oxygen","C":"Nitrogen","D":"Hydrogen"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Trees release carbon dioxide at night and carbon dioxide being heavier than air descendes.So a person sleeping under a tree breathes carbon dioxide which is harmful for the human body.', 0, 0, 0, 1790968062108) ON CONFLICT(id) DO NOTHING;